INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('elitan/frost/monitor', 'community', 'elitan', 'frost', 'elitan/frost', 'monitor', 0, 0, 20, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:03.343Z', 'd162cc7298e54a06e9b056a73ddac267c82bda4943cc4407fe4d66d531292a38', '{"id":"elitan/frost/monitor","name":"monitor","description":{"en":"Monitor automates CI checks for Vercel experience and VPS pricing, ensuring 100% green status. It analyzes failures, fixes issues, and pushes updates, benefiting developers and DevOps teams.","zh":"Monitor是一种自动化CI检查和故障修复的工具，使用gh pr checks命令获取PR状态，分析和修复故障","ja":"MonitorはCIチェックと障害修復を自動化するツールで、gh pr checksコマンドを使ってPRの状態を取得し、障害を分析して修復します","ko":"Monitor는 CI 체크와 오류 수정을 자동화하는 도구로 gh pr checks 명령을 사용하여 PR 상태를 가져오고 오류를 분석하고 수정합니다","es":"Un agente de IA que monitoriza automáticamente el estado de tus Pull Requests en Vercel. Utiliza la CLI de GitHub (`gh pr checks`) para verificar el CI, analizar logs de error, aplicar correcciones y repetir el proceso hasta que todas las checks estén en verde.","fr":"Un agent IA qui surveille automatiquement l''état de vos Pull Requests sur Vercel. Il utilise la CLI GitHub (`gh pr checks`) pour vérifier le CI, analyser les logs d''erreur, appliquer des corrections et répéter le processus jusqu''à ce que tous les checks soient verts.","de":"Ein KI-Agent, der automatisch den Status Ihrer Pull Requests auf Vercel überwacht. Er verwendet die GitHub-CLI (`gh pr checks`), um den CI-Status zu prüfen, Fehlerprotokolle zu analysieren, Korrekturen anzuwenden und den Prozess zu wiederholen, bis alle Checks grün sind.","pt":"O monitor é uma ferramenta que garante PRs 100% green com os comandos `gh pr checks`. Ele analisa falhas, corrige problemas e repete até que todos os testes passem.","ru":"Монитор - это инструмент, обеспечивающий PR 100% зеленый с помощью команды `gh pr checks`. Он анализирует неудачи, исправляет проблемы и повторяет до тех пор, пока все проверки не пройдут с ИИ Агентами","ar":"أداة المراقبة هي أداة تضمن Pull Requests بنسبة 100% خضراء باستخدام الأمر `gh pr checks`. أنها تحلل الأخطاء، تصحح المشاكل وتكرر حتى جميع الاختبارات تنجح"},"seo":{"title":{"en":"Monitor: Automated CI Check Setup Guide | AI Agent Skill","zh":"Monitor Setup Guide: 自动化CI检查和故障修复","ja":"Monitor ベストプラクティス: CIエージェントによる自動化","ko":"Monitor 설정 가이드: 자동화된 CI 체크와 오류 수정","es":"Monitor de PR: Guía de Configuración para CI/CD 100% Verde","fr":"Agent Monitor : Guide de Configuration pour CI/CD 100% Vert","de":"Monitor Skill: Setup-Anleitung für 100% grüne CI/CD-PRs","pt":"Guia de Configuração do Monitor para Desenvolvedores","ru":"Настройка Монитора: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد أداة المراقبة لمنصة فيرسل"},"description":{"en":"Learn how to automate CI checks with Monitor. Get step-by-step instructions on setting up Monitor for Vercel experience and VPS pricing optimization. Start now!","zh":"使用Monitor自动化CI检查和故障修复，确保代码质量和稳定性，了解更多关于Vercel和VPS的信息","ja":"Monitorを使ってCIチェックと障害修復を自動化し、コードの品質と安定性を確保します。VercelとVPSの詳細を確認","ko":"Monitor를 사용하여 CI 체크와 오류 수정을 자동화하고 코드 품질과 안정성을 보장합니다. Vercel과 VPS에 대한 자세한 정보","es":"Automatiza la monitorización de tus PRs en Vercel. Este agente de IA usa `gh pr checks`, analiza fallos de CI, aplica fixes y repite hasta conseguir un estad...","fr":"Automatisez la surveillance de vos PRs sur Vercel. Cet agent IA utilise `gh pr checks`, analyse les échecs CI, applique des correctifs et répète jusqu''à un s...","de":"Automatisieren Sie die Überwachung Ihrer Vercel-PRs. Dieser KI-Agent nutzt `gh pr checks`, analysiert CI-Fehler, wendet Fixes an und wiederholt, bis der Stat...","pt":"Aprenda a configurar o monitor para garantir PRs 100% green com os comandos `gh pr checks` e melhore a experiência do Vercel","ru":"Узнайте, как настроить монитор для обеспечения PR 100% зеленый с помощью команды `gh pr checks` и улучшить опыт Vercel с ИИ Агентами","ar":"تعرف على كيفية إعداد أداة المراقبة لضمان Pull Requests بنسبة 100% خضراء باستخدام الأمر `gh pr checks` و تحسين تجربة منصة فيرسل"},"definition":{"en":"Monitor is a skill that automates Continuous Integration (CI) checks, ensuring 100% green status by analyzing failures, fixing issues, and pushing updates.","zh":"Monitor是一种自动化CI检查和故障修复的AIエージェント，用于确保代码质量和稳定性","ja":"Monitorはコードの品質と安定性を確保するためのCIチェックと障害修復を自動化するAIエージェントです","ko":"Monitor는 코드 품질과 안정성을 보장하기 위한 CI 체크와 오류 수정을 자동화하는 AI 도구입니다","es":"El skill ''monitor'' es un agente de IA automatizado para GitHub. Su función es monitorizar Pull Requests, asegurar que todas las comprobaciones de CI estén en verde, analizar fallos, aplicar fixes y repetir el proceso de forma autónoma.","fr":"Le skill ''monitor'' est un agent IA automatisé pour GitHub. Sa fonction est de surveiller les Pull Requests, de s''assurer que toutes les vérifications CI sont vertes, d''analyser les échecs, d''appliquer des correctifs et de répéter le processus de manière autonome.","de":"Der ''monitor''-Skill ist ein automatisierter KI-Agent für GitHub. Seine Funktion ist die Überwachung von Pull Requests, um sicherzustellen, dass alle CI-Checks grün sind, Fehler zu analysieren, Fixes anzuwenden und den Prozess autonom zu wiederholen.","pt":"O monitor é uma ferramenta de desenvolvimento que garante a integridade dos Pull Requests","ru":"Монитор - это инструмент разработки, обеспечивающий целостность Pull Requests с ИИ Агентами","ar":"أداة المراقبة هي أداة تطوير تضمن سلامة Pull Requests"},"features":{"en":["Uses `gh pr checks` command to get current PR status","Analyzes failure logs to identify and fix issues","Commits and pushes fixes to ensure 100% green status","Supports 60-second sleep intervals between status checks","Repeats checks until all CI checks pass","Utilizes Vercel experience and VPS pricing for optimization"],"zh":["自动化CI检查","故障分析和修复","使用gh pr checks命令获取PR状态","支持Vercel和VPS","自动化代码质量检查","提高代码稳定性"],"ja":["CIチェックの自動化","障害分析と修復","gh pr checksコマンドを使ったPR状態の取得","VercelとVPSのサポート","コード品質の自動化チェック","コード安定性の向上"],"ko":["CI 체크 자동화","오류 분석과 수정","gh pr checks 명령을 사용한 PR 상태 가져오기","Vercel과 VPS 지원","코드 품질 자동화 체크","코드 안정성 향상"],"es":["Monitorización automática con el comando `gh pr checks`","Análisis de logs de error en comprobaciones de CI fallidas","Aplicación autónoma de fixes para los problemas detectados","Commit y push automático de las correcciones","Intervalo configurable de espera entre checks (por defecto 60s)","Bucle de repetición hasta alcanzar un estado 100% verde"],"fr":["Surveillance automatique avec la commande `gh pr checks`","Analyse des logs d''erreur des vérifications CI en échec","Application autonome de correctifs pour les problèmes identifiés","Commit et push automatiques des corrections","Intervalle d''attente configurable entre les vérifications (par défaut 60s)","Boucle de répétition jusqu''à l''obtention d''un statut 100% vert"],"de":["Automatische Überwachung mit dem Befehl `gh pr checks`","Analyse von Fehlerprotokollen fehlgeschlagener CI-Checks","Autonome Anwendung von Fixes für erkannte Probleme","Automatisches Commit und Push der Korrekturen","Konfigurierbares Warteintervall zwischen Checks (Standard: 60s)","Wiederholungsschleife bis ein 100% grüner Status erreicht ist"],"pt":["Verificação de status de PR com `gh pr checks`","Análise de falhas e correção de problemas","Repetição de testes até que todos passem","Suporte à experiência do Vercel","Integração com comandos CLI","Aumento da eficiência do desenvolvimento"],"ru":["Проверка статуса PR с помощью команды `gh pr checks`","Анализ неудач и исправление проблем","Повторение тестов до тех пор, пока все проверки не пройдут","Поддержка опыта Vercel с ИИ Агентами","Интеграция с командами CLI","Повышение эффективности разработки"],"ar":["تحقق من حالة Pull Request باستخدام الأمر `gh pr checks`","تحليل الأخطاء وتصحيح المشاكل","تكرار الاختبارات حتى جميع الاختبارات تنجح","دعم تجربة منصة فيرسل","تكامل مع أوامر CLI","زيادة كفاءة التطوير"]},"keywords":{"en":["how to use monitor for CI checks","monitor vs github actions","monitor setup guide for Vercel","what is monitor skill","monitor alternative for DevOps","monitor install for VPS pricing optimization"],"zh":["Monitor","CI检查","故障修复","Vercel","VPS","自动化","代码质量","AIエージェント","gh pr checks","代码稳定性"],"ja":["Monitor","CIチェック","障害修復","Vercel","VPS","自動化","コード品質","AIエージェント","gh pr checks","コード安定性"],"ko":["Monitor","CI 체크","오류 수정","Vercel","VPS","자동화","코드 품질","AI 도구","gh pr checks","코드 안정성"],"es":["agente de IA monitor PR","automatizar checks CI GitHub","gh pr checks vercel","fix automático CI fallido","monitor pull requests verde","agente IA desarrollo DevOps","CLI GitHub automatización"],"fr":["agent IA monitor PR","automatiser vérifications CI GitHub","gh pr checks vercel","correctif automatique CI échoué","surveiller pull requests vert","agent IA développement DevOps","CLI GitHub automatisation"],"de":["KI-Agent PR Monitor","CI-Checks GitHub automatisieren","gh pr checks vercel","automatischer Fix CI-Fehler","Pull Requests grün überwachen","KI-Agent DevOps Entwicklung","GitHub-CLI Automatisierung"],"pt":["monitor de PR","gh pr checks","Vercel experience","desenvolvimento de software","ferramentas de desenvolvimento","integração contínua","testes automatizados","desenvolvedores de software"],"ru":["монитор PR","gh pr checks","Vercel опыт","разработка программного обеспечения","инструменты разработки","ИИ Агенты","непрерывная интеграция","автоматизированное тестирование","разработчики программного обеспечения"],"ar":["أداة مراقبة Pull Request","الأمر gh pr checks","تجربة منصة فيرسل","تطوير البرمجيات","أدوات التطوير","وكلاء الذكاء الاصطناعي","التكامل المستمر","اختبارات آلية","مطورو البرمجيات"]}},"owner":"elitan","repo":"frost","repoPath":"elitan/frost","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"monitor","description":"Monitor a PR until CI is 100% green, fixing any failures","bodyPreview":"Monitor this PR and ensure it''s 100% green. If any CI checks fail, analyze the failure, fix the issue, and push the fix. Repeat until all checks pass.\n\nSteps:\n1. Get current PR status with `gh pr checks`\n2. If all green, done\n3. If any failing, get the failure logs\n4. Analyze and fix the issue\n5. Commit and push the fix\n6. Sleep 60s between status checks (CI can take a while)\n7. Repeat until 100% green\n\n$ARGUMENTS","body":"Monitor this PR and ensure it''s 100% green. If any CI checks fail, analyze the failure, fix the issue, and push the fix. Repeat until all checks pass.\n\nSteps:\n1. Get current PR status with `gh pr checks`\n2. If all green, done\n3. If any failing, get the failure logs\n4. Analyze and fix the issue\n5. Commit and push the fix\n6. Sleep 60s between status checks (CI can take a while)\n7. Repeat until 100% green\n\n$ARGUMENTS\n"},"lastSynced":"2026-03-08T02:01:03.343Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated CI/CD pipeline monitoring and issue resolution.","zh":"适用于需要自动化CI/CD流水线监控和问题解决的DevOps代理。","ja":"DevOpsエージェントが自動化されたCI/CDパイプラインの監視と問題解決を必要とする場合に適しています。","ko":"자동화된 CI/CD 파이프라인 모니터링 및 문제 해결이 필요한 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren un monitoreo automatizado de la tubería de CI/CD y resolución de problemas.","fr":"Idéal pour les agents DevOps nécessitant un monitoring automatique de la chaîne de CI/CD et une résolution de problèmes.","de":"Ideal für DevOps-Agents, die ein automatisiertes Monitoring der CI/CD-Pipeline und eine Fehlerbehebung benötigen.","pt":"Ideal para Agentes DevOps que exigem monitoramento e resolução automatizados de pipelines de CI/CD.","ru":"Идеально для агентов DevOps, требующих автоматизированного мониторинга и решения проблем конвейера CI/CD.","ar":"مثالي للوكلاء DevOps الذين يتطلبون مراقبة وتصحيح آليين لأنابيب CI/CD."},"recommendation":{"en":"Empowers agents to automate CI checks using GitHub PR checks, analyze failures, and push fixes, ensuring 100% green status and streamlining development workflows with gh commands and CI protocols.","zh":"赋予代理人使用GitHub PR检查自动化CI检查、分析失败、推送修复的能力，确保100%的绿色状态，并通过gh命令和CI协议简化开发工作流。","ja":"エージェントがGitHub PRチェックを使用してCIチェックを自動化し、失敗を分析し、修正をプッシュして100%のグリーン状態を確保し、ghコマンドとCIプロトコルで開発ワークフローを効率化することができます。","ko":"에이전트가 GitHub PR 검사를 사용하여 CI 검사를 자동화하고, 실패를 분석하고, 수정을 푸시하여 100%의 녹색 상태를 보장하며, gh 명령과 CI 프로토콜로 개발 워크플ロー를 간소화하는 기능을 제공합니다.","es":"Permite a los agentes automatizar las comprobaciones de CI utilizando comprobaciones de GitHub PR, analizar fallos y enviar soluciones, asegurando un estado verde al 100% y optimizando los flujos de trabajo de desarrollo con comandos gh y protocolos de CI.","fr":"Permet aux agents d''automatiser les vérifications de CI à l''aide de vérifications de GitHub PR, d''analyser les défaillances et de pousser des correctifs, assurant un statut vert à 100% et rationalisant les flux de travail de développement avec des commandes gh et des protocoles de CI.","de":"Ermächtigt Agenten, CI-Prüfungen mithilfe von GitHub-PR-Prüfungen zu automatisieren, Ausfälle zu analysieren und Korrekturen zu übertragen, um einen 100-prozentigen grünen Status sicherzustellen und Entwicklungsworkflows mit gh-Befehlen und CI-Protokollen zu optimieren.","pt":"Habilita os agentes a automatizar verificações de CI usando verificações de PR do GitHub, analisar falhas e enviar correções, garantindo status 100% verde e otimizando fluxos de trabalho de desenvolvimento com comandos gh e protocolos de CI.","ru":"Наделяет агентов возможностью автоматизировать проверки CI с помощью проверок PR GitHub, анализировать неудачи и отправлять исправления, обеспечивая 100% зеленый статус и оптимизируя рабочие процессы разработки с помощью команд gh и протоколов CI.","ar":"تمكين الوكلاء من توفير عمليات تحقق آليّة ل CI باستخدام عمليات التحقق من PR في GitHub وتحليل الأعطال وإرسال الإصلاحات، مما يضمن الحالة الخضراء 100% وتبسيط سير العمل التطويرية باستخدام أوامر gh وبروتوكولات CI."},"useCases":{"en":["Automating Vercel experience and VPS pricing checks","Debugging failing CI checks with failure log analysis","Ensuring 100% green PR status with iterative fix and push cycles"],"zh":["自动化Vercel体验和VPS价格检查","使用故障日志分析调试失败的CI检查","通过迭代修复和推送循环确保100%的绿色PR状态"],"ja":["Vercel体験とVPS価格のチェックを自動化する","失敗したCIチェックを故障ログ分析でデバッグする","イテレーティブな修正とプッシュサイクルで100%のグリーンPR状態を確保する"],"ko":["Vercel 경험 및 VPS 가격 체크 자동화","故障 로그 분석을 통한 실패한 CI 체크 디버깅","반복적 수정 및 푸시 주기를 통해 100% 녹색 PR 상태 보장"],"es":["Automatizar las comprobaciones de experiencia y precios de VPS de Vercel","Depurar comprobaciones de CI fallidas con análisis de registros de fallos","Asegurar un estado de PR verde al 100% con ciclos de solución y envío iterativos"],"fr":["Automatiser les vérifications d''expérience et de tarification de VPS de Vercel","Déboguer les vérifications de CI défaillantes avec une analyse des journaux de défaillance","Assurer un statut de PR vert à 100% avec des cycles de correction et de poussée itératifs"],"de":["Automatisieren von Vercel-Erfahrung und VPS-Preisprüfungen","Fehlschlagende CI-Prüfungen mit Fehlerprotokollanalyse debuggen","100-prozentigen grünen PR-Status mit iterativen Korrektur- und Übertragungszyklen sicherstellen"],"pt":["Automatizar experiência do Vercel e verificações de preços de VPS","Depurar verificações de CI com falha com análise de log de falha","Garantir status de PR 100% verde com ciclos de correção e envio iterativos"],"ru":["Автоматизировать опыт Vercel и проверки цен VPS","Отладить неудачные проверки CI с помощью анализа журнала неудач","Обеспечить 100% зеленый статус PR с итеративными циклами исправления и отправки"],"ar":["توفير تجربة Vercel وتحقق من أسعار VPS","تصحيح اختبارات CI الفاشلة مع تحليل سجل الفشل","ضمان حالة PR 100% خضراء مع دورات تصحيح وارسال متكررة"]},"limitations":{"en":["Requires GitHub access and permissions","Limited to CI checks with gh pr checks command","Dependent on CI pipeline setup and configuration"],"zh":["需要GitHub访问和权限","仅限使用gh pr checks命令的CI检查","依赖于CI流水线设置和配置"],"ja":["GitHubへのアクセスと権限が必要","gh pr checksコマンドでのCIチェックのみ","CIパイプラインの設定と構成に依存"],"ko":["GitHub 접근 및 권한 필요","gh pr checks 명령으로만 사용 가능한 CI 체크","CI 파이프라인 설정 및 구성에 의존"],"es":["Requiere acceso y permisos de GitHub","Limitado a comprobaciones de CI con el comando gh pr checks","Dependiente de la configuración y el establecimiento de la tubería de CI"],"fr":["Nécessite un accès et des autorisations GitHub","Limité aux vérifications de CI avec la commande gh pr checks","Dépend de la configuration et de la mise en place de la chaîne de CI"],"de":["Benötigt GitHub-Zugriff und -Berechtigungen","Begrenzt auf CI-Prüfungen mit dem Befehl gh pr checks","Abhängig von der Einrichtung und Konfiguration der CI-Pipeline"],"pt":["Exige acesso e permissões do GitHub","Limitado a verificações de CI com comando gh pr checks","Dependente da configuração e instalação do pipeline de CI"],"ru":["Требует доступа и разрешений GitHub","Ограничен проверками CI с командой gh pr checks","Зависит от настройки и конфигурации конвейера CI"],"ar":["يتطلب الوصول والصلاحيات إلى GitHub","محدود بالتحقق من CI باستخدام أمر gh pr checks","اعتمادية إعداد وتثبيت أنابيب CI"]},"version":4},"contentHash":"d162cc7298e54a06e9b056a73ddac267c82bda4943cc4407fe4d66d531292a38","qualityScore":20}');
