INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('elitan/frost/monitor', 'monitor', 'elitan', 'frost', 'community', 'monitor elitan frost community Monitor automates CI checks for Vercel experience and VPS pricing, ensuring 100% green status. It analyzes failures, fixes issues, and pushes updates, benefiting developers and DevOps teams. Monitor是一种自动化CI检查和故障修复的工具，使用gh pr checks命令获取PR状态，分析和修复故障 MonitorはCIチェックと障害修復を自動化するツールで、gh pr checksコマンドを使ってPRの状態を取得し、障害を分析して修復します Monitor는 CI 체크와 오류 수정을 자동화하는 도구로 gh pr checks 명령을 사용하여 PR 상태를 가져오고 오류를 분석하고 수정합니다 Un agente de IA que monitoriza automáticamente el estado de tus Pull Requests en Vercel. Utiliza la CLI de GitHub (`gh pr checks`) para verificar el CI, analizar logs de error, aplicar correcciones y repetir el proceso hasta que todas las checks estén en verde. Un agent IA qui surveille automatiquement l''état de vos Pull Requests sur Vercel. Il utilise la CLI GitHub (`gh pr checks`) pour vérifier le CI, analyser les logs d''erreur, appliquer des corrections et répéter le processus jusqu''à ce que tous les checks soient verts. Ein KI-Agent, der automatisch den Status Ihrer Pull Requests auf Vercel überwacht. Er verwendet die GitHub-CLI (`gh pr checks`), um den CI-Status zu prüfen, Fehlerprotokolle zu analysieren, Korrekturen anzuwenden und den Prozess zu wiederholen, bis alle Checks grün sind. O monitor é uma ferramenta que garante PRs 100% green com os comandos `gh pr checks`. Ele analisa falhas, corrige problemas e repete até que todos os testes passem. Монитор - это инструмент, обеспечивающий PR 100% зеленый с помощью команды `gh pr checks`. Он анализирует неудачи, исправляет проблемы и повторяет до тех пор, пока все проверки не пройдут с ИИ Агентами أداة المراقبة هي أداة تضمن Pull Requests بنسبة 100% خضراء باستخدام الأمر `gh pr checks`. أنها تحلل الأخطاء، تصحح المشاكل وتكرر حتى جميع الاختبارات تنجح how to use monitor for CI checks monitor vs github actions monitor setup guide for Vercel what is monitor skill monitor alternative for DevOps monitor install for VPS pricing optimization Monitor CI检查 故障修复 Vercel VPS 自动化 代码质量 AIエージェント gh pr checks 代码稳定性 Uses `gh pr checks` command to get current PR status Analyzes failure logs to identify and fix issues Commits and pushes fixes to ensure 100% green status Supports 60-second sleep intervals between status checks Repeats checks until all CI checks pass Utilizes Vercel experience and VPS pricing for optimization Monitor is a skill that automates Continuous Integration (CI) checks, ensuring 100% green status by analyzing failures, fixing issues, and pushing updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MetaMask/ocap-kernel/glossary', 'community', 'MetaMask', 'ocap-kernel', 'MetaMask/ocap-kernel', 'glossary', 0, 0, 20, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:04.604Z', '077e3821301b05882b56eec5b411addb71b965221a277d98fce6d7df65f1ca05', '{"id":"MetaMask/ocap-kernel/glossary","name":"glossary","description":{"en":"The glossary skill provides a technical reference for the MetaMask Ocap Kernel monorepo, explaining specific terms and concepts. It benefits developers working on the project by providing a clear understanding of the terminology used.","zh":"MetaMask Ocap Kernel monorepo 的专用术语表技能，帮助开发者维护项目特定术语的定义和关联。支持术语与实现文件的直接链接和概念间的交叉引用。","ja":"MetaMask Ocap Kernel monorepoの専門用語を管理するAIエージェントスキル。用語定義の追加、実装ファイルへのリンク、概念間の相互参照をサポートします。","ko":"MetaMask Ocap Kernel monorepo의 전용 용어집 스킬로, 개발자가 프로젝트 특정 용어의 정의와 연관성을 유지관리합니다. 구현 파일 직접 링크와 개념 간 교차 참조를 지원합니다.","es":"El glossario de MetaMask Ocap Kernel es una herramienta para explicar términos técnicos y conceptos relacionados. Permite enlazar términos con archivos de implementación y conceptos relacionados","fr":"Le glossaire de MetaMask Ocap Kernel est un outil pour expliquer des termes techniques et des concepts liés. Il permet de relier des termes à des fichiers d''implémentation et à des concepts liés","de":"Das Glossar von MetaMask Ocap Kernel ist ein Werkzeug, um Fachbegriffe und verwandte Konzepte zu erklären. Es ermöglicht das Verknüpfen von Begriffen mit Implementierungsdateien und verwandten Konzepten","pt":"Esta skill de IA gerencia o glossário técnico do monorepo MetaMask Ocap Kernel, automatizando a documentação de termos. Ela permite vincular termos diretamente aos arquivos de implementação em TypeScript e criar relações semânticas entre conceitos arquiteturais.","ru":"Этот ИИ агент управляет техническим глоссарием монорепозитория MetaMask Ocap Kernel, автоматизируя документирование терминов. Он позволяет связывать термины напрямую с файлами реализации на TypeScript и создавать семантические связи между архитектурными концепциями.","ar":"يدير وكيل الذكاء الاصطناعي هذا المسرد التقني لمستودع MetaMask Ocap Kernel monorepo، مما يوثق المصطلحات تلقائيًا. يسمح بربط المصطلحات مباشرة بملفات التنفيذ في TypeScript وإنشاء علاقات دلالية بين المفاهيم المعمارية."},"seo":{"title":{"en":"Glossary: Technical Reference Setup Guide | AI Agent Skill","zh":"MetaMask Ocap Kernel 词汇表指南 - 开发者术语管理","ja":"MetaMask Ocap Kernel 用語集ガイド - AIエージェント開発向け","ko":"MetaMask Ocap Kernel 용어집 가이드 - 개발자 용어 관리","es":"Guía de configuración de Glossary para MetaMask Ocap Kernel","fr":"Guide de démarrage rapide pour Glossary de MetaMask Ocap ...","de":"Einrichtungsleitfaden für Glossary in MetaMask Ocap Kernel","pt":"Glossary AI Agent: Guia de Implementação para Desenvolved...","ru":"Глоссарий ИИ Агента: Руководство по внедрению для разрабо...","ar":"قاموس وكيل الذكاء الاصطناعي: دليل التنفيذ للمطورين"},"description":{"en":"Discover how to effectively utilize the glossary skill for MetaMask Ocap Kernel monorepo, learn how to add new terms and link relevant concepts","zh":"MetaMask Ocap Kernel monorepo 专用术语表管理指南。学习如何添加术语条目、链接实现文件，并使用交叉引用构建结构化技术文档。","ja":"MetaMask Ocap Kernel monorepo向け用語集管理AIエージェント。用語追加、実装ファイルリンク、クロスリファレンス活用方法を解説。","ko":"MetaMask Ocap Kernel monorepo 전용 용어집 관리 가이드. 용어 추가, 구현 파일 링크, 교차 참조를 활용한 구조화된 기술 문서 구축 방법.","es":"Aprende a utilizar el glossario de MetaMask Ocap Kernel para mejorar la comprensión de términos técnicos y conceptos relacionados","fr":"Découvrez comment utiliser le glossaire de MetaMask Ocap Kernel pour améliorer votre compréhension des termes techniques et des concepts liés","de":"Erfahren Sie, wie Sie das Glossar von MetaMask Ocap Kernel nutzen können, um Ihr Verständnis von Fachbegriffen und verwandten Konzepten zu verbessern","pt":"Implemente um glossário técnico dinâmico no MetaMask Ocap Kernel monorepo. Aprenda a vincular termos a arquivos de implementação e criar referências cruzadas...","ru":"Реализуйте динамический технический глоссарий в MetaMask Ocap Kernel monorepo. Узнайте, как связывать термины с файлами реализации и создавать перекрестные с...","ar":"نفذ مسردًا تقنيًا ديناميكيًا في مستودع MetaMask Ocap Kernel monorepo. تعلم كيفية ربط المصطلحات بملفات التنفيذ وإنشاء إحالات مرجعية لتحسين التوثيق."},"definition":{"en":"Glossary is a technical reference that explains terms with specific meanings in the MetaMask Ocap Kernel monorepo project","zh":"MetaMask Ocap Kernel 词汇表是该项目中特定术语的集中解释文档。它通过术语条目、实现文件链接和概念交叉引用，为开发者提供清晰的技术概念定义和架构上下文。","ja":"MetaMask Ocap Kernel用語集は、プロジェクト内の専門用語を解説するAIエージェント機能です。用語エントリ、実装ファイルリンク、概念間の相互参照を通じて技術概念を明確化します。","ko":"MetaMask Ocap Kernel 용어집은 프로젝트 내 특정 용어들의 정의를 집중적으로 설명하는 문서입니다. 용어 항목, 구현 파일 링크, 개념 간 교차 참조를 통해 기술 개념과 아키텍처 컨텍스트를 제공합니다.","es":"Un glossario es una lista de términos técnicos con explicaciones detalladas, utilizado para mejorar la comprensión de conceptos complejos","fr":"Un glossaire est une liste de termes techniques avec des explications détaillées, utilisé pour améliorer la compréhension de concepts complexes","de":"Ein Glossar ist eine Liste von Fachbegriffen mit detaillierten Erklärungen, die zur Verbesserung des Verständnisses komplexer Konzepte verwendet wird","pt":"O Glossary AI Agent é uma ferramenta de documentação automatizada para o MetaMask Ocap Kernel que gerencia termos técnicos, vinculando-os a arquivos de implementação e criando uma rede semântica de conceitos através de referências cruzadas.","ru":"Глоссарий ИИ Агент — это инструмент автоматизированной документации для MetaMask Ocap Kernel, который управляет техническими терминами, связывая их с файлами реализации и создавая семантическую сеть концепций через перекрестные ссылки.","ar":"Glossary AI Agent هو أداة توثيق تلقائي لـ MetaMask Ocap Kernel تدير المصطلحات التقنية، وتربطها بملفات التنفيذ وتنشئ شبكة دلالية من المفاهيم عبر الإحالات المرجعية."},"features":{"en":["Includes links to relevant implementation files using [term](../path/to/file.ts) syntax","Supports cross-references with [term](#term) syntax to link related concepts","Allows adding new terms to the glossary with consideration of existing architectural concepts","Provides a clear understanding of specific terms and concepts in the project","Enables effective communication among developers working on the project","Facilitates the discovery of related concepts and implementation files"],"zh":["项目特定术语的集中化定义管理","使用 [term](../path/to/file.ts) 语法链接到相关实现文件","通过 [term](#term) 语法实现概念间的交叉引用","支持新术语与现有架构概念的关联分析","促进技术文档的结构化和一致性","基于 Markdown 的轻量级术语表实现"],"ja":["プロジェクト固有の用語定義の集中管理","[term](../path/to/file.ts) 構文による実装ファイルリンク","[term](#term) 構文を用いた概念間の相互参照","新規用語と既存アーキテクチャ概念の関連付け","技術文書の構造化と一貫性の促進","Markdownベースの軽量用語集実装"],"ko":["프로젝트 특정 용어의 집중화된 정의 관리","[term](../path/to/file.ts) 구문을 이용한 관련 구현 파일 링크","[term](#term) 구문을 통한 개념 간 교차 참조","신규 용어와 기존 아키텍처 개념의 연관성 분석 지원","기술 문서의 구조화와 일관성 촉진","Markdown 기반의 경량 용어집 구현"],"es":["Enlaces a archivos de implementación relevantes","Referencias cruzadas a conceptos relacionados","Inclusión de nuevos términos y conceptos","Uso de la sintaxis [term](../path/to/file.ts) para enlazar términos","Uso de la sintaxis [term](#term) para referencias cruzadas","Relación de nuevos términos con conceptos arquitectónicos existentes"],"fr":["Liens vers des fichiers d''implémentation pertinents","Références croisées à des concepts liés","Inclusion de nouveaux termes et concepts","Utilisation de la syntaxe [term](../path/to/file.ts) pour relier des termes","Utilisation de la syntaxe [term](#term) pour des références croisées","Relation de nouveaux termes avec des concepts architecturaux existants"],"de":["Verknüpfung mit relevanten Implementierungsdateien","Kreuzreferenzen zu verwandten Konzepten","Einbindung neuer Begriffe und Konzepte","Verwendung der Syntax [term](../path/to/file.ts) zur Verknüpfung von Begriffen","Verwendung der Syntax [term](#term) für Kreuzreferenzen