INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tdhopper/dotfiles2.0/home-network-admin', 'home-network-admin', 'tdhopper', 'dotfiles2.0', 'community', 'home-network-admin tdhopper dotfiles2.0 community The home-network-admin skill manages Tim''s home network, including devices connected via Tailscale, a Synology NAS, and Macs accessible via SSH. It provides a centralized way to administer the network. Home Network Admin使用yadm管理dotfiles，管理家庭网络中的设备 Home Network Adminはyadmでdotfilesを管理し、家庭ネットワーク内のデバイスを管理 홈 네트워크 관리는 yadm으로 dotfiles를 관리하여 홈 네트워크의 장치를 관리 home-network-admin es una herramienta para administrar redes domésticas con Tailscale y Synology. Ofrece acceso SSH y configuración de dispositivos home-network-admin est un outil pour administrer les réseaux domestiques avec Tailscale et Synology. Il propose un accès SSH et une configuration d''appareils home-network-admin ist ein Tool zur Verwaltung von Heimnetzwerken mit Tailscale und Synology. Es bietet SSH-Zugriff und Gerätekonfiguration O home-network-admin é uma ferramenta para gerenciar redes domésticas com yadm, incluindo dispositivos conectados via Tailscale e acesso SSH. Home-network-admin - это инструмент для управления домашней сетью с помощью yadm, включая устройства, подключенные через Tailscale, и доступ по SSH. home-network-admin هي أداة لإدارة الشبكات المحلية باستخدام yadm، بما في ذلك الأجهزة المتصلة عبر Tailscale ووصول SSH. how to use home-network-admin home-network-admin setup guide Tailscale network configuration yadm dotfiles management SSH access to Synology NAS home-network-admin alternative home-network-admin vs Tailscale install home-network-admin home-network-admin tutorial Home Network Admin yadm dotfiles Tailscale Synology NAS Mac SSH AIエージェント 家庭网络管理 设备管理 Manages devices connected over Tailscale Provides SSH access to Synology NAS and Macs Uses yadm for dotfiles management Defines SSH configs in ~/.ssh/config Supports short aliases for SSH connections, such as ''ssh synology'' and ''ssh dobro'' home-network-admin is a skill that administers a home network using yadm, featuring SSH access to devices like Synology NAS and Macs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KanayaActa/ai-driven-dev-template/commit-push-pr-flow', 'community', 'KanayaActa', 'ai-driven-dev-template', 'KanayaActa/ai-driven-dev-template', 'commit-push-pr-flow', 0, 0, 20, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:50.058Z', '1ef3bc9666707afc0e36d8a1bd2c406a034659003517398b9a98e7fe8d21bc6b', '{"id":"KanayaActa/ai-driven-dev-template/commit-push-pr-flow","name":"commit-push-pr-flow","description":{"en":"The commit-push-pr-flow skill automates Git workflows for developers, generating Conventional Commits messages and creating PRs with ease.","zh":"Commit-Push-PR-Flow是一种优化代码提交和审查的流程，通过git和GitHub API实现高效的代码管理","ja":"Commit-Push-PR-Flowは、コードの提出とレビューを最適化するための手順です。gitとGitHub APIを使用して効率的なコード管理を実現します","ko":"Commit-Push-PR-Flow는 코드 제출과 리뷰를 최적화하는 절차입니다. git과 GitHub API를 사용하여 효율적인 코드 관리를 구현합니다","es":"El commit-push-pr-flow es un flujo de trabajo de Git que automatiza los commits, push y solicitudes de extracción. Aprende a configurarlo para mejorar tu productividad","fr":"Le commit-push-pr-flow est un workflow Git qui automatise les commits, push et demandes d''extraction. Découvrez comment le configurer pour améliorer votre productivité","de":"Der commit-push-pr-flow ist ein Git-Workflow, der Commits, Push und Pull-Requests automatisiert. Erfahren Sie, wie Sie ihn konfigurieren, um Ihre Produktivität zu steigern","pt":"O fluxo de commit, push e PR é uma sequência de comandos Git para gerenciar alterações no código. Aprenda a configurá-lo com o agente AI Ferramentas","ru":"Поток commit, push и PR - это последовательность команд Git для управления изменениями в коде. Узнайте, как настроить его с помощью ИИ Агенты","ar":"تدفق Commit و Push و PR هو تسلسل من أوامر Git لإدارة التغييرات في الكود. تعرف على كيفية إعداده مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"commit-push-pr-flow: Git Workflow Automation Setup Guide ...","zh":"Commit-Push-PR-Flow Setup Guide: 优化代码提交和审查","ja":"Commit-Push-PR-Flow のベストプラクティス: AIエージェントを使用した効率的なコードレビュー","ko":"Commit-Push-PR-Flow 설정 가이드: 효율적인 코드 제출과 리뷰","es":"Guía de configuración de commit-push-pr-flow para flujos ...","fr":"Guide de mise en place de commit-push-pr-flow pour les wo...","de":"Einrichtungsleitfaden für commit-push-pr-flow in Git-Work...","pt":"Guia de Configuração do Fluxo de Commit, Push e PR","ru":"Настройка Потока Commit, Push и PR: Лучшие Практики","ar":"دليل إعداد تدفق Commit و Push و PR"},"description":{"en":"Streamline your Git workflow with commit-push-pr-flow. Learn how to automate commits, pushes, and PRs with this AI agent skill. Get started now!","zh":"了解Commit-Push-PR-Flow的技术细节，优化代码提交和审查流程，提高开发效率","ja":"Commit-Push-PR-Flowの技術的な内容を学び、コードの提出とレビューのプロセスを最適化する","ko":"Commit-Push-PR-Flow의 기술적인 세부사항을 익히고 코드 제출 및 리뷰 프로세스를 최적화하여 개발 효율성을 높여보세요","es":"Aprende a configurar commit-push-pr-flow para optimizar tus flujos de trabajo de Git con esta guía paso a paso","fr":"Découvrez comment configurer commit-push-pr-flow pour optimiser vos workflows Git avec ce guide étape par étape","de":"Erfahren Sie, wie Sie commit-push-pr-flow konfigurieren, um Ihre Git-Workflows zu optimieren, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o fluxo de commit, push e PR com o agente AI Ferramentas. Melhore sua produtividade com Git e GitHub","ru":"Узнайте, как настроить поток commit, push и PR с помощью ИИ Агенты. Улучшите свою производительность с Git и GitHub","ar":"تعرف على كيفية إعداد تدفق Commit و Push و PR باستخدام أدوات الذكاء الاصطناعي. تحسين الإنتاجية مع Git و GitHub"},"definition":{"en":"commit-push-pr-flow is a Git workflow automation skill that generates Conventional Commits messages and creates PRs using Git and GitHub CLI commands.","zh":"Commit-Push-PR-Flow是一种代码管理流程，使用git和GitHub API自动化代码提交和审查","ja":"Commit-Push-PR-Flowは、AIエージェントを使用したコード管理手順であり、gitとGitHub APIを使用してコードの提出とレビューを自動化する","ko":"Commit-Push-PR-Flow는 코드 관리 프로세스로, git과 GitHub API를 사용하여 코드 제출과 리뷰를 자동화합니다","es":"El commit-push-pr-flow es un flujo de trabajo de Git que combina commits, push y solicitudes de extracción para agilizar el desarrollo de software","fr":"Le commit-push-pr-flow est un workflow Git qui combine les commits, push et demandes d''extraction pour accélérer le développement de logiciels","de":"Der commit-push-pr-flow ist ein Git-Workflow, der Commits, Push und Pull-Requests kombiniert, um die Softwareentwicklung zu beschleunigen","pt":"O fluxo de commit, push e PR é um conjunto de etapas para gerenciar alterações no código fonte","ru":"Поток commit, push и PR - это набор этапов для управления изменениями в исходном коде","ar":"تدفق Commit و Push و PR هو مجموعة من المراحل لإدارة التغييرات في الكود المصدري"},"features":{"en":["Generates Conventional Commits messages for commit consistency","Automates `git add` and `git commit` commands for streamlined workflow","Creates PRs using `gh pr create` command with customizable titles and bodies","Supports `git push` with upstream tracking for seamless remote updates","Integrates with GitHub CLI for PR creation and viewing","Enforces best practices with PR title and body formatting guidelines"],"zh":["使用git status命令检查代码变化","生成Conventional Commits格式的提交消息","使用git add和git commit命令提交代码","使用git push命令将代码推送到远程仓库","使用gh pr create命令创建pull request","使用gh pr view命令查看pull request"],"ja":["git statusコマンドを使用してコードの変更を確認","Conventional Commits形式のコミットメッセージを生成","git addとgit commitコマンドを使用してコードをコミット","git pushコマンドを使用してコードをリモートリポジトリにプッシュ","gh pr createコマンドを使用してプルリクエストを作成","gh pr viewコマンドを使用してプルリクエストを表示"],"ko":["git status 명령어를 사용하여 코드 변경 사항을 확인","Conventional Commits 형식의 커밋 메시지를 생성","git add와 git commit 명령어를 사용하여 코드를 커밋","git push 명령어를 사용하여 코드를 원격 저장소에 푸시","gh pr create 명령어를 사용하여 풀 리퀘스트를 생성","gh pr view 명령어를 사용하여 풀 리퀘스트를 보기"],"es":["Automatización de commits con mensajes en formato Conventional Commits","Push automático a la rama de origen","Creación automática de solicitudes de extracción con título y descripción","Integración con la CLI de GitHub para una configuración más sencilla","Compatibilidad con archivos de configuración para personalizar el flujo de trabajo","Soporte para múltiples lenguajes de programación"],"fr":["Automatisation des commits avec des messages au format Conventional Commits","Push automatique vers la branche d''origine","Création automatique de demandes d''extraction avec titre et description","Intégration avec la CLI de GitHub pour une configuration plus simple","Compatibilité avec les fichiers de configuration pour personnaliser le workflow","Prise en charge de plusieurs langages de programmation"],"de":["Automatisierung von Commits mit Nachrichten im Conventional-Commits-Format","Automatischer Push an den Ursprungszweig","Automatische Erstellung von Pull-Requests mit Titel und Beschreibung","Integration mit der GitHub-CLI für eine einfachere Konfiguration","Kompatibilität mit Konfigurationsdateien für die Anpassung des Workflows","Unterstützung für mehrere Programmiersprachen"],"pt":["Gerenciamento de alterações com Git","Criação de commits com mensagens no formato Conventional Commits","Envio de alterações para o GitHub com git push","Criação de pull requests com gh pr create","Visualização de pull requests com gh pr view","Integração com o GitHub para melhorar a produtividade"],"ru":["Управление изменениями с помощью Git","Создание коммитов с сообщениями в формате Conventional Commits","Отправка изменений на GitHub с помощью git push","Создание запросов на принятие изменений с помощью gh pr create","Просмотр запросов на принятие изменений с помощью gh pr view","Интеграция с GitHub для улучшения производительности"],"ar":["إدارة التغييرات مع Git","إنشاءCommits مع رسائل بالتنسيق Conventional Commits","إرسال التغييرات إلى GitHub مع git push","إنشاء طلبات سحب مع gh pr create","عرض طلبات سحب مع gh pr view","التكامل مع GitHub لتحسين الإنتاجية"]},"keywords":{"en":["commit-push-pr-flow setup guide","git workflow automation","conventional commits tutorial","github cli commands","automate git commits","pr creation best practices","git push workflow","commit-push-pr-flow alternative","how to use commit-push-pr-flow","commit-push-pr-flow install"],"zh":["Commit-Push-PR-Flow","代码提交","代码审查","git","GitHub API","Conventional Commits","代码管理","自动化代码提交","优化代码提交和审查"],"ja":["Commit-Push-PR-Flow","コードの提出","コードのレビュー","git","GitHub API","Conventional Commits","コード管理","自動化コード提出","AIエージェント"],"ko":["Commit-Push-PR-Flow","코드 제출","코드 리뷰","git","GitHub API","Conventional Commits","코드 관리","자동화 코드 제출","효율적인 코드 관리"],"es":["commit-push-pr-flow","flujo de trabajo de Git","automatización de commits","push automático","solicitudes de extracción","Conventional Commits","CLI de GitHub","desarrollo de software","productividad","Herramientas de AI para desarrolladores"],"fr":["commit-push-pr-flow","workflow Git","automatisation des commits","push automatique","demandes d''extraction","Conventional Commits","CLI de GitHub","développement de logiciels","productivité","Outils d''IA pour les développeurs"],"de":["commit-push-pr-flow","Git-Workflow","Automatisierung von Commits","automatischer Push","Pull-Requests","Conventional Commits","GitHub-CLI","Softwareentwicklung","Produktivität","KI-Tools für Entwickler"],"pt":["fluxo de commit","push e PR","Git","GitHub","Conventional Commits","agente AI Ferramentas","produtividade","desenvolvimento de software","controle de versão"],"ru":["поток commit","push и PR","Git","GitHub","Conventional Commits","ИИ Агенты","производительность","разработка программного обеспечения","контроль версий"],"ar":["تدفق Commit","Push و PR","Git","GitHub","Conventional Commits","أدوات الذكاء الاصطناعي","الإنتاجية","تطوير البرمجيات","مراقبة الإصدار"]}},"owner":"KanayaActa","repo":"ai-driven-dev-template","repoPath":"KanayaActa/ai-driven-dev-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"commit-push-pr-flow","description":"タスク完了後に自動的に実行する必要があるフロースキルです","bodyPreview":"Commit, push, and open a PR\n\n## 手順\n1. `git status` で変更を確認\n2. 変更内容からConventional Commits形式のメッセージを生成\n3. `git add .` でステージング（.env等の機密ファイルがないか確認）\n4. `git commit -m \"生成したメッセージ\"`\n5. `git push -u origin HEAD`\n6. `gh pr create --title \"PRタイトル\" --body \"説明（日本語）\"`\n7. `gh pr view --web` で結果を共有して完了\n\n## 注意\n- PRタイトルにイシュー番号を含める（例: [YOUR_PREFIX]-15: ...）\n- 説明は日本語で記述","body":"Commit, push, and open a PR\n\n## 手順\n1. `git status` で変更を確認\n2. 変更内容からConventional Commits形式のメッセージを生成\n3. `git add .` でステージング（.env等の機密ファイルがないか確認）\n4. `git commit -m \"生成したメッセージ\"`\n5. `git push -u origin HEAD`\n6. `gh pr create --title \"PRタイトル\" --body \"説明（日本語）\"`\n7. `gh pr view --web` で結果を共有して完了\n\n## 注意\n- PRタイトルにイシュー番号を含める（例: [YOUR_PREFIX]-15: ...）\n- 説明は日本語で記述\n"},"lastSynced":"2026-03-08T02:01:50.058Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring streamlined Git workflow automation and Conventional Commits integration.","zh":"适用于需要简化 Git 工作流自动化和 Conventional Commits 集成的 DevOps Agents。","ja":"DevOps エージェントが Git ワークフロー自動化と Conventional Commits 統合をストリームライン化する必要がある場合に最適です。","ko":"Git 워크플ロー 자동화 및 Conventional Commits 통합을 간소화해야 하는 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren una automatización de flujo de trabajo de Git optimizada y una integración con Conventional Commits.","fr":"Idéal pour les agents DevOps nécessitant une automatisation du flux de travail Git optimisée et une intégration avec Conventional Commits.","de":"Ideal für DevOps-Agents, die eine optimierte Git-Workflow-Automatisierung und eine Integration mit Conventional Commits erfordern.","pt":"Ideal para Agentes DevOps que requerem automação de fluxo de trabalho Git simplificada e integração de Commits Convencionais.","ru":"Идеально подходит для агентов DevOps, требующих оптимизированной автоматизации рабочего процесса Git и интеграции с Conventional Commits.","ar":"مثالي لعمليات وكيل DevOps التي تتطلب تلقيم عمل Git المُبسط وتكامل Commits التقليدية."},"recommendation":{"en":"Empowers agents to automate Git workflows, generating Conventional Commits messages and creating PRs with ease, utilizing Git commands like `git add` and `git push`, and GitHub CLI commands such as `gh pr create` for seamless repository management.","zh":"赋予代理自动化 Git 工作流的能力，生成 Conventional Commits 消息并轻松创建 PR，利用 Git 命令如 `git add` 和 `git push`，以及 GitHub CLI 命令如 `gh pr create` 进行无缝的仓库管理。","ja":"エージェントが Git ワークフローを自動化し、Conventional Commits メッセージを生成し、`git add` および `git push` などの Git コマンドおよび `gh pr create` などの GitHub CLI コマンドを使用して PR を簡単に作成し、リポジトリをシームレスに管理できるようにします。","ko":"에이전트가 Git 워크플ロー 자동화 및 Conventional Commits 메시지 생성 및 PR 생성을 쉽게 하고 `git add` 및 `git push`와 같은 Git 명령어와 `gh pr create`와 같은 GitHub CLI 명령어를 사용하여 리포지토리 관리를 원활하게 진행할 수 있도록 합니다.","es":"Permite a los agentes automatizar flujos de trabajo de Git, generar mensajes de Conventional Commits y crear solicitudes de extracción con facilidad, utilizando comandos de Git como `git add` y `git push`, y comandos de GitHub CLI como `gh pr create` para una gestión de repositorios sin problemas.","fr":"Permet aux agents d''automatiser les flux de travail Git, de générer des messages Conventional Commits et de créer des demandes d''extraction avec facilité, en utilisant des commandes Git comme `git add` et `git push`, et des commandes GitHub CLI comme `gh pr create` pour une gestion de référentiels sans problèmes.","de":"Ermöglicht es Agenten, Git-Workflows zu automatisieren, Conventional Commits-Meldungen zu generieren und Pull-Requests mit Leichtigkeit zu erstellen, indem Git-Befehle wie `git add` und `git push` sowie GitHub-CLI-Befehle wie `gh pr create` für eine reibungslose Repository-Verwaltung verwendet werden.","pt":"Habilita os agentes a automatizar fluxos de trabalho Git, gerando mensagens de Commits Convencionais e criando PRs com facilidade, utilizando comandos Git como `git add` e `git push`, e comandos GitHub CLI como `gh pr create` para gerenciamento de repositório sem interrupções.","ru":"Позволяет агентам автоматизировать рабочие процессы Git, генерируя сообщения Conventional Commits и создавая запросы на включение изменений с легкостью, используя команды Git, такие как `git add` и `git push`, и команды GitHub CLI, такие как `gh pr create`, для бесперебойного управления репозиторием.","ar":"يتمكن الوكيل من تلقيم عمل Git، وتوليد رسائل Commits التقليدية، وإنشاء طلبات الدمج بسهولة، باستخدام أوامر Git مثل `git add` و `git push`، وأوامر GitHub CLI مثل `gh pr create` من أجل إدارة المستودع دون انقطاع."},"useCases":{"en":["Automating commit and push processes with standardized messages","Generating and managing Pull Requests with custom titles and descriptions","Streamlining development workflows by integrating with GitHub repositories"],"zh":["使用标准化消息自动化提交和推送过程","使用自定义标题和描述生成和管理拉取请求","通过与 GitHub 仓库集成简化开发工作流"],"ja":["標準化されたメッセージを使用してコミットとプッシュのプロセスを自動化する","カスタムのタイトルと説明を使用してプルリクエストを生成して管理する","GitHub リポジトリと統合して開発ワークフローを簡素化する"],"ko":["표준화된 메시지를 사용하여 커밋 및 푸시 프로세스 자동화","사용자 지정 제목 및 설명을 사용하여 풀 리퀘스트 생성 및 관리","GitHub 리포지토리와 통합하여 개발 워크플로우 간소화"],"es":["Automatizar procesos de confirmación y envío con mensajes estandarizados","Generar y administrar solicitudes de extracción con títulos y descripciones personalizados","Optimizar flujos de desarrollo integrándose con repositorios de GitHub"],"fr":["Automatiser les processus de validation et d''envoi avec des messages standardisés","Générer et gérer des demandes d''extraction avec des titres et des descriptions personnalisés","Optimiser les flux de développement en s''intégrant avec les référentiels GitHub"],"de":["Automatisieren von Commit- und Push-Prozessen mit standardisierten Meldungen","Erstellen und Verwalten von Pull-Requests mit benutzerdefinierten Titeln und Beschreibungen","Optimieren von Entwicklungsworkflows durch Integration mit GitHub-Repositories"],"pt":["Automatizar processos de compromisso e envio com mensagens padronizadas","Gerar e gerenciar solicitações de pull com títulos e descrições personalizados","Otimizar fluxos de trabalho de desenvolvimento integrando-se com repositórios GitHub"],"ru":["Автоматизировать процессы фиксации и публикации с стандартизированными сообщениями","Генерировать и управлять запросами на включение изменений с пользовательскими заголовками и описаниями","Оптимизировать рабочие процессы разработки, интегрируясь с репозиториями GitHub"],"ar":["تلقيم عملية الالتزام والإرسال بمessages معيارية","توليد وإدارة طلبات الدمج مع عناوين وصفحات مخصصة","تحسين سير عمل التطوير من خلال التكامل مع مستودعات GitHub"]},"limitations":{"en":["Requires GitHub CLI installation and configuration","Needs access to Git repository and GitHub authentication","Limited to Git version control system"],"zh":["需要 GitHub CLI 安装和配置","需要访问 Git 仓库和 GitHub 身份验证","仅限 Git 版本控制系统"],"ja":["GitHub CLI のインストールと設定が必要","Git リポジトリと GitHub 認証へのアクセスが必要","Git バージョン管理システムのみに限定"],"ko":["GitHub CLI 설치 및 구성이 필요","Git 리포지토리 및 GitHub 인증에 대한 액세스가 필요","Git 버전 관리 시스템으로 제한"],"es":["Requiere la instalación y configuración de GitHub CLI","Necesita acceso al repositorio de Git y autenticación de GitHub","Limitado al sistema de control de versiones Git"],"fr":["Nécessite l''installation et la configuration de GitHub CLI","Nécessite l''accès au référentiel Git et à l''authentification GitHub","Limité au système de contrôle de version Git"],"de":["Benötigt die Installation und Konfiguration von GitHub CLI","Benötigt den Zugriff auf das Git-Repository und die GitHub-Authentifizierung","Begrenzt auf das Git-Versionssystem"],"pt":["Requer instalação e configuração do GitHub CLI","Necessita acesso ao repositório Git e autenticação GitHub","Limitado ao sistema de controle de versão Git"],"ru":["Требует установки и настройки GitHub CLI","Требует доступа к репозиторию Git и аутентификации GitHub","Ограничен системой контроля версий Git"],"ar":["يتطلب تثبيت وتكوين واجهة سطر أوامر GitHub","يحتاج إلى الوصول إلى مستودع Git وتحقق GitHub","محدود بنظام التحكم في الإصدار Git"]},"v