INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('atlanhq/atlan-sample-apps/atlan-sql-connector-patterns', 'atlan-sql-connector-patterns', 'atlanhq', 'atlan-sample-apps', 'community', 'atlan-sql-connector-patterns atlanhq atlan-sample-apps community The atlan-sql-connector-patterns skill provides a sample application built using Atlan Application SDK, helping developers choose the right connector strategy and implement it consistently. Atlan SQL 连接器模式是样本应用程序，使用 Atlan Application SDK 构建。它提供了选择合适的连接器策略和一致性实现的指导 Atlan SQL コネクタ パターンは、Atlan Application SDK を使用して構築されたサンプル アプリケーションです。コネクタ戦略の選択と一貫性のある実装を提供します Atlan SQL 커넥터 패턴은 Atlan Application SDK를 사용하여 구축된 샘플 애플리케이션입니다. 적절한 커넥터 전략을 선택하고 일관성 있게 구현하는 방법을 제공합니다 Atlan SQL Connector Patterns es una aplicación de ejemplo construida con el SDK de Atlan que ayuda a elegir la estrategia de conector correcta Atlan SQL Connector Patterns est une application exemple construite avec le SDK Atlan qui aide à choisir la stratégie de connecteur appropriée Atlan SQL Connector Patterns ist eine Beispielanwendung, die mit dem Atlan-SDK erstellt wurde und hilft bei der Auswahl der richtigen Connector-Strategie Atlan SQL Connector Patterns é uma aplicação de exemplo construída com o SDK do Atlan para ajudar a escolher a estratégia de conector certa Atlan SQL Connector Patterns - это образец приложения, построенного с помощью SDK Atlan для выбора правильной стратегии соединителя اتلن SQL كونيكتور باتيرنز هو تطبيق مثال مبني على SDK اتلن لمساعدتك في اختيار استراتيجية الموصل الصحيح how to use atlan-sql-connector-patterns atlan-sql-connector-patterns setup guide atlan-sql-connector-patterns alternative atlan-sql-connector-patterns vs redshift-custom atlan-sql-connector-patterns install what is atlan-sql-connector-patterns Atlan SQL 连接器模式 SQL 连接器策略 Atlan Application SDK Postgres 连接器 Redshift 连接器 AIエージェント SQL 工作流 Uses references/decision-tree.md to choose between postgres-minimal and redshift-custom Implements required components for selected connector path Verifies auth, preflight, workflow map, and transformation behavior against references Runs atlan-fact-verification-gate for source-specific behavior or SDK override risk Hands off to atlan-e2e-contract-validator for contract validation atlan-sql-connector-patterns is a sample application that demonstrates how to implement connector patterns using Atlan Application SDK');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pedroct/treit-kit-agentes/deployment-playbook', 'community', 'pedroct', 'treit-kit-agentes', 'pedroct/treit-kit-agentes', 'deployment-playbook', 0, 0, 20, '2026-03-08T01:57:15.329Z', '2026-03-08T02:03:08.831Z', '235a27682fbb9039a8fd540474010eba430b9990cdfaaa4e3c03c31396ae4459', '{"id":"pedroct/treit-kit-agentes/deployment-playbook","name":"deployment-playbook","description":{"en":"The deployment-playbook skill automates deployment workflows for AI agents, validating builds, configurations, and secrets. It benefits developers by simplifying the deployment process.","zh":"部署游戏规则是一种确保AI代理部署和验证的方法，涉及构建、测试和配置验证等步骤","ja":"デプロイメントプレイブックは、AIエージェントのデプロイメントと検証をスムーズに行うための手順を提供するものです","ko":"배포 플레이북은 AI 에이전트의 배포와 검증을 원활하게 수행하는 데 필요한 절차를 제공하는 것입니다","es":"El deployment-playbook es una herramienta para implementar Agentes de IA de manera eficiente, con pasos como confirmar compilaciones y pruebas, validar configuraciones y secretos, y desplegar en entornos de staging o previsualización","fr":"Le deployment-playbook est un outil pour mettre en œuvre les Agents d''IA de manière efficace, avec des étapes telles que confirmer les compilations et les tests, valider les configurations et les secrets, et déployer dans des environnements de staging ou de prévisualisation","de":"Das deployment-playbook ist ein Werkzeug, um KI-Agents effizient zu implementieren, mit Schritten wie Bestätigung von Builds und Tests, Validierung von Konfigurationen und Geheimnissen und Bereitstellung in Staging- oder Vorschauumgebungen","pt":"O deployment playbook é um guia de implantação de agentes de IA que abrange passos como confirmação de build e testes, validação de configuração e segredos, e deploy para staging ou pré-visualização.","ru":"Руководство по развертыванию ИИ Агентов - это руководство по развертыванию ИИ Агентов, которое охватывает шаги, такие как подтверждение сборки и тестирования, проверка конфигурации и секретов, и развертывание в стадии или предварительного просмотра.","ar":"دليل توزيع وكلاء الذكاء الاصطناعي هو كتاب إرشاد لنشر وكلاء الذكاء الاصطناعي يشمل خطوات مثل.confirmation من البناء والاختبارات، وتحقق من التكوين والأسرار، ونشر إلى مرحلة أو معاينة مسبقة."},"seo":{"title":{"en":"Deployment-Playbook: Automated Deployment Setup Guide | A...","zh":"部署游戏规则设置指南","ja":"デプロイメントプレイブック設定ガイド","ko":"배포 플레이북 설정 가이드","es":"Guía de implementación de deployment-playbook para Agente...","fr":"Guide de mise en œuvre de deployment-playbook pour les Ag...","de":"Einrichtungsleitfaden für deployment-playbook bei KI-Agents","pt":"Guia de Implantação de Agente de IA: Deployment Playbook","ru":"Руководство по развертыванию ИИ Агентов: Deployment Playbook","ar":"دليل توزيع وكيل الذكاء الاصطناعي: Deployment Playbook"},"description":{"en":"Streamline your deployment process with the deployment-playbook skill. Learn how to automate build validation, configuration, and rollback steps. Get started...","zh":"了解如何使用部署游戏规则确保AI代理的顺利部署和验证，包括构建、测试和配置验证等步骤","ja":"AIエージェントのデプロイメントをスムーズに行うためのデプロイメントプレイブックの設定方法について学びます","ko":"AI 에이전트의 배포를 원활하게 수행하는 데 필요한 배포 플레이북 설정 방법을 알아보세요","es":"Aprende a implementar deployment-playbook para Agentes de IA de manera efectiva con esta guía paso a paso","fr":"Découvrez comment mettre en œuvre deployment-playbook pour les Agents d''IA avec ce guide étape par étape","de":"Erfahren Sie, wie Sie deployment-playbook für KI-Agents effektiv implementieren können, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a implantar agentes de IA com eficiência usando o deployment playbook. Confira os passos e melhores práticas para uma implantação bem-sucedida.","ru":"Узнайте, как развертывать ИИ Агентов эффективно с помощью deployment playbook. Проверьте шаги и лучшие практики для успешного развертывания.","ar":"تعرف على كيفية توزيع وكلاء الذكاء الاصطناعي بفعالية باستخدام كتاب الإرشاد للتوزيع. راجع الخطوات وأفضل الممارسات لنشر ناجح."},"definition":{"en":"Deployment-playbook is a skill that automates deployment workflows, covering steps from build confirmation to rollback preparation.","zh":"部署游戏规则是AI代理的部署和验证过程中的一个步骤，涉及一系列的检查和验证","ja":"デプロイメントプレイブックとは、AIエージェントのデプロイメントと検証における一連の手順です","ko":"배포 플레이북은 AI 에이전트의 배포와 검증 과정에서の一系列의 절차입니다","es":"El deployment-playbook es un conjunto de pasos para implementar Agentes de IA de manera automatizada y eficiente","fr":"Le deployment-playbook est un ensemble d''étapes pour mettre en œuvre les Agents d''IA de manière automatisée et efficace","de":"Das deployment-playbook ist eine Sammlung von Schritten, um KI-Agents automatisiert und effizient zu implementieren","pt":"O deployment playbook é um conjunto de passos para implantar agentes de IA de forma eficiente e segura.","ru":"Руководство по развертыванию ИИ Агентов - это набор шагов для развертывания ИИ Агентов эффективно и безопасно.","ar":"دليل توزيع وكلاء الذكاء الاصطناعي هو مجموعة من الخطوات لنشر وكلاء الذكاء الاصطناعي بفعالية وأمان."},"features":{"en":["Confirms build and tests for validation","Validates configuration and secrets for secure deployment","Deploys to staging or preview environments when possible","Verifies key flows for smooth operation","Prepares rollback steps for error recovery"],"zh":["构建和测试验证","配置和密钥验证","预发环境或预览环境部署","关键流程验证","回滚步骤准备"],"ja":["ビルドとテストの検証","設定とシークレットの検証","ステージング環境またはプレビュー環境へのデプロイ","重要なフローの検証","ロールバック手順の準備"],"ko":["빌드 및 테스트 확인","설정 및 시크릿 확인","스테이징 환경 또는 미리 보기 환경에 대한 배포","중요한 흐름 확인","롤백 단계 준비"],"es":["Confirmación de compilaciones y pruebas","Validación de configuraciones y secretos","Despliegue en entornos de staging o previsualización","Verificación de flujos clave","Preparación de pasos de reversión"],"fr":["Confirmation des compilations et des tests","Validation des configurations et des secrets","Déploiement dans des environnements de staging ou de prévisualisation","Vérification des flux clés","Préparation des étapes de réversion"],"de":["Bestätigung von Builds und Tests","Validierung von Konfigurationen und Geheimnissen","Bereitstellung in Staging- oder Vorschauumgebungen","Überprüfung von Schlüsselabläufen","Vorbereitung von Rückgängigkeitschritten"],"pt":["Confirmação de build e testes","Validação de configuração e segredos","Deploy para staging ou pré-visualização","Verificação de fluxos principais","Preparação de etapas de rollback"],"ru":["Подтверждение сборки и тестирования","Проверка конфигурации и секретов","Развертывание в стадии или предварительного просмотра","Проверка основных потоков","Подготовка шагов отката"],"ar":["تأكيد البناء والاختبارات","تحقق من التكوين والأسرار","نشر إلى مرحلة أو معاينة مسبقة","تحقق من تدفقات المفتاح","إعداد خطوات الإرجاع"]},"keywords":{"en":["how to use deployment-playbook","deployment-playbook setup guide","automated deployment workflows","deployment-playbook vs manual deployment","what is deployment-playbook","deployment-playbook install","deployment-playbook for AI agents","deployment-playbook best practices","deployment-playbook tutorial"],"zh":["AI代理部署","部署游戏规则","AI工具部署","构建和测试","配置验证","预发环境部署"],"ja":["AIエージェントのデプロイメント","デプロイメントプレイブック","AIツールのデプロイメント","ビルドとテスト","設定の検証","ステージング環境へのデプロイ"],"ko":["AI 에이전트 배포","배포 플레이북","AI 도구 배포","빌드 및 테스트","설정 확인","스테이징 환경에 대한 배포"],"es":["Agentes de IA","deployment-playbook","implementación de Agentes de IA","despliegue automático","pruebas y validación","entornos de staging","previsualización de despliegue"],"fr":["Agents d''IA","deployment-playbook","mise en œuvre des Agents d''IA","déploiement automatisé","tests et validation","environnements de staging","prévisualisation de déploiement"],"de":["KI-Agents","deployment-playbook","Implementierung von KI-Agents","automatisierte Bereitstellung","Tests und Validierung","Staging-Umgebungen","Vorschau der Bereitstellung"],"pt":["deployment playbook","agentes de IA","implantação de agentes de IA","guia de implantação","melhores práticas de implantação","confirmação de build e testes","validação de configuração e segredos"],"ru":["deployment playbook","ИИ Агенты","развертывание ИИ Агентов","руководство по развертыванию","лучшие практики развертывания","подтверждение сборки и тестирования","проверка конфигурации и секретов"],"ar":["كتاب الإرشاد للتوزيع","وكلاء الذكاء الاصطناعي","نشر وكلاء الذكاء الاصطناعي","دليل الإرشاد لنشر","أفضل الممارسات لنشر","تأكيد البناء والاختبارات","تحقق من التكوين والأسرار"]}},"owner":"pedroct","repo":"treit-kit-agentes","repoPath":"pedroct/treit-kit-agentes","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.329Z","topics":[],"category":"community","skillMd":{"name":"deployment-playbook","description":"Safe deployment steps and verification.","bodyPreview":"# Deployment Playbook\n\n## Steps\n1. Confirm build and tests.\n2. Validate configuration and secrets.\n3. Deploy to staging or preview when possible.\n4. Verify key flows.\n5. Prepare rollback steps.","body":"# Deployment Playbook\n\n## Steps\n1. Confirm build and tests.\n2. Validate configuration and secrets.\n3. Deploy to staging or preview when possible.\n4. Verify key flows.\n5. Prepare rollback steps.\n"},"lastSynced":"2026-03-08T02:03:08.831Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring streamlined deployment workflows and validation of builds, configurations, and secrets.","zh":"适用于需要简化部署工作流和验证构建、配置和密钥的DevOps代理的理想选择","ja":"DevOpsエージェントがストリームライン化されたデプロイワークフローとビルド、構成、シークレットの検証を必要とする場合に最適","ko":"구조적 배포 워크플ロー와 빌드, 구성 및 보안을 검증해야 하는 DevOps 에이전트에 적합","es":"Ideal para agentes de DevOps que requieren flujos de trabajo de implementación optimizados y validación de compilaciones, configuraciones y secretos.","fr":"Idéal pour les agents DevOps nécessitant des flux de travail de déploiement rationalisés et une validation des builds, configurations et secrets.","de":"Ideal für DevOps-Agents, die optimierte Bereitstellungs-Workflows und eine Validierung von Builds, Konfigurationen und Geheimnissen erfordern.","pt":"Ideal para agentes DevOps que exigem fluxos de implantação otimizados e validação de compilações, configurações e segredos.","ru":"Идеально подходит для агентов DevOps, требующих упрощенных рабочих процессов развертывания и проверки сборок, конфигураций и секретов.","ar":"مثالي للوكلاء DevOps الذين يتطلبون تدفقات التثبيت المُبسطة والتحقق من البناء والتصريفات والأسرار."},"recommendation":{"en":"Empowers agents to automate deployment workflows, validate configurations and secrets, and verify key flows using protocols like staging or preview deployments, while preparing rollback steps and confirming builds and tests.","zh":"赋予代理自动化部署工作流、验证配置和密钥，并使用诸如预发布或预览部署等协议验证关键流程，同时准备回滚步骤和确认构建和测试","ja":"エージェントにデプロイワークフローの自動化、構成とシークレットの検証、ステージングまたはプレビューのデプロイなどのプロトコルを使用した重要なフローの検証、およびロールバックの準備とビルドおよびテストの確認を可能にします","ko":"에이전트가 배포 워크플로를 자동화하고, 구성 및 보안을 검증하며, 스테이징 또는预览 배포와 같은 프로토콜을 사용하여 주요 프로세스를 검증하고 롤백 단계를 준비하고 빌드 및 테스트를 확인할 수 있도록 합니다","es":"Habilita a los agentes a automatizar los flujos de trabajo de implementación, validar configuraciones y secretos, y verificar flujos clave utilizando protocolos como implementaciones de staging o vista previa, mientras se preparan los pasos de reversión y se confirman las compilaciones y las pruebas.","fr":"Permet aux agents d''automatiser les flux de travail de déploiement, de valider les configurations et les secrets, et de vérifier les flux clés en utilisant des protocoles tels que les déploiements de staging ou d''aperçu, tout en préparant les étapes de réversion et en confirmant les builds et les tests.","de":"Ermöglicht es den Agenten, Bereitstellungs-Workflows zu automatisieren, Konfigurationen und Geheimnisse zu validieren und Schlüssel-Flows unter Verwendung von Protokollen wie Staging- oder Vorschau-Bereitstellungen zu überprüfen, während Rollback-Schritte vorbereitet und Builds und Tests bestätigt werden.","pt":"Habilita os agentes a automatizar fluxos de trabalho de implantação, validar configurações e segredos e verificar fluxos principais de aplicativos usando protocolos como implantações de preparação ou visualização, ao mesmo tempo em que prepara etapas de reversão e confirma compilações e testes.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы развертывания, проверять конфигурации и секреты, а также проверять основные потоки приложений с помощью протоколов, таких как подготовка или предварительные развертывания, а также подготовку шагов откате и подтверждение сборок и тестов.","ar":"يمنح الوكلاء القدرة على توفير تدفقات عمل التثبيت، والتحقق من التصريفات والأسرار، والتحقق من تدفقات التطبيقات الأساسية باستخدام بروتوكولات مثل عمليات النشر بالمراحل أو العرض، مع الاستعداد لخطوات التراجع وتأكيد البناء والاختبارات."},"useCases":{"en":["Automating deployment workflows for AI models","Validating configuration files and secrets for security","Verifying key application flows in staging environments"],"zh":["自动化AI模型的部署工作流","验证配置文件和密钥的安全性","在预发布环境中验证关键应用程序流程"],"ja":["AIモデルへのデプロイワークフローの自動化","セキュリティのための構成ファイルとシークレットの検証","ステージング環境での重要なアプリケーションフローの検証"],"ko":["AI 모델의 배포 워크플로 자동화","보안을 위한 구성 파일 및 보안 키의 검증","스테이징 환경에서 주요 응용 프로그램 흐름의 검증"],"es":["Automatizar flujos de trabajo de implementación para modelos de AI","Validar archivos de configuración y secretos para la seguridad","Verificar flujos clave de la aplicación en entornos de staging"],"fr":["Automatiser les flux de travail de déploiement pour les modèles d''IA","Valider les fichiers de configuration et les secrets pour la sécurité","Vérifier les flux clés de l''application dans les environnements de staging"],"de":["Automatisieren von Bereitstellungs-Workflows für KI-Modelle","Validieren von Konfigurationsdateien und Geheimnissen für die Sicherheit","Überprüfen von Schlüssel-Flows der Anwendung in Staging-Umgebungen"],"pt":["Automatizar fluxos de trabalho de implantação para modelos de IA","Validar arquivos de configuração e segredos para segurança","Verificar fluxos de aplicativos principais em ambientes de preparação"],"ru":["Автоматизация рабочих процессов развертывания для моделей ИИ","Проверка файлов конфигурации и секретов для безопасности","Проверка основных потоков приложений в средах подготовки"],"ar":["توفير تدفقات العمل للتثبيت لطرازات الذكاء الاصطناعي","التحقق من ملفات التهيئة والأسرار لأغراض الأمن","التحقق من تدفقات التطبيقات الأساسية في بيئات الإعداد"]},"limitations":{"en":["Requires access to build and test environments","Limited to staging or preview deployments"],"zh":["需要访问构建和测试环境","仅限于预发布或预览部署"],"ja":["ビルドおよびテスト環境へのアクセスが必要","ステージングまたはプレビューのデプロイのみ"],"ko":["빌드 및 테스트 환경에 대한 액세스가 필요","스테이징 또는预览 배포만"],"es":["Requiere acceso a entornos de compilación y prueba","Limitado a implementaciones de staging o vista previa"],"fr":["Nécessite l''accès aux environnements de build et de test","Limité aux déploiements de staging ou d''aperçu"],"de":["Erfordert den Zugriff auf Build- und Testumgebungen","Begrenzt auf Staging- oder Vorschau-Bereitstellungen"],"pt":["Exige acesso a ambientes de compilação e teste","Limitado a implantações de preparação ou visualização"],"ru":["Требует доступа к средам сборки и тестирования","Ограничен подготовкой или предварительными развертываниями"],"ar":["يتطلب الوصول إلى بيئات البناء والاختبار","محدود بنشرات المراحل أو المعاينة"]},"version":4},"contentHash":"235a27682fbb9039a8fd540474010eba430b9990cdfaaa4e3c03c31396ae4459","qualityScore":20}');
