INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pedroct/treit-kit-agentes/deployment-playbook', 'deployment-playbook', 'pedroct', 'treit-kit-agentes', 'community', 'deployment-playbook pedroct treit-kit-agentes community The deployment-playbook skill automates deployment workflows for AI agents, validating builds, configurations, and secrets. It benefits developers by simplifying the deployment process. 部署游戏规则是一种确保AI代理部署和验证的方法，涉及构建、测试和配置验证等步骤 デプロイメントプレイブックは、AIエージェントのデプロイメントと検証をスムーズに行うための手順を提供するものです 배포 플레이북은 AI 에이전트의 배포와 검증을 원활하게 수행하는 데 필요한 절차를 제공하는 것입니다 El deployment-playbook es una herramienta para implementar Agentes de IA de manera eficiente, con pasos como confirmar compilaciones y pruebas, validar configuraciones y secretos, y desplegar en entornos de staging o previsualización Le deployment-playbook est un outil pour mettre en œuvre les Agents d''IA de manière efficace, avec des étapes telles que confirmer les compilations et les tests, valider les configurations et les secrets, et déployer dans des environnements de staging ou de prévisualisation Das deployment-playbook ist ein Werkzeug, um KI-Agents effizient zu implementieren, mit Schritten wie Bestätigung von Builds und Tests, Validierung von Konfigurationen und Geheimnissen und Bereitstellung in Staging- oder Vorschauumgebungen O deployment playbook é um guia de implantação de agentes de IA que abrange passos como confirmação de build e testes, validação de configuração e segredos, e deploy para staging ou pré-visualização. Руководство по развертыванию ИИ Агентов - это руководство по развертыванию ИИ Агентов, которое охватывает шаги, такие как подтверждение сборки и тестирования, проверка конфигурации и секретов, и развертывание в стадии или предварительного просмотра. دليل توزيع وكلاء الذكاء الاصطناعي هو كتاب إرشاد لنشر وكلاء الذكاء الاصطناعي يشمل خطوات مثل.confirmation من البناء والاختبارات، وتحقق من التكوين والأسرار، ونشر إلى مرحلة أو معاينة مسبقة. how to use deployment-playbook deployment-playbook setup guide automated deployment workflows deployment-playbook vs manual deployment what is deployment-playbook deployment-playbook install deployment-playbook for AI agents deployment-playbook best practices deployment-playbook tutorial AI代理部署 部署游戏规则 AI工具部署 构建和测试 配置验证 预发环境部署 Confirms build and tests for validation Validates configuration and secrets for secure deployment Deploys to staging or preview environments when possible Verifies key flows for smooth operation Prepares rollback steps for error recovery Deployment-playbook is a skill that automates deployment workflows, covering steps from build confirmation to rollback preparation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('diana-uk/senior-interview-mentor/hint', 'community', 'diana-uk', 'senior-interview-mentor', 'diana-uk/senior-interview-mentor', 'hint', 0, 0, 20, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:32.677Z', '8c76a4b93f8a01e1d9e80645d88c0b7acc0d815a9567bdfc9b32bd124a20e1c0', '{"id":"diana-uk/senior-interview-mentor/hint","name":"hint","description":{"en":"Hint is an AI-powered coding interview coaching system that provides targeted hints and feedback to help developers improve their coding skills. It benefits developers who need guidance on specific coding challenges.","zh":"Hint AI 编码面试辅导系统是一个对话式的辅导工具，通过与用户交互提供有针对性的提示","ja":"Hint AI コーディング面接コーチングシステムは、ユーザーとの対話を通じてターゲットを絞ったヒントを提供する対話式のツールです","ko":"Hint AI 코딩 면접 코칭 시스템은 사용자와의 대화를 통해 목표를 명확히 하는 대화형 도구입니다","es":"Hint es un sistema de entrenamiento de codificación asistido por IA que ofrece ayuda conversacional para resolver problemas de programación","fr":"Hint est un système de coaching de codage par IA qui offre une aide conversationnelle pour résoudre des problèmes de programmation","de":"Hint ist ein KI-gestütztes Codetraining-System, das konversationelle Hilfe zur Lösung von Programmierproblemen bietet","pt":"O Hint é um sistema de treinamento de entrevista de codificação que fornece dicas personalizadas para ajudar os desenvolvedores a melhorar suas habilidades de codificação.","ru":"Hint - это система коучинга для кодирования интервью, которая предоставляет персонализированные подсказки, чтобы помочь разработчикам улучшить свои навыки кодирования","ar":"Hint هو نظام تدريب مقابلة تعليم برمجي ي提供 نصائح مخصصة لمساعدة المطورين على تحسين مهاراتهم في البرمجة"},"seo":{"title":{"en":"Hint: AI-Powered Coding Interview Coaching System | AI Ag...","zh":"Hint AI 编码面试辅导系统设置指南","ja":"Hint AI コーディング面接コーチングシステムのベストプラクティス","ko":"Hint AI 코딩 면접 코칭 시스템 구축 가이드","es":"Guía de configuración de Hint - Entrenamiento de codifica...","fr":"Guide de démarrage de Hint - Coaching de codage par IA","de":"Einrichtungsleitfaden für Hint - KI-gestütztes Codetraining","pt":"Guia de Configuração do Hint: Sistema de Treinamento de E...","ru":"Настройка ИИ Агента Hint: Система Коучинга для Кодировани...","ar":"دليل إعداد Hint: نظام تدريب مقابلة تعليم برمجي ذكي"},"description":{"en":"Unlock expert coding interview coaching with Hint. Get personalized feedback and improve your coding skills - try it now!","zh":"Hint AI 编码面试辅导系统提供对话式帮助，了解如何获取有针对性的提示和改善编码技能","ja":"Hint AI コーディング面接コーチングシステムは、対話式のヒントを提供し、コーディングスキルを向上させるのに役立ちます","ko":"Hint AI 코딩 면접 코칭 시스템은 대화형 힌트를 제공하여 코딩 스킬을 향상시킵니다","es":"Aprende a utilizar Hint, un sistema de entrenamiento de codificación asistido por IA, para mejorar tus habilidades de programación","fr":"Découvrez comment utiliser Hint, un système de coaching de codage par IA, pour améliorer vos compétences en programmation","de":"Erfahren Sie, wie Sie Hint, ein KI-gestütztes Codetraining-System, nutzen können, um Ihre Programmierfähigkeiten zu verbessern","pt":"Aprenda a configurar o sistema de treinamento de entrevista de codificação Hint, com dicas e práticas para melhorar suas habilidades de codificação","ru":"Узнайте, как настроить систему коучинга для кодирования интервью Hint, с советами и лучшими практиками для улучшения ваших навыков кодирования","ar":"تعرف على كيفية إعداد نظام تدريب مقابلة تعليم برمجي Hint، مع نصائح وأفضل الممارسات لتحسين مهاراتك في البرمجة"},"definition":{"en":"Hint is an AI-powered conversational help system that provides coding interview coaching and feedback to developers.","zh":"Hint AI 编码面试辅导系统是一种提供对话式帮助的 AI 工具","ja":"Hint AI コーディング面接コーチングシステムは、対話式のヒントを提供する AI エージェントの一種です","ko":"Hint AI 코딩 면접 코칭 시스템은 대화형 힌트를 제공하는 AI 도구입니다","es":"Hint es un agente de IA que proporciona ayuda conversacional para entrenamiento de codificación","fr":"Hint est un agent IA qui offre une aide conversationnelle pour le coaching de codage","de":"Hint ist ein KI-Agent, der konversationelle Hilfe für Codetraining bietet","pt":"O que é Hint? Um sistema de treinamento de entrevista de codificação que fornece dicas personalizadas para desenvolvedores","ru":"Что такое Hint? Система коучинга для кодирования интервью, которая предоставляет персонализированные подсказки для разработчиков","ar":"ما هو Hint؟ نظام تدريب مقابلة تعليم برمجي ي提供 نصائح مخصصة للمطورين"},"features":{"en":["Provides level-based hints (1, 2, or 3) for coding challenges","Engages in brief exchanges to understand user''s stuck points","Asks clarifying questions to provide targeted hints","Considers user''s gut feeling about the problem","Offers a quick check-in to ensure effective hint provision"],"zh":["提供有针对性的提示","对话式的交互","快速检查用户的进度","了解用户的困难点","提供改善编码技能的建议"],"ja":["ターゲットを絞ったヒントを提供","対話式のインタラクション","ユーザーの進度を迅速に確認","ユーザーの困難点を理解","コーディングスキルを向上させる提案を提供"],"ko":["목표를 명확히 하는 힌트 제공","대화형의 상호작용","사용자의 진행 상황을 빠르게 확인","사용자의 어려움을 이해","코딩 스킬을 향상시키는 제안을 제공"],"es":["Niveles de ayuda personalizados (1, 2 o 3)","Interacción conversacional para resolver problemas de programación","Análisis de intentos y sentimientos para ofrecer ayuda más precisa","Compatibilidad con problemas de programación de diferentes niveles de dificultad"],"fr":["Niveaux d''aide personnalisés (1, 2 ou 3)","Interaction conversationnelle pour résoudre des problèmes de programmation","Analyse des tentatives et des sentiments pour offrir une aide plus précise","Compatibilité avec des problèmes de programmation de différentes difficultés"],"de":["Benutzerdefinierte Hilfeeinstufungen (1, 2 oder 3)","Konversationelle Interaktion zur Lösung von Programmierproblemen","Analyse von Versuchen und Gefühlen, um präzisere Hilfe zu bieten","Kompatibilität mit Programmierproblemen unterschiedlicher Schwierigkeitsgrade"],"pt":["Fornece dicas personalizadas com base no nível de dificuldade (1, 2 ou 3)","Permite uma troca rápida de informações antes de fornecer a dica","Inclui verificações rápidas para garantir que a dica seja mais direcionada","Pode ser usado para melhorar habilidades de codificação em várias linguagens de programação","Oferece uma abordagem de mentor para ajudar os desenvolvedores a superar obstáculos","Fornece uma oportunidade para que os desenvolvedores compartilhem suas impressões e ideias sobre o problema"],"ru":["Предоставляет персонализированные подсказки на основе уровня сложности (1, 2 или 3)","Позволяет быстро обмениваться информацией перед предоставлением подсказки","Включает быстрые проверки, чтобы убедиться, что подсказка более нацелена","Может быть использован для улучшения навыков кодирования на различных языках программирования","Предлагает подход наставника, чтобы помочь разработчикам преодолеть препятствия","Предоставляет возможность разработчикам поделиться своими впечатлениями и идеями о проблеме"],"ar":["يقدم نصائح مخصصة بناءً على مستوى الصعوبة (1، 2 أو 3)","يسمح بتبادل سريع للمعلومات قبل تقديم النصيحة","يشمل فحوصات سريعة لضمان أن تكون النصيحة أكثر تركيزًا","يمكن استخدامها لتحسين مهارات البرمجة في لغات برمجة متعددة","يقدم نهجًا لتدريب المطورين لمساعدتهم على التغلب على العقبات","يقدم فرصة للمطورين لمشاركة انطباعاتهم وأفكارهم حول المشكلة"]},"keywords":{"en":["how to use hint for coding interviews","hint alternative for coding coaching","what is hint in coding","hint setup guide for developers","hint vs coding interview platforms","hint install for AI-powered coaching"],"zh":["AI 编码面试辅导","对话式帮助","编码面试辅导系统","AI 工具","编码技能改善","面试辅导"],"ja":["AI コーディング面接コーチング","対話式のヒント","コーディング面接コーチングシステム","AI エージェント","コーディングスキル向上","面接コーチング"],"ko":["AI 코딩 면접 코칭","대화형 힌트","코딩 면접 코칭 시스템","AI 도구","코딩 스킬 향상","면접 코칭"],"es":["entrenamiento de codificación asistido por IA","agente de IA para programación","herramientas de codificación","coaching de codage","resolución de problemas de programación","desarrollo de software","programación de computadoras"],"fr":["coaching de codage par IA","agent IA pour la programmation","outils de codage","formation de codage","résolution de problèmes de programmation","développement de logiciels","programmation informatique"],"de":["KI-gestütztes Codetraining","KI-Agent für Programmierung","Codierungstools","Codetraining","Lösung von Programmierproblemen","Softwareentwicklung","Computerprogrammierung"],"pt":["hint","sistema de treinamento de entrevista de codificação","dicas personalizadas","nível de dificuldade","linguagens de programação","desenvolvedores","entrevista de codificação","treinamento de codificação","melhoria de habilidades de codificação"],"ru":["hint","система коучинга для кодирования интервью","персонализированные подсказки","уровень сложности","языки программирования","разработчики","интервью по кодированию","тренинг по кодированию","улучшение навыков кодирования"],"ar":["hint","نظام تدريب مقابلة تعليم برمجي","نصائح مخصصة","مستوى الصعوبة","لغات برمجة","مطورون","مقابلة تعليم برمجي","تدريب تعليم برمجي","تحسين مهارات البرمجة"]}},"owner":"diana-uk","repo":"senior-interview-mentor","repoPath":"diana-uk/senior-interview-mentor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.344Z","topics":[],"category":"community","skillMd":{"name":"hint","description":"Get a progressive hint for the current problem. Use when user is stuck and asks for help.","bodyPreview":"# Hint - Conversational Help\n\nThe user is asking for a hint. Level requested: $ARGUMENTS (1, 2, or 3)\n\n## Your Approach\nYou''re a mentor helping someone who''s stuck. Don''t just dump a hint - have a brief exchange first.\n\n## Before Giving the Hint\n\nStart with a quick check-in:\n- \"Alright, before I give you a hint - tell me quickly, where exactly are you stuck?\"\n- \"What have you tried so far?\"\n- \"What''s your gut feeling about this problem?\"\n\nThis helps you:\n1. Give a more targeted hint\n2. Make sure","body":"# Hint - Conversational Help\n\nThe user is asking for a hint. Level requested: $ARGUMENTS (1, 2, or 3)\n\n## Your Approach\nYou''re a mentor helping someone who''s stuck. Don''t just dump a hint - have a brief exchange first.\n\n## Before Giving the Hint\n\nStart with a quick check-in:\n- \"Alright, before I give you a hint - tell me quickly, where exactly are you stuck?\"\n- \"What have you tried so far?\"\n- \"What''s your gut feeling about this problem?\"\n\nThis helps you:\n1. Give a more targeted hint\n2. Make sure they''ve actually attempted something\n3. Sometimes they''ll figure it out just by explaining\n\n## Giving the Hint\n\n### Level 1 - Nudge (Light Touch)\nJust a small push. Don''t reveal structure.\n- \"Think about this: what operation do you need to do repeatedly? And what data structure makes that operation fast?\"\n- \"The key insight here is about [pattern]. What do you know about that pattern?\"\n- \"If you had to solve this by hand, what would you keep track of?\"\n\nThen ask: \"Does that help point you in a direction?\"\n\n### Level 2 - Structure (More Concrete)\nNow give them the shape of the solution.\n- \"Okay, here''s more structure. You''ll want to use a [data structure]. The basic flow is: [3-4 steps in plain English]. Make sense?\"\n- Don''t give code. Give the roadmap.\n\nThen ask: \"Can you see how to translate that into code?\"\n\n### Level 3 - Pseudocode (Almost There)\nWalk through the logic together.\n- \"Let me walk through the pseudocode with you. We start by... then we iterate... for each element we... and finally we...\"\n- Still don''t write the actual code for them.\n\nThen say: \"That''s the logic. Now you need to turn it into TypeScript. Give it a shot.\"\n\n## After the Hint\n- Don''t just leave them. Ask: \"Does that make sense? Any part unclear?\"\n- If they''re still stuck, ask what specifically is confusing\n- Encourage them to try before asking for more help\n\n## Tone\n- Supportive, not condescending\n- Brief, not lecture-y\n- \"Let''s figure this out together\" energy\n\n## Note on Scoring\nEach hint level costs points:\n- Level 1: -0.25\n- Level 2: -0.5\n- Level 3: -1.0\n\nDon''t mention this unless they ask about scoring.\n"},"lastSynced":"2026-03-08T02:03:32.677Z","agentAnalysis":{"suitability":{"en":"Ideal for Conversational AI Agents requiring targeted feedback and guidance capabilities.","zh":"适用于需要有针对性反馈和指导能力的对话式 AI 代理。","ja":"対話式 AI エージェントがターゲットを絞ったフィードバックとガイダンス機能を必要とする場合に最適です。","ko":"대화형 AI 에이전트가 타겟을 좁힌 피드백 및 가이드 기능을 필요로 할 경우 적합합니다.","es":"Ideal para agentes de IA Conversacional que requieren capacidades de retroalimentación y orientación dirigidas.","fr":"Idéal pour les agents d''IA Conversationnels nécessitant des capacités de rétroaction et d''orientation ciblées.","de":"Ideal für Conversational AI-Agents, die gezielte Feedback- und Leitfunktionen erfordern.","pt":"Ideal para Agentes de IA Conversacional que exigem feedback e capacidades de orientação direcionados.","ru":"Идеально для конверсационных агентов ИИ, требующих целевого обратной связи и возможностей руководства.","ar":"مثالية للوكلاء الذكية بالمحادثة التي تتطلب ملاحظات و إمكانيات توجيه موجهة."},"recommendation":{"en":"Empowers agents to provide personalized coding hints and feedback using conversational exchanges, incorporating quick check-ins and gut feeling assessments to offer more targeted guidance, leveraging protocols like conversational help.","zh":"赋予代理提供个性化编码提示和反馈的能力，使用对话式交换，结合快速检查和直觉评估以提供更有针对性的指导，利用诸如对话式帮助的协议。","ja":"エージェントが会話型のやり取りを使用して、パーソナライズされたコードのヒントやフィードバックを提供できるようにすることで、会話型のヘルプなどのプロトコルを利用して、より的を絞ったガイダンスを提供します。","ko":"에이전트가 대화형 교환을 사용하여 개인화된 코드 힌트 및 피드백을 제공할 수 있게 함으로써, 대화형 도움말과 같은 프로토콜을 활용하여 더 타겟을 좁힌 가이드를 제공합니다.","es":"Habilita a los agentes para proporcionar pistas de codificación personalizadas y retroalimentación utilizando intercambios conversacionales, incorporando controles rápidos y evaluaciones de instinto para ofrecer una orientación más dirigida, aprovechando protocolos como la ayuda conversacional.","fr":"Permet aux agents de fournir des conseils de codage personnalisés et des rétroactions en utilisant des échanges conversationnels, en intégrant des contrôles rapides et des évaluations d''instinct pour offrir des conseils plus ciblés, en exploitant des protocoles tels que l''aide conversationnelle.","de":"Ermächtigt Agenten, personalisierte Codierhinweise und Feedback mithilfe konversationeller Austausche bereitzustellen, indem es schnelle Überprüfungen und Bauchgefühlbewertungen einbezieht, um gezieltere Anleitung zu bieten, Protokolle wie konversationelle Hilfe nutzend.","pt":"Habilita os agentes a fornecer dicas de codificação personalizadas e feedback usando trocas conversacionais, incorporando verificações rápidas e avaliações de sensação para oferecer orientação mais direcionada, aproveitando protocolos como ajuda conversacional.","ru":"Наделяет агентов возможностью предоставлять персонализированные подсказки кодирования и обратную связь с помощью разговорных обменов, включая быстрые проверки и оценки интуиции, чтобы предложить более целевое руководство, используя протоколы, такие как разговорная помощь.","ar":"تمكين الوكلاء من تقديم تلميحات برمجة مخصصة و ملاحظات باستخدام تبادلات محادثات، و ذلك عن طريق إدراج فحص سريع و تقييمات الشعور لتقديم إرشادات أكثر موجهة، و استخدام بروتوكولات مثل المساعدة بالمحادثة."},"useCases":{"en":["Providing targeted coding hints","Offering feedback on coding challenges","Engaging in brief exchanges to understand user needs"],"zh":["提供有针对性的编码提示","提供编码挑战的反馈","进行简短的交换以了解用户需求"],"ja":["的を絞ったコードのヒントを提供する","コードの課題についてのフィードバックを提供する","ユーザーのニーズを理解するための簡単なやり取りを行う"],"ko":["타겟을 좁힌 코드 힌트 제공","코드 챌린지에 대한 피드백 제공","사용자需求을 이해하기 위한简短 교환"],"es":["Proporcionar pistas de codificación dirigidas","Ofrecer retroalimentación sobre desafíos de codificación","Participar en intercambios breves para comprender las necesidades del usuario"],"fr":["Fournir des conseils de codage ciblés","Offrir des rétroactions sur les défis de codage","S''engager dans des échanges brefs pour comprendre les besoins de l''utilisateur"],"de":["Gezielte Codierhinweise bereitstellen","Feedback zu Codierherausforderungen anbieten","An kurzen Austauschen teilnehmen, um die Bedürfnisse des Benutzers zu verstehen"],"pt":["Fornecendo dicas de codificação direcionadas","Oferecendo feedback em desafios de codificação","Engajando-se em trocas breves para entender as necessidades do usuário"],"ru":["Предоставление целевых подсказок кодирования","Предложение обратной связи по задачам кодирования","Занятие краткими обменами для понимания потребностей пользователя"],"ar":["تقديم تلميحات برمجة موجهة","تقديم ملاحظات على تحديات البرمجة","المشاركة في تبادلات قصيرة لفهم احتياجات المستخدم"]},"limitations":{"en":["Requires user input and engagement","Limited to coding challenges and interview practice"],"zh":["需要用户输入和参与","仅限于编码挑战和面试练习"],"ja":["ユーザーの入力と関与が必要","コードの課題や面接練習に限定される"],"ko":["사용자 입력 및 참여가 필요","코드 챌린지 및 면접 연습에만 한정"],"es":["Requiere entrada y participación del usuario","Limitado a desafíos de codificación y práctica de entrevistas"],"fr":["Nécessite une entrée et une participation de l''utilisateur","Limité aux défis de codage et à la pratique d''entretien"],"de":["Benutzerinput und -beteiligung erfordern","Begrenzt auf Codierherausforderungen und Bewerbungspraxis"],"pt":["Exige entrada e engajamento do usuário","Limitado a desafios de codificação e prática de entrevista"],"ru":["Требует ввода и участия пользователя","Ограничен задачами кодирования и практикой интервью"],"ar":["يتطلب إدخال و مشاركة المستخدم","محدود بالتحديات البرمجية و ممارسة المقابلة"]},"version":4},"contentHash":"8c76a4b93f8a01e1d9e80645d88c0b7acc0d815a9567bdfc9b32bd124a20e1c0","qualityScore":20}');
