INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('uhyo/funstack-static/create-pr', 'create-pr', 'uhyo', 'funstack-static', 'community', 'create-pr uhyo funstack-static community The create-pr skill automates GitHub pull requests for developers, creating a new branch, committing changes, and pushing to the remote repository. It benefits developers working with React frameworks and GitHub repositories. Create-PR 是一个用于创建 GitHub 仓库合并请求的工具，通过自动化工作流程提高开发效率 Create-PR は GitHub リポジトリのプルリクエストを作成するためのツールであり、ワークフローを自動化して開発効率を向上させます Create-PR는 GitHub 저장소의 풀 리퀘스트를 생성하는 도구로, 자동화된 워크플로우를 통해 개발 효율성을 높입니다 Create-pr es una habilidad de agente de inteligencia artificial que permite a los desarrolladores crear solicitudes de extracción en GitHub de manera automática Create-pr est un outil d''agent d''intelligence artificielle qui permet aux développeurs de créer des demandes d''extraction sur GitHub de manière automatisée Create-pr ist ein KI-Tool, das es Entwicklern ermöglicht, Pull-Requests auf GitHub automatisch zu erstellen O Create-PR é uma ferramenta que permite criar solicitações de pull request no GitHub, simplificando o processo de contribuição para projetos open source Create-PR - это инструмент, который позволяет создавать запросы на слияние в GitHub, упрощая процесс внесения изменений в проекты с открытым исходным кодом Create-PR هو أداة تمكن من إنشاء طلبات سحب في GitHub، لتسهيل عملية المساهمة في المشاريع مفتوحة المصدر how to use create-pr create-pr setup guide create-pr vs GitHub CLI create-pr install what is create-pr create-pr alternative automating pull requests with create-pr create-pr for React developers GitHub pull request automation Create-PR GitHub 合并请求 自动化工作流程 React 框架 gh CLI AI 工具 开发效率 GitHub 仓库管理 Creates a new branch for changes using Git Commits changes to the new branch Pushes the branch to the remote GitHub repository Uses the gh CLI to create a pull request Specifies the target branch as master by default Provides the URL to the created pull request create-pr is a skill that automates the process of creating a pull request on a GitHub repository using the gh CLI, supporting React framework development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('u9401066/med-paper-assistant/roadmap-updater', 'community', 'u9401066', 'med-paper-assistant', 'u9401066/med-paper-assistant', 'roadmap-updater', 0, 0, 20, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:07.360Z', '643cdb2e326d7294b1044c96841f49cc8862b5be001692e9c6eb8c9f4c5f75a6', '{"id":"u9401066/med-paper-assistant/roadmap-updater","name":"roadmap-updater","description":{"en":"The roadmap-updater skill automates roadmap updates by analyzing commit messages and user input, benefiting developers and project managers. It utilizes tools like read_file and replace_string_in_file to update ROADMAP.md files.","zh":"ROADMAP 更新技能是一种自动化更新 ROADMAP 的工具，通过 read_file 和 replace_string_in_file 实现版本控制","ja":"ロードマップ更新ツールは、ロードマップを自動化して更新するツールで、read_file と replace_string_in_file を使用してバージョン管理を行います","ko":"로드맵 업데이트 스킬은 ROADMAP를 자동으로 업데이트하는 도구로 read_file와 replace_string_in_file를 사용하여 버전 관리를 수행합니다","es":"roadmap-updater es una habilidad que actualiza automáticamente las hojas de ruta mediante la lectura y reemplazo de texto en archivos","fr":"roadmap-updater est une compétence qui met à jour automatiquement les feuilles de route en lisant et en remplaçant du texte dans des fichiers","de":"roadmap-updater ist eine Fähigkeit, die Roadmaps automatisch aktualisiert, indem sie Text in Dateien liest und ersetzt","pt":"O roadmap-updater é uma ferramenta que atualiza automaticamente o seu roadmap com base nas alterações no commit message ou descrição do usuário","ru":"roadmap-updater - это инструмент, который автоматически обновляет вашу дорожную карту на основе изменений в сообщении коммита или описании пользователя с помощью ИИ Агентов","ar":"roadmap-updater هو أداة تحديث خارطة الطريق تلقائيًا بناءً على التغييرات في رسالة Commit أو وصف المستخدم باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"roadmap-updater: Automated Roadmap Management for AI Agen...","zh":"ROADMAP 更新技能设置指南","ja":"ロードマップ更新ツールのベストプラクティス - AIエージェント","ko":"로드맵 업데이트 스킬 구현 가이드","es":"Configuración de roadmap-updater: Guía de actualización d...","fr":"Mise en place de roadmap-updater: Guide de mise à jour de...","de":"Einrichtung von roadmap-updater: Anleitung zur Aktualisie...","pt":"Guia de Configuração do roadmap-updater: Atualize Seu Roa...","ru":"Настройка roadmap-updater: Руководство по Обновлению ИИ А...","ar":"دليل إعداد roadmap-updater: تحديث خارطة الطريق بفعالية با..."},"description":{"en":"Discover how to automate roadmap updates with roadmap-updater. Learn how to integrate it with git-precommit and optimize your workflow today!","zh":"了解 ROADMAP 更新技能的工作流和技术细节，实现自动化更新和版本控制","ja":"ロードマップ更新ツールの仕組みと技術的詳細を紹介します。AIエージェントを使用して自動化を実現しましょう","ko":"로드맵 업데이트 스킬의 작동 원리와 기술적 세부 사항을 알아보고 자동화된 버전 관리를 구현하세요","es":"Aprende a configurar roadmap-updater para automatizar la actualización de tus hojas de ruta con herramientas como read_file y replace_string_in_file","fr":"Découvrez comment mettre en place roadmap-updater pour automatiser la mise à jour de vos feuilles de route avec des outils comme read_file et replace_string_...","de":"Erfahren Sie, wie Sie roadmap-updater einrichten, um Ihre Roadmaps mit Tools wie read_file und replace_string_in_file zu aktualisieren","pt":"Aprenda a configurar o roadmap-updater para automatizar a atualização do seu roadmap e melhorar a produtividade do seu time de desenvolvimento","ru":"Узнайте, как настроить roadmap-updater для автоматизации обновления вашей дорожной карты и повышения производительности вашей команды разработчиков с помощью...","ar":"تعلم كيفية إعداد roadmap-updater لتحديث خارطة الطريق تلقائيًا ورفعประสطة فريق تطويرك باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"roadmap-updater is a skill that automates the process of updating roadmaps by triggering updates, completing milestones, and integrating with git-precommit.","zh":"ROADMAP 更新技能是一种自动化工具，用于更新 ROADMAP 状态和版本","ja":"ロードマップ更新ツールは、ロードマップの状態とバージョンを自動化して更新するツールです","ko":"로드맵 업데이트 스킬은 ROADMAP 상태와 버전을 자동으로 업데이트하는 도구입니다","es":"roadmap-updater es una herramienta de inteligencia artificial que actualiza hojas de ruta","fr":"roadmap-updater est un outil d''intelligence artificielle qui met à jour des feuilles de route","de":"roadmap-updater ist ein künstliches Intelligenz-Tool, das Roadmaps aktualisiert","pt":"O roadmap-updater é uma ferramenta de automação que atualiza o status de itens no roadmap de acordo com as alterações no código","ru":"roadmap-updater - это инструмент автоматизации, который обновляет статус элементов в дорожной карте в соответствии с изменениями в коде с помощью ИИ Агентов","ar":"roadmap-updater هو أداة أتمتة تحديث حالة العناصر في خارطة الطريق وفقًا للتغييرات في الكود باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Reads ROADMAP.md files using the read_file function","Analyzes commit messages and user input to determine completed items","Utilizes replace_string_in_file to update roadmap status from - [ ] to - [x] ","Supports automatic triggering via git-precommit","Updates roadmap status with completion dates in the format YYYY-MM-DD"],"zh":["使用 read_file 函数读取 ROADMAP.md 文件","通过 grep_search 分析 commit message 和用户说明","使用 replace_string_in_file 函数更新 ROADMAP 状态","支持版本控制和自动化更新","集成 git-precommit 工具实现自动化调用","使用状态标记（- [ ]、- [x]、✅）表示项目进度"],"ja":["read_file 関数を使用して ROADMAP.md ファイルを読み取ります","grep_search を使用してコミットメッセージとユーザー説明を分析します","replace_string_in_file 関数を使用してロードマップ状態を更新します","バージョン管理と自動化更新をサポートします","git-precommit ツールを統合して自動化呼び出しを実現します","状態マーク（- [ ]、- [x]、✅）を使用してプロジェクトの進度を表示します"],"ko":["read_file 함수를 사용하여 ROADMAP.md 파일을 읽습니다","grep_search를 사용하여 커밋 메시지와 사용자 설명을 분석합니다","replace_string_in_file 함수를 사용하여 로드맵 상태를 업데이트합니다","버전 관리와 자동 업데이트를 지원합니다","git-precommit 도구를 통합하여 자동 호출을 구현합니다","상태 표시기（- [ ]、- [x]、✅）를 사용하여 프로젝트 진행 상황을 표시합니다"],"es":["Lectura de archivos con read_file","Reemplazo de texto en archivos con replace_string_in_file","Búsqueda de texto con grep_search","Actualización de estado de proyectos con 📋, 🚧 y ✅","Compatibilidad con git-precommit para actualizaciones automáticas"],"fr":["Lecture de fichiers avec read_file","Remplacement de texte dans des fichiers avec replace_string_in_file","Recherche de texte avec grep_search","Mise à jour de l''état de projets avec 📋, 🚧 et ✅","Compatibilité avec git-precommit pour des mises à jour automatiques"],"de":["Dateilektüre mit read_file","Textersatz in Dateien mit replace_string_in_file","Textsuche mit grep_search","Aktualisierung des Projektstatus mit 📋, 🚧 und ✅","Kompatibilität mit git-precommit für automatische Aktualisierungen"],"pt":["Leitura de arquivos com `read_file(ROADMAP.md)`","Análise de commit message e descrição do usuário","Atualização de status de itens com `replace_string_in_file`","Suporte a marcação de status com 📋, 🚧 e ✅","Integração com git-precommit para atualização automática"],"ru":["Чтение файлов с помощью `read_file(ROADMAP.md)`","Анализ сообщения коммита и описания пользователя","Обновление статуса элементов с помощью `replace_string_in_file`","Поддержка маркировки статуса с 📋, 🚧 и ✅","Интеграция с git-precommit для автоматического обновления с помощью ИИ Агентов"],"ar":["قراءة الملفات باستخدام `read_file(ROADMAP.md)`","تحليل رسالة Commit ووصف المستخدم","تحديث حالة العناصر باستخدام `replace_string_in_file`","دعم الترميز بحالة مع 📋, 🚧 و ✅","التكامل مع git-precommit لتحديث تلقائي باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use roadmap-updater","roadmap-updater setup guide","automated roadmap management","roadmap-updater vs manual updates","roadmap-updater install","git-precommit integration with roadmap-updater","roadmap-updater alternative","what is roadmap-updater","roadmap-updater tutorial"],"zh":["ROADMAP 更新技能","自动化更新","版本控制","read_file","replace_string_in_file","git-precommit","AI 工具","开发者工具"],"ja":["ロードマップ更新ツール","自動化更新","バージョン管理","read_file","replace_string_in_file","git-precommit","AIエージェント","開発者ツール"],"ko":["로드맵 업데이트 스킬","자동 업데이트","버전 관리","read_file","replace_string_in_file","git-precommit","AI 도구","개발자 도구"],"es":["roadmap-updater","herramientas de inteligencia artificial","actualización de hojas de ruta","read_file","replace_string_in_file","git-precommit","automatización de tareas"],"fr":["roadmap-updater","outils d''intelligence artificielle","mise à jour de feuille de route","read_file","replace_string_in_file","git-precommit","automatisation de tâches"],"de":["roadmap-updater","künstliche Intelligenz-Tools","Aktualisierung von Roadmaps","read_file","replace_string_in_file","git-precommit","Automatisierung von Aufgaben"],"pt":["roadmap-updater","automatizar roadmap","ferramenta de automação","commit message","descrição do usuário","git-precommit","CLI","Python","React"],"ru":["roadmap-updater","автоматизация дорожной карты","инструмент автоматизации","сообщение коммита","описание пользователя","git-precommit","CLI","Python","React","ИИ Агенты"],"ar":["roadmap-updater","أتمتة خارطة الطريق","أداة أتمتة","رسالة Commit","وصف المستخدم","git-precommit","CLI","Python","React","أدوات الذكاء الاصطناعي"]}},"owner":"u9401066","repo":"med-paper-assistant","repoPath":"u9401066/med-paper-assistant","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"roadmap-updater","description":"更新 ROADMAP.md 狀態。觸發：roadmap、路線、規劃、里程碑。","bodyPreview":"# ROADMAP 更新技能\n\n觸發：更新 roadmap、完成里程碑、被 git-precommit 自動調用\n\n工具：`read_file(\"ROADMAP.md\")`、`replace_string_in_file`、`grep_search`\n\n---\n\n## 狀態標記\n\n📋 計劃中 → 🚧 進行中 → ✅ 已完成\n\n格式：`- [ ] 項目` → `- [x] 項目 ✅ (YYYY-MM-DD)`\n\n## 工作流\n\n1. `read_file(\"ROADMAP.md\")`\n2. 從 commit message / 用戶說明分析完成項目\n3. `replace_string_in_file` 更新 `- [ ]` → `- [x] ✅ (date)`","body":"# ROADMAP 更新技能\n\n觸發：更新 roadmap、完成里程碑、被 git-precommit 自動調用\n\n工具：`read_file(\"ROADMAP.md\")`、`replace_string_in_file`、`grep_search`\n\n---\n\n## 狀態標記\n\n📋 計劃中 → 🚧 進行中 → ✅ 已完成\n\n格式：`- [ ] 項目` → `- [x] 項目 ✅ (YYYY-MM-DD)`\n\n## 工作流\n\n1. `read_file(\"ROADMAP.md\")`\n2. 從 commit message / 用戶說明分析完成項目\n3. `replace_string_in_file` 更新 `- [ ]` → `- [x] ✅ (date)`\n"},"lastSynced":"2026-03-08T02:04:07.360Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated roadmap management and version control integration.","zh":"适合需要自动化路线图管理和版本控制集成的开发代理。","ja":"開発エージェントが自動化されたロードマップ管理とバージョン管理の統合を必要とする場合に最適です。","ko":"자동화된 로드맵 관리 및 버전 관리 통합이 필요한 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de hoja de ruta automatizada y una integración de control de versiones.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de feuille de route automatisée et d''une intégration de contrôle de version.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Roadmap-Verwaltung und eine Versionskontroll-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de roadmap automatizado e integração de controle de versão.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированное управление дорожной картой и интеграция с системой контроля версий.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى إدارة مسار التطوير الآلي وتكامل إدارة الإصدارات."},"recommendation":{"en":"Empowers agents to automate roadmap updates by analyzing commit messages and user input, utilizing tools like read_file and replace_string_in_file to update ROADMAP.md files, and leveraging grep_search for efficient text processing.","zh":"通过分析提交消息和用户输入来赋予代理自动更新路线图的能力，利用诸如 read_file 和 replace_string_in_file 等工具来更新 ROADMAP.md 文件，并利用 grep_search 进行高效的文本处理。","ja":"コミットメッセージとユーザー入力を分析することで、ROADMAP.md ファイルを更新するための read_file や replace_string_in_file などのツールを利用し、grep_search を使用して効率的なテキスト処理を行うことで、エージェントがロードマップを自動更新できるようにします。","ko":"提交 메시지와 사용자 입력을 분석하여 에이전트가 로드맵을 자동으로 업데이트할 수 있도록 하며, read_file 및 replace_string_in_file와 같은 도구를 사용하여 ROADMAP.md 파일을 업데이트하고, grep_search를 사용하여 효율적인 텍스트 처리를 수행합니다.","es":"Habilita a los agentes a automatizar las actualizaciones de la hoja de ruta analizando mensajes de confirmación y entrada de usuario, utilizando herramientas como read_file y replace_string_in_file para actualizar archivos ROADMAP.md, y aprovechando grep_search para un procesamiento de texto eficiente.","fr":"Permet aux agents d''automatiser les mises à jour de la feuille de route en analysant les messages de validation et les entrées utilisateur, en utilisant des outils tels que read_file et replace_string_in_file pour mettre à jour les fichiers ROADMAP.md, et en exploitant grep_search pour un traitement de texte efficace.","de":"Ermöglicht es den Agenten, die Aktualisierungen der Roadmap zu automatisieren, indem sie Commit-Nachrichten und Benutzereingaben analysieren, Werkzeuge wie read_file und replace_string_in_file verwenden, um ROADMAP.md-Dateien zu aktualisieren, und grep_search für eine effiziente Textverarbeitung nutzen.","pt":"Habilita os agentes a automatizar atualizações de roadmap analisando mensagens de commit e entrada do usuário, utilizando ferramentas como read_file e replace_string_in_file para atualizar arquivos ROADMAP.md, e aproveitando grep_search para processamento de texto eficiente.","ru":"Позволяет агентам автоматизировать обновления дорожной карты, анализируя сообщения о коммитах и ввод пользователя, используя инструменты seperti read_file и replace_string_in_file для обновления файлов ROADMAP.md, и используя grep_search для эффективной обработки текста.","ar":"تمكّن الوكلاء من توفير تحديثات المسار التطويري آليًا من خلال تحليل رسائل الالتزام ومدخلات المستخدم، واستخدام أدوات مثل read_file و replace_string_in_file لتحديث ملفات ROADMAP.md، وتفعيل grep_search من أجل معالجة نصية فعالة."},"useCases":{"en":["Automating roadmap updates based on commit messages and user input","Updating ROADMAP.md files with completed milestones and corresponding dates","Streamlining project management workflows by integrating with git-precommit hooks"],"zh":["基于提交消息和用户输入的自动化路线图更新","使用完成的里程碑和对应的日期更新 ROADMAP.md 文件","通过与 git-precommit hooks 集成来简化项目管理工作流"],"ja":["コミットメッセージとユーザー入力を基にしたロードマップの自動更新","完了したマイルストーンと対応する日付を使用して ROADMAP.md ファイルを更新する","git-precommit hooks と統合することでプロジェクト管理ワークフローを合理化する"],"ko":["提交 메시지와 사용자 입력 기반의 자동화된 로드맵 업데이트","완료된 마일스톤 및 해당 날짜를 사용하여 ROADMAP.md 파일을 업데이트하는","git-precommit hooks와 통합하여 프로젝트 관리 워크플ロー简化"],"es":["Automatizar las actualizaciones de la hoja de ruta en función de los mensajes de confirmación y la entrada de usuario","Actualizar archivos ROADMAP.md con hitos completados y fechas correspondientes","Optimizar flujos de trabajo de gestión de proyectos integrándolos con ganchos git-precommit"],"fr":["Automatiser les mises à jour de la feuille de route en fonction des messages de validation et des entrées utilisateur","Mettre à jour les fichiers ROADMAP.md avec les jalons terminés et les dates correspondantes","Optimiser les flux de travail de gestion de projet en les intégrant avec des crochets git-precommit"],"de":["Automatisierung von Roadmap-Aktualisierungen basierend auf Commit-Nachrichten und Benutzereingaben","Aktualisieren von ROADMAP.md-Dateien mit abgeschlossenen Meilensteinen und entsprechenden Datum","Optimierung von Projektmanagement-Workflows durch Integration mit git-precommit-Hooks"],"pt":["Automatizar atualizações de roadmap com base em mensagens de commit e entrada do usuário","Atualizar arquivos ROADMAP.md com marcos concluídos e datas correspondentes","Otimizar fluxos de trabalho de gerenciamento de projetos integrando-se com ganchos git-precommit"],"ru":["Автоматизировать обновления дорожной карты на основе сообщений о коммитах и ввода пользователя","Обновлять файлы ROADMAP.md с завершенными вехами и соответствующими датами","Оптимизировать рабочие процессы управления проектами, интегрируясь с крючками git-precommit"],"ar":["توفير تحديثات المسار التطويري آليًا بناءً على رسائل الالتزام ومدخلات المستخدم","تحديث ملفات ROADMAP.md مع المراحل المكتملة وأيامها المناسبة","تحسين سير عمل إدارة المشاريع من خلال التكامل مع مشابك git-precommit"]},"limitations":{"en":["Requires access to ROADMAP.md files","Dependent on git-precommit hooks for automated triggering","Limited to updating ROADMAP.md files in Markdown format"],"zh":["需要访问 ROADMAP.md 文件","依赖于 git-precommit hooks 进行自动触发","仅限于更新 Markdown 格式的 ROADMAP.md 文件"],"ja":["ROADMAP.md ファイルへのアクセスが必要","自動トリガーには git-precommit hooks 依存","ROADMAP.md ファイルの更新は Markdown 形式のみ"],"ko":["ROADMAP.md 파일에 대한 액세스가 필요함","자동 트리거에는 git-precommit hooks 의존","ROADMAP.md 파일의 업데이트는 Markdown 형식만 해당"],"es":["Requiere acceso a archivos ROADMAP.md","Dependiente de ganchos git-precommit para activación automática","Limitado a la actualización de archivos ROADMAP.md en formato Markdown"],"fr":["Nécessite un accès aux fichiers ROADMAP.md","Dépendant des crochets git-precommit pour la déclenchement automatique","Limité à la mise à jour des fichiers ROADMAP.md au format Markdown"],"de":["Erfordert Zugriff auf ROADMAP.md-Dateien","Abhängig von git-precommit-Hooks für automatisches Auslösen","Begrenzt auf die Aktualisierung von ROADMAP.md-Dateien im Markdown-Format"],"pt":["Requer acesso a arquivos ROADMAP.md","Depende de ganchos git-precommit para acionamento automatizado","Limitado a atualizar arquivos ROADMAP.md no formato Markdown"],"ru":["Требует доступа к файлам ROADMAP.md","Зависит от крючков git-precommit для автоматического запуска","Ограничен обновлением файлов ROADMAP.md в формате Markdown"],"ar":["يتطلب الوصول إلى ملفات ROADMAP.md","يعتمد على مشابك git-precommit للحصول على التنشيط الآلي","محدود بتحديث ملفات ROADMAP.md بصيغة Markdown"]},"version":4},"contentHash":"643cdb2e326d7294b1044c96841f49cc8862b5be001692e9c6eb8c9f4c5f75a6","qualityScore":20}');
