INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('willyu1007/Skill_Template_Module/plan-code-refactors', 'plan-code-refactors', 'willyu1007', 'Skill_Template_Module', 'community', 'plan-code-refactors willyu1007 Skill_Template_Module community The plan-code-refactors skill provides a modular approach to code refactoring, offering basic version functionality and enabling most add-ons by default. This skill benefits developers seeking efficient refactoring solutions. plan-code-refactors技能基于模块化方法，具有基本版本功能，并支持大多数默认添加的模块 plan-code-refactorsスキルはモジュラーなアプローチに基づいており、基本的なバージョンの機能を備えており、ほとんどの追加モジュールをデフォルトで有効にします plan-code-refactors 스킬은 모듈식 접근법을 기반으로 하며, 기본 버전의 기능을 가지고 있으며, 대부분의 추가 모듈을 기본적으로 활성화합니다 plan-code-refactors es una plantilla de habilidad basada en un enfoque modular que permite la funcionalidad básica y habilita la mayoría de los complementos por defecto. plan-code-refactors est un modèle de compétence basé sur une approche modulaire qui permet la fonctionnalité de base et active la plupart des extensions par défaut. plan-code-refactors ist eine Fähigkeitsvorlage basierend auf einem modularen Ansatz, der die grundlegende Funktionalität ermöglicht und die meisten Erweiterungen standardmäßig aktiviert. O plan-code-refactors é um modelo de habilidade baseado em abordagem modular, com funcionalidades básicas completas e suporte a maioria dos add-ons План-code-refactors - это шаблон навыка, основанный на модульном подходе, с полными базовыми функциями и поддержкой большинства добавок خطة-код-إعادة-بناء هي قوالب مهارة تعتمد على نهج modular، مع وظائف أساسية كاملة ودعم معظم الإضافات how to use plan-code-refactors what is plan-code-refactors plan-code-refactors alternative plan-code-refactors setup guide modular code refactoring efficient refactoring solutions plan-code-refactors install plan-code-refactors vs other refactoring tools AI工具 plan-code-refactors 模块化方法 基本版本功能 CLI配置 脚本和模板 开发效率 AI开发工具 Utilizes a modular approach for efficient code refactoring Includes complete basic version functionality Enables most add-ons by default References canonical source files from `.ai/skills/workflows/planning/plan-code-refactors/` Supports navigation through added frontmatter like `ssot_path` and `category` Leverages supporting files like `reference.md`, `examples.md`, `scripts/`, and `templates/` plan-code-refactors is a skill template that utilizes a modular approach for efficient code refactoring, with complete basic version functionality and default add-on enablement.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PHMbench/PHM-Vibench/workflow-to-skill', 'community', 'PHMbench', 'PHM-Vibench', 'PHMbench/PHM-Vibench', 'workflow-to-skill', 0, 0, 20, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:29.584Z', '0185e49e27009d54a2f99a0ba6c293e8e01f280d893653242e8508eb67954f56', '{"id":"PHMbench/PHM-Vibench/workflow-to-skill","name":"workflow-to-skill","description":{"en":"The workflow-to-skill AI agent skill helps developers structure their operations into standardized SOPs, decision branches, and quality gates, benefiting DevOps teams and workflow managers.","zh":"工作流到技能抽取器是一种将用户操作步骤结构化为流程地图、决策分支、质量门禁和技能规格的工具，提高开发效率","ja":"ワークフローからスキルへの抽出器は、ユーザーの操作手順を流程図、意思決定分岐、品質ゲート、スキル仕様に構造化するツールであり、開発効率を向上させる","ko":"워크플로우에서 스킬로의 추출기는 사용자의 운영 단계를 프로세스 맵, 의사 결정 분기, 품질 게이트 및 스킬 사양으로 구조화하여 개발 효율성을 높이는 도구입니다","es":"El Skill de Workflow-to-Skill permite estructurar flujos de trabajo en un formato estándar, incluyendo SOP, decisiones y calidad","fr":"Le Skill de Workflow-to-Skill permet de structurer les flux de travail dans un format standard, incluant SOP, décisions et qualité","de":"Der Skill von Workflow-to-Skill ermöglicht die Strukturierung von Arbeitsabläufen in einem Standardformat, einschließlich SOP, Entscheidungen und Qualität","pt":"O Workflow-to-Skill é uma ferramenta para automatizar processos e melhorar a eficiência. Aprenda a configurá-lo para atender às suas necessidades.","ru":"Workflow-to-Skill - это инструмент для автоматизации процессов и повышения эффективности. Узнайте, как настроить его для решения ваших задач ИИ Агентов.","ar":"Workflow-to-Skill هو أداة لتحسين العمليات وزيادة الكفاءة. تعرف على كيفية إعداده لتلبي احتياجاتك في عمليات الذكاء الاصطناعي"},"seo":{"title":{"en":"Workflow-to-Skill: SOP Generation Guide | AI Agent","zh":"工作流到技能抽取器设置指南","ja":"ワークフローからスキルへの抽出器のベストプラクティス","ko":"워크플로우에서 스킬로의 추출기 설정 가이드","es":"Guía de configuración de Workflow-to-Skill para agentes d...","fr":"Guide de configuration de Workflow-to-Skill pour les outi...","de":"Einrichtungsleitfaden für Workflow-to-Skill in KI-Agenten","pt":"Guia de Configuração do Workflow-to-Skill: Melhores Práticas","ru":"Настройка Workflow-to-Skill: Лучшие Практики для ИИ Агентов","ar":"دليل إعداد Workflow-to-Skill: أفضل الممارسات لعمليات الذك..."},"description":{"en":"Unlock efficient workflow management with workflow-to-skill. Discover how to structure your operations into actionable SOPs, decision branches, and quality g...","zh":"了解如何使用工作流到技能抽取器将用户的操作步骤结构化为流程地图、决策分支、质量门禁和技能规格，提高开发效率","ja":"ワークフローからスキルへの抽出器を使用して、ユーザーの操作手順を流程図、意思決定分岐、品質ゲート、スキル仕様に構造化し、開発効率を向上させる方法を学びます","ko":"워크플로우에서 스킬로의 추출기를 사용하여 사용자의 운영 단계를 프로세스 맵, 의사 결정 분기, 품질 게이트 및 스킬 사양으로 구조화하여 개발 효율성을 높이는 방법을 알아보세요","es":"Aprende a estructurar tus flujos de trabajo en un Skill para agentes de IA con nuestra guía paso a paso","fr":"Découvrez comment structurer vos flux de travail en un Skill pour les outils d''IA avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Ihre Arbeitsabläufe in einem Skill für KI-Agenten strukturieren können, mit unserem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o Workflow-to-Skill para automatizar processos e melhorar a eficiência. Descubra as melhores práticas e recursos para desenvolvedores.","ru":"Узнайте, как настроить Workflow-to-Skill для автоматизации процессов и повышения эффективности. Откройте для себя лучшие практики и ресурсы для разработчиков...","ar":"تعرف على كيفية إعداد Workflow-to-Skill لتحسين العمليات وتحقيق الكفاءة. استكشف أفضل الممارسات والموارد للعاملين في مجال الذكاء الاصطناعي"},"definition":{"en":"workflow-to-skill is a process extraction tool that converts unstructured user operations into structured workflow maps, decision trees, and quality checkpoints.","zh":"工作流到技能抽取器是一种工具，用于将用户的操作步骤结构化为流程地图、决策分支、质量门禁和技能规格","ja":"ワークフローからスキルへの抽出器は、ユーザーの操作手順を流程図、意思決定分岐、品質ゲート、スキル仕様に構造化するためのツール","ko":"워크플로우에서 스킬로의 추출기는 사용자의 운영 단계를 프로세스 맵, 의사 결정 분기, 품질 게이트 및 스킬 사양으로 구조화하는 도구입니다","es":"Un Skill de Workflow-to-Skill es una herramienta que convierte flujos de trabajo en un formato estructurado para agentes de IA","fr":"Un Skill de Workflow-to-Skill est un outil qui convertit les flux de travail en un format structuré pour les outils d''IA","de":"Ein Skill von Workflow-to-Skill ist ein Werkzeug, das Arbeitsabläufe in ein strukturiertes Format für KI-Agenten umwandelt","pt":"O Workflow-to-Skill é uma ferramenta que converte fluxos de trabalho em habilidades automatizadas.","ru":"Workflow-to-Skill - это инструмент, который преобразует рабочие процессы в автоматизированные навыки для ИИ Агентов.","ar":"Workflow-to-Skill هو أداة تحول تدفقات العمل إلى مهارات متوفرة آليًا"},"features":{"en":["Generates Step-by-Step SOPs with executable operations and dependency tracking","Creates decision branches with conditional logic and minimal evidence requirements","Implements quality gates with mandatory checks and failure handling strategies","Defines skill specifications with trigger conditions, context, and execution steps","Produces MVP versions with minimal viable workflows and iteration roadmaps","Outputs SKILL.md drafts with recommended directory structures and script templates"],"zh":["流程地图（SOP）生成","决策分支与最小证据","质量门禁与失败处理策略","技能规格与触发条件","MVP版本与迭代路线"],"ja":["流程図（SOP）生成","意思決定分岐と最小証拠","品質ゲートと失敗処理戦略","スキル仕様とトリガ条件","MVPバージョンとイテレーションルート"],"ko":["프로세스 맵（SOP）생성","의사 결정 분기 및 최소 증거","품질 게이트 및 실패 처리 전략","스킬 사양 및 트리거 조건","MVP 버전 및 반복 路線"],"es":["Estructuración de flujos de trabajo en SOP (Procedimiento Operativo Estándar)","Creación de decisiones y ramificaciones condicionales","Definición de calidad y puntos de control","Generación de un Skill con especificaciones y parámetros","Creación de una versión MVP (Producto Mínimo Viable) con iteraciones","Generación de un borrador de SKILL.md con estructura recomendada"],"fr":["Structuration des flux de travail en SOP (Procédure Opérationnelle Standard)","Création de décisions et de ramifications conditionnelles","Définition de la qualité et des points de contrôle","Génération d''un Skill avec spécifications et paramètres","Création d''une version MVP (Produit Minimum Viable) avec itérations","Génération d''un brouillon de SKILL.md avec structure recommandée"],"de":["Strukturierung von Arbeitsabläufen in SOP (Standardoperatives Verfahren)","Erstellung von Entscheidungen und bedingten Verzweigungen","Definition von Qualität und Kontrollpunkten","Generierung eines Skills mit Spezifikationen und Parametern","Erstellung einer MVP-Version (Minimales Produkt) mit Iterationen","Generierung eines Entwurfs für SKILL.md mit empfohlener Struktur"],"pt":["Criação de mapas de processos (SOP) com passos, objetivos e operações","Definição de decisões condicionais com mínimo de evidências","Implementação de portas de qualidade com verificações e estratégias de falha","Definição de especificações de habilidades com condições de disparo e parâmetros","Criação de versões MVP com iterações de v0.1 a v1.0","Geração de modelos de SKILL.md com diretórios e arquivos recomendados"],"ru":["Создание карт процессов (SOP) с шагами, целями и операциями для ИИ Агентов","Определение условных решений с минимальными доказательствами","Реализация контрольных точек качества с проверками и стратегиями неисправностей","Определение спецификаций навыков с условиями срабатывания и параметрами","Создание версий MVP с итерациями от v0.1 до v1.0","Генерация шаблонов SKILL.md с рекомендуемой структурой директорий и файлов"],"ar":["إنشاءخرائط العمليات (SOP) بخطوات وأهداف وعمليات","تحديد القرارات الشرطية بأدلة أدنى","تنفيذ أبواب الجودة بالتحقق واستراتيجيات الفشل","تحديد مواصفات المهارات بشروط الإطلاق والمعاملات","إنشاء إصدارات MVP بالتكرارات من v0.1 إلى v1.0","توليد نماذج SKILL.md بالهيكل الموصى به للمجلدات والملفات"]},"keywords":{"en":["how to use workflow-to-skill","workflow-to-skill tutorial","workflow management best practices","SOP generation tools","decision tree implementation","quality gate setup guide","workflow-to-skill alternative","workflow-to-skill vs competing tools","workflow-to-skill install and setup"],"zh":["工作流到技能抽取器","流程地图","决策分支","质量门禁","技能规格","MVP版本","AIエージェント","开发效率"],"ja":["ワークフローからスキルへの抽出器","流程図","意思決定分岐","品質ゲート","スキル仕様","MVPバージョン","AIエージェント","開発効率"],"ko":["워크플로우에서 스킬로의 추출기","프로세스 맵","의사 결정 분기","품질 게이트","스킬 사양","MVP 버전","AI 에이전트","개발 효율성"],"es":["agentes de IA","Workflow-to-Skill","SOP","decisiones condicionales","calidad y control","Skill de IA","MVP","SKILL.md","estructuración de flujos de trabajo","herramientas de IA"],"fr":["outils d''IA","Workflow-to-Skill","SOP","décisions conditionnelles","qualité et contrôle","Skill d''IA","MVP","SKILL.md","structuration des flux de travail","outils d''IA"],"de":["KI-Agenten","Workflow-to-Skill","SOP","bedingte Verzweigungen","Qualität und Kontrolle","Skill für KI","MVP","SKILL.md","Strukturierung von Arbeitsabläufen","KI-Werkzeuge"],"pt":["workflow to skill","automatização de processos","melhorias de eficiência","ferramentas de desenvolvimento","SKILL.md","mapas de processos","decisões condicionais","portas de qualidade","especificações de habilidades","versões MVP"],"ru":["workflow to skill","автоматизация процессов","повышение эффективности","инструменты разработки","SKILL.md","карты процессов","условные решения","контрольные точки качества","спецификации навыков","версии MVP","ИИ Агенты"],"ar":["workflow to skill","تحسين العمليات","زيادة الكفاءة","أدوات التطوير","SKILL.md","خرائط العمليات","قرارات شرطية","أبواب الجودة","مواصفات المهارات","إصدارات MVP","عمليات الذكاء الاصطناعي"]}},"owner":"PHMbench","repo":"PHM-Vibench","repoPath":"PHMbench/PHM-Vibench","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"workflow-to-skill","description":"将用户的手工SOP/工作流抽取为可复用的Agent Skill规格与SKILL.md草案。适用于“把这个流程封装成skill/把步骤做成skill/从手工步骤生成SOP+分支+质量门禁+技能文件/元prompt做成skill”等请求。Use when the user describes a manual workflow and wants to turn it into a reusable Skill.","bodyPreview":"# Workflow → Skill 抽取器（元 Skill）\n\n## 你要交付什么\n把用户“不开 skill 时的真实操作步骤”（可以很乱）结构化为：\n1) **流程地图（SOP）**：Step | 目的 | 操作（可执行） | 前置/依赖 | 产物 | 完成判定 | 风险/回滚\n2) **决策分支**：如果…则…，每条附“最小证据”（看什么日志/文件/信号）\n3) **质量门禁（Quality Gates）**：必须通过的检查点 + 失败处理策略\n4) **Skill 规格**：触发条件、上下文、执行步骤粒度、产物清单、默认参数、禁止项、需人工确认项\n5) **MVP 版本**：只保留最省时的 20% 步骤，并给出 v0.1→v0.2→v1.0 迭代路线\n6) （可选）**可落地的 `SKILL.md` 草案**：给出推荐目录结构（`SKILL.md` / `scripts/` / `references/` / `assets/`）\n\n## 交互策略（先收口，再抽取）\n- 先给“可直接填空模板”，不要一次问很多问题\n- 信息缺失时先做合理假设，并在输出开头明确列出假设\n- 默认只","body":"# Workflow → Skill 抽取器（元 Skill）\n\n## 你要交付什么\n把用户“不开 skill 时的真实操作步骤”（可以很乱）结构化为：\n1) **流程地图（SOP）**：Step | 目的 | 操作（可执行） | 前置/依赖 | 产物 | 完成判定 | 风险/回滚\n2) **决策分支**：如果…则…，每条附“最小证据”（看什么日志/文件/信号）\n3) **质量门禁（Quality Gates）**：必须通过的检查点 + 失败处理策略\n4) **Skill 规格**：触发条件、上下文、执行步骤粒度、产物清单、默认参数、禁止项、需人工确认项\n5) **MVP 版本**：只保留最省时的 20% 步骤，并给出 v0.1→v0.2→v1.0 迭代路线\n6) （可选）**可落地的 `SKILL.md` 草案**：给出推荐目录结构（`SKILL.md` / `scripts/` / `references/` / `assets/`）\n\n## 交互策略（先收口，再抽取）\n- 先给“可直接填空模板”，不要一次问很多问题\n- 信息缺失时先做合理假设，并在输出开头明确列出假设\n- 默认只产出文本规范与草案；需要执行命令/改代码/写文件时，先说明“将要做什么 + 风险”，再等用户明确确认\n\n## 采集模板（发给用户粘贴填写）\n- 任务名称：\n- 触发场景：\n- 成功标准（做到什么算完成）：\n- 输入来源与示例（issue/报错/段落/日志/数据…）：\n- 输出落点（必须生成哪些文件/目录/产物）：\n- 相关目录/文件路径（可选）：\n- 手工步骤（Step 0..N，乱序也行）：\n- 判断依据/经验规则（如何选A/B、如何定位根因、如何验收）：\n- 验收方式（测试/编译/复现/一致性检查等）：\n- 禁止自动做的事（例如强推、删除、全仓格式化等）：\n\n## 抽取与归纳规则\n- 把每一步改写为“动词开头、可执行、可验证”的操作描述\n- 对每步补齐：前置条件 / 输入 / 输出 / 完成判定 / 风险与回滚\n- 从经验规则中抽取“决策分支”和“门禁条件”\n- 标注：可脚本化/模板化/并行化/缓存化的步骤\n\n## 输出格式（强制）\n按以下标题输出，优先用表格/清单：\n1) 假设与范围\n2) 流程地图（SOP 表格）\n3) 决策分支（如果…则… + 最小证据）\n4) 质量门禁（Quality Gates）\n5) Skill 规格（可落地）\n6) MVP + 迭代路线（v0.1→v0.2→v1.0）\n7) （可选）`SKILL.md` 草案 + 推荐目录结构\n\n## 生成 `SKILL.md` 的约束（当用户要求落地文件时）\n- Skill 名称：小写 + 数字 + 连字符（hyphen-case），目录名与 skill 名一致，≤64 字符\n- Frontmatter：只写 `name` 和 `description`；把触发条件写进 `description`\n- 正文：用祈使句；信息尽量放在可复用步骤/检查清单上\n- 资源：只有在确实复用时才建 `scripts/`/`references/`/`assets/`，避免额外文档噪声\n\n## 安全策略（硬约束）\n- 默认不做不可逆操作（强推、删除、覆盖大文件、改主分支）\n- 默认不做“全仓库格式化”这类噪声变更；需要用户明确要求\n- 对任何会修改文件/运行命令的动作：先列“将要做什么 + 风险 + 回滚方式”，再等用户确认\n"},"lastSynced":"2026-03-08T02:04:29.584Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps and Workflow Manager Agents needing to structure operations into standardized SOPs, decision branches, and quality gates.","zh":"非常适合需要将操作标准化为SOP、决策分支和质量门的DevOps和工作流管理器代理。","ja":"DevOpsとワークフローマネージャーエージェントが操作を標準化されたSOP、意思決定ブランチ、品質ゲートに構造化する必要がある場合に最適です。","ko":"DevOps와 워크플로 매니저 에이전트가 작업을 표준화된 SOP, 의사 결정 지점 및 품질 게이트로 구조화해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de DevOps y Workflow Manager que necesitan estructurar operaciones en SOPs estandarizadas, ramas de decisión y puertas de calidad.","fr":"Parfait pour les agents DevOps et Workflow Manager ayant besoin de structurer les opérations en SOP standardisées, branches de décision et portes de qualité.","de":"Perfekt für DevOps- und Workflow-Manager-Agents, die Operationen in standardisierte SOPs, Entscheidungsverzweigungen und Qualitätsprüfungen strukturieren müssen.","pt":"Perfeito para Agentes de DevOps e Workflow Manager que precisam estruturar operações em SOPs padronizados, ramificações de decisão e portões de qualidade.","ru":"Идеально подходит для агентов DevOps и Workflow Manager, которым необходимо структурировать операции в стандартизированные SOP, ветки решений и ворота качества.","ar":"مثالي لعمليات DevOps ووكلاء إدارة العمل التى تحتاج إلى بنية العمليات إلى إجراءات العمل المعيارية ، وفروع القرار ، وأبواب الجودة."},"recommendation":{"en":"Empowers agents to generate comprehensive workflow maps, including decision branches, quality gates, and skill specifications, utilizing SOPs, quality gates, and skill extraction, while providing iterative development paths like MVP versions and SKILL.md drafts.","zh":"赋予代理生成综合工作流地图的能力，包括决策分支、质量门、技能规格，利用SOP、质量门和技能提取，同时提供迭代开发路径，如MVP版本和SKILL.md草稿。","ja":"エージェントが、SOP、品質ゲート、スキル抽出を利用して、意思決定ブランチ、品質ゲート、スキル仕様を含む包括的なワークフローマップを生成する機能を提供し、MVPバージョンやSKILL.md草案などのイテレーティブ開発パスも提供します。","ko":"에이전트가 SOP, 품질 게이트 및 스킬 추출을 사용하여 의사 결정 지점, 품질 게이트 및 스킬 사양을 포함하는 포괄적인 워크플로우 맵을 생성할 수 있는 기능을 제공하며, MVP 버전 및 SKILL.md 초안과 같은 반복적 개발 경로도 제공합니다.","es":"Habilita a los agentes a generar mapas de flujo de trabajo integrales, incluyendo ramas de decisión, puertas de calidad y especificaciones de habilidades, utilizando SOP, puertas de calidad y extracción de habilidades, mientras proporciona caminos de desarrollo iterativos como versiones MVP y borradores de SKILL.md.","fr":"Permet aux agents de générer des cartes de workflow complètes, incluant des branches de décision, des portes de qualité et des spécifications de compétences, en utilisant les SOP, les portes de qualité et l''extraction de compétences, tout en fournissant des chemins de développement itératifs comme les versions MVP et les brouillons de SKILL.md.","de":"Ermöglicht es Agents, umfassende Workflow-Karten zu generieren, einschließlich Entscheidungsverzweigungen, Qualitätsprüfungen und Fertigkeitsbeschreibungen, unter Verwendung von SOP, Qualitätsprüfungen und Fertigkeitsextraktion, während iterative Entwicklungswege wie MVP-Versionen und SKILL.md-Entwürfe bereitgestellt werden.","pt":"Habilita os agentes a gerar mapas de fluxo de trabalho abrangentes, incluindo ramificações de decisão, portões de qualidade e especificações de habilidades, utilizando SOPs, portões de qualidade e extração de habilidades, ao mesmo tempo em que fornece caminhos de desenvolvimento iterativos como versões MVP e rascunhos de SKILL.md.","ru":"Наделяет агентов возможностью генерировать комплексные карты рабочих процессов, включая ветки решений, ворота качества и спецификации навыков, используя SOP, ворота качества и извлечение навыков, а также предоставляя итеративные пути развития, такие как версии MVP и черновики SKILL.md.","ar":"تمكن الوكلاء من توليد خرائط شاملة لتدفق العمل ، بما في ذلك فروع القرار وأبواب الجودة ومواصفات المهارات ، باستخدام إجراءات العمل المعيارية وأبواب الجودة واستخراج المهارات ، وفي الوقت نفسه تقديم مسارات تطوير متكررة مثل إصدارات MVP ومسودات SKILL.md."},"useCases":{"en":["Automating workflow standardization for DevOps teams","Generating decision branches with minimal evidence requirements","Creating quality gates for risk management and rollback strategies"],"zh":["为DevOps团队自动化工作流标准化","使用最小证据要求生成决策分支","为风险管理和回滚策略创建质量门"],"ja":["DevOpsチームのワークフローの標準化を自動化する","最小限の証拠要件で意思決定ブランチを生成する","リスク管理とロールバック戦略のために品質ゲートを作成する"],"ko":["DevOps 팀의 워크플로우 표준화를 자동화하는 것","최소한의 증거 요구 사항으로 의사 결정 지점을 생성하는 것","위험 관리 및 롤백 전략을 위한 품질 게이트 생성"],"es":["Automatización de la estandarización de flujos de trabajo para equipos de DevOps","Generación de ramas de decisión con requisitos de evidencia mínimos","Creación de puertas de calidad para la gestión de riesgos y estrategias de reversión"],"fr":["Automatisation de la standardisation des flux de travail pour les équipes DevOps","Génération de branches de décision avec des exigences de preuve minimales","Création de portes de qualité pour la gestion des risques et les stratégies de réversibilité"],"de":["Automatisierung der Standardisierung von Workflows für DevOps-Teams","Erstellung von Entscheidungsverzweigungen mit minimalen Beweisanforderungen","Erstellung von Qualitätsprüfungen für Risikomanagement und Rollback-Strategien"],"pt":["Automatizar a padronização do fluxo de trabalho para equipes de DevOps","Gerar ramificações de decisão com requisitos mínimos de evidência","Criar portões de qualidade para gestão de riscos e estratégias de reverter"],"ru":["Автоматизировать стандартизацию рабочих процессов для команд DevOps","Генерировать ветки решений с минимальными требованиями к доказательствам","Создавать ворота качества для управления рисками и стратегий откатов"],"ar":["تأتمتة معايير تدفق العمل للفرق DevOps","توليد فروع القرار مع متطلبات أدلة минимальية","إنشاء أبواب الجودة لإدارة المخاطر وخطط التراجع"]},"limitations":{"en":["Requires user input for initial workflow steps","Assumes a basic understanding of workflow management and SOP creation","May need additional customization for complex workflows"],"zh":["需要用户输入初始工作流步骤","假设基本的工作流管理和SOP创建知识","可能需要额外的自定义以适应复杂的工作流"],"ja":["初期のワークフローのステップに入力が必要","基本的なワークフローマネジメントとSOP作成の知識が必要","複雑なワークフローに適応するために追加のカスタマイズが必要になる可能性がある"],"ko":["초기 워크플로우 단계에 사용자 입력이 필요함","기본적인 워크플로우 관리 및 SOP 생성 지식이 필요함","복잡한 워크플로우에 적응하기 위해 추가적인 사용자 정의가 필요할 수 있음"],"es":["Requiere entrada de usuario para los pasos iniciales del flujo de trabajo","Supone un conocimiento básico de la gestión de flujos de trabajo y la creación de SOP","Puede necesitar personalización adicional para flujos de trabajo complejos"],"fr":["Nécessite une entrée utilisateur pour les premières étapes du flux de travail","Suppose une compréhension de base de la gestion des flux de travail et de la création de SOP","Peut nécessiter une personnalisation supplémentaire pour les flux de travail complexes"],"de":["Benötigt Benutzereingaben für die ersten Schritte des Workflows","Geht von einem grundlegenden Verständnis der Workflow-Verwaltung und der SOP-Erstellung aus","Kann für komplexe Workflows eine zusätzliche Anpassung erfordern"],"pt":["Exige entrada do usuário para os primeiros passos do fluxo de trabalho","Pressupõe uma compreensão básica da gestão de fluxo de trabalho e criação de SOP","Pode precisar de personalização adicional para fluxos de trabalho complexos"],"ru":["Требует ввода пользователя для начальных шагов рабочего процесса","Предполагает базовое понимание управления рабочим процессом и создания SOP","Может потребовать дополнительной настройки для сложных рабочих процессов"],"ar":["يتطلب إدخال المستخدم للخطوات الأولى من تدفق العمل","يفترض فهمًا أساسيًا لإدارة تدفق العمل وإنشاء إجراءات العمل المعيارية","قد يحتاج إلى تخصيص إضافي لتدفقات العمل المعقدة"]},"version":4},"contentHash":"0185e49e27009d54a2f99a0ba6c293e8e01f280d893653242e8508eb67954f56","qualityScore":20}');
DELETE FROM skills_fts WHERE id = 'PHMbench/PHM-Vibench/workflow-to-skill';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PHMbench/PHM-Vibench/workflow-to-skill', 'workflow-to-skill', 'PHMbench', 'PHM-Vibench', 'community', 'workflow-to-skill PHMbench PHM-Vibench community The workflow-to-skill AI agent skill helps developers structure their operations into standardized SOPs, decision branches, and quality gates, benefiting DevOps teams and workflow managers. 工作流到技能抽取器是一种将用户操作步骤结构化为流程地图、决策分支、质量门禁和技能规格的工具，提高开发效率 ワークフローからスキルへの抽出器は、ユーザーの操作手順を流程図、意思決定分岐、品質ゲート、スキル仕様に構造化するツールであり、開発効率を向上させる 워크플로우에서 스킬로의 추출기는 사용자의 운영 단계를 프로세스 맵, 의사 결정 분기, 품질 게이트 및 스킬 사양으로 구조화하여 개발 효율성을 높이는 도구입니다 El Skill de Workflow-to-Skill permite estructurar flujos de trabajo en un formato estándar, incluyendo SOP, decisiones y calidad Le Skill de Workflow-to-Skill permet de structurer les flux de travail dans un format standard, incluant SOP, décisions et qualité Der Skill von Workflow-to-Skill ermöglicht die Strukturierung von Arbeitsabläufen in einem Standardformat, einschließlich SOP, Entscheidungen und Qualität O Workflow-to-Skill é uma ferramenta para automatizar processos e melhorar a eficiência. Aprenda a configurá-lo para atender às suas necessidades. Workflow-to-Skill - это инструмент для автоматизации процессов и повышения эффективности. Узнайте, как настроить его для решения ваших задач ИИ Агентов. Workflow-to-Skill هو أداة لتحسين العمليات وزيادة الكفاءة. تعرف على كيفية إعداده لتلبي احتياجاتك في عمليات الذكاء الاصطناعي how to use workflow-to-skill workflow-to-skill tutorial workflow management best practices SOP generation tools decision tree implementation quality gate setup guide workflow-to-skill alternative workflow-to-skill vs competing tools workflow-to-skill install and setup 工作流到技能抽取器 流程地图 决策分支 质量门禁 技能规格 MVP版本 AIエージェント 开发效率 Generates Step-by-Step SOPs with executable operations and dependency tracking Creates decision branches with conditional logic and minimal evidence requirements Implements quality gates with mandatory checks and failure handling strategies Defines skill specifications with trigger conditions, context, and execution steps Produces MVP versions with minimal viable workflows and iteration roadmaps Outputs SKILL.md drafts with recommended directory structures and script templates workflow-to-skill is a process extraction tool that converts unstructured user operations into structured workflow maps, decision trees, and quality checkpoints.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SidU/GoodDocs/doc-author', 'community', 'SidU', 'GoodDocs', 'SidU/GoodDocs', 'doc-author', 0, 0, 20, '2026-03-08T01:57:15.374Z', '2026-03-08T02:04:32.532Z', '42e5283d7ef45421983dc0870f095f5d0bd41fa5cfc35bc0faa7cb30c70a9e11', '{"id":"SidU/GoodDocs/doc-author","name":"doc-author","description":{"en":"The doc-author skill assists users in creating new documents using the GoodDocs template, automating tasks such as determining the next numeric ID and setting frontmatter. It benefits developers and document authors.","zh":"doc-author 是一种 AI 工具，用于指导用户创建新文档，使用 GoodDocs 模板和验证规则。它可以自动设置文档标题、动机、提案解决方案和替代方案等内容","ja":"doc-author は、GoodDocs テンプレートと検証ルールを使用して新しい文書を作成するための AI エージェントです。ユーザーは文書のタイトル、動機、提案された解決策、代替質問などを入力します","ko":"doc-author는 사용자가 새로운 문서를 작성하는 것을 도와주는 AI 에이전트입니다. GoodDocs 템플릿과 검증 규칙을 사용하여 문서 제목, 동기, 제안된 해결책 및 대안 등을 생성합니다","es":"El agente doc-author es una herramienta de AI que guía a los usuarios a través de la creación de un nuevo documento utilizando el template y las reglas de validación de GoodDocs","fr":"L''agent doc-author est un outil d''IA qui guide les utilisateurs à travers la création d''un nouveau document en utilisant le modèle et les règles de validation de GoodDocs","de":"Der doc-author-Agent ist ein AI-Tool, das Benutzer durch die Erstellung eines neuen Dokuments mit dem GoodDocs-Template und den Validierungsregeln führt","pt":"O doc-author é uma ferramenta que ajuda a criar documentos com o template e regras de validação do GoodDocs. Ele automatiza a criação de documentos","ru":"ИИ Агент doc-author - это инструмент, помогающий создавать документы с помощью шаблона и правил проверки GoodDocs. Он автоматизирует создание документов","ar":"وظيفة doc-author هي أداة تساعد في إنشاء مستندات باستخدام قالب و قواعد التحقق من GoodDocs. إنها توفير الوقت في إنشاء المستندات"},"seo":{"title":{"en":"doc-author: Automated Document Creation Guide | AI Agent ...","zh":"doc-author 设备指南：自动化文档创建","ja":"doc-author セットアップガイド：GoodDocs テンプレートを使用した文書作成","ko":"doc-author 설정 가이드: 자동 문서 작성 및 검증","es":"Guía de Configuración para doc-author: Creación de Docume...","fr":"Guide de Configuration pour doc-author: Création de Docum...","de":"Konfigurationsleitfaden für doc-author: Dokumenterstellun...","pt":"Guia de Configuração do doc-author: Criando Documentos co...","ru":"Настройка ИИ Агента doc-author: Руководство по созданию д...","ar":"دليل إعداد وظيفة doc-author: إنشاء مستندات باستخدام GoodDocs"},"description":{"en":"Streamline your documentation process with doc-author, an AI agent skill that guides users through authoring new documents using GoodDocs templates and valid...","zh":"使用 doc-author AI 工具自动化文档创建流程，包括文档标题、动机、提案解决方案和替代方案的生成","ja":"doc-author AIエージェントを使用して、GoodDocs テンプレートと検証ルールに基づいて文書を作成します","ko":"doc-author AI 에이전트를 사용하여 문서 작성 및 검증 프로세스를 자동화합니다. 문서 제목, 동기, 제안된 해결책 및 대안에 대한 입력을 제공합니다","es":"Aprende a configurar doc-author para crear documentos con GoodDocs. Descubre cómo utilizar el template y las reglas de validación para un proceso de autoría ...","fr":"Découvrez comment configurer doc-author pour créer des documents avec GoodDocs. Apprenez à utiliser le modèle et les règles de validation pour un processus d...","de":"Erfahren Sie, wie Sie doc-author konfigurieren, um Dokumente mit GoodDocs zu erstellen. Entdecken Sie, wie Sie das Template und die Validierungsregeln für ei...","pt":"Aprenda a configurar o doc-author para criar documentos com o template e regras de validação do GoodDocs. Descubra como automatizar a criação de documentos","ru":"Узнайте, как настроить ИИ Агент doc-author для создания документов с помощью шаблона и правил проверки GoodDocs. Автоматизируйте создание документов","ar":"تعلم كيفية إعداد وظيفة doc-author لإنشاء مستندات باستخدام قالب و قواعد التحقق من GoodDocs. اكتشف كيفية توفير الوقت في إنشاء المستندات"},"definition":{"en":"doc-author is an AI agent skill that automates the process of authoring new documents using predefined templates and validation rules.","zh":"doc-author 是一种用于自动化文档创建的 AI 工具","ja":"doc-author は、文書を作成するための AI エージェントです","ko":"doc-author는 문서 작성 및 검증을 자동화하는 AI 에이전트입니다","es":"El agente doc-author es una herramienta de autoría asistida por IA que utiliza el template y las reglas de validación de GoodDocs para crear documentos","fr":"L''agent doc-author est un outil d''authoring assisté par l''IA qui utilise le modèle et les règles de validation de GoodDocs pour créer des documents","de":"Der doc-author-Agent ist ein von der KI unterstütztes Autorisierungstool, das das GoodDocs-Template und die Validierungsregeln verwendet, um Dokumente zu erstellen","pt":"O doc-author é uma ferramenta de criação de documentos que usa o template e regras de validação do GoodDocs","ru":"ИИ Агент doc-author - это инструмент создания документов, использующий шаблон и правила проверки GoodDocs","ar":"وظيفة doc-author هي أداة إنشاء مستندات تستخدم قالب و قواعد التحقق من GoodDocs"},"features":{"en":["Automatically uses defaultDocTypeKey and defaultOwners from repo.config.json","Asks users for title, motivation, proposed solution, and alternatives/open questions","Determines the next numeric ID by scanning docs/<docRoot> for ####-*.md files","Sets frontmatter id to DOC-#### and generates markdown files","Validates user input using GoodDocs validation rules","Supports GoodDocs template for document creation"],"zh":["自动设置文档标题和动机","使用 GoodDocs 模板和验证规则","生成文档 ID 和 frontmatter","支持多种文档类型和所有者","自动检测和设置下一个文档 ID"],"ja":["文書のタイトルと動機を自動設定","GoodDocs テンプレートと検証ルールを使用","文書 ID と frontmatter を生成","複数の文書タイプと所有者をサポート","次の文書 ID を自動検出して設定"],"ko":["문서 제목과 동기를 자동으로 설정","GoodDocs 템플릿과 검증 규칙을 사용","문서 ID와 frontmatter를 생성","다양한 문서 유형과 소유자를 지원","다음 문서 ID를 자동으로 감지하고 설정"],"es":["Uso automático de defaultDocTypeKey y defaultOwners desde repo.config.json","Solicitud de título, motivación, solución propuesta y alternativas","Determinación del ID numérico siguiente mediante escaneo de docs/<docRoot>","Establecimiento de frontmatter id como DOC-####","Generación de encabezados con #"],"fr":["Utilisation automatique de defaultDocTypeKey et defaultOwners depuis repo.config.json","Demande de titre, motivation, solution proposée et alternatives","Détermination de l''ID numérique suivant par analyse de docs/<docRoot>","Définition de l''en-tête id comme DOC-####","Génération d''en-têtes avec #"],"de":["Automatische Verwendung von defaultDocTypeKey und defaultOwners aus repo.config.json","Anfrage von Titel, Motivation, vorgeschlagener Lösung und Alternativen","Bestimmung der nächsten numerischen ID durch Scannen von docs/<docRoot>","Festlegung von Frontmatter-ID als DOC-####","Generierung von Überschriften mit #"],"pt":["Criação de documentos com o template do GoodDocs","Regras de validação automatizadas","Atribuição automática de ID de documento","Suporte a repositorios com configuração em JSON"],"ru":["Создание документов с помощью шаблона GoodDocs","Автоматизированные правила проверки","Автоматическое присвоение идентификатора документа","Поддержка репозиториев с конфигурацией в JSON"],"ar":["إنشاء مستندات باستخدام قالب GoodDocs","قواعد التحقق المُتوماتيك","تعيين تلقائي لمعرف المستند","دعم للمستودعات مع تكوين JSON"]},"keywords":{"en":["how to use doc-author","doc-author setup guide","what is doc-author","doc-author alternative","doc-author vs GoodDocs","doc-author install","automated document creation","GoodDocs template","document validation rules"],"zh":["doc-author","AI 工具","文档创建","GoodDocs 模板","验证规则","自动化文档","文档标题","动机","提案解决方案","替代方案"],"ja":["doc-author","AIエージェント","文書作成","GoodDocs テンプレート","検証ルール","自動化文書","文書タイトル","動機","提案された解決策","代替質問"],"ko":["doc-author","AI 에이전트","문서 작성","GoodDocs 템플릿","검증 규칙","자동화 문서","문서 제목","동기","제안된 해결책","대안"],"es":["herramientas de AI para la autoría de documentos","configuración de doc-author","GoodDocs template","reglas de validación","creación de documentos","autoría asistida por IA"],"fr":["outils d''IA pour l''authoring de documents","configuration de doc-author","modèle GoodDocs","règles de validation","création de documents","authoring assisté par l''IA"],"de":["AI-Tools für die Dokumentenerstellung","Konfiguration von doc-author","GoodDocs-Template","Validierungsregeln","Dokumentenerstellung","KI-unterstütztes Autorisieren"],"pt":["doc-author","GoodDocs","criação de documentos","regras de validação","automatização de documentos","template de documentos","configuração de repositorio"],"ru":["ИИ Агент doc-author","GoodDocs","создание документов","правила проверки","автоматизация документов","шаблон документов","конфигурация репозитория"],"ar":["وظيفة doc-author","GoodDocs","إنشاء مستندات","قواعد التحقق","توفير الوقت في إنشاء المستندات","قالب المستندات","تكوين المستودع"]}},"owner":"SidU","repo":"GoodDocs","repoPath":"SidU/GoodDocs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.374Z","topics":[],"category":"community","skillMd":{"name":"doc-author","description":"Guide a user through authoring a new document using the GoodDocs template and validation rules.","bodyPreview":"# Skill: doc-author\n\n## Purpose\nGuide a user through authoring a new document using the GoodDocs template and validation rules.\n\n## Behavior\n1. If `repo.config.json` exists, use `defaultDocTypeKey` and `defaultOwners` automatically.\n2. Ask the user for:\n   - Title\n   - Motivation\n   - Proposed solution\n   - Alternatives/open questions\n3. Determine the next numeric ID by scanning `docs/<docRoot>` for `####-*.md` and incrementing the max value.\n4. Set frontmatter `id` to `DOC-####` and generate `#","body":"# Skill: doc-author\n\n## Purpose\nGuide a user through authoring a new document using the GoodDocs template and validation rules.\n\n## Behavior\n1. If `repo.config.json` exists, use `defaultDocTypeKey` and `defaultOwners` automatically.\n2. Ask the user for:\n   - Title\n   - Motivation\n   - Proposed solution\n   - Alternatives/open questions\n3. Determine the next numeric ID by scanning `docs/<docRoot>` for `####-*.md` and incrementing the max value.\n4. Set frontmatter `id` to `DOC-####` and generate `####-<kebab-title>.md` using `templates/doc-template.md`.\n5. Update `docs/README.md` to include a link to the new document.\n6. Run `python3 scripts/validate_docs.py` and fix issues before finishing.\n"},"lastSynced":"2026-03-08T02:04:32.532Z","agentAnalysis":{"suitability":{"en":"Perfect for Documentation Agents needing automated document generation with GoodDocs template validation","zh":"适合需要使用GoodDocs模板验证自动化文档生成的文档代理","ja":"GoodDocsテンプレートの検証を使用した自動ドキュメント生成を必要とするドキュメントエージェントに適しています","ko":"GoodDocs 템플릿 유효성 검사를 사용하여 자동화된 문서 생성이 필요한 문서 에이전트에 적합합니다","es":"Perfecto para Agentes de Documentación que necesitan generación de documentos automatizada con validación de plantilla GoodDocs","fr":"Parfait pour les Agents de documentation ayant besoin d''une génération de documents automatisée avec validation de modèle GoodDocs","de":"Perfekt für Dokumentationsagenten, die automatisierte Dokumentenerstellung mit GoodDocs-Vorlagenvalidierung benötigen","pt":"Perfeito para Agentes de Documentação que necessitam de geração automática de documentos com validação de modelo GoodDocs","ru":"Идеально для агентов документации, которым требуется автоматическая генерация документов с проверкой шаблона GoodDocs","ar":"مثالي للوكلاء الوثائقية الذين يحتاجون إلى إنشاء مستندات تلقائي باستخدام نموذج GoodDocs"},"recommendation":{"en":"Empowers agents to create new documents with automated frontmatter setup, including numeric ID determination and validation against repo.config.json, leveraging GoodDocs templates and Markdown file formats","zh":"赋予代理创建新文档的能力，包括自动设置前置内容，包括数字ID的确定和对repo.config.json的验证，利用GoodDocs模板和Markdown文件格式","ja":"エージェントが新しいドキュメントを作成できるようにし、自動的な前置きの設定を含め、数字IDの決定とrepo.config.jsonに対する検証を行い、GoodDocsテンプレートとMarkdownファイル形式を利用する","ko":"에이전트가 새로운 문서를 생성할 수 있도록 하며, 자동적인 프론트매터 설정을 포함하여 숫자 ID의 결정과 repo.config.json에 대한 검증을 수행하며, GoodDocs 템플릿과 Markdown 파일 형식을 활용합니다","es":"Habilita a los agentes a crear nuevos documentos con configuración de frontmatter automatizada, incluyendo la determinación y validación de ID numérico contra repo.config.json, aprovechando plantillas GoodDocs y formatos de archivo Markdown","fr":"Permet aux agents de créer de nouveaux documents avec une configuration de frontmatter automatisée, y compris la détermination et la validation de l''ID numérique contre repo.config.json, en exploitant les modèles GoodDocs et les formats de fichiers Markdown","de":"Ermächtigt Agenten, neue Dokumente mit automatisierter Frontmatter-Einrichtung zu erstellen, einschließlich numerischer ID-Bestimmung und Validierung gegen repo.config.json, unter Nutzung von GoodDocs-Vorlagen und Markdown-Dateiformaten","pt":"Habilita os agentes a criar novos documentos com configuração automática de frontmatter, incluindo determinação de ID numérico e validação contra repo.config.json, utilizando modelos GoodDocs e formatos de arquivo Markdown","ru":"Предоставляет агентам возможность создавать новые документы с автоматической настройкой frontmatter, включая определение числового идентификатора и проверку против repo.config.json, используя шаблоны GoodDocs и форматы файлов Markdown","ar":"تمكين الوكلاء من إنشاء مستندات جديدة مع إعداد تلقائي للمعلومات الأمامية ، بما في ذلك تحديد الهوية الرقمية والتحقق من صحة repo.config.json ، باستخدام قوالب GoodDocs وأشكال الملفات Markdown"},"useCases":{"en":["Automating document creation with standardized frontmatter","Generating new documents with incremental numeric IDs","Validating document structure against GoodDocs templates"],"zh":["使用标准化的前置内容自动化文档创建","使用递增的数字ID生成新文档","使用GoodDocs模板验证文档结构"],"ja":["標準化された前置きを使用してドキュメントの作成を自動化する","増分の数字IDを使用して新しいドキュメントを生成する","GoodDocsテンプレートを使用してドキュメント構造を検証する"],"ko":["표준화된 프론트매터를 사용하여 문서 생성을 자동화하는こと","증분 숫자 ID를 사용하여 새로운 문서를 생성하는 것","GoodDocs 템플릿을 사용하여 문서 구조를 검증하는 것"],"es":["Automatización de la creación de documentos con frontmatter estandarizado","Generación de nuevos documentos con ID numéricos incrementales","Validación de la estructura del documento contra plantillas GoodDocs"],"fr":["Automatisation de la création de documents avec frontmatter standardisé","Génération de nouveaux documents avec ID numériques incrémentiels","Validation de la structure du document contre les modèles GoodDocs"],"de":["Automatisierung der Dokumentenerstellung mit standardisiertem Frontmatter","Erzeugung neuer Dokumente mit inkrementellen numerischen IDs","Validierung der Dokumentenstruktur gegen GoodDocs-Vorlagen"],"pt":["Automatizar a criação de documentos com frontmatter padronizado","Gerar novos documentos com IDs numéricas incrementais","Validar a estrutura do documento contra modelos GoodDocs"],"ru":["Автоматизировать создание документов со стандартизированным frontmatter","Генерировать новые документы с инкрементными числовыми идентификаторами","Проверять структуру документа против шаблонов GoodDocs"],"ar":["أتمتة إنشاء المستندات مع معلومات أمامية معيارية","إنشاء مستندات جديدة مع تعريفات رقمية متزايدة","التحقق من بنية المستند مقابل قوالب GoodDocs"]},"limitations":{"en":["Requires repo.config.json for automated default settings","Limited to Markdown file format (.md)","Dependent on GoodDocs template structure"],"zh":["需要repo.config.json来实现自动默认设置","仅限于Markdown文件格式（.md）","依赖于GoodDocs模板结构"],"ja":["自動的なデフォルト設定を実現するためにrepo.config.jsonが必要","Markdownファイル形式（.md）のみに限定される","GoodDocsテンプレート構造に依存する"],"ko":["자동 기본 설정을 구현하기 위해 repo.config.json이 필요함","Markdown 파일 형식(.md)으로만 제한됨","GoodDocs 템플릿 구조에 의존함"],"es":["Requiere repo.config.json para la configuración automática de valores predeterminados","Limitado al formato de archivo Markdown (.md)","Dependiente de la estructura de la plantilla GoodDocs"],"fr":["Nécessite repo.config.json pour les paramètres par défaut automatisés","Limité au format de fichier Markdown (.md)","Dépendant de la structure du modèle GoodDocs"],"de":["Benötigt repo.config.json für automatisierte Standard-Einstellungen","Begrenzt auf Markdown-Dateiformat (.md)","Abhängig von der Struktur der GoodDocs-Vorlage"],"pt":["Requer repo.config.json para configurações padrão automatizadas","Limitado ao formato de arquivo Markdown (.md)","Dependente da estrutura do modelo GoodDocs"],"ru":["Требуется repo.config.json для автоматических настроек по умолчанию","Ограничен форматом файла Markdown (.md)","Зависит от структуры шаблона GoodDocs"],"ar":["يتطلب repo.config.json لإعدادات افتراضية آلية","محدود بالتنسيق Markdown (.md)","يعتمد على هيكل قالب GoodDocs"]},"version":4},"contentHash":"42e5283d7ef45421983dc0870f095f5d0bd41fa5cfc35bc0faa7cb30c70a9e11","qualityScore":20}');
