INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SidU/GoodDocs/doc-author', 'doc-author', 'SidU', 'GoodDocs', 'community', 'doc-author SidU GoodDocs community The doc-author skill assists users in creating new documents using the GoodDocs template, automating tasks such as determining the next numeric ID and setting frontmatter. It benefits developers and document authors. doc-author 是一种 AI 工具，用于指导用户创建新文档，使用 GoodDocs 模板和验证规则。它可以自动设置文档标题、动机、提案解决方案和替代方案等内容 doc-author は、GoodDocs テンプレートと検証ルールを使用して新しい文書を作成するための AI エージェントです。ユーザーは文書のタイトル、動機、提案された解決策、代替質問などを入力します doc-author는 사용자가 새로운 문서를 작성하는 것을 도와주는 AI 에이전트입니다. GoodDocs 템플릿과 검증 규칙을 사용하여 문서 제목, 동기, 제안된 해결책 및 대안 등을 생성합니다 El agente doc-author es una herramienta de AI que guía a los usuarios a través de la creación de un nuevo documento utilizando el template y las reglas de validación de GoodDocs L''agent doc-author est un outil d''IA qui guide les utilisateurs à travers la création d''un nouveau document en utilisant le modèle et les règles de validation de GoodDocs Der doc-author-Agent ist ein AI-Tool, das Benutzer durch die Erstellung eines neuen Dokuments mit dem GoodDocs-Template und den Validierungsregeln führt O doc-author é uma ferramenta que ajuda a criar documentos com o template e regras de validação do GoodDocs. Ele automatiza a criação de documentos ИИ Агент doc-author - это инструмент, помогающий создавать документы с помощью шаблона и правил проверки GoodDocs. Он автоматизирует создание документов وظيفة doc-author هي أداة تساعد في إنشاء مستندات باستخدام قالب و قواعد التحقق من GoodDocs. إنها توفير الوقت في إنشاء المستندات how to use doc-author doc-author setup guide what is doc-author doc-author alternative doc-author vs GoodDocs doc-author install automated document creation GoodDocs template document validation rules doc-author AI 工具 文档创建 GoodDocs 模板 验证规则 自动化文档 文档标题 动机 提案解决方案 替代方案 Automatically uses defaultDocTypeKey and defaultOwners from repo.config.json Asks users for title, motivation, proposed solution, and alternatives/open questions Determines the next numeric ID by scanning docs/<docRoot> for ####-*.md files Sets frontmatter id to DOC-#### and generates markdown files Validates user input using GoodDocs validation rules Supports GoodDocs template for document creation doc-author is an AI agent skill that automates the process of authoring new documents using predefined templates and validation rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fwojciec/quiver/work', 'community', 'fwojciec', 'quiver', 'fwojciec/quiver', 'work', 0, 0, 20, '2026-03-08T01:57:15.375Z', '2026-03-08T02:04:35.147Z', '494b4eca63cbf4369e0c7537dc15d4eac6a40d4b74321055df1b730bfa75f6a7', '{"id":"fwojciec/quiver/work","name":"work","description":{"en":"Work is a Rust query engine designed for reading data from multiple sources like BigQuery and PostgreSQL using Apache Arrow, benefiting developers and data engineers. It streamlines data integration and processing.","zh":"Work是一个Rust查询引擎，能够从多个数据源读取数据，如BigQuery和PostgreSQL，使用Apache Arrow进行数据处理","ja":"Workは、BigQueryやPostgreSQLなどの複数のデータソースからデータを読み込むことができるRustクエリエンジンで、Apache Arrowを使用してデータを処理します","ko":"Work는 러스트 쿼리 엔진으로 BigQuery와 PostgreSQL 등의 다중 데이터 소스에서 데이터를 읽어들이고 Apache Arrow로 데이터를 처리합니다","es":"Work es un motor de consulta de Rust para leer datos de múltiples fuentes como BigQuery y PostgreSQL utilizando Apache Arrow. Permite la implementación de pruebas unitarias y el manejo de issues de manera eficiente","fr":"Work est un moteur de requête Rust pour lire des données à partir de plusieurs sources telles que BigQuery et PostgreSQL en utilisant Apache Arrow. Il permet la mise en œuvre de tests unitaires et la gestion des problèmes de manière efficace","de":"Work ist ein Rust-Abfrage-Motor, um Daten aus mehreren Quellen wie BigQuery und PostgreSQL mit Apache Arrow zu lesen. Es ermöglicht die Implementierung von Einheitstests und die effiziente Handhabung von Issues","pt":"O Work é um motor de consulta Rust para ler dados de BigQuery e PostgreSQL usando Apache Arrow. Confira como configurá-lo","ru":"Работа - это движок запросов Rust для чтения данных из BigQuery и PostgreSQL, используя Apache Arrow. Узнайте, как его настроить","ar":"العمل هو محرك استعلام رست لقراءة البيانات من بيجكوري وبوستجرسكيول باستخدام أباتشي أرو. تعلم كيفية إعداده"},"seo":{"title":{"en":"Work: Apache Arrow-Powered Query Engine Setup Guide | AI ...","zh":"Work AI工具：Rust查询引擎设置指南","ja":"Work AIエージェント：Apache Arrowを使用した多源データ読み込み","ko":"Work AI 에이전트: 러스트 쿼리 엔진 설정 가이드","es":"Guía de configuración de Work: Motor de consulta de Rust ...","fr":"Guide de mise en place de Work : Moteur de requête Rust p...","de":"Work-Setup-Anleitung: Rust-Abfrage-Motor für BigQuery und...","pt":"Guia de Configuração do Work: Motor de Consulta Rust para...","ru":"Настройка Работы: Руководство по использованию Rust запро...","ar":"إعداد عمل: دليل لاستخدام محرك استعلام رست لبيجكوري وبوستج..."},"description":{"en":"Unlock efficient data reading from BigQuery and PostgreSQL with Work. Learn how to harness Apache Arrow for seamless data integration and discover expert tip...","zh":"使用Work AI工具，实现BigQuery和PostgreSQL等多源数据的高效读取，通过Apache Arrow进行数据处理","ja":"Work AIエージェントを使用して、BigQueryやPostgreSQLなどの複数のデータソースからデータを読み込み、Apache Arrowでデータを処理します","ko":"Work AI 에이전트를 사용하여 BigQuery와 PostgreSQL 등의 다중 데이터 소스를 효율적으로 읽고 Apache Arrow로 데이터를 처리합니다","es":"Aprende a utilizar Work, un motor de consulta de Rust para leer datos de múltiples fuentes como BigQuery y PostgreSQL utilizando Apache Arrow","fr":"Découvrez comment utiliser Work, un moteur de requête Rust pour lire des données à partir de plusieurs sources telles que BigQuery et PostgreSQL en utilisant...","de":"Erfahren Sie, wie Sie Work verwenden, einen Rust-Abfrage-Motor, um Daten aus mehreren Quellen wie BigQuery und PostgreSQL mit Apache Arrow zu lesen","pt":"Aprenda a configurar o Work, um motor de consulta Rust para ler dados de múltiplas fontes como BigQuery e PostgreSQL usando Apache Arrow","ru":"Узнайте, как настроить Работу, движок запросов Rust для чтения данных из нескольких источников, таких как BigQuery и PostgreSQL, используя Apache Arrow и ИИ ...","ar":"تعلم كيفية إعداد عمل، محرك استعلام رست لقراءة البيانات من مصادر متعددة مثل بيجكوري وبوستجرسكيول باستخدام أباتشي أرو وادوات الذكاء الاصطناعي"},"definition":{"en":"Work is a Rust-based query engine that utilizes Apache Arrow for efficient data reading from various sources, including BigQuery and PostgreSQL","zh":"Work是一个使用Rust语言开发的查询引擎，支持从多个数据源读取数据","ja":"Workは、Rustで開発されたクエリエンジンで、複数のデータソースからデータを読み込むことができます","ko":"Work는 러스트로 개발된 쿼리 엔진으로 다중 데이터 소스에서 데이터를 읽어들일 수 있습니다","es":"Work es un motor de consulta de Rust que permite leer datos de múltiples fuentes como BigQuery y PostgreSQL","fr":"Work est un moteur de requête Rust qui permet de lire des données à partir de plusieurs sources telles que BigQuery et PostgreSQL","de":"Work ist ein Rust-Abfrage-Motor, der das Lesen von Daten aus mehreren Quellen wie BigQuery und PostgreSQL ermöglicht","pt":"O Work é um motor de consulta Rust que lê dados de múltiplas fontes, incluindo BigQuery e PostgreSQL","ru":"Работа - это движок запросов Rust, который читает данные из нескольких источников, включая BigQuery и PostgreSQL","ar":"العمل هو محرك استعلام رست يقرأ البيانات من مصادر متعددة، بما في ذلك بيجكوري وبوستجرسكيول"},"features":{"en":["Fetches issue details and creates branches using kebab-title format","Supports Test-Driven Development (TDD) for behavior changes","Implements non-behavioral wiring and types directly","Confirms repository safety with a clean tree on the main branch","Lists open issues and allows users to select one for processing","Creates deterministic branches for issue tracking and resolution"],"zh":["支持从多个数据源读取数据，如BigQuery和PostgreSQL","使用Apache Arrow进行数据处理","实现TDD（测试驱动开发）行为变化","直接实现非行为性质的连线和类型","创建分支以便于issue跟踪"],"ja":["BigQueryやPostgreSQLなどの複数のデータソースからデータを読み込むことができる","Apache Arrowを使用してデータを処理する","TDD（テスト駆動開発）による動作変更の実装","非動作的性質のワイヤリングやタイプの直接実装","issueのトラッキングのためにブランチを作成する"],"ko":["BigQuery와 PostgreSQL 등의 다중 데이터 소스에서 데이터를 읽어들일 수 있다","Apache Arrow로 데이터를 처리한다","TDD（테스트 주도 개발）를 통해 동작 변경을 구현한다","비동작적 속성의 와이어링 및 유형을 직접 구현한다","이슈 추적을 위해 브랜치를 생성한다"],"es":["Soporte para BigQuery y PostgreSQL","Utiliza Apache Arrow para la lectura de datos","Implementación de pruebas unitarias con TDD","Manejo eficiente de issues con confirmación de estado de repositorio","Creación de ramas con títulos en kebab-case"],"fr":["Prise en charge de BigQuery et PostgreSQL","Utilise Apache Arrow pour la lecture de données","Mise en œuvre de tests unitaires avec TDD","Gestion efficace des problèmes avec confirmation de l''état du référentiel","Création de branches avec des titres en kebab-case"],"de":["Unterstützung für BigQuery und PostgreSQL","Verwenden von Apache Arrow für die Datenlektüre","Implementierung von Einheitstests mit TDD","Effiziente Handhabung von Issues mit Bestätigung des Repository-Zustands","Erstellung von Branches mit Titeln im kebab-Format"],"pt":["Leitura de dados de BigQuery e PostgreSQL","Uso de Apache Arrow para processamento de dados","Implementação de TDD para mudanças de comportamento","Criação de branch para issues com título em kebab-case","Fetch de detalhes de issues, incluindo comentários"],"ru":["Чтение данных из BigQuery и PostgreSQL","Использование Apache Arrow для обработки данных","Реализация TDD для изменений поведения","Создание ветки для проблем с названием в kebab-case","Получение деталей проблем, включая комментарии, с помощью ИИ Агентов"],"ar":["قراءة البيانات من بيجكوري وبوستجرسكيول","استخدام أباتشي أرو للتحليل البياني","تنفيذ TDD لتغيرات السلوك","إنشاء فرع للاشكالات بعنوان kebab-case","استرجاع تفاصيل الاشكالات، بما في ذلك التعليقات، مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use work with Apache Arrow","work vs other query engines","work setup guide for BigQuery","what is work in data engineering","work alternative for PostgreSQL","work install for Rust developers","work tutorial for data integration","work best practices for efficient data reading","work documentation for AI agents"],"zh":["Work AI工具","Rust查询引擎","Apache Arrow","BigQuery","PostgreSQL","多源数据读取","TDD","测试驱动开发"],"ja":["Work AIエージェント","Rustクエリエンジン","Apache Arrow","BigQuery","PostgreSQL","複数データソース","TDD","テスト駆動開発"],"ko":["Work AI 에이전트","러스트 쿼리 엔진","Apache Arrow","BigQuery","PostgreSQL","다중 데이터 소스","TDD","테스트 주도 개발"],"es":["work ai agent","motor de consulta de rust","bigquery y postgresql","apache arrow","tdd en rust","manejo de issues en git","desarrollo de software con rust"],"fr":["work ai outil","moteur de requête rust","bigquery et postgresql","apache arrow","tdd en rust","gestion de problèmes sur git","développement de logiciels avec rust"],"de":["work ai agent","rust-abfrage-motor","bigquery und postgresql","apache arrow","tdd in rust","issue-handling in git","software-entwicklung mit rust"],"pt":["Work","Rust","BigQuery","PostgreSQL","Apache Arrow","TDD","Desenvolvimento de software","Motor de consulta","Leitura de dados"],"ru":["Работа","Rust","BigQuery","PostgreSQL","Apache Arrow","TDD","Разработка программного обеспечения","Движок запросов","Чтение данных","ИИ Агенты"],"ar":["العمل","Rust","بيجكوري","بوستجرسكيول","أباتشي أرو","TDD","تطوير البرمجيات","محرك استعلام","قراءة البيانات","أدوات الذكاء الاصطناعي"]}},"owner":"fwojciec","repo":"quiver","repoPath":"fwojciec/quiver","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.375Z","topics":[],"category":"community","skillMd":{"name":"work","description":"Execute an end-to-end GitHub issue workflow: select an issue, branch, implement with tests, validate, review, and open a PR. Use when asked to work on issue X or deliver a complete implementation workflow.","bodyPreview":"# Work Issue End-to-End\n\nDrive issue work from selection to PR with minimal back-and-forth.\n\n## Phase 1: Preflight + Selection\n\n1. Confirm repo is in a safe starting state (usually clean tree on `main`).\n2. If issue number is missing, list open issues and ask user to pick one.\n3. Fetch issue details (including comments) and create branch `<number>-<kebab-title>`.\n\n## Phase 2: Implement\n\n1. Prefer TDD for behavior changes (red/green/refactor).\n2. Implement non-behavioral wiring/types directly.\n3.","body":"# Work Issue End-to-End\n\nDrive issue work from selection to PR with minimal back-and-forth.\n\n## Phase 1: Preflight + Selection\n\n1. Confirm repo is in a safe starting state (usually clean tree on `main`).\n2. If issue number is missing, list open issues and ask user to pick one.\n3. Fetch issue details (including comments) and create branch `<number>-<kebab-title>`.\n\n## Phase 2: Implement\n\n1. Prefer TDD for behavior changes (red/green/refactor).\n2. Implement non-behavioral wiring/types directly.\n3. Run `make validate` during development.\n4. Keep scope aligned with issue constraints.\n\n## Phase 3: Review\n\n1. Run `code-review` skill.\n2. Run `review-with-gemini` when available.\n3. Apply straightforward fixes automatically.\n4. If blocking feedback remains, pause and present options:\n   - fix and re-review,\n   - proceed with explicit override,\n   - stop and document learnings.\n\n## Phase 4: Finalize\n\n1. Run full checks (`make validate-full` when available, else project equivalent).\n2. Commit cleanly.\n3. Push branch and open PR with summary + test plan + `Closes #<issue>`.\n4. Comment on issue with PR link and validation status.\n\n## Phase 5: Handoff\n\nAfter PR creation, ask whether to:\n1. merge now,\n2. leave for user merge,\n3. keep iterating on branch.\n\nPrefer ending in a clean local state on latest `main` unless user wants continued branch work.\n"},"lastSynced":"2026-03-08T02:04:35.147Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Engineering Agents requiring streamlined multi-source data integration with Apache Arrow.","zh":"适用于需要使用 Apache Arrow 进行多源数据集成的数据工程 Agent 的理想选择","ja":"Apache Arrow を使用したマルチソースデータ統合を必要とするデータエンジニアリングエージェントに最適","ko":"Apache Arrow를 사용한 멀티 소스 데이터 통합이 필요한 데이터 엔지니어링 에이전트에 적합","es":"Ideal para Agentes de Ingeniería de Datos que requieren una integración de datos de múltiples fuentes simplificada con Apache Arrow.","fr":"Idéal pour les agents d''ingénierie de données nécessitant une intégration de données multi-sources simplifiée avec Apache Arrow.","de":"Ideal für Data-Engineering-Agents, die eine vereinfachte Multi-Quellen-Datenintegration mit Apache Arrow benötigen.","pt":"Ideal para Agentes de Engenharia de Dados que exigem integração de dados de múltiplas fontes simplificada com Apache Arrow.","ru":"Идеально подходит для агентов инженерии данных, требующих упрощенной многократной интеграции данных с Apache Arrow.","ar":"مثالية لوكلاء هندسة البيانات الذين يحتاجون إلى دمج بيانات متعددة المصادر مبسط مع Apache Arrow."},"recommendation":{"en":"Enables agents to drive issue work from selection to PR with minimal back-and-forth using TDD methodology. It provides direct implementation of non-behavioral wiring/types and leverages Rust for reading data from BigQuery and PostgreSQL sources.","zh":"使得 Agent 能够从选择到 PR 的整个过程中使用 TDD 方法论以最小化来回操作。它提供了非行为绑定/类型的直接实现，并利用 Rust 从 BigQuery 和 PostgreSQL 源读取数据","ja":"エージェントが選択から PR までの作業を TDD 方法論を使用して最小限のやり取りで実行できるようにします。非動作的配線/タイプの直接的な実装を提供し、BigQuery および PostgreSQL ソースからのデータの読み取りに Rust を使用します","ko":"에이전트가 선택에서 PR까지의 작업을 TDD 방법론을 사용하여 최소한의 왕복 작업으로 수행할 수 있도록 합니다. 비동작 연결/타입의 직접 구현을 제공하며 BigQuery 및 PostgreSQL 소스에서 데이터를 읽어오기 위해 Rust를 사용합니다","es":"Permite a los agentes impulsar el trabajo de problemas desde la selección hasta la PR con un mínimo de ida y vuelta utilizando la metodología TDD. Proporciona una implementación directa de cableado/tipos no comportamentales y aprovecha Rust para leer datos desde fuentes BigQuery y PostgreSQL.","fr":"Permet aux agents de piloter les travaux de problèmes de la sélection à la PR avec un minimum d''aller-retour en utilisant la méthodologie TDD. Il fournit une mise en œuvre directe de câblage/types non comportementaux et utilise Rust pour lire des données à partir de sources BigQuery et PostgreSQL.","de":"Ermöglicht es Agents, Problem-Arbeit von der Auswahl bis zur PR mit minimaler Rückkehr zu treiben, indem die TDD-Methode verwendet wird. Es bietet eine direkte Implementierung von nicht-verhaltensbezogenem Verkabelung/Typen und nutzt Rust, um Daten aus BigQuery- und PostgreSQL-Quellen zu lesen.","pt":"Permite que os agentes conduzam o trabalho de problemas desde a seleção até a PR com mínimo retorno usando a metodologia TDD. Ele fornece implementação direta de fios/tipos não comportamentais e aproveita Rust para ler dados de fontes BigQuery e PostgreSQL.","ru":"Позволяет агентам управлять работой над проблемами от выбора до PR с минимальным обменом информацией, используя методологию TDD. Он обеспечивает прямую реализацию не-бихевиоральных проводов/типов и использует Rust для чтения данных из источников BigQuery и PostgreSQL.","ar":"تمكن الوكلاء من تشغيل عمل القضايا من التحديد إلى Requests مع الحد الأدنى من التبادل باستخدام منهجية TDD. يوفر التنفيذ المباشر للأسلاك / الأنواع غير السلوكية ويستفيد من Rust لقراءة البيانات من مصادر BigQuery و PostgreSQL."},"useCases":{"en":["Automating data integration workflows","Implementing TDD for behavior changes","Streamlining PR creation from issue selection"],"zh":["自动化数据集成工作流程","为行为变化实施 TDD","从问题选择到 PR 创建的简化"],"ja":["データ統合ワークフローの自動化","動作の変更に対する TDD の実装","問題の選択から PR の作成までの簡素化"],"ko":["데이터 통합 워크플로의 자동화","동작의 변경에 대한 TDD의 구현","문제 선택에서 PR 생성까지의 간소화"],"es":["Automatización de flujos de trabajo de integración de datos","Implementación de TDD para cambios de comportamiento","Optimización de la creación de PR desde la selección de problemas"],"fr":["Automatisation des flux de travail d''intégration de données","Implémentation de TDD pour les changements de comportement","Optimisation de la création de PR à partir de la sélection de problèmes"],"de":["Automatisierung von Daten-Integrations-Workflows","Implementierung von TDD für Verhaltensänderungen","Optimierung der PR-Erstellung von der Problemauswahl"],"pt":["Automatizar fluxos de trabalho de integração de dados","Implementar TDD para alterações de comportamento","Simplificar a criação de PR a partir da seleção de problemas"],"ru":["Автоматизация рабочих процессов интеграции данных","Реализация TDD для изменений поведения","Упрощение создания PR из выбора проблем"],"ar":["توفير أتمتة سير عمل دمج البيانات","تنفيذ TDD لتغييرات السلوك","تبسيط إنشاء Requests من تحديد المشكلات"]},"limitations":{"en":["Requires clean repo state on main branch","Depends on Apache Arrow infrastructure","Needs issue number input for branch creation"],"zh":["需要主分支上的干净仓库状态","依赖于 Apache Arrow 基础设施","需要问题编号输入以创建分支"],"ja":["メインブランチ上のクリーンなリポジトリ状態が必要","Apache Arrow インフラストラクチャに依存","ブランチの作成には問題番号の入力が必要"],"ko":["메인 브랜치上的 깨끗한 리포지토리 상태가 필요","Apache Arrow 인프라스트럭처에 의존","브랜치 생성을 위해 문제 번호 입력이 필요"],"es":["Requiere un estado de repositorio limpio en la rama principal","Depende de la infraestructura de Apache Arrow","Necesita la entrada del número de problema para la creación de ramas"],"fr":["Nécessite un état de référentiel propre sur la branche principale","Dépend de l''infrastructure Apache Arrow","Nécessite la saisie du numéro de problème pour la création de branches"],"de":["Benötigt einen sauberen Repository-Zustand auf dem Hauptzweig","Hängt von der Apache Arrow-Infrastruktur ab","Benötigt die Eingabe der Problemmummer für die Erstellung von Zweigen"],"pt":["Exige um estado de repositório limpo na branch principal","Depende da infraestrutura do Apache Arrow","Necessita da entrada do número da problema para criação de branch"],"ru":["Требует чистого состояния репозитория в основной ветке","Зависит от инфраструктуры Apache Arrow","Требует ввода номера проблемы для создания ветки"],"ar":["يتطلب حالة مستودع نظيفة على الفرع الرئيسي","يعتمد على بنية تحتية Apache Arrow","يحتاج إلى إدخال رقم المشكلة لإنشاء الفرع"]},"version":4},"contentHash":"494b4eca63cbf4369e0c7537dc15d4eac6a40d4b74321055df1b730bfa75f6a7","qualityScore":20}');
