INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fwojciec/quiver/work', 'work', 'fwojciec', 'quiver', 'community', 'work fwojciec quiver community Work is a Rust query engine designed for reading data from multiple sources like BigQuery and PostgreSQL using Apache Arrow, benefiting developers and data engineers. It streamlines data integration and processing. Work是一个Rust查询引擎，能够从多个数据源读取数据，如BigQuery和PostgreSQL，使用Apache Arrow进行数据处理 Workは、BigQueryやPostgreSQLなどの複数のデータソースからデータを読み込むことができるRustクエリエンジンで、Apache Arrowを使用してデータを処理します Work는 러스트 쿼리 엔진으로 BigQuery와 PostgreSQL 등의 다중 데이터 소스에서 데이터를 읽어들이고 Apache Arrow로 데이터를 처리합니다 Work es un motor de consulta de Rust para leer datos de múltiples fuentes como BigQuery y PostgreSQL utilizando Apache Arrow. Permite la implementación de pruebas unitarias y el manejo de issues de manera eficiente Work est un moteur de requête Rust pour lire des données à partir de plusieurs sources telles que BigQuery et PostgreSQL en utilisant Apache Arrow. Il permet la mise en œuvre de tests unitaires et la gestion des problèmes de manière efficace Work ist ein Rust-Abfrage-Motor, um Daten aus mehreren Quellen wie BigQuery und PostgreSQL mit Apache Arrow zu lesen. Es ermöglicht die Implementierung von Einheitstests und die effiziente Handhabung von Issues O Work é um motor de consulta Rust para ler dados de BigQuery e PostgreSQL usando Apache Arrow. Confira como configurá-lo Работа - это движок запросов Rust для чтения данных из BigQuery и PostgreSQL, используя Apache Arrow. Узнайте, как его настроить العمل هو محرك استعلام رست لقراءة البيانات من بيجكوري وبوستجرسكيول باستخدام أباتشي أرو. تعلم كيفية إعداده how to use work with Apache Arrow work vs other query engines work setup guide for BigQuery what is work in data engineering work alternative for PostgreSQL work install for Rust developers work tutorial for data integration work best practices for efficient data reading work documentation for AI agents Work AI工具 Rust查询引擎 Apache Arrow BigQuery PostgreSQL 多源数据读取 TDD 测试驱动开发 Fetches issue details and creates branches using kebab-title format Supports Test-Driven Development (TDD) for behavior changes Implements non-behavioral wiring and types directly Confirms repository safety with a clean tree on the main branch Lists open issues and allows users to select one for processing Creates deterministic branches for issue tracking and resolution Work is a Rust-based query engine that utilizes Apache Arrow for efficient data reading from various sources, including BigQuery and PostgreSQL');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('maitlandmarshall/voltaire/pdf-to-md', 'community', 'maitlandmarshall', 'voltaire', 'maitlandmarshall/voltaire', 'pdf-to-md', 0, 0, 20, '2026-03-08T01:57:15.380Z', '2026-03-08T02:05:37.402Z', '30546bfb1214624d88285a852e653f948f1bb2c445379f5dae927d6f2a42d3a6', '{"id":"maitlandmarshall/voltaire/pdf-to-md","name":"pdf-to-md","description":{"en":"The pdf-to-md skill converts campaign PDFs into Obsidian-friendly Markdown, extracting embedded images into a sibling folder. It benefits developers and users working with PDFs and Markdown files.","zh":"pdf-to-md 技能用于将 PDF 文件转换为 Obsidian 友好的 Markdown 格式，并支持提取嵌入的图像","ja":"PDF to Markdown 変換ツールは、PDF ファイルを Obsidian フレンドリーな Markdown 形式に変換し、埋め込まれた画像を抽出する機能を提供します","ko":"pdf-to-md 기능은 PDF 파일을 Obsidian 친화적인 Markdown 형식으로 변환하고 내장된 이미지를 추출하는 데 사용됩니다","es":"El skill pdf-to-md permite convertir documentos PDF en Markdown y extraer imágenes con Python y CLI","fr":"Le skill pdf-to-md permet de convertir des documents PDF en Markdown et d''extraire des images avec Python et CLI","de":"Das Skill pdf-to-md ermöglicht die Umwandlung von PDF-Dokumenten in Markdown und die Extraktion von Bildern mit Python und CLI","pt":"O pdf-to-md é uma habilidade que converte PDFs em Markdown, permitindo a extração de imagens em uma pasta irmã. Use com Python e linha de comando para automatizar tarefas","ru":"pdf-to-md - это навык, который конвертирует PDF в Markdown, позволяя извлекать изображения в соседнюю папку. Используйте с Python и командной строкой для автоматизации задач с помощью ИИ Агентов","ar":"pdf-to-md هو مهارة تقوم بتحويل PDF إلى Markdown، مما يسمح bằng استخراج الصور في مجلد شقيق. استخدم مع Python وسطر الأوامر لآليّة المهام مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"pdf-to-md: Markdown Conversion Setup Guide | AI Agent Skill","zh":"PDF 到 Markdown 转换工具 - AIエージェント快速指南","ja":"PDF to Markdown 変換ツール - AIエージェントのベストプラクティス","ko":"PDF to Markdown 변환 도구 - AI 에이전트 설정 가이드","es":"Guía de configuración de pdf-to-md: Conversión de PDF a M...","fr":"Guide de démarrage rapide de pdf-to-md: Conversion de PDF...","de":"Einrichtungsleitfaden für pdf-to-md: PDF in Markdown umwa...","pt":"Guia de Configuração do pdf-to-md: Conversão de PDF para ...","ru":"Настройка pdf-to-md: Руководство по конвертации PDF в Mar...","ar":"دليل إعداد pdf-to-md: تحويل PDF إلى Markdown باستخدام أدو..."},"description":{"en":"Unlock efficient PDF conversions with pdf-to-md! Learn how to convert campaign PDFs to Obsidian-friendly Markdown and extract images with ease. Get started now!","zh":"使用 pdf-to-md 技能将 PDF 文件转换为 Obsidian 友好的 Markdown 格式，并提取嵌入的图像","ja":"PDF to Markdown 変換ツールを使用して、PDF ファイルを Obsidian フレンドリーな Markdown 形式に変換し、埋め込まれた画像を抽出します","ko":"pdf-to-md 기능을 사용하여 PDF 파일을 Obsidian 친화적인 Markdown 형식으로 변환하고 내장된 이미지를 추출합니다","es":"Aprende a utilizar pdf-to-md para convertir documentos PDF en Markdown y extraer imágenes con Python y CLI","fr":"Découvrez comment utiliser pdf-to-md pour convertir des documents PDF en Markdown et extraire des images avec Python et CLI","de":"Erfahren Sie, wie Sie pdf-to-md verwenden, um PDF-Dokumente in Markdown umzuwandeln und Bilder mit Python und CLI zu extrahieren","pt":"Aprenda a usar o pdf-to-md para converter PDFs em Markdown e extrair imagens em uma pasta irmã, com exemplos de linha de comando em Python","ru":"Узнайте, как использовать pdf-to-md для конвертации PDF в Markdown и извлечения изображений в соседнюю папку, с примерами командной строки на Python и ИИ Аге...","ar":"تعرف على كيفية استخدام pdf-to-md لتحويل PDF إلى Markdown واستخراج الصور في مجلد شقيق، مع أمثلة على سطر الأوامر في Python وأدوات الذكاء الاصطناعي"},"definition":{"en":"pdf-to-md is a skill that converts PDF files to Markdown format, optionally extracting embedded images into a sibling folder for easy access and organization.","zh":"pdf-to-md 是一种将 PDF 文件转换为 Markdown 格式的 AI 技能","j