INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('maitlandmarshall/voltaire/pdf-to-md', 'pdf-to-md', 'maitlandmarshall', 'voltaire', 'community', 'pdf-to-md maitlandmarshall voltaire community The pdf-to-md skill converts campaign PDFs into Obsidian-friendly Markdown, extracting embedded images into a sibling folder. It benefits developers and users working with PDFs and Markdown files. pdf-to-md 技能用于将 PDF 文件转换为 Obsidian 友好的 Markdown 格式，并支持提取嵌入的图像 PDF to Markdown 変換ツールは、PDF ファイルを Obsidian フレンドリーな Markdown 形式に変換し、埋め込まれた画像を抽出する機能を提供します pdf-to-md 기능은 PDF 파일을 Obsidian 친화적인 Markdown 형식으로 변환하고 내장된 이미지를 추출하는 데 사용됩니다 El skill pdf-to-md permite convertir documentos PDF en Markdown y extraer imágenes con Python y CLI Le skill pdf-to-md permet de convertir des documents PDF en Markdown et d''extraire des images avec Python et CLI Das Skill pdf-to-md ermöglicht die Umwandlung von PDF-Dokumenten in Markdown und die Extraktion von Bildern mit Python und CLI O pdf-to-md é uma habilidade que converte PDFs em Markdown, permitindo a extração de imagens em uma pasta irmã. Use com Python e linha de comando para automatizar tarefas pdf-to-md - это навык, который конвертирует PDF в Markdown, позволяя извлекать изображения в соседнюю папку. Используйте с Python и командной строкой для автоматизации задач с помощью ИИ Агентов pdf-to-md هو مهارة تقوم بتحويل PDF إلى Markdown، مما يسمح bằng استخراج الصور في مجلد شقيق. استخدم مع Python وسطر الأوامر لآليّة المهام مع أدوات الذكاء الاصطناعي how to use pdf-to-md pdf-to-md alternative pdf-to-md setup guide pdf to markdown conversion obsidian markdown conversion python pdf conversion pdf-to-md install pdf-to-md vs smallpdf pdf-to-md AI 技能 PDF 转换 Markdown 格式 Obsidian 友好 图像提取 Python 脚本 CLI 命令行工具 批量转换 根目录转换 Converts PDF files to Obsidian-friendly Markdown using Python 3 Extracts embedded images into a sibling folder Supports conversion of single PDF files or all PDFs under a specified root directory Utilizes the `pdf_to_md.py` script for conversion Allows for forced conversion using the `--force` command pdf-to-md is a skill that converts PDF files to Markdown format, optionally extracting embedded images into a sibling folder for easy access and organization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LDmoxeii/only-danmuku/cleanddd-requirements-analysis', 'community', 'LDmoxeii', 'only-danmuku', 'LDmoxeii/only-danmuku', 'cleanddd-requirements-analysis', 0, 0, 20, '2026-03-08T01:57:15.380Z', '2026-03-08T02:05:38.192Z', 'fbe1286fd06abb40c587c811ebafac718aeda4317c8b83126b262d95097502eb', '{"id":"LDmoxeii/only-danmuku/cleanddd-requirements-analysis","name":"cleanddd-requirements-analysis","description":{"en":"The cleanddd-requirements-analysis skill enables AI agents to perform demand analysis and produce structured descriptions for CleanDDD modeling, benefiting developers and modelers. It analyzes business needs and breaks them down into actionable items.","zh":"CleanDDD需求分析技能是面向CleanDDD建模前的需求澄清与拆解，产出的结构化需求描述","ja":"CleanDDD要件分析AIエージェントは、CleanDDDモデリング前の要件分析と分解を行い、構造化された要件記述を生成します","ko":"CleanDDD 요구 사항 분석 도구는 CleanDDD 모델링 전의 요구 사항 분석과 분해를 수행하여 구조화된 요구 사항 설명을 생성합니다","es":"cleanddd-requirements-analysis es una habilidad que analiza requisitos y estructura descripciones de requisitos para un modelado eficaz","fr":"cleanddd-requirements-analysis est une compétence qui analyse les exigences et structure les descriptions de requisitos pour un modelage efficace","de":"cleanddd-requirements-analysis ist eine Fähigkeit, die Anforderungen analysiert und Anforderungsbeschreibungen strukturiert für ein effektives Modellieren","pt":"O cleanddd-requirements-analysis é uma habilidade que realiza análise de requisitos e descrição estruturada para projetos de desenvolvimento de software","ru":"ИИ Агент cleanddd-requirements-analysis выполняет анализ требований и структурированное описание для проектов разработки ПО","ar":"cleanddd-requirements-analysis هو مهارة تقوم بتحليل المتطلبات والوصف الهيكلي لمشاريع تطوير البرمجيات"},"seo":{"title":{"en":"cleanddd-requirements-analysis: Setup Guide for AI Agents","zh":"CleanDDD 需求分析技能