INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('willyu1007/Skill_Template_Basic/apply-backend-database-patterns', 'apply-backend-database-patterns', 'willyu1007', 'Skill_Template_Basic', 'community', 'apply-backend-database-patterns willyu1007 Skill_Template_Basic community The apply-backend-database-patterns skill integrates standard skills into a repository template, benefiting developers who need to apply backend database patterns efficiently. It provides a canonical source for skills and supporting files. 本技能提供一个集成标准技能的存储库模板，用于应用后端数据库模式 このスキルは、バックエンドデータベースパターンを適用するための標準スキルを統合したリポジトリテンプレートを提供します 이 스킬은 백엔드 데이터베이스 패턴을 적용하기 위한 표준 스킬을 통합한 저장소 템플릿을 제공합니다 La habilidad apply-backend-database-patterns es una plantilla de repositorio que integra patrones de base de datos estándar para proyectos backend La compétence apply-backend-database-patterns est un modèle de référentiel qui intègre des modèles de base de données standard pour les projets backend Die Fähigkeit apply-backend-database-patterns ist eine Repository-Vorlage, die Standard-Datenbankmuster für Backend-Projekte integriert O apply-backend-database-patterns é um modelo de repositório que integra habilidades padrão para desenvolvedores Применение шаблонов базы данных бэкенда - это модель репозитория, которая интегрирует стандартные навыки для разработчиков نماذج قواعد البيانات الخلفية هو نموذج مستودع يدمج المهارات القياسية للمطورين how to use apply-backend-database-patterns apply-backend-database-patterns setup guide what is apply-backend-database-patterns apply-backend-database-patterns alternative apply-backend-database-patterns vs repository templates apply-backend-database-patterns install Apply Backend Database Patterns AI工具 后端数据库模式 开发效率 存储库模板 标准技能 后端数据库 Integrates standard skills into a repository template Utilizes SKILL.md and supporting files for efficient pattern application References canonical source at .ai/skills/backend/data/apply-backend-database-patterns/ Supports opening and utilizing reference.md, examples.md, scripts/, and templates/ Provides a consistent frontmatter for navigation and organization apply-backend-database-patterns is a repository template that integrates standard skills for efficient backend database pattern application.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mbtz/morningweave/issue-tracking', 'community', 'mbtz', 'morningweave', 'mbtz/morningweave', 'issue-tracking', 0, 0, 20, '2026-03-08T01:57:15.389Z', '2026-03-08T02:06:00.068Z', 'a335dbd1836b9fe6683f34c5cebbd7a4ac77311df8ce8c09ffbf254f22c6a181', '{"id":"mbtz/morningweave/issue-tracking","name":"issue-tracking","description":{"en":"The issue-tracking skill provides a helper CLI tool for curating news, utilizing tk commands for efficient issue management, benefiting developers and teams.","zh":"使用tk命令行工具进行问题跟踪，支持查看、开始和关闭问题单","ja":"tk CLIツールを使用してIssue Trackingを実行します","ko":"tk 명령어 도구를 사용하여 이슈 트래킹을 수행합니다","es":"La herramienta CLI de seguimiento de incidencias permite gestionar tickets de trabajo con comandos como ''tk ready'' y ''tk show''.","fr":"L''outil CLI de suivi des problèmes permet de gérer les tickets de travail avec des commandes comme ''tk ready'' et ''tk show''.","de":"Das CLI-Tool für die Verfolgung von Problemtickets ermöglicht die Verwaltung von Arbeitstickets mit Befehlen wie ''tk ready'' und ''tk show''.","pt":"O tk é uma ferramenta CLI para rastreamento de problemas que permite listar trabalhos prontos, visualizar detalhes e marcar trabalhos em andamento","ru":"ИИ Агент tk - это инструмент командной строки для отслеживания проблем, который позволяет перечислить готовые работы, просмотреть детали и отметить работу в процессе","ar":"أداة tk هي أداة سطر أوامر لتعقب المشكلات التي تسمح بقائمة العمل الجاهز وعرض التفاصيل وتحديد العمل قيد التقدم"},"seo":{"title":{"en":"Issue-Tracking: CLI Tool Setup Guide | AI Agent Skill","zh":"Issue Tracking Setup Guide - AIエージェント工具","ja":"Issue Tracking ベストプラクティス - AIエージェント","ko":"이슈 트래킹 가이드 - AI 에이전트 도구","es":"Guía de Configuración de Seguimiento de Incidencias con CLI","fr":"Guide de Configuration de Suivi des Problèmes avec CLI","de":"Einrichtungsleitfaden für Problemticket-Verfolgung mit CLI","pt":"Guia de Configuração de Rastreamento de Problemas com tk","ru":"Настройка отслеживания проблем с помощью ИИ Агентов и tk","ar":"دليل إعداد تتبع المشكلات باستخدام أدوات ذكاء اصطناعي و tk"},"description":{"en":"Discover how to streamline issue tracking with tk commands. Learn to curate news and manage tickets efficiently - get started now!","zh":"使用tk命令行工具进行问题跟踪，提高开发效率，了解更多关于AIエージェント的信息","ja":"Issue Trackingを効率化するために、tk CLIツールを使用する方法について学びます - AIエージェント","ko":"이슈 트래킹을 위한 tk 명령어 도구 사용법, 개발 생산성을 높이세요 - AI 에이전트","es":"Aprenda a utilizar la herramienta CLI para el seguimiento de incidencias en su proyecto con comandos como ''tk ready'' y ''tk show''","fr":"Découvrez comment utiliser l''outil CLI pour suivre les problèmes dans votre projet avec des commandes comme ''tk ready'' et ''tk show''","de":"Erfahren Sie, wie Sie das CLI-Tool für die Verfolgung von Problemtickets in Ihrem Projekt mit Befehlen wie ''tk ready'' und ''tk show'' verwenden","pt":"Aprenda a usar tk para rastrear problemas no repositório, incluindo listagem de trabalhos prontos e visualização de detalhes","ru":"Узнайте, как использовать tk для отслеживания проблем в репозитории, включая список готовых работ и просмотр деталей","ar":"تعلم كيفية استخدام tk لتعقب المشكلات في المستودع، بما في ذلك قائمة العمل الجاهز وعرض التفاصيل"},"definition":{"en":"Issue-tracking is a process of managing and curating issues using a command-line interface tool, such as tk, for streamlined workflow and productivity.","zh":"Issue Tracking是使用tk命令行工具来管理和跟踪问题单的过程","ja":"Issue Trackingは、tk CLIツールを使用して問題を管理および追跡するプロセスです","ko":"이슈 트래킹은 tk 명령어 도구를 사용하여 문제를 관리하고 추적하는 과정입니다","es":"El seguimiento de incidencias es una herramienta que utiliza CLI para gestionar y resolver problemas en un proyecto.","fr":"Le suivi des problèmes est un outil qui utilise CLI pour gérer et résoudre des problèmes dans un projet.","de":"Die Verfolgung von Problemtickets ist ein Tool, das CLI verwendet, um Probleme in einem Projekt zu verwalten und zu lösen.","pt":"Rastreamento de problemas é o processo de acompanhamento e gerenciamento de problemas ou erros em um repositório","ru":"Отслеживание проблем - это процесс отслеживания и управления проблемами или ошибками в репозитории","ar":"تتبع المشكلات هو عملية متابعة وإدارة المشكلات أو الأخطاء في مستودع"},"features":{"en":["Utilizes tk commands for issue tracking and management","Lists ready work with `tk ready` command","Views details with `tk show <id>` command","Supports marking work in progress with `tk start <id>` command","Closes work with `tk close <id>` command","Stores tickets in `.tickets/` directory for version control"],"zh":["使用tk ready命令列出待处理的问题","使用tk show命令查看问题单详情","使用tk start命令标记问题单为处理中","使用tk close命令关闭问题单","问题单存储在.tickets/目录中","支持与代码变更一起提交问题单"],"ja":["tk readyコマンドを使用して処理待ちの問題をリストします","tk showコマンドを使用して問題の詳細を表示します","tk startコマンドを使用して問題を処理中としてマークします","tk closeコマンドを使用して問題を閉じます","問題は.tickets/ディレクトリに保存されます","コード変更と一緒に問題をコミットすることができます"],"ko":["tk ready 명령어를 사용하여 처리 대기 중인 문제를 목록화합니다","tk show 명령어를 사용하여 문제 세부 정보를 표시합니다","tk start 명령어를 사용하여 문제를 처리 중으로 표시합니다","tk close 명령어를 사용하여 문제를 닫습니다","문제는 .tickets/ 디렉토리에 저장됩니다","코드 변경과 함께 문제를 커밋할 수 있습니다"],"es":["Utiliza comandos como ''tk ready'' para listar el trabajo listo","Utiliza comandos como ''tk show'' para ver detalles de los tickets","Utiliza comandos como ''tk start'' para marcar el trabajo en progreso","Utiliza comandos como ''tk close'' para cerrar los tickets","Almacena los tickets en el directorio ''.tickets/''","Se integra con los cambios de código relacionados"],"fr":["Utilise des commandes comme ''tk ready'' pour lister le travail prêt","Utilise des commandes comme ''tk show'' pour afficher les détails des tickets","Utilise des commandes comme ''tk start'' pour marquer le travail en cours","Utilise des commandes comme ''tk close'' pour fermer les tickets","Stocke les tickets dans le répertoire ''.tickets/''","S''intègre avec les modifications de code associées"],"de":["Verwendet Befehle wie ''tk ready'', um bereite Arbeit zu listen","Verwendet Befehle wie ''tk show'', um Details der Tickets anzuzeigen","Verwendet Befehle wie ''tk start'', um die Arbeit als im Gange zu markieren","Verwendet Befehle wie ''tk close'', um Tickets zu schließen","Speichert Tickets im Verzeichnis ''.tickets/''","Integriert sich mit den zugehörigen Codeänderungen"],"pt":["Listagem de trabalhos prontos com `tk ready`","Visualização de detalhes com `tk show <id>`","Marcar trabalhos em andamento com `tk start <id>`","Fechamento de trabalhos com `tk close <id>`","Armazenamento de tickets em `.tickets/`"],"ru":["Список готовых работ с `tk ready`","Просмотр деталей с `tk show <id>`","Отметка работы в процессе с `tk start <id>`","Закрытие работы с `tk close <id>`","Хранение тикетов в `.tickets/`"],"ar":["قائمة العمل الجاهز مع `tk ready`","عرض التفاصيل مع `tk show <id>`","تحديد العمل قيد التقدم مع `tk start <id>`","إغلاق العمل مع `tk close <id>`","تخزين التذاكر في `.tickets/`"]},"keywords":{"en":["how to use issue-tracking","issue-tracking cli tool","issue-tracking alternative","issue-tracking vs jira","issue-tracking install","issue-tracking setup guide","tk command reference","issue tracking best practices"],"zh":["Issue Tracking","AIエージェント","tk命令行工具","问题跟踪","CLI工具","代码变更","问题管理"],"ja":["Issue Tracking","AIエージェント","tk CLIツール","問題追跡","CLIツール","コード変更","問題管理"],"ko":["이슈 트래킹","AI 에이전트","tk 명령어 도구","문제 추적","CLI 도구","코드 변경","문제 관리"],"es":["seguimiento de incidencias","herramienta CLI","gestión de tickets","tk ready","tk show","desarrollo de software","herramientas de desarrollo","seguimiento de problemas","CLI para seguimiento de incidencias"],"fr":["suivi des problèmes","outil CLI","gestion de tickets","tk ready","tk show","développement de logiciels","outils de développement","suivi de problèmes","CLI pour suivi des problèmes"],"de":["Verfolgung von Problemtickets","CLI-Tool","Verwaltung von Arbeitstickets","tk ready","tk show","Softwareentwicklung","Entwicklungstools","Verfolgung von Problemen","CLI für die Verfolgung von Problemtickets"],"pt":["rastreamento de problemas","tk","CLI","repositório","trabalhos prontos","visualização de detalhes","marcar trabalhos em andamento","fechamento de trabalhos","armazenamento de tickets"],"ru":["отслеживание проблем","ИИ Агенты","tk","CLI","репозиторий","готовые работы","просмотр деталей","отметка работы в процессе","закрытие работы","хранение тикетов"],"ar":["تتبع المشكلات","أدوات ذكاء اصطناعي","tk","CLI","مستودع","قائمة العمل الجاهز","عرض التفاصيل","تحديد العمل قيد التقدم","إغلاق العمل","تخزين التذاكر"]}},"owner":"mbtz","repo":"morningweave","repoPath":"mbtz/morningweave","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.389Z","topics":[],"category":"community","skillMd":{"name":"issue-tracking","description":"Use tk to manage tickets and keep .tickets/ in sync with code changes.","bodyPreview":"Use `tk` for issue tracking in this repo.\n\n- List ready work with `tk ready`.\n- View details with `tk show <id>`.\n- Mark work in progress with `tk start <id>`.\n- Close work with `tk close <id>`.\n- Tickets live in `.tickets/` and should be committed with related code changes.\n\nReference: `references/tk-quickref.md`.","body":"Use `tk` for issue tracking in this repo.\n\n- List ready work with `tk ready`.\n- View details with `tk show <id>`.\n- Mark work in progress with `tk start <id>`.\n- Close work with `tk close <id>`.\n- Tickets live in `.tickets/` and should be committed with related code changes.\n\nReference: `references/tk-quickref.md`.\n"},"lastSynced":"2026-03-08T02:06:00.068Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents utilizing tk commands for streamlined issue management and version control.","zh":"适用于使用tk命令进行流畅的问题管理和版本控制的开发代理。","ja":"tkコマンドを使用してストリームライン化された問題管理とバージョン管理を行う開発エージェントに適しています。","ko":"tk 명령을 사용하여 문제 관리와 버전 관리를 간소화하는 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que utilizan comandos tk para una gestión de problemas y control de versiones simplificada.","fr":"Idéal pour les agents de développement qui utilisent des commandes tk pour une gestion de problèmes et un contrôle de version rationalisés.","de":"Ideal für Entwicklungsmittel, die tk-Befehle für eine vereinfachte Problemanalyse und Versionskontrolle nutzen.","pt":"Ideal para Agentes de Desenvolvimento que utilizam comandos tk para gerenciamento de problemas e controle de versão simplificados.","ru":"Идеально подходит для агентов разработки, использующих команды tk для упрощенного управления проблемами и контроля версий.","ar":"مثالي لعميل التطوير الذين يستخدمون أوامر tk لتدفق إدارة المشاكل والتحكم في الإصدار المُبسّط."},"recommendation":{"en":"Empowers agents to efficiently track and manage issues using tk commands, facilitating collaborative development workflows with features like `tk ready`, `tk show`, and `tk close`, all while integrating with Git for seamless version control and issue tracking within the `.tickets/` directory.","zh":"赋予代理高效地跟踪和管理问题的能力，使用tk命令促进协作开发工作流，具有`tk ready`、`tk show`和`tk close`等功能，同时与Git集成实现版本控制和问题跟踪在`.tickets/`目录中。","ja":"エージェントが効率的に問題を追跡して管理できるようにし、`tk ready`、`tk show`、`tk close`などの機能を使用してコラボレーション開発ワークフローを促進し、Gitと統合して`.tickets/`ディレクトリ内でのバージョン管理と問題追跡を実現します。","ko":"에이전트가 효율적으로 문제를 추적하고 관리할 수 있도록 하며, `tk ready`, `tk show`, `tk close`などの 기능을 사용하여 협력 개발 워크플로우를促進하며, Git과 통합하여 `.tickets/` 디렉토리 내에서의 버전 관리와 문제 추적을 구현합니다.","es":"Permite a los agentes realizar un seguimiento y una gestión eficaces de los problemas utilizando comandos tk, facilitando flujos de trabajo de desarrollo colaborativos con características como `tk ready`, `tk show` y `tk close`, todo ello integrándose con Git para un control de versiones y seguimiento de problemas sin problemas dentro del directorio `.tickets/`.","fr":"Permet aux agents de suivre et de gérer efficacement les problèmes en utilisant des commandes tk, facilitant ainsi les flux de travail de développement collaboratif avec des fonctionnalités comme `tk ready`, `tk show` et `tk close`, le tout en s''intégrant avec Git pour un contrôle de version et un suivi de problèmes sans problème dans le répertoire `.tickets/`.","de":"Ermöglicht es Agenten, Probleme effizient mit tk-Befehlen zu verfolgen und zu verwalten, wodurch kollaborative Entwicklungsworkflows mit Funktionen wie `tk ready`, `tk show` und `tk close` erleichtert werden, während sie sich nahtlos in Git für Versionskontrolle und Problemanalyse im `.tickets/`-Verzeichnis integrieren.","pt":"Habilita os agentes a rastrear e gerenciar problemas de forma eficiente usando comandos tk, facilitando fluxos de trabalho de desenvolvimento colaborativo com recursos como `tk ready`, `tk show` e `tk close`, todos integrados com o Git para controle de versão e rastreamento de problemas sem problemas dentro do diretório `.tickets/`.","ru":"Наделяет агентов возможностью эффективно отслеживать и управлять проблемами с помощью команд tk, облегчая сотрудничество в рабочих процессах разработки с функциями seperti `tk ready`, `tk show` и `tk close`, все интегрированное с Git для бесшовного контроля версий и отслеживания проблем в директории `.tickets/`.","ar":"تمكّن الوكيل من تتبع وإدارة المشاكل بفعالية باستخدام أوامر tk، ويسهّل تدفقات العمل التطويرية التعاونية باستخدام ميزات مثل `tk ready` و `tk show` و `tk close`، وجميعها متكاملة مع Git من أجل التحكم في الإصدار وتتبع المشاكل بشكل سلس داخل دليل `.tickets/`."},"useCases":{"en":["Tracking project issues with `tk ready`","Debugging specific tickets using `tk show <id>`","Managing workflow states with `tk start` and `tk close` commands"],"zh":["使用`tk ready`跟踪项目问题","使用`tk show <id>`调试特定票据","使用`tk start`和`tk close`命令管理工作流状态"],"ja":["`tk ready`を使用してプロジェクトの問題を追跡する","`tk show <id>`を使用して特定のチケットをデバッグする","`tk start`および`tk close`コマンドを使用してワークフローの状態を管理する"],"ko":["`tk ready`를 사용하여 프로젝트 문제를 추적하는 것","`tk show <id>`를 사용하여 특정 티켓을 디버깅하는 것","`tk start` 및 `tk close` 명령을 사용하여 워크플로우 상태를 관리하는 것"],"es":["Seguimiento de problemas del proyecto con `tk ready`","Depuración de billetes específicos con `tk show <id>`","Gestión de estados de flujo de trabajo con los comandos `tk start` y `tk close`"],"fr":["Suivi des problèmes de projet avec `tk ready`","Débogage de tickets spécifiques avec `tk show <id>`","Gestion des états de flux de travail avec les commandes `tk start` et `tk close`"],"de":["Verfolgung von Projektproblemen mit `tk ready`","Fehlerbehebung bei bestimmten Tickets mit `tk show <id>`","Verwaltung von Workflow-Zuständen mit den Befehlen `tk start` und `tk close`"],"pt":["Rastrear problemas do projeto com `tk ready`","Depurar tickets específicos usando `tk show <id>`","Gerenciar estados de fluxo de trabalho com comandos `tk start` e `tk close`"],"ru":["Отслеживать проблемы проекта с помощью `tk ready`","Отладить конкретные тикеты, используя `tk show <id>`","Управлять состояниями рабочего процесса с помощью команд `tk start` и `tk close`"],"ar":["تتبع مشاكل المشروع باستخدام `tk ready`","تصحيح أخطاء تذاكر محددة باستخدام `tk show <id>`","إدارة حالات سير العمل باستخدام أوامر `tk start` و `tk close`"]},"limitations":{"en":["Requires CLI access","Dependent on tk command functionality","Tickets must be committed with related code changes"],"zh":["需要CLI访问","依赖于tk命令功能","票据必须与相关代码更改一起提交"],"ja":["CLIアクセスが必要","tkコマンドの機能に依存している","チケットは関連するコード変更とともにコミットする必要がある"],"ko":["CLI 액세스가 필요함","tk 명령의 기능에 의존함","티켓은 관련 코드 변경과 함께 커밋되어야 함"],"es":["Requiere acceso a CLI","Dependiente de la funcionalidad del comando tk","Los billetes deben estar comprometidos con los cambios de código relacionados"],"fr":["Nécessite un accès à la CLI","Dépend de la fonctionnalité de la commande tk","Les tickets doivent être validés avec les modifications de code associées"],"de":["Benötigt Zugriff auf CLI","Abhängig von der Funktionalität des tk-Befehls","Tickets müssen mit den entsprechenden Codeänderungen committet werden"],"pt":["Requer acesso CLI","Dependente da funcionalidade do comando tk","Os tickets devem ser comprometidos com alterações de código relacionadas"],"ru":["Требует доступа CLI","Зависит от функциональности команды tk","Тикеты должны быть зафиксированы с相关ными изменениями кода"],"ar":["يتطلب الوصول إلى CLI","يعتمد على وظائف أمر tk","يجب أن يتم التزام التذاكر مع تغييرات الكود المرتبطة"]},"version":4},"contentHash":"a335dbd1836b9fe6683f34c5cebbd7a4ac77311df8ce8c09ffbf254f22c6a181","qualityScore":20}');
