INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mbtz/morningweave/issue-tracking', 'issue-tracking', 'mbtz', 'morningweave', 'community', 'issue-tracking mbtz morningweave community The issue-tracking skill provides a helper CLI tool for curating news, utilizing tk commands for efficient issue management, benefiting developers and teams. 使用tk命令行工具进行问题跟踪，支持查看、开始和关闭问题单 tk CLIツールを使用してIssue Trackingを実行します tk 명령어 도구를 사용하여 이슈 트래킹을 수행합니다 La herramienta CLI de seguimiento de incidencias permite gestionar tickets de trabajo con comandos como ''tk ready'' y ''tk show''. L''outil CLI de suivi des problèmes permet de gérer les tickets de travail avec des commandes comme ''tk ready'' et ''tk show''. Das CLI-Tool für die Verfolgung von Problemtickets ermöglicht die Verwaltung von Arbeitstickets mit Befehlen wie ''tk ready'' und ''tk show''. O tk é uma ferramenta CLI para rastreamento de problemas que permite listar trabalhos prontos, visualizar detalhes e marcar trabalhos em andamento ИИ Агент tk - это инструмент командной строки для отслеживания проблем, который позволяет перечислить готовые работы, просмотреть детали и отметить работу в процессе أداة tk هي أداة سطر أوامر لتعقب المشكلات التي تسمح بقائمة العمل الجاهز وعرض التفاصيل وتحديد العمل قيد التقدم how to use issue-tracking issue-tracking cli tool issue-tracking alternative issue-tracking vs jira issue-tracking install issue-tracking setup guide tk command reference issue tracking best practices Issue Tracking AIエージェント tk命令行工具 问题跟踪 CLI工具 代码变更 问题管理 Utilizes tk commands for issue tracking and management Lists ready work with `tk ready` command Views details with `tk show <id>` command Supports marking work in progress with `tk start <id>` command Closes work with `tk close <id>` command Stores tickets in `.tickets/` directory for version control Issue-tracking is a process of managing and curating issues using a command-line interface tool, such as tk, for streamlined workflow and productivity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dspangenberg/twc-ui/tailwindcss-development', 'community', 'dspangenberg', 'twc-ui', 'dspangenberg/twc-ui', 'tailwindcss-development', 0, 0, 20, '2026-03-08T01:57:15.396Z', '2026-03-08T02:06:21.739Z', '7d006586644836216d261284d194efb0dd041f07b6accb66d16ee926bc0db1c7', '{"id":"dspangenberg/twc-ui/tailwindcss-development","name":"tailwindcss-development","description":{"en":"The tailwindcss-development skill provides DRY-er, accessible React Aria components optimized for Inertia.js and Laravel''s Precognition. It benefits developers working with responsive design and custom styling.","zh":"Tailwind CSS 是一个用于构建响应式和可访问的 React 组件的实用工具","ja":"Tailwind CSS は、レスポンシブでアクセシブルな React コンポーネントを構築するためのユーティリティです","ko":"Tailwind CSS는 반응형 및 접근성 높은 React 컴포넌트를 구축하는 데 사용되는 유틸리티입니다","es":"Tailwind CSS es una herramienta para crear componentes React accesibles y personalizables con Inertia.js y Laravel","fr":"Tailwind CSS est un outil pour créer des composants React accessibles et personnalisables avec Inertia.js et Laravel","de":"Tailwind CSS ist ein Tool zum Erstellen von zugänglichen und anpassbaren React-Komponenten mit Inertia.js und Laravel","pt":"O Tailwind CSS é uma ferramenta para criar componentes React Aria acessíveis e personalizados com Inertia.js e Laravel.","ru":"Tailwind CSS - это инструмент для создания доступных и настраиваемых компонентов React Aria с Inertia.js и Laravel для ИИ Агентов.","ar":"Tailwind CSS هو أداة لإنشاء مكونات React Aria قابل للوصول وتخصيصها مع Inertia.js و Laravel لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"tailwindcss-development: Setup Guide for AI Agents","zh":"Tailwind CSS 开发最佳实践","ja":"Tailwind CSS 開発ガイド - AIエージェント","ko":"Tailwind CSS 개발 설정 가이드","es":"Guía de Configuración de Tailwind CSS para Desarrollo","fr":"Guide de Mise en Place de Tailwind CSS pour le Développement","de":"Einrichtungsleitfaden für Tailwind CSS-Entwicklung","pt":"Guia de Configuração do Tailwind CSS para Desenvolvimento","ru":"Руководство по настройке Tailwind CSS для разработки ИИ А...","ar":"دليل إعداد Tailwind CSS للتنمية مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient React component styling with Tailwind CSS. Learn how to apply this skill for responsive design, dark mode, and more. Get started now!","zh":"使用 Tailwind CSS 实现响应式设计、暗黑模式和可访问的 React 组件","ja":"Tailwind CSS を使用してレスポンシブデザイン、ダークモード、React コンポーネントを実現","ko":"Tailwind CSS로 반응형 디자인, 다크 모드, 접근성 높은 React 컴포넌트 구현","es":"Aprende a utilizar Tailwind CSS con Inertia.js y Laravel para crear componentes React accesibles y personalizables","fr":"Découvrez comment utiliser Tailwind CSS avec Inertia.js et Laravel pour créer des composants React accessibles et personnalisables","de":"Erfahren Sie, wie Sie Tailwind CSS mit Inertia.js und Laravel verwenden, um zugängliche und anpassbare React-Komponenten zu erstellen","pt":"Aprenda a usar o Tailwind CSS para criar componentes React Aria acessíveis e personalizados com Inertia.js e Laravel","ru":"Узнайте, как использовать Tailwind CSS для создания доступных и настраиваемых компонентов React Aria с Inertia.js и Laravel для ИИ Агентов","ar":"تعلم كيفية استخدام Tailwind CSS لإنشاء مكونات React Aria قابل للوصول وتخصيصها مع Inertia.js و Laravel لأدوات الذكاء الاصطناعي"},"definition":{"en":"tailwindcss-development is a skill for creating optimized, accessible React components using Tailwind CSS, ideal for Inertia.js and Laravel projects.","zh":"Tailwind CSS 是一个基于 CSS 的实用工具框架","ja":"Tailwind CSS は、CSS ベースのユーティリティフレームワークです","ko":"Tailwind CSS는 CSS 기반의 유틸리티 프레임워크입니다","es":"Tailwind CSS es un framework de CSS para crear componentes React personalizables y accesibles","fr":"Tailwind CSS est un framework CSS pour créer des composants React personnalisables et accessibles","de":"Tailwind CSS ist ein CSS-Framework zum Erstellen von anpassbaren und zugänglichen React-Komponenten","pt":"Tailwind CSS é uma ferramenta de desenvolvimento que ajuda a criar componentes React Aria acessíveis e personalizados","ru":"Tailwind CSS - это инструмент разработки, помогающий создавать доступные и настраиваемые компоненты React Aria","ar":"Tailwind CSS هو أداة تنمية تساعد على إنشاء مكونات React Aria قابل للوصول وتخصيصها"},"features":{"en":["Utilizes Tailwind CSS classes for styling HTML","Supports responsive design and dark mode implementation","Enables extraction of repeated patterns into reusable components","Facilitates debugging of spacing and layout issues","Integrates with Inertia.js and Laravel''s Precognition feature"],"zh":["使用 Tailwind CSS 类来实现响应式设计","支持暗黑模式和可访问的 React 组件","与 Inertia.js 和 Laravel 的 Precognition 功能集成","使用 search-docs 查找详细的 Tailwind CSS 文档","遵循现有的 Tailwind CSS 约定"],"ja":["Tailwind CSS クラスを使用してレスポンシブデザインを実現","ダークモードとアクセシブルな React コンポーネントをサポート","Inertia.js と Laravel の Precognition 機能との統合","search-docs を使用して詳細な Tailwind CSS ドキュメントを検索","既存の Tailwind CSS 約定に従う"],"ko":["Tailwind CSS 클래스를 사용하여 반응형 디자인을 구현","다크 모드와 접근성 높은 React 컴포넌트를 지원","Inertia.js와 Laravel의 Precognition 기능과 통합","search-docs를 사용하여 자세한 Tailwind CSS 문서를 검색","既存의 Tailwind CSS 규약을 따름"],"es":["Utiliza clases de Tailwind CSS para personalizar componentes","Compatibilidad con Inertia.js y Laravel","Creación de componentes React accesibles","Soporte para diseño responsivo","Implementación de modo oscuro","Depuración de problemas de espaciado y diseño"],"fr":["Utilisez des classes Tailwind CSS pour personnaliser les composants","Compatibilité avec Inertia.js et Laravel","Création de composants React accessibles","Prise en charge de la conception réactive","Mise en œuvre du mode sombre","Débogage des problèmes d''espacement et de conception"],"de":["Verwenden Sie Tailwind-CSS-Klassen, um Komponenten zu personalisieren","Kompatibilität mit Inertia.js und Laravel","Erstellung von zugänglichen React-Komponenten","Unterstützung für responsives Design","Implementierung des Dunkelmodus","Fehlerbehebung bei Platzierungs- und Layoutproblemen"],"pt":["Criação de componentes React Aria acessíveis","Personalização de componentes com Inertia.js","Integração com Laravel","Otimização para design responsivo","Implementação de modo escuro","Depuração de problemas de layout"],"ru":["Создание доступных компонентов React Aria","Настройка компонентов с Inertia.js","Интеграция с Laravel","Оптимизация для адаптивного дизайна","Реализация темного режима","Отладка проблем макета"],"ar":["إنشاء مكونات React Aria قابل للوصول","تخصيص المكونات مع Inertia.js","إضافة وظيفة مع Laravel","تحسين التصميم للتكيف مع الأجهزة المختلفة","تنفيذ وضع الليل","تصحيح أخطاء التصميم"]},"keywords":{"en":["how to use tailwindcss-development","tailwindcss-development setup guide","tailwindcss-development vs bootstrap","tailwindcss-development install","what is tailwindcss-development","tailwindcss-development alternative","tailwindcss-development for react","tailwindcss-development with inertia.js","tailwindcss-development and laravel"],"zh":["Tailwind CSS","React","响应式设计","暗黑模式","可访问性","Inertia.js","Laravel","Precognition","search-docs"],"ja":["Tailwind CSS","React","レスポンシブデザイン","ダークモード","アクセシビリティ","Inertia.js","Laravel","Precognition","search-docs","AIエージェント"],"ko":["Tailwind CSS","React","반응형 디자인","다크 모드","접근성","Inertia.js","Laravel","Precognition","search-docs","AI 도구"],"es":["Tailwind CSS","Desarrollo web","React","Inertia.js","Laravel","Diseño responsivo","Modo oscuro","Accesibilidad web","Desarrollo de componentes","CSS"],"fr":["Tailwind CSS","Développement web","React","Inertia.js","Laravel","Conception réactive","Mode sombre","Accessibilité web","Développement de composants","CSS"],"de":["Tailwind CSS","Webentwicklung","React","Inertia.js","Laravel","Responsives Design","Dunkelmodus","Webzugänglichkeit","Komponentenentwicklung","CSS"],"pt":["Tailwind CSS","React Aria","Inertia.js","Laravel","desenvolvimento web","componentes acessíveis","design responsivo","modo escuro"],"ru":["Tailwind CSS","React Aria","Inertia.js","Laravel","разработка веб-приложений","доступные компоненты","адаптивный дизайн","темный режим","ИИ Агенты"],"ar":["Tailwind CSS","React Aria","Inertia.js","Laravel","تطوير الويب","مكونات قابل للوصول","تصميم مرن","وضع الليل","أدوات الذكاء الاصطناعي"]}},"owner":"dspangenberg","repo":"twc-ui","repoPath":"dspangenberg/twc-ui","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.396Z","topics":[],"category":"community","skillMd":{"name":"tailwindcss-development","description":">-","bodyPreview":"# Tailwind CSS Development\n\n## When to Apply\n\nActivate this skill when:\n\n- Adding styles to components or pages\n- Working with responsive design\n- Implementing dark mode\n- Extracting repeated patterns into components\n- Debugging spacing or layout issues\n\n## Documentation\n\nUse `search-docs` for detailed Tailwind CSS v4 patterns and documentation.\n\n## Basic Usage\n\n- Use Tailwind CSS classes to style HTML. Check and follow existing Tailwind conventions in the project before introducing new patterns","body":"# Tailwind CSS Development\n\n## When to Apply\n\nActivate this skill when:\n\n- Adding styles to components or pages\n- Working with responsive design\n- Implementing dark mode\n- Extracting repeated patterns into components\n- Debugging spacing or layout issues\n\n## Documentation\n\nUse `search-docs` for detailed Tailwind CSS v4 patterns and documentation.\n\n## Basic Usage\n\n- Use Tailwind CSS classes to style HTML. Check and follow existing Tailwind conventions in the project before introducing new patterns.\n- Offer to extract repeated patterns into components that match the project''s conventions (e.g., Blade, JSX, Vue).\n- Consider class placement, order, priority, and defaults. Remove redundant classes, add classes to parent or child elements carefully to reduce repetition, and group elements logically.\n\n## Tailwind CSS v4 Specifics\n\n- Always use Tailwind CSS v4 and avoid deprecated utilities.\n- `corePlugins` is not supported in Tailwind v4.\n\n### CSS-First Configuration\n\nIn Tailwind v4, configuration is CSS-first using the `@theme` directive — no separate `tailwind.config.js` file is needed:\n\n<code-snippet name=\"CSS-First Config\" lang=\"css\">\n@theme {\n  --color-brand: oklch(0.72 0.11 178);\n}\n</code-snippet>\n\n### Import Syntax\n\nIn Tailwind v4, import Tailwind with a regular CSS `@import` statement instead of the `@tailwind` directives used in v3:\n\n<code-snippet name=\"v4 Import Syntax\" lang=\"diff\">\n- @tailwind base;\n- @tailwind components;\n- @tailwind utilities;\n+ @import \"tailwindcss\";\n</code-snippet>\n\n### Replaced Utilities\n\nTailwind v4 removed deprecated utilities. Use the replacements shown below. Opacity values remain numeric.\n\n| Deprecated | Replacement |\n|------------|-------------|\n| bg-opacity-* | bg-black/* |\n| text-opacity-* | text-black/* |\n| border-opacity-* | border-black/* |\n| divide-opacity-* | divide-black/* |\n| ring-opacity-* | ring-black/* |\n| placeholder-opacity-* | placeholder-black/* |\n| flex-shrink-* | shrink-* |\n| flex-grow-* | grow-* |\n| overflow-ellipsis | text-ellipsis |\n| decoration-slice | box-decoration-slice |\n| decoration-clone | box-decoration-clone |\n\n## Spacing\n\nUse `gap` utilities instead of margins for spacing between siblings:\n\n<code-snippet name=\"Gap Utilities\" lang=\"html\">\n<div class=\"flex gap-8\">\n    <div>Item 1</div>\n    <div>Item 2</div>\n</div>\n</code-snippet>\n\n## Dark Mode\n\nIf existing pages and components support dark mode, new pages and components must support it the same way, typically using the `dark:` variant:\n\n<code-snippet name=\"Dark Mode\" lang=\"html\">\n<div class=\"bg-white dark:bg-gray-900 text-gray-900 dark:text-white\">\n    Content adapts to color scheme\n</div>\n</code-snippet>\n\n## Common Patterns\n\n### Flexbox Layout\n\n<code-snippet name=\"Flexbox Layout\" lang=\"html\">\n<div class=\"flex items-center justify-between gap-4\">\n    <div>Left content</div>\n    <div>Right content</div>\n</div>\n</code-snippet>\n\n### Grid Layout\n\n<code-snippet name=\"Grid Layout\" lang=\"html\">\n<div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6\">\n    <div>Card 1</div>\n    <div>Card 2</div>\n    <div>Card 3</div>\n</div>\n</code-snippet>\n\n## Common Pitfalls\n\n- Using deprecated v3 utilities (bg-opacity-*, flex-shrink-*, etc.)\n- Using `@tailwind` directives instead of `@import \"tailwindcss\"`\n- Trying to use `tailwind.config.js` instead of CSS `@theme` directive\n- Using margins for spacing between siblings instead of gap utilities\n- Forgetting to add dark mode variants when the project uses dark mode"},"lastSynced":"2026-03-08T02:06:21.739Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring efficient and customizable CSS styling with Tailwind CSS","zh":"适合需要高效且可自定义CSS样式的前端代理，使用Tailwind CSS","ja":"フロントエンドエージェントが効率的でカスタマイズ可能なCSSスタイリングを必要とする場合に最適です。Tailwind CSSを使用します","ko":"프론트엔드 에이전트가 효율적이고 사용자 정의 가능한 CSS 스타일링을 필요로 할 때 적합합니다. Tailwind CSS를 사용합니다","es":"Ideal para Agentes Frontend que requieren un estilo de CSS eficiente y personalizable con Tailwind CSS","fr":"Idéal pour les agents Frontend nécessitant un style CSS efficace et personnalisable avec Tailwind CSS","de":"Ideal für Frontend-Agenten, die eine effiziente und anpassbare CSS-Styling mit Tailwind CSS benötigen","pt":"Ideal para Agentes Frontend que exigem estilização CSS eficiente e personalizável com Tailwind CSS","ru":"Идеально для фронтенд-агентов, требующих эффективного и настраиваемого стиля CSS с помощью Tailwind CSS","ar":"مثالي للوكلاء الأماميين الذين يتطلبون تنسيقًا قابلًا للتخصيص بكفاءة مع Tailwind CSS"},"recommendation":{"en":"Empowers agents to create responsive and accessible React Aria components optimized for Inertia.js and Laravel''s Precognition, utilizing Tailwind CSS classes for styling and debugging spacing or layout issues","zh":"赋予代理创建响应式和可访问的React Aria组件的能力，针对Inertia.js和Laravel的Precognition进行优化，使用Tailwind CSS类进行样式设置和调试间距或布局问题","ja":"エージェントがレスポンシブでアクセス可能なReact Ariaコンポーネントを作成できるようにし、Inertia.jsとLaravelのPrecognitionを最適化し、Tailwind CSSクラスを使用してスタイリングとスペースやレイアウトの問題のデバッグを行う","ko":"에이전트가 반응형이고 접근 가능한 React Aria 컴포넌트를 생성할 수 있도록 하며, Inertia.js와 Laravel의 Precognition에 최적화되어 있으며, Tailwind CSS 클래스를 사용하여 스타일링 및 간격 또는 레이아웃 문제를 디버깅합니다","es":"Habilita a los agentes a crear componentes de React Aria responsivos y accesibles, optimizados para Inertia.js y la Precognition de Laravel, utilizando clases de Tailwind CSS para el estilo y la depuración de problemas de espaciado o diseño","fr":"Permet aux agents de créer des composants React Aria réactifs et accessibles, optimisés pour Inertia.js et la Precognition de Laravel, en utilisant des classes Tailwind CSS pour le style et le débogage des problèmes d''espacement ou de disposition","de":"Ermächtigt Agenten, responsive und zugängliche React-Aria-Komponenten zu erstellen, die für Inertia.js und Laravels Precognition optimiert sind, wobei Tailwind-CSS-Klassen für das Styling und die Fehlerbehebung von Abstands- oder Layoutproblemen verwendet werden","pt":"Habilita os agentes a criarem componentes React Aria responsivos e acessíveis, otimizados para Inertia.js e Precognition do Laravel, utilizando classes Tailwind CSS para estilização e depuração de problemas de espaçamento ou layout","ru":"Наделяет агентов возможностью создавать отзывчивые и доступные компоненты React Aria, оптимизированные для Inertia.js и Precognition Laravel, используя классы Tailwind CSS для стиля и отладки проблем разметки или макета","ar":"تمكين الوكلاء من إنشاء مكونات React Aria المستجيبة وقابلة للاستخدام، محسّنة ل Inertia.js و Precognition من Laravel، باستخدام فئات Tailwind CSS للتنسيق وتصحيح مشاكل التباعد أو الإعداد"},"useCases":{"en":["Automating responsive design implementation","Generating custom CSS components with Tailwind CSS","Debugging layout issues with existing Tailwind conventions"],"zh":["实现响应式设计的自动化","使用Tailwind CSS生成自定义CSS组件","使用现有的Tailwind约定调试布局问题"],"ja":["レスポンシブデザインの実装を自動化する","Tailwind CSSを使用してカスタムCSSコンポーネントを生成する","既存のTailwind規約を使用してレイアウトの問題をデバッグする"],"ko":["반응형 디자인 구현 자동화","Tailwind CSS를 사용하여 사용자 정의 CSS 컴포넌트 생성","기존 Tailwind 규약을 사용하여 레이아웃 문제 디버깅"],"es":["Implementación automática de diseño responsivo","Generación de componentes de CSS personalizados con Tailwind CSS","Depuración de problemas de diseño con convenciones de Tailwind existentes"],"fr":["Mise en œuvre automatique de la conception réactive","Génération de composants CSS personnalisés avec Tailwind CSS","Débogage des problèmes de disposition avec les conventions Tailwind existantes"],"de":["Automatisierte Implementierung responsiver Designs","Erzeugung benutzerdefinierter CSS-Komponenten mit Tailwind CSS","Fehlerbehebung von Layoutproblemen mit bestehenden Tailwind-Konventionen"],"pt":["Implementação automática de design responsivo","Geração de componentes CSS personalizados com Tailwind CSS","Depuração de problemas de layout com convenções Tailwind existentes"],"ru":["Автоматическая реализация отзывчивого дизайна","Генерация пользовательских компонентов CSS с помощью Tailwind CSS","Отладка проблем макета с существующими конвенциями Tailwind"],"ar":["تنفيذ التصميم الاستجابي تلقائيًا","إنشاء مكونات CSS مخصصة باستخدام Tailwind CSS","تصحيح مشاكل الإعداد باستخدام الاتفاقيات الحالية من Tailwind"]},"limitations":{"en":["Requires existing Tailwind CSS project setup","Limited to React Aria components and Inertia.js or Laravel''s Precognition frameworks"],"zh":["需要现有的Tailwind CSS项目设置","仅限于React Aria组件和Inertia.js或Laravel的Precognition框架"],"ja":["既存のTailwind CSSプロジェクト設定が必要","React AriaコンポーネントとInertia.jsまたはLaravelのPrecognitionフレームワークに限定される"],"ko":["기존 Tailwind CSS 프로젝트 설정이 필요","React Aria 컴포넌트 및 Inertia.js 또는 Laravel의 Precognition 프레임워크에만 제한"],"es":["Requiere una configuración de proyecto de Tailwind CSS existente","Limitado a componentes de React Aria y frameworks de Inertia.js o Precognition de Laravel"],"fr":["Nécessite une configuration de projet Tailwind CSS existante","Limité aux composants React Aria et aux frameworks Inertia.js ou Precognition de Laravel"],"de":["Benötigt eine bestehende Tailwind-CSS-Projekt-Konfiguration","Begrenzt auf React-Aria-Komponenten und Inertia.js- oder Laravels Precognition-Frameworks"],"pt":["Exige configuração de projeto Tailwind CSS existente","Limitado a componentes React Aria e frameworks Inertia.js ou Precognition do Laravel"],"ru":["Требует наличия настроенного проекта Tailwind CSS","Ограничен компонентами React Aria и фреймворками Inertia.js или Precognition Laravel"],"ar":["يتطلب إعداد مشروع Tailwind CSS موجود","محدود بمكونات React Aria وأطر عمل Inertia.js أو Precognition من Laravel"]},"version":4},"contentHash":"7d006586644836216d261284d194efb0dd041f07b6accb66d16ee926bc0db1c7","qualityScore":20}');
