INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dspangenberg/twc-ui/tailwindcss-development', 'tailwindcss-development', 'dspangenberg', 'twc-ui', 'community', 'tailwindcss-development dspangenberg twc-ui community The tailwindcss-development skill provides DRY-er, accessible React Aria components optimized for Inertia.js and Laravel''s Precognition. It benefits developers working with responsive design and custom styling. Tailwind CSS 是一个用于构建响应式和可访问的 React 组件的实用工具 Tailwind CSS は、レスポンシブでアクセシブルな React コンポーネントを構築するためのユーティリティです Tailwind CSS는 반응형 및 접근성 높은 React 컴포넌트를 구축하는 데 사용되는 유틸리티입니다 Tailwind CSS es una herramienta para crear componentes React accesibles y personalizables con Inertia.js y Laravel Tailwind CSS est un outil pour créer des composants React accessibles et personnalisables avec Inertia.js et Laravel Tailwind CSS ist ein Tool zum Erstellen von zugänglichen und anpassbaren React-Komponenten mit Inertia.js und Laravel O Tailwind CSS é uma ferramenta para criar componentes React Aria acessíveis e personalizados com Inertia.js e Laravel. Tailwind CSS - это инструмент для создания доступных и настраиваемых компонентов React Aria с Inertia.js и Laravel для ИИ Агентов. Tailwind CSS هو أداة لإنشاء مكونات React Aria قابل للوصول وتخصيصها مع Inertia.js و Laravel لأدوات الذكاء الاصطناعي. how to use tailwindcss-development tailwindcss-development setup guide tailwindcss-development vs bootstrap tailwindcss-development install what is tailwindcss-development tailwindcss-development alternative tailwindcss-development for react tailwindcss-development with inertia.js tailwindcss-development and laravel Tailwind CSS React 响应式设计 暗黑模式 可访问性 Inertia.js Laravel Precognition search-docs Utilizes Tailwind CSS classes for styling HTML Supports responsive design and dark mode implementation Enables extraction of repeated patterns into reusable components Facilitates debugging of spacing and layout issues Integrates with Inertia.js and Laravel''s Precognition feature tailwindcss-development is a skill for creating optimized, accessible React components using Tailwind CSS, ideal for Inertia.js and Laravel projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wmeints/promptyard/edit-backlog-item', 'community', 'wmeints', 'promptyard', 'wmeints/promptyard', 'edit-backlog-item', 0, 0, 20, '2026-03-08T01:57:15.409Z', '2026-03-08T02:06:59.769Z', 'b9ba803337fd3a4b72ff4309415d0824f37df9c5adab44315c364e386cb3bfb0', '{"id":"wmeints/promptyard/edit-backlog-item","name":"edit-backlog-item","description":{"en":"The edit-backlog-item skill helps developers manage GitHub issues, user stories, and bugs. It enables the creation and editing of issues on the GitHub repository.","zh":"edit-backlog-item技能用于在Github仓库中创建或编辑问题，支持优化prompt管理。它遵循特定的模板和指南","ja":"edit-backlog-itemスキルは、Githubリポジトリで問題を作成または編集し、プロンプト管理を最適化するために使用されます。特定のテンプレートとガイドラインに従います","ko":"edit-backlog-item 스킬은 Github 리포지토리에서 이슈를 생성 또는 편집하고 프로ンプ트 관리를 최적화하는 데 사용됩니다. 특정 템플릿과 가이드라인을 따릅니다","es":"Edit-backlog-item es una habilidad que permite crear o editar elementos de backlog en Github, mejorando la gestión de proyectos y flujos de trabajo de desarrollo","fr":"Edit-backlog-item est une compétence qui permet de créer ou de modifier des éléments de backlog sur Github, améliorant la gestion de projets et les flux de travail de développement","de":"Edit-backlog-item ist eine Fähigkeit, die die Erstellung oder Bearbeitung von Backlog-Elementen in Github ermöglicht, um die Projektverwaltung und Entwicklungsworkflows zu verbessern","pt":"O edit-backlog-item é uma habilidade que permite criar ou editar itens de backlog em um repositório Github, seguindo um template de história de usuário","ru":"ИИ Агент edit-backlog-item позволяет создавать или редактировать элементы бэклога в репозитории Github, следуя шаблону истории пользователя","ar":"الوكلاء الذكية edit-backlog-item تسمح بإنشاء أو تحرير عناصر بيكلوغ في مستودع جيثب، باتباع قالب قصة المستخدم"},"seo":{"title":{"en":"edit-backlog-item: GitHub Issue Management Setup Guide | ...","zh":"编辑待办事项设置指南 - edit-backlog-item","ja":"バックログアイテム編集ベストプラクティス - edit-backlog-item AIエージェント","ko":"백로그 아이템 편집 가이드 - edit-backlog-item AI 도구","es":"Guía de configuración de edit-backlog-item para herramien...","fr":"Configurer edit-backlog-item pour les outils d''IA","de":"Einrichtungsleitfaden für edit-backlog-item in AI-Tools","pt":"Guia de Configuração do edit-backlog-item para Ferramenta...","ru":"Настройка ИИ Агента edit-backlog-item: Лучшие Практики","ar":"دليل إعداد edit-backlog-item لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to optimize your GitHub workflow with edit-backlog-item. Learn to create and edit issues, user stories, and bugs with ease. Get started now!","zh":"了解如何使用edit-backlog-item技能在Github仓库中创建或编辑问题，优化prompt管理","ja":"edit-backlog-itemスキルを使用してGithubリポジトリで問題を作成または編集する方法を学び、プロンプト管理を最適化する","ko":"edit-backlog-item 스킬을 사용하여 Github 리포지토리에서 이슈를 생성 또는 편집하는 방법을 알아보고 프로ンプ트 관리를 최적화하세요","es":"Aprende a usar edit-backlog-item para gestionar elementos de backlog en Github y mejorar tus flujos de trabajo de desarrollo","fr":"Découvrez comment utiliser edit-backlog-item pour gérer les éléments de backlog sur Github et améliorer vos flux de travail de développement","de":"Erfahren Sie, wie Sie edit-backlog-item verwenden, um Backlog-Elemente in Github zu verwalten und Ihre Entwicklungsworkflows zu verbessern","pt":"Aprenda a configurar o edit-backlog-item para gerenciar prompts de forma eficaz e melhorar a produtividade do seu projeto","ru":"Узнайте, как настроить ИИ Агент edit-backlog-item для эффективного управления промптами и повышения производительности проекта","ar":"تعرف على كيفية إعداد edit-backlog-item لإدارة البرومبتات بفعالية وتحسين إنتاجية مشروعك"},"definition":{"en":"edit-backlog-item is a skill that allows AI agents to create or edit issues on GitHub repositories, following a specific template for user stories.","zh":"edit-backlog-item是一个用于创建或编辑Github仓库问题的技能，用于优化prompt管理","ja":"edit-backlog-itemは、Githubリポジトリで問題を作成または編集し、プロンプト管理を最適化するために使用されるスキルです","ko":"edit-backlog-item은 Github 리포지토리에서 이슈를 생성 또는 편집하여 프로ンプ트 관리를 최적화하는 스킬입니다","es":"Edit-backlog-item es una habilidad de AI que permite gestionar elementos de backlog en Github","fr":"Edit-backlog-item est une compétence d''IA qui permet de gérer les éléments de backlog sur Github","de":"Edit-backlog-item ist eine KI-Fähigkeit, die die Verwaltung von Backlog-Elementen in Github ermöglicht","pt":"O edit-backlog-item é uma habilidade de gerenciamento de prompts que permite criar ou editar itens de backlog em um repositório Github","ru":"ИИ Агент edit-backlog-item - это способность управления промптами, которая позволяет создавать или редактировать элементы бэклога в репозитории Github","ar":"الوكلاء الذكية edit-backlog-item هي khả năng لإدارة البرومبتات التي تسمح بإنشاء أو تحرير عناصر بيكلوغ في مستودع جيثب"},"features":{"en":["Creates and edits issues on GitHub repositories","Follows a template for user stories described in ./templates/user-story.md","Supports task management for user stories with a focus on adding value","Enables the editing of bugs and user stories in a GitHub repository","Uses a specific format for tasks in user stories to ensure concrete results","Manages backlog items for projects on GitHub"],"zh":["支持创建和编辑Github仓库问题","遵循特定的模板和指南","优化prompt管理","支持用户故事和任务管理","集成Github仓库"],"ja":["Githubリポジトリで問題を作成および編集","特定のテンプレートとガイドラインに従う","プロンプト管理を最適化","ユーザーストーリーとタスク管理をサポート","Githubリポジトリとの統合"],"ko":["Github 리포지토리에서 이슈를 생성 및 편집","특정 템플릿과 가이드라인을 따름","프로ンプ트 관리를 최적화","유저 스토리와 태스크 관리를 지원","Github 리포지토리와의 통합"],"es":["Creación y edición de elementos de backlog en Github","Gestión de user stories y tareas","Seguimiento de progreso y estado de los elementos de backlog","Integración con herramientas de desarrollo como React y Python","Compatibilidad con la línea de comandos (CLI) para automatización"],"fr":["Création et modification d''éléments de backlog sur Github","Gestion de user stories et de tâches","Suivi de l''avancement et de l''état des éléments de backlog","Intégration avec des outils de développement comme React et Python","Compatibilité avec la ligne de commande (CLI) pour l''automatisation"],"de":["Erstellung und Bearbeitung von Backlog-Elementen in Github","Verwaltung von User Stories und Aufgaben","Verfolgung des Fortschritts und des Status von Backlog-Elementen","Integration mit Entwicklungstools wie React und Python","Kompatibilität mit der Kommandozeile (CLI) für Automatisierung"],"pt":["Criação ou edição de itens de backlog em um repositório Github","Segue um template de história de usuário","Permite gerenciar prompts de forma eficaz","Integração com o repositório Github","Suporte à criação de tarefas que adicionam valor ao objetivo"],"ru":["Создание или редактирование элементов бэклога в репозитории Github","Следует шаблону истории пользователя","Позволяет эффективно управлять промптами","Интеграция с репозиторием Github","Поддержка создания задач, которые добавляют ценность к цели"],"ar":["إنشاء أو تحرير عناصر بيكلوغ في مستودع جيثب","ياتباع قالب قصة المستخدم","تسمح بإدارة البرومبتات بفعالية","التكامل مع مستودع جيثب","دعم إنشاء مهام تضيف قيمة إلى الهدف"]},"keywords":{"en":["how to use edit-backlog-item","edit-backlog-item GitHub integration","edit-backlog-item vs GitHub issues","edit-backlog-item setup guide","what is edit-backlog-item","edit-backlog-item alternative","edit-backlog-item install","GitHub issue management with edit-backlog-item","edit-backlog-item for AI agents","edit-backlog-item user story template"],"zh":["edit-backlog-item","Github仓库","prompt管理","用户故事","任务管理","AI工具","プロンプト管理","Github问题"],"ja":["edit-backlog-item","Githubリポジトリ","プロンプト管理","ユーザーストーリー","タスク管理","AIエージェント","Github問題"],"ko":["edit-backlog-item","Github 리포지토리","프로ンプ트 관리","유저 스토리","태스크 관리","AI 도구","Github 이슈"],"es":["edit-backlog-item","herramientas de AI","gestión de proyectos","Github","desarrollo de software","React","Python","CLI","automatización"],"fr":["edit-backlog-item","outils d''IA","gestion de projets","Github","développement de logiciels","React","Python","CLI","automatisation"],"de":["edit-backlog-item","KI-Tools","Projektverwaltung","Github","Softwareentwicklung","React","Python","CLI","Automatisierung"],"pt":["edit-backlog-item","gerenciamento de prompts","repositório Github","história de usuário","criação de tarefas","integração com Github","ferramentas de IA","desenvolvimento de software","produtividade"],"ru":["ИИ Агент edit-backlog-item","управление промптами","репозиторий Github","история пользователя","создание задач","интеграция с Github","ИИ инструменты","разработка программного обеспечения","производительность"],"ar":["الوكلاء الذكية edit-backlog-item","إدارة البرومبتات","مستودع جيثب","قصة المستخدم","إنشاء مهام","التكامل مع جيثب","أدوات الذكاء الاصطناعي","تطوير البرمجيات","الإنتاجية"]}},"owner":"wmeints","repo":"promptyard","repoPath":"wmeints/promptyard","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.409Z","topics":[],"category":"community","skillMd":{"name":"edit-backlog-item","description":"Use this skill when creating or editing issues on Github or when asked to write user-stories or record bugs.","bodyPreview":"## Edit Backlog Item\n\nUse this skill to create or edit issues on the Github repository for the project.\nYou should use this skill also when asked to write or edit user stories or bugs.\n\n## Managing user stories\n\n- User stories follow the template described in ./templates/user-story.md\n- Tasks in user stories should add value towards the goal. When you need to\n  complete multiple tasks to get a concrete runnable result, it should be one\n  task on the list instead of separate tasks.\n- Important: Y","body":"## Edit Backlog Item\n\nUse this skill to create or edit issues on the Github repository for the project.\nYou should use this skill also when asked to write or edit user stories or bugs.\n\n## Managing user stories\n\n- User stories follow the template described in ./templates/user-story.md\n- Tasks in user stories should add value towards the goal. When you need to\n  complete multiple tasks to get a concrete runnable result, it should be one\n  task on the list instead of separate tasks.\n- Important: You must adhere to the provided template.\n\n## Managing bugs\n\n- User stories follow the template described in ./templates/user-story.md\n- Tasks in user stories should add value towards the goal. When you need to\n  complete multiple tasks to get a concrete runnable result, it should be one\n  task on the list instead of separate tasks.\n- Important: You must adhere to the provided template.\n\n## Recording user stories and bugs\n\n- Important: record user stories and bugs in the GitHub repository associated with the codebase!\n- Use the label `kind:bug` for recording bugs on GitHub.\n- Use the label `kind:story` for recording user stories on GitHub."},"lastSynced":"2026-03-08T02:06:59.769Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents managing GitHub repositories and needing to create or edit issues, user stories, and bugs.","zh":"适合管理 GitHub 仓库并需要创建或编辑问题、用户故事和 bug 的开发代理。","ja":"GitHub リポジトリを管理し、問題、ユーザー ストーリー、バグを作成または編集する必要がある開発エージェントに適しています。","ko":"GitHub 저장소를 관리하고 문제, 사용자 스토리, 버그를 생성하거나 편집해야 하는 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que gestionan repositorios de GitHub y necesitan crear o editar incidencias, historias de usuario y errores.","fr":"Idéal pour les agents de développement qui gèrent des dépôts GitHub et ont besoin de créer ou de modifier des problèmes, des histoires d''utilisateurs et des bogues.","de":"Ideal für Entwicklungssagenten, die GitHub-Repositorys verwalten und Probleme, Benutzerstories und Fehler erstellen oder bearbeiten müssen.","pt":"Ideal para Agentes de Desenvolvimento que gerenciam repositórios GitHub e precisam criar ou editar problemas, histórias de usuário e bugs.","ru":"Идеально для агентов разработки, управляющих репозиториями GitHub и нуждающихся в создании или редактировании вопросов, историй пользователей и ошибок.","ar":"مثالي للوكلاء الناشئين الذين يديرون مستودعات GitHub ويدخلون في создание أو تعديل المشكلات وقصص المستخدمين والاخطاء."},"recommendation":{"en":"Empowers agents to manage GitHub issues, user stories, and bugs, utilizing templates like ./templates/user-story.md and handling tasks that add value towards project goals, all through the GitHub repository.","zh":"赋予代理管理 GitHub 问题、用户故事和 bug 的能力，利用诸如 ./templates/user-story.md 的模板，并处理为项目目标增加价值的任务，所有这些都通过 GitHub 仓库完成。","ja":"エージェントが GitHub の問題、ユーザー ストーリー、バグを管理できるようにし、./templates/user-story.md のようなテンプレートを使用し、プロジェクトの目標に価値を追加するタスクを処理するすべての機能を GitHub リポジトリを通じて提供します。","ko":"에이전트가 GitHub 문제, 사용자 스토리, 버그를 관리할 수 있도록 하며, ./templates/user-story.md와 같은 템플릿을 사용하여 프로젝트 목표에 값을 추가하는 작업을 모두 GitHub 저장소를 통해 처리합니다.","es":"Habilita a los agentes a gestionar problemas de GitHub, historias de usuario y errores, utilizando plantillas como ./templates/user-story.md y realizando tareas que agregan valor hacia los objetivos del proyecto, todo a través del repositorio de GitHub.","fr":"Permet aux agents de gérer les problèmes GitHub, les histoires d''utilisateurs et les bogues, en utilisant des modèles comme ./templates/user-story.md et en effectuant des tâches qui ajoutent de la valeur aux objectifs du projet, le tout via le dépôt GitHub.","de":"Ermöglicht es Agenten, GitHub-Probleme, Benutzerstories und Fehler zu verwalten, indem sie Vorlagen wie ./templates/user-story.md verwenden und Aufgaben ausführen, die zum Projektziel beitragen, und all dies über das GitHub-Repository.","pt":"Permite que os agentes gerenciem problemas do GitHub, histórias de usuário e bugs, utilizando modelos como ./templates/user-story.md e lidando com tarefas que adicionam valor aos objetivos do projeto, tudo por meio do repositório do GitHub.","ru":"Наделяет агентов возможностью управлять проблемами GitHub, историями пользователей и ошибками, используя шаблоны, такие как ./templates/user-story.md, и обрабатывая задачи, которые добавляют ценность к целям проекта, все через репозиторий GitHub.","ar":"يتمكن الوكلاء من إدارة مشاكل GitHub وقصص المستخدمين والأخطاء، باستخدام قوالب مثل ./templates/user-story.md ومعالجة المهام التي تضيف قيمة إلى أهداف المشروع، كل ذلك من خلال مستودع GitHub."},"useCases":{"en":["Creating and editing GitHub issues for project management","Managing user stories with specific templates and task validation","Editing bugs and tasks to ensure they add concrete value to the project"],"zh":["为项目管理创建和编辑 GitHub 问题","使用特定模板和任务验证管理用户故事","编辑 bug 和任务以确保它们为项目增加具体价值"],"ja":["プロジェクト管理のために GitHub の問題を作成および編集する","特定のテンプレートとタスクの検証を使用してユーザー ストーリーを管理する","バグとタスクを編集して、プロジェクトに具体的な価値を追加することを確認する"],"ko":["프로젝트 관리를 위해 GitHub 문제를 생성 및 편집하는 것","특정 템플릿 및 작업 유효성을 사용하여 사용자 스토리를 관리하는 것","버그 및 작업을 편집하여 프로젝트에 구체적인 값을 추가하는 것을 보장하는 것"],"es":["Creación y edición de problemas de GitHub para la gestión de proyectos","Gestión de historias de usuario con plantillas específicas y validación de tareas","Edición de errores y tareas para asegurar que aporten un valor concreto al proyecto"],"fr":["Création et modification de problèmes GitHub pour la gestion de projet","Gestion d''histoires d''utilisateurs avec des modèles spécifiques et validation de tâches","Édition de bogues et de tâches pour garantir qu''ils apportent une valeur concrète au projet"],"de":["Erstellung und Bearbeitung von GitHub-Problemen für das Projektmanagement","Verwaltung von Benutzerstories mit spezifischen Vorlagen und Aufgabenvalidierung","Bearbeitung von Fehlern und Aufgaben, um sicherzustellen, dass sie einen konkreten Wert für das Projekt haben"],"pt":["Criar e editar problemas do GitHub para gerenciamento de projetos","Gerenciar histórias de usuário com modelos específicos e validação de tarefas","Editar bugs e tarefas para garantir que eles adicionem valor concreto ao projeto"],"ru":["Создание и редактирование проблем GitHub для управления проектами","Управление историями пользователей с помощью специальных шаблонов и проверки задач","Редактирование ошибок и задач для обеспечения того, чтобы они добавляли конкретную ценность проекту"],"ar":["إنشاء وتحرير مشاكل GitHub لإدارة المشاريع","إدارة قصص المستخدمين باستخدام قوالب محددة وتحقق المهام","تحرير الأخطاء والمهام لضمان إضافة قيمة ملموسة إلى المشروع"]},"limitations":{"en":["Requires access to the GitHub repository","Adherence to specific user story templates like ./templates/user-story.md"],"zh":["需要访问 GitHub 仓库","遵守特定用户故事模板，如 ./templates/user-story.md"],"ja":["GitHub リポジトリへのアクセスが必要","特定のユーザー ストーリー テンプレート (例: ./templates/user-story.md) に従う"],"ko":["GitHub 저장소에 대한 액세스가 필요함","특정 사용자 스토리 템플릿(예: ./templates/user-story.md)을 준수"],"es":["Requiere acceso al repositorio de GitHub","Cumplimiento de plantillas de historias de usuario específicas como ./templates/user-story.md"],"fr":["Nécessite un accès au dépôt GitHub","Respect de modèles d''histoires d''utilisateurs spécifiques comme ./templates/user-story.md"],"de":["Erfordert Zugriff auf das GitHub-Repository","Einhaltung spezifischer Benutzerstory-Vorlagen wie ./templates/user-story.md"],"pt":["Requer acesso ao repositório do GitHub","Conformidade com modelos específicos de histórias de usuário, como ./templates/user-story.md"],"ru":["Требует доступа к репозиторию GitHub","Соблюдение специальных шаблонов историй пользователей, таких как ./templates/user-story.md"],"ar":["يتطلب الوصول إلى مستودع GitHub","الامتثال لقوالب محددة لحكايات المستخدمين مثل ./templates/user-story.md"]},"version":4},"contentHash":"b9ba803337fd3a4b72ff4309415d0824f37df9c5adab44315c364e386cb3bfb0","qualityScore":20}');
