INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Tetsu-is/claude-turtle-soup-skills/describe topics', 'describe topics', 'Tetsu-is', 'claude-turtle-soup-skills', 'community', 'describe topics Tetsu-is claude-turtle-soup-skills community The describe topics skill enables AI agents to explain topics by reading question.md files and providing user-centric answers. This skill benefits developers and users seeking informative responses. describe topics是一个基于文件名和问题描述的AI技能，用于与用户交互 describe topicsはファイル名と問題の説明に基づくAIスキルで、ユーザーとのやり取りに使用されます describe topics는 파일 이름과 문제 설명을 기반으로 하는 AI 에이전트로, 사용자와의 상호 작용에 사용됩니다 El skill de describir temas utiliza archivos question.md para proporcionar explicaciones detalladas a los usuarios Le skill de description de sujets utilise des fichiers question.md pour fournir des explications détaillées aux utilisateurs Das Skill zum Beschreiben von Themen verwendet Dateien question.md, um detaillierte Erklärungen für Benutzer bereitzustellen O skill de descrição de tópicos com Claude Code é uma funcionalidade que permite responder a perguntas dos usuários com base em arquivos question.md Навык описания тем с помощью Claude Code - это функция, которая позволяет отвечать на вопросы пользователей на основе файлов question.md для ИИ Агентов مهارة وصف المواضيع باستخدام Claude Code هي功能ة تسمح بالرد على أسئلة المستخدمين بناءً على الملفات question.md لأدوات الذكاء الاصطناعي how to use describe topics what is describe topics describe topics alternative describe topics vs chatbots describe topics install guide describe topics setup for AI agents describe topics technical documentation implementing describe topics in AI describe topics file format describe topics user interaction AI工具 describe topics 文件名 问题描述 用户交互 question.md AI开发 技术文档 Loads question.md files to retrieve topic information Provides problem explanations to users based on loaded content Supports YES, NO, and unrelated responses to user queries Utilizes file-based data storage for topic descriptions Enables AI agents to convey complex topic information to users describe topics is a skill that allows AI agents to explain topics by loading and processing question.md files to provide descriptive answers.');
