INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Rukkha1024/replace_V3D/md-style-preserving-edit', 'md-style-preserving-edit', 'Rukkha1024', 'replace_V3D', 'community', 'md-style-preserving-edit Rukkha1024 replace_V3D community The md-style-preserving-edit skill edits existing Markdown documents by adding content in a way that matches the document''s current writing style and structure, benefiting developers and content creators. MD 风格保留编辑是一种编辑现有 Markdown 文档的方法，添加内容时保持文档的当前写作风格和结构 MD スタイル保持編集は、既存の Markdown ドキュメントを編集する方法で、内容を追加するときにドキュメントの現在の書き方と構造を保持します MD 스타일 보존 편집은 기존 Markdown 문서를 편집하는 방법으로, 내용을 추가할 때 문서의 현재 작성 스타일과 구조를 유지합니다 md-style-preserving-edit es una herramienta de edición de Markdown que permite agregar contenido de manera no destructiva, manteniendo el estilo y la estructura actuales md-style-preserving-edit est un outil d''édition de Markdown qui permet d''ajouter du contenu de manière non destructive, en conservant le style et la structure actuels md-style-preserving-edit ist ein Markdown-Editor-Tool, das es ermöglicht, Inhalte nicht-destructiv hinzuzufügen und Stil und Struktur beizubehalten O md-style-preserving-edit é uma ferramenta que edita documentos Markdown existentes, adicionando conteúdo que combina com o estilo e estrutura atuais md-style-preserving-edit - это инструмент, который редактирует существующие документы Markdown, добавляя содержание, соответствующее текущему стилю и структуре md-style-preserving-edit هو أداة لتحرير مستندات Markdown الحالية، بإضافة محتوى يتوافق مع الأسلوب والهيكل الحاليين how to use md-style-preserving-edit md-style-preserving-edit alternative md-style-preserving-edit setup guide what is md-style-preserving-edit md-style-preserving-edit vs markdown editors md-style-preserving-edit install markdown editing tools ai agent skills for developers non-destructive markdown editing MD 风格保留编辑 Markdown 编辑 AI 工具 文档编辑 写作风格保持 结构保持 扫描样式和结构 保持现有文本完整 Scans Markdown files for heading hierarchy and numbering conventions Preserves terminology and labels, including window names and variables Performs non-destructive editing, keeping existing text intact Inserts new sections where appropriate, maintaining document structure Supports editing of .md files, ensuring consistency in Markdown formatting md-style-preserving-edit is a skill that enables non-destructive editing of Markdown documents, preserving heading hierarchy and terminology while inserting new sections.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yumehiko/jp-ui/jp-ui-foundations', 'community', 'yumehiko', 'jp-ui', 'yumehiko/jp-ui', 'jp-ui-foundations', 0, 0, 20, '2026-03-08T01:57:15.424Z', '2026-03-08T02:07:26.611Z', '1afc8d18969bedd4714256b73771e93c767073f24a1e1e413ecadf454110280f', '{"id":"yumehiko/jp-ui/jp-ui-foundations","name":"jp-ui-foundations","description":{"en":"jp-ui-foundations is a technical skill that facilitates UI component implementation by referencing Foundation tokens. It benefits developers by automating updates to tokens, roles, and tones.","zh":"jp-ui-foundations是一个用于实现Foundation トークンのAIエージェント技能，帮助开发者优化UI组件的实现","ja":"jp-ui-foundationsは、Foundation トークンの実装を支援するAIエージェントスキルです","ko":"jp-ui-foundations는 Foundation トークンの 구현을 지원하는 AI 도구 스킬입니다","es":"jp-ui-foundations es un conjunto de herramientas para implementar tokens de interfaz de usuario. Permite generar tonos de color, roles y tokens de tipografía de manera efectiva","fr":"jp-ui-foundations est un ensemble d''outils pour mettre en place des tokens d''interface utilisateur. Il permet de générer des tons de couleur, des rôles et des tokens de typographie de manière efficace","de":"jp-ui-foundations ist ein Satz von Tools zur Implementierung von Benutzeroberflächentoken. Es ermöglicht die effektive Generierung von Farbtönen, Rollen und Typografie-Tokens","pt":"O jp-ui-foundations é uma ferramenta para implementação de componentes UI com tokens de cor, tipo e ícone","ru":"jp-ui-foundations - это инструмент для реализации компонентов UI с токенами цвета, типа и иконки","ar":"jp-ui-foundations هو أداة لتنفيذ مكونات واجهة المستخدم مع رموز الألوان والنصوص والأيقونات"},"seo":{"title":{"en":"jp-ui-foundations: Foundation Token Management for AI Age...","zh":"jp-ui-foundations Setup Guide: AIエージェント集成","ja":"jp-ui-foundations セットアップガイド: Foundation トークンの実装","ko":"jp-ui-foundations 설정 가이드: AI 도구와의 통합","es":"jp-ui-foundations: Guía de configuración para tokens de i...","fr":"jp-ui-foundations: Guide de mise en place des tokens d''in...","de":"jp-ui-foundations: Einrichtungsleitfaden für Benutzerober...","pt":"Guia de Configuração do jp-ui-foundations para Desenvolve...","ru":"Руководство по настройке jp-ui-foundations для разработчиков","ar":"دليل إعداد jp-ui-foundations للمطورين"},"description":{"en":"Discover how jp-ui-foundations streamlines UI development with automated token updates. Learn more and get started with our setup guide today!","zh":"了解jp-ui-foundations的技术细节，并学习如何将其与AIエージェント集成，优化您的开发流程","ja":"jp-ui-foundationsの技術的特徴を学び、Foundation トークンの実装方法をマスターしてください","ko":"jp-ui-foundations의 기술 세부 정보를 학습하고 AI 도구와의 통합을 통해 개발 프로세스를 최적화하세요","es":"Aprende a implementar tokens de interfaz de usuario con jp-ui-foundations. Descubre cómo generar tonos de color, roles y tokens de tipografía","fr":"Découvrez comment mettre en place des tokens d''interface utilisateur avec jp-ui-foundations. Apprenez à générer des tons de couleur, des rôles et des tokens ...","de":"Erfahren Sie, wie Sie Benutzeroberflächentoken mit jp-ui-foundations implementieren. Entdecken Sie, wie Sie Farbtöne, Rollen und Typografie-Tokens generieren","pt":"Aprenda a configurar o jp-ui-foundations com nossos guias e melhores práticas para desenvolvedores","ru":"Узнайте, как настроить jp-ui-foundations с нашими руководствами и лучшими практиками для разработчиков","ar":"تعرف على كيفية إعداد jp-ui-foundations مع أدلةنا وأفضل الممارسات للمطورين"},"definition":{"en":"jp-ui-foundations is a technical skill that provides a foundation for UI development by managing tokens, including color, typography, icons, shapes, and shadows.","zh":"jp-ui-foundations是指一种用于实现UI组件的Foundation トークンのAIエージェント技能","ja":"jp-ui-foundationsは、UIコンポーネントの実装を支援するFoundation トークンのAIエージェントスキルを指します","ko":"jp-ui-foundations는 UI 컴포넌트의 구현을 지원하는 Foundation トークンの AI 도구 스킬을 의미합니다","es":"jp-ui-foundations es un conjunto de herramientas para la implementación de tokens de interfaz de usuario","fr":"jp-ui-foundations est un ensemble d''outils pour la mise en place des tokens d''interface utilisateur","de":"jp-ui-foundations ist ein Satz von Tools zur Implementierung von Benutzeroberflächentoken","pt":"O que é jp-ui-foundations? É uma fundação para implementação de componentes UI com tokens","ru":"Что такое jp-ui-foundations? Это основа для реализации компонентов UI с токенами","ar":"ما هو jp-ui-foundations؟ هو أساس لتنفيذ مكونات واجهة المستخدم مع رموز"},"features":{"en":["Generates color tones using scripts/generate-tones.mjs","Extracts roles via scripts/extract-roles.mjs","Updates role CSS with scripts/generate-roles-css.mjs","Manages color input and output via tokens/source.json and tokens/tones.json","Produces role output files including tokens/roles.light.json and tokens/roles.dark.json","Utilizes basic CSS tokens from src/index.css"],"zh":["使用scripts/generate-tones.mjs生成色トーン","通过scripts/extract-roles.mjs抽取Role","利用scripts/generate-roles-css.mjs生成Role CSS","支持tokens/source.json色入力","输出tokens/tones.json、tokens/tones.css色トーン","输出tokens/roles.light.json、tokens/roles.dark.json、tokens/roles.css Role"],"ja":["scripts/generate-tones.mjsを使用して色トーンを生成","scripts/extract-roles.mjsを使用してRoleを抽出","scripts/generate-roles-css.mjsを使用してRole CSSを生成","tokens/source.json色入力のサポート","tokens/tones.json、tokens/tones.css色トーンの出力","tokens/roles.light.json、tokens/roles.dark.json、tokens/roles.css Roleの出力"],"ko":["scripts/generate-tones.mjs를 사용하여 색조를 생성","scripts/extract-roles.mjs를 사용하여 역할을 추출","scripts/generate-roles-css.mjs를 사용하여 역할 CSS를 생성","tokens/source.json 색 입력 지원","tokens/tones.json, tokens/tones.css 색조 출력","tokens/roles.light.json, tokens/roles.dark.json, tokens/roles.css 역할 출력"],"es":["Generación de tonos de color con scripts/generate-tones.mjs","Extracción de roles con scripts/extract-roles.mjs","Generación de tokens de tipografía con src/index.css","Actualización automática de tokens con cambios en tokens/source.json","Compatibilidad con tokens de color, roles y tipografía"],"fr":["Génération de tons de couleur avec scripts/generate-tones.mjs","Extraction de rôles avec scripts/extract-roles.mjs","Génération de tokens de typographie avec src/index.css","Mise à jour automatique des tokens avec des changements dans tokens/source.json","Compatibilité avec les tokens de couleur, les rôles et la typographie"],"de":["Generierung von Farbtönen mit scripts/generate-tones.mjs","Extraktion von Rollen mit scripts/extract-roles.mjs","Generierung von Typografie-Tokens mit src/index.css","Automatische Aktualisierung von Tokens mit Änderungen in tokens/source.json","Kompatibilität mit Farb-, Rollen- und Typografie-Tokens"],"pt":["Utiliza tokens de cor e tipo para implementação de componentes","Suporta atualização de tokens e roles","Inclui scripts para geração de tons e extração de roles","Fornece saídas em JSON e CSS para tokens e roles","Permite personalização de cores e tipos de fontes"],"ru":["Использует токены цвета и типа для реализации компонентов","Поддерживает обновление токенов и ролей","Включает скрипты для генерации тонов и извлечения ролей","Предоставляет выходные данные в JSON и CSS для токенов и ролей","Позволяет настраивать цвета и типы шрифтов"],"ar":["يستخدم رموز الألوان والنصوص لتنفيذ المكونات","يدعم تحديث الرموز والصلاحيات","يضم سكريبتات لإنشاء درجات الألوان واستخراج الصلاحيات","يوفر مخرجات في JSON وCSS للرموز والصلاحيات","يسمح بالتخصيص الألوان وأنواع الخطوط"]},"keywords":{"en":["how to use jp-ui-foundations","what is jp-ui-foundations","jp-ui-foundations setup guide","jp-ui-foundations alternative","jp-ui-foundations vs material ui","jp-ui-foundations install","jp-ui-foundations foundation token management","jp-ui-foundations UI development","jp-ui-foundations automated token updates"],"zh":["jp-ui-foundations","AIエージェント","Foundation トークン","UI组件","颜色トーン生成","Role抽出","React","Python","CLI"],"ja":["jp-ui-foundations","AIエージェント","Foundation トークン","UIコンポーネント","色トーン生成","Role抽出","React","Python","CLI"],"ko":["jp-ui-foundations","AI 도구","Foundation トークン","UI 컴포넌트","색조 생성","역할 추출","React","Python","CLI"],"es":["jp-ui-foundations","tokens de interfaz de usuario","generación de tonos de color","extracción de roles","tokens de tipografía","implementación de tokens","herramientas de desarrollo","interfaz de usuario"],"fr":["jp-ui-foundations","tokens d''interface utilisateur","génération de tons de couleur","extraction de rôles","tokens de typographie","mise en place des tokens","outils de développement","interface utilisateur"],"de":["jp-ui-foundations","Benutzeroberflächentoken","Generierung von Farbtönen","Extraktion von Rollen","Typografie-Tokens","Implementierung von Token","Entwicklungstools","Benutzeroberfläche"],"pt":["jp-ui-foundations","tokens de cor","tokens de tipo","implementação de componentes UI","desenvolvimento de software","ferramentas de desenvolvimento","guias de configuração","melhores práticas de desenvolvimento"],"ru":["jp-ui-foundations","токены цвета","токены типа","реализация компонентов UI","разработка программного обеспечения","инструменты разработки","руководства по настройке","лучшие практики разработки"],"ar":["jp-ui-foundations","رموز الألوان","رموز النصوص","تنفيذ مكونات واجهة المستخدم","تطوير البرمجيات","أدوات التطوير","دلائل الإعداد","أفضل الممارسات للتطوير"]}},"owner":"yumehiko","repo":"jp-ui","repoPath":"yumehiko/jp-ui","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.424Z","topics":[],"category":"community","skillMd":{"name":"jp-ui-foundations","description":"jp-uiのFoundation（色/タイポ/アイコン/形状/影）を参照して実装するためのスキル。Foundationトークンや関連ファイルが更新されたらこのスキルも更新する。","bodyPreview":"# jp-ui Foundations\n\n## 使いどころ\n- コンポーネント実装時に Foundation トークン（色/タイポ/アイコン/形状/影）を参照する\n- Tokens/roles/tones の更新があった場合に内容を追随\n\n## 参照先（Source of Truth）\n- 色トーン生成: `scripts/generate-tones.mjs`\n- Role抽出: `scripts/extract-roles.mjs`\n- Role CSS生成: `scripts/generate-roles-css.mjs`\n- 色入力: `tokens/source.json`\n- 色トーン出力: `tokens/tones.json`, `tokens/tones.css`\n- Role出力: `tokens/roles.light.json`, `tokens/roles.dark.json`, `tokens/roles.css`\n- 基本CSSトークン: `src/index.css`\n\n## Foundation トークン\n### Typography\n- ベースフォン","body":"# jp-ui Foundations\n\n## 使いどころ\n- コンポーネント実装時に Foundation トークン（色/タイポ/アイコン/形状/影）を参照する\n- Tokens/roles/tones の更新があった場合に内容を追随\n\n## 参照先（Source of Truth）\n- 色トーン生成: `scripts/generate-tones.mjs`\n- Role抽出: `scripts/extract-roles.mjs`\n- Role CSS生成: `scripts/generate-roles-css.mjs`\n- 色入力: `tokens/source.json`\n- 色トーン出力: `tokens/tones.json`, `tokens/tones.css`\n- Role出力: `tokens/roles.light.json`, `tokens/roles.dark.json`, `tokens/roles.css`\n- 基本CSSトークン: `src/index.css`\n\n## Foundation トークン\n### Typography\n- ベースフォント: `\"Hiragino Sans\", sans-serif`\n- `typesetting-body` / `typesetting-betagumi` / `typesetting-tsumegumi`\n- 見出し: `typesetting-display`, `typesetting-headline`, `typesetting-title`\n- ラベル: `typesetting-label` (tsumegumi), `typesetting-editable-label` (betagumi)\n- キャプション: `typesetting-caption` (betagumi)\n\n### Color\n- 役割色: `tokens/roles.css` から `--surface`, `--on-surface`, `--primary`, `--on-primary` など\n- パレット色: `--red`, `--on-red`, `--red-container`, `--on-red-container`, `--inverse-red` など\n- Fixed: `--true-white`, `--true-black`\n- テーマクラス: `.theme-light`, `.theme-dark`\n\n### Shape\n- `--radius-none: 0`\n- `--radius-xs: 4px`\n- `--radius-s: 8px`\n- `--radius-m: 12px`\n- `--radius-l: 16px`\n- `--radius-xl: 28px`\n- `--radius-full: 8192px`\n\n### Shadow\n- `--shadow-rgb: 0 0 0`\n- `--elevation-0..5`\n- `--elevation-1`: `0 0 8px 0 rgb(var(--shadow-rgb) / 0.2), 1px 1px 4px 0 rgb(var(--shadow-rgb) / 0.1)`\n- `--elevation-2`: `0 0 12px 0 rgb(var(--shadow-rgb) / 0.2), 1px 1px 6px 0 rgb(var(--shadow-rgb) / 0.15)`\n- `--elevation-3`: `0 0 16px 0 rgb(var(--shadow-rgb) / 0.2), 2px 2px 8px 0 rgb(var(--shadow-rgb) / 0.2)`\n- `--elevation-4`: `0 0 20px 0 rgb(var(--shadow-rgb) / 0.2), 3px 3px 12px 0 rgb(var(--shadow-rgb) / 0.2)`\n- `--elevation-5`: `0 0 24px 0 rgb(var(--shadow-rgb) / 0.2), 4px 4px 16px 0 rgb(var(--shadow-rgb) / 0.3)`\n\n### Icons\n- アイコン: `src/assets/icons/Icon.tsx`\n- 生成マップ: `src/assets/icons/iconMap.generated.ts`\n- アイコン一覧: `src/pages/IconsPage.tsx`\n\n## 更新時のルール\n- Foundation トークンを更新したら、このスキルの記載も更新する\n- 新しい参照先ファイルを追加したら `参照先` セクションに追加\n\n## スクリプト実行コマンド\n- `pnpm gen:tones`\n- `pnpm gen:roles`\n- `pnpm gen:roles-css`\n"},"lastSynced":"2026-03-08T02:07:26.611Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined UI component implementation with Foundation tokens","zh":"非常适合需要简化UI组件实现的Foundation令牌的前端代理","ja":"Foundationトークンのストリームライン化されたUIコンポーネントの実装が必要なフロントエンドエージェントに最適","ko":"Foundation 토큰의 스트리밍된 UI 컴포넌트 구현이 필요한 프론트엔드 에이전트에 적합","es":"Perfecto para agentes frontend que necesitan una implementación de componentes de interfaz de usuario optimizada con tokens de Foundation","fr":"Parfait pour les agents frontend qui ont besoin d''une mise en œuvre de composants d''interface utilisateur rationalisée avec des jetons de Foundation","de":"Perfekt für Frontend-Agents, die eine optimierte Implementierung von Benutzeroberflächenkomponenten mit Foundation-Tokens benötigen","pt":"Perfeito para Agentes de Frontend que necessitam de uma implementação simplificada de componentes de UI com tokens do Foundation","ru":"Идеально подходит для Фронтенд-Агентов, которым требуется упрощенная реализация компонентов пользовательского интерфейса с использованием токенов Foundation","ar":"مثالي لوكلاء الواجهة الأمامية الذين يحتاجون إلى تنفيذ مبسط لمكونات واجهة المستخدم باستخدام رموز Foundation"},"recommendation":{"en":"Empowers agents to automate updates to tokens, roles, and tones, leveraging scripts like generate-tones.mjs and extract-roles.mjs, and utilizing JSON files such as tokens/source.json and tokens/tones.json for seamless UI development","zh":"赋予代理自动更新令牌、角色和语气的能力，利用诸如generate-tones.mjs和extract-roles.mjs的脚本，并利用诸如tokens/source.json和tokens/tones.json的JSON文件进行无缝的UI开发","ja":"エージェントにトークン、ロール、トーンを自動更新する能力を付与し、generate-tones.mjsやextract-roles.mjsなどのスクリプトを使用し、tokens/source.jsonやtokens/tones.jsonなどのJSONファイルを使用してシームレスなUI開発を行う","ko":"에이전트가 토큰, 역할 및 음색을 자동으로 업데이트할 수 있는 기능을 제공하며 generate-tones.mjs 및 extract-roles.mjs와 같은 스크립트를 사용하고 tokens/source.json 및 tokens/tones.json과 같은 JSON 파일을 사용하여 無縫의 UI 개발을 수행","es":"Permite a los agentes automatizar las actualizaciones de tokens, roles y tonos, aprovechando scripts como generate-tones.mjs y extract-roles.mjs, y utilizando archivos JSON como tokens/source.json y tokens/tones.json para un desarrollo de interfaz de usuario sin problemas","fr":"Permet aux agents d''automatiser les mises à jour des jetons, des rôles et des tons, en exploitant des scripts tels que generate-tones.mjs et extract-roles.mjs, et en utilisant des fichiers JSON tels que tokens/source.json et tokens/tones.json pour un développement d''interface utilisateur sans accroc","de":"Ermächtigt Agenten, Updates von Tokens, Rollen und Tönen zu automatisieren, indem sie Skripte wie generate-tones.mjs und extract-roles.mjs nutzen und JSON-Dateien wie tokens/source.json und tokens/tones.json für eine reibungslose Benutzeroberflächenentwicklung verwenden","pt":"Capacita os agentes a automatizar atualizações de tokens, roles e tones, aproveitando scripts como generate-tones.mjs e extract-roles.mjs, e utilizando arquivos JSON como tokens/source.json e tokens/tones.json para um desenvolvimento de UI sem interrupções","ru":"Позволяет агентам автоматизировать обновления токенов, ролей и тонов, используя скрипты, такие как generate-tones.mjs и extract-roles.mjs, и применяя JSON-файлы, например tokens/source.json и tokens/tones.json, для беспрепятственной разработки пользовательского интерфейса","ar":"يمكن الوكلاء من أتمتة التحديثات للرموز والأدوار والدرجات، والاستفادة من البرامج النصية مثل generate-tones.mjs و extract-roles.mjs، واستخدام ملفات JSON مثل tokens/source.json و tokens/tones.json لتطوير واجهة المستخدم بسلاسة"},"useCases":{"en":["Automating Foundation token updates for color, typography, and icon consistency","Generating tones and roles for light and dark modes using scripts/generate-tones.mjs and scripts/extract-roles.mjs","Referencing source of truth files like tokens/source.json for accurate color input"],"zh":["自动更新Foundation令牌以实现颜色、排版和图标的一致性","使用scripts/generate-tones.mjs和scripts/extract-roles.mjs脚本为浅色和深色模式生成语气和角色","引用诸如tokens/source.json的真实文件以获取准确的颜色输入"],"ja":["Foundationトークンを自動更新してカラー、タイポグラフィー、アイコンの一貫性を実現する","scripts/generate-tones.mjsやscripts/extract-roles.mjsなどのスクリプトを使用してライトモードとダークモードのトーンやロールを生成する","tokens/source.jsonなどの真実のファイルを参照して正確なカラー入力を取得する"],"ko":["Foundation 토큰을 자동으로 업데이트하여 색상, 타이포그래피 및 아이콘의 일관성을 실현","scripts/generate-tones.mjs 및 scripts/extract-roles.mjs와 같은 스크립트를 사용하여浅色 및 深色 모드의 음색 및 역할을 생성","tokens/source.json과 같은 진실 파일을 참조하여 정확한 색상 입력을 얻는 것"],"es":["Automatización de actualizaciones de tokens de Foundation para la coherencia de color, tipografía e iconos","Generación de tonos y roles para modos claros y oscuros utilizando scripts/generate-tones.mjs y scripts/extract-roles.mjs","Referencia a archivos de verdad como tokens/source.json para una entrada de color precisa"],"fr":["Automatisation des mises à jour des jetons de Foundation pour la cohérence des couleurs, de la typographie et des icônes","Génération de tons et de rôles pour les modes clair et sombre en utilisant scripts/generate-tones.mjs et scripts/extract-roles.mjs","Référence à des fichiers de vérité tels que tokens/source.json pour une saisie de couleur précise"],"de":["Automatisierung von Foundation-Token-Updates für Farb-, Typografie- und Icon-Konsistenz","Generierung von Tönen und Rollen für helle und dunkle Modi unter Verwendung von scripts/generate-tones.mjs und scripts/extract-roles.mjs","Verweis auf Wahrheitsdateien wie tokens/source.json für eine genaue Farbeingabe"],"pt":["Automatização de atualizações de tokens do Foundation para cores, tipografia e consistência de ícones","Geração de tons e roles para modos claro e escuro usando scripts/generate-tones.mjs e scripts/extract-roles.mjs","Referência a arquivos de fonte da verdade como tokens/source.json para entrada de cor precisa"],"ru":["Автоматизация обновлений токенов Foundation для обеспечения согласованности цветов, типографики и иконок","Генерация тонов и ролей для светлого и темного режимов с использованием scripts/generate-tones.mjs и scripts/extract-roles.mjs","Обращение к файлам единственного источника истины, таким как tokens/source.json, для точного ввода цвета"],"ar":["أتمتة تحديثات رموز Foundation للألوان والطباعة واتساق الأيقونات","إنشاء الدرجات والأدوار لوضعيات الضوء والظلام باستخدام scripts/generate-tones.mjs و scripts/extract-roles.mjs","الرجوع إلى ملفات المصدر الموثوق مثل tokens/source.json لإدخال لون دقيق"]},"limitations":{"en":["Requires access to Foundation token scripts and JSON files","Limited to UI component implementation with Foundation tokens"],"zh":["需要访问Foundation令牌脚本和JSON文件","仅限于使用Foundation令牌进行UI组件实现"],"ja":["FoundationトークンのスクリプトやJSONファイルへのアクセスが必要","Foundationトークンを使用したUIコンポーネントの実装に限定される"],"ko":["Foundation 토큰 스크립트 및 JSON 파일에 대한 액세스가 필요","Foundation 토큰을 사용한 UI 컴포넌트 구현에만 محدود"],"es":["Requiere acceso a scripts y archivos JSON de tokens de Foundation","Limitado a la implementación de componentes de interfaz de usuario con tokens de Foundation"],"fr":["Nécessite un accès aux scripts et aux fichiers JSON de jetons de Foundation","Limité à la mise en œuvre de composants d''interface utilisateur avec des jetons de Foundation"],"de":["Benötigt Zugriff auf Foundation-Token-Skripte und JSON-Dateien","Begrenzt auf die Implementierung von Benutzeroberflächenkomponenten mit Foundation-Tokens"],"pt":["Requer acesso aos scripts de tokens do Foundation e arquivos JSON","Limitado à implementação de componentes de UI com tokens do Foundation"],"ru":["Требует доступа к скриптам токенов Foundation и JSON-файлам","Ограничено реализацией компонентов пользовательского интерфейса с токенами Foundation"],"ar":["يتطلب الوصول إلى برامج رموز Foundation النصية وملفات JSON","ي