INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yumehiko/jp-ui/jp-ui-foundations', 'jp-ui-foundations', 'yumehiko', 'jp-ui', 'community', 'jp-ui-foundations yumehiko jp-ui community jp-ui-foundations is a technical skill that facilitates UI component implementation by referencing Foundation tokens. It benefits developers by automating updates to tokens, roles, and tones. jp-ui-foundations是一个用于实现Foundation トークンのAIエージェント技能，帮助开发者优化UI组件的实现 jp-ui-foundationsは、Foundation トークンの実装を支援するAIエージェントスキルです jp-ui-foundations는 Foundation トークンの 구현을 지원하는 AI 도구 스킬입니다 jp-ui-foundations es un conjunto de herramientas para implementar tokens de interfaz de usuario. Permite generar tonos de color, roles y tokens de tipografía de manera efectiva jp-ui-foundations est un ensemble d''outils pour mettre en place des tokens d''interface utilisateur. Il permet de générer des tons de couleur, des rôles et des tokens de typographie de manière efficace jp-ui-foundations ist ein Satz von Tools zur Implementierung von Benutzeroberflächentoken. Es ermöglicht die effektive Generierung von Farbtönen, Rollen und Typografie-Tokens O jp-ui-foundations é uma ferramenta para implementação de componentes UI com tokens de cor, tipo e ícone jp-ui-foundations - это инструмент для реализации компонентов UI с токенами цвета, типа и иконки jp-ui-foundations هو أداة لتنفيذ مكونات واجهة المستخدم مع رموز الألوان والنصوص والأيقونات how to use jp-ui-foundations what is jp-ui-foundations jp-ui-foundations setup guide jp-ui-foundations alternative jp-ui-foundations vs material ui jp-ui-foundations install jp-ui-foundations foundation token management jp-ui-foundations UI development jp-ui-foundations automated token updates jp-ui-foundations AIエージェント Foundation トークン UI组件 颜色トーン生成 Role抽出 React Python CLI Generates color tones using scripts/generate-tones.mjs Extracts roles via scripts/extract-roles.mjs Updates role CSS with scripts/generate-roles-css.mjs Manages color input and output via tokens/source.json and tokens/tones.json Produces role output files including tokens/roles.light.json and tokens/roles.dark.json Utilizes basic CSS tokens from src/index.css jp-ui-foundations is a technical skill that provides a foundation for UI development by managing tokens, including color, typography, icons, shapes, and shadows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Exaphis/baby-copilot/unslop', 'community', 'Exaphis', 'baby-copilot', 'Exaphis/baby-copilot', 'unslop', 0, 0, 20, '2026-03-08T01:57:15.440Z', '2026-03-08T02:07:41.308Z', 'bfdce7c7e99813d81853540f1e5fac2152928603c5f21d390b56e49034997556', '{"id":"Exaphis/baby-copilot/unslop","name":"unslop","description":{"en":"unslop is a code completion tool that helps developers clean up AI-generated code by removing extra comments, defensive checks, and inconsistent styles. It benefits developers working with large codebases.","zh":"unslop是一种代码优化工具，帮助开发者清除AI生成的冗余代码。它可以检查代码差异并删除不必要的注释、防御性检查和类型转换","ja":"unslopは、AIエージェントによって生成された冗長コードを削除するコード最適化ツールです。コードの差分を分析して、不要なコードを削除します","ko":"unslop는 개발자가 AI 생성 코드의冗余 부분을 제거하는 코드 최적화 도구입니다. 코드 차이점을 분석하여 불필요한 부분을 제거하여 코드의 가독성을 향상합니다","es":"Unslop es una herramienta de finalización de código que elimina el código innecesario introducido por la IA. Ayuda a mantener un código limpio y consistente","fr":"Unslop est un outil de complétion de code qui élimine le code inutile introduit par l''IA. Il aide à maintenir un code propre et cohérent","de":"Unslop ist ein Code-Vervollständigungstool, das den nicht benötigten Code entfernt, der von der KI eingeführt wurde. Es hilft, einen sauberen und konsistenten Code beizubehalten","pt":"O Unslop é uma ferramenta de conclusão de código que ajuda a remover código desnecessário e melhorar a qualidade do código","ru":"Unslop - это инструмент автозавершения кода, который помогает удалять ненужный код и улучшать качество кода","ar":"Unslop هو أداة استكمال الشفرة التي تساعد على إزالة الشفرة غير الضرورية وتحسين جودة الشفرة"},"seo":{"title":{"en":"unslop: Code Cleanup and Optimization Guide | AI Agent Skill","zh":"unslop 代码优化工具：清除AI生成的冗余代码","ja":"unslop Setup Guide: AIエージェントによる冗長コードの削除","ko":"unslop 코드 최적화 가이드: AI 생성 코드 정리","es":"Guía de configuración de unslop: Herramienta de finalizac...","fr":"Guide d''installation d''unslop: Outil de complétion de code","de":"Einrichtungsleitfaden für unslop: Code-Vervollständigungs...","pt":"Guia de Configuração do Unslop: Ferramenta de Conclusão d...","ru":"Настройка Unslop: ИИ Агенты для Автозавершения Код","ar":"دليل إعداد Unslop: أداة استكمال الشفرة الذكية"},"description":{"en":"Discover how unslop simplifies code review by removing unnecessary AI-generated content. Learn how to integrate unslop into your workflow today!","zh":"unslop是一种代码优化工具，帮助开发者清除AI生成的冗余代码，包括多余的注释、防御性检查和类型转换","ja":"unslopは、AIエージェントによって生成された冗長コードを削除するコード最適化ツールです。コードのクリーンアップを支援します","ko":"unslop는 개발자가 AI 생성 코드의冗余 부분을 제거하는 코드 최적화 도구입니다. 코드 차이점을 분석하여 불필요한 부분을 제거합니다","es":"Aprende a utilizar unslop, una herramienta de finalización de código que elimina el ''slop'' introducido por la IA en tu código","fr":"Découvrez comment utiliser unslop, un outil de complétion de code qui élimine le ''slop'' introduit par l''IA dans votre code","de":"Erfahren Sie, wie Sie unslop verwenden, ein Code-Vervollständigungstool, das den von der KI eingeführten ''slop'' in Ihrem Code entfernt","pt":"Aprenda a usar o Unslop para melhorar a qualidade do seu código, removendo comentários desnecessários e defensive checks","ru":"Узнайте, как настроить Unslop для улучшения качества кода, удаляя ненужные комментарии и защитные проверки","ar":"تعرف على كيفية استخدام Unslop لتحسين جودة الشفرة الخاصة بك، وإزالة التعليقات الزائدة والتحقق الدفاعي"},"definition":{"en":"unslop is a teeny code completion tool that checks diffs against the main branch and removes AI-generated slop, ensuring consistent coding styles.","zh":"unslop是一种代码优化工具，用于清除AI生成的冗余代码","ja":"unslopは、AIエージェントによって生成された冗長コードを削除するためのコード最適化ツール","ko":"unslop는 AI 생성 코드의冗余 부분을 제거하는 코드 최적화 도구","es":"Unslop es una herramienta de código que elimina el ''slop'' introducido por la IA en el código","fr":"Unslop est un outil de code qui élimine le ''slop'' introduit par l''IA dans le code","de":"Unslop ist ein Code-Tool, das den von der KI eingeführten ''slop'' im Code entfernt","pt":"O que é Unslop? Uma ferramenta de conclusão de código que remove comentários desnecessários e defensive checks","ru":"Что такое Unslop? Инструмент автозавершения кода, который удаляет ненужные комментарии и защитные проверки","ar":"ما هو Unslop؟ أداة استكمال الشفرة التي تزيل التعليقات الزائدة والتحقق الدفاعي"},"features":{"en":["Removes extra comments inconsistent with the rest of the file","Eliminates abnormal defensive checks and try/catch blocks","Removes casts to any that get around type issues","Deletes tests that do not test actual code","Reports inconsistencies at the end of the cleanup process"],"zh":["清除AI生成的冗余代码","检查代码差异","删除不必要的注释","删除防御性检查和类型转换","改善代码的可读性"],"ja":["AIエージェントによって生成された冗長コードの削除","コードの差分の分析","不要なコメントの削除","防御性チェックと型変換の削除","コードの可読性の向上"],"ko":["AI 생성 코드의冗余 부분을 제거","코드 차이점을 분석","불필요한 주석을 제거","防御적 체크와 타입 변환을 제거","코드의 가독성을 향상"],"es":["Elimina comentarios adicionales inconsistentes","Remueve comprobaciones defensivas y bloques try/catch innecesarios","Elimina conversiones a ''any'' para evitar problemas de tipo","Elimina pruebas que no verifican código real","Mantiene un estilo de código consistente con el resto del archivo"],"fr":["Élimine les commentaires supplémentaires incohérents","Supprime les vérifications défensives et les blocs try/catch inutiles","Élimine les conversions en ''any'' pour éviter les problèmes de type","Élimine les tests qui ne vérifient pas de code réel","Maintient un style de code cohérent avec le reste du fichier"],"de":["Entfernt inkonsistente Zusatzkommentare","Entfernt unnötige defensive Prüfungen und try/catch-Blöcke","Entfernt Umwandlungen in ''any'', um Typprobleme zu vermeiden","Entfernt Tests, die keinen echten Code überprüfen","Hält einen konsistenten Code-Stil mit dem Rest der Datei bei"],"pt":["Remoção de comentários desnecessários","Remoção de defensive checks anormais","Verificação de casts para any","Remoção de testes que não testam código real","Compatibilidade com CLI"],"ru":["Удаление ненужных комментариев","Удаление аномальных защитных проверок","Проверка кастов для any","Удаление тестов, которые не тестируют реальный код","Совместимость с CLI"],"ar":["إزالة التعليقات غير الضرورية","إزالة التحقق الدفاعي غير العادي","التحقق من التحويلات إلى أي","إزالة الاختبارات التي لا تختبر الشفرة الحقيقية","التوافق مع CLI"]},"keywords":{"en":["how to use unslop","unslop alternative","unslop setup guide","what is unslop","unslop vs code cleanup tools","unslop install"],"zh":["代码优化工具","AI生成代码","代码清理","代码差异分析","代码可读性","代码优化","AI代码优化","代码分析工具"],"ja":["コード最適化ツール","AIエージェント","コードクリーンアップ","コードの差分分析","コードの可読性","コード最適化","AIコード最適化","コード分析ツール"],"ko":["코드 최적화 도구","AI 생성 코드","코드 정리","코드 차이점 분석","코드 가독성","코드 최적화","AI 코드 최적화","코드 분석 도구"],"es":["herramientas de código","finalización de código","IA y desarrollo","herramientas de desarrollo de software","code review","mejora del código","herramientas de automatización de código","desarrollo de software ágil"],"fr":["outils de code","complétion de code","IA et développement","outils de développement de logiciels","revue de code","amélioration du code","outils d''automatisation de code","développement de logiciels agile"],"de":["Code-Tools","Code-Vervollständigung","KI und Entwicklung","Software-Entwicklungstools","Code-Review","Code-Verbesserung","Code-Automatisierungstools","agiles Software-Entwickeln"],"pt":["ferramenta de conclusão de código","melhoria da qualidade do código","remoção de comentários desnecessários","defensive checks","CLI","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["инструмент автозавершения кода","улучшение качества кода","удаление ненужных комментариев","защитные проверки","CLI","разработка программного обеспечения","инструменты разработки"],"ar":["أداة استكمال الشفرة","تحسين جودة الشفرة","إزالة التعليقات غير الضرورية","التحقق الدفاعي","CLI","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Exaphis","repo":"baby-copilot","repoPath":"Exaphis/baby-copilot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.440Z","topics":[],"category":"community","skillMd":{"name":"unslop","description":"Only use when explicitly specified by the user.","bodyPreview":"Check the diff against main, and remove all AI generated slop introduced in this branch.\n\nThis includes:\n- Extra comments that a human wouldn''t add or is inconsistent with the rest of the file\n- Extra defensive checks or try/catch blocks that are abnormal for that area of the codebase (especially if called by trusted / validated codepaths)\n- Casts to any to get around type issues\n- Tests that do not test actual code\n- Any other style that is inconsistent with the file\n\nReport at the end with onl","body":"Check the diff against main, and remove all AI generated slop introduced in this branch.\n\nThis includes:\n- Extra comments that a human wouldn''t add or is inconsistent with the rest of the file\n- Extra defensive checks or try/catch blocks that are abnormal for that area of the codebase (especially if called by trusted / validated codepaths)\n- Casts to any to get around type issues\n- Tests that do not test actual code\n- Any other style that is inconsistent with the file\n\nReport at the end with only a 1-3 sentence summary of what you changed\n"},"lastSynced":"2026-03-08T02:07:41.308Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents needing advanced code cleanup capabilities for AI-generated code.","zh":"非常适合需要高级代码清理功能的代码重构代理，特别是在处理AI生成的代码时。","ja":"AIによって生成されたコードの高度なコードクリーニング機能を必要とするコードリファクタリングエージェントに最適。","ko":"AI가 생성한 코드에 대한 고급 코드 정리 기능을 필요로 하는 코드 리팩토링 에이전트에게 적합합니다.","es":"Perfecto para agentes de refactorización de código que necesitan capacidades avanzadas de limpieza de código para código generado por AI.","fr":"Parfait pour les agents de refactoring de code nécessitant des capacités de nettoyage de code avancées pour le code généré par l''IA.","de":"Perfekt für Code-Refactoring-Agents, die erweiterte Code-Reinigungsfunktionen für von KI generierten Code benötigen.","pt":"Perfeito para Agentes de Refatoração de Código que necessitam de capacidades avançadas de limpeza de código para código gerado por IA.","ru":"Идеально подходит для агентов рефакторинга кода, которым требуются расширенные возможности очистки кода для кода, сгенерированного ИИ.","ar":"مثالي لعميل إعادة هيكلة الشفرة الذي يحتاج إلى إمكانيات متقدمة لتنظيف الشفرة المولدة بواسطة الذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to refactor AI-generated code by removing extra comments, defensive checks, and inconsistent styles, ensuring consistency with the rest of the codebase through diff analysis against the main branch, utilizing features like comment removal and defensive check validation.","zh":"赋予代理重构AI生成的代码的能力，通过删除多余的注释、防御性检查和不一致的样式，确保代码与主分支的一致性，利用诸如注释删除和防御性检查验证等功能。","ja":"エージェントにAIによって生成されたコードをリファクタリングする能力を与え、余分なコメント、防御的チェック、および一貫性のないスタイルを削除し、差分分析を使用してメインブランチとの一貫性を確保する。","ko":"에이전트가 AI가 생성한 코드를 리팩토링할 수 있도록 해주며, 불필요한 주석, 방어적 확인 및 일관성 없는 스타일을 제거하여 코드베이스의 나머지 부분과 일관성을 유지하고, 주석 제거 및 방어적 확인 유효성 검사와 같은 기능을 사용합니다.","es":"Habilita a los agentes a refactorizar el código generado por la IA eliminando comentarios adicionales, comprobaciones defensivas y estilos inconsistentes, garantizando la coherencia con el resto de la base de código a través del análisis de diff contra la rama principal, utilizando características como la eliminación de comentarios y la validación de comprobaciones defensivas.","fr":"Permet aux agents de refactoriser le code généré par l''IA en supprimant les commentaires supplémentaires, les vérifications de défense et les styles incohérents, en garantissant la cohérence avec le reste de la base de code grâce à l''analyse de diff par rapport à la branche principale, en utilisant des fonctionnalités telles que la suppression de commentaires et la validation des vérifications de défense.","de":"Ermächtigt Agenten, von KI generierten Code zu refaktorisieren, indem es zusätzliche Kommentare, defensive Prüfungen und inkonsistente Stile entfernt, um die Konsistenz mit dem Rest des Codebases durch Diff-Analyse gegen den Hauptzweig sicherzustellen, indem es Funktionen wie Kommentarentfernung und Validierung von Schutzprüfungen nutzt.","pt":"Habilita os agentes a refactorar o código gerado por IA, removendo comentários adicionais, verificações defensivas e estilos inconsistentes, garantindo a consistência com o restante da base de código por meio da análise de diff contra o branch principal, utilizando recursos como remoção de comentários e validação de verificações defensivas.","ru":"Предоставляет агентам возможность рефакторинга кода, сгенерированного ИИ, путем удаления лишних комментариев, защитных проверок и несоответствующих стилей, гарантируя согласованность с остальной частью кодовой базы посредством анализа diff против основной ветки, используя функции, такие как удаление комментариев и проверка защитных проверок.","ar":"تمكين الوكلاء من إعادة هيكلة الشفرة المولدة بواسطة الذكاء الاصطناعي من خلال إزالة التعليقات الإضافية والتحقق الدفاعي والأسلوب غير المتسق، وضمان الاتساق مع بقية قاعدة الشفرة من خلال تحليل الفرق ضد الفرع الرئيسي، باستخدام ميزات مثل إزالة التعليقات وتحقق التحقق الدفاعي."},"useCases":{"en":["Refactoring AI-generated code for consistency","Removing unnecessary defensive checks and try/catch blocks","Cleaning up extra comments and casts in code"],"zh":["为了与代码库保持一致而重构AI生成的代码","删除不必要的防御性检查和try/catch块","清理代码中的多余注释和强制类型转换"],"ja":["コードベースの一貫性を保つためにAIによって生成されたコードをリファクタリングする","不要な防御的チェックとtry/catchブロックを削除する","コード内の余分なコメントとキャストをクリーンアップする"],"ko":["코드베이스와 일관성을 유지하기 위해 AI가 생성한 코드를 리팩토링하는こと","필요없는 방어적 확인 및 try/catch 블록을 제거하는 것","코드 내의 불필요한 주석 및 캐스트를 정리하는 것"],"es":["Refactorización de código generado por AI para la coherencia","Eliminación de comprobaciones defensivas y bloques try/catch innecesarios","Limpieza de comentarios y conversiones adicionales en el código"],"fr":["Refactoring de code généré par l''IA pour la cohérence","Suppression de vérifications de défense et de blocs try/catch inutiles","Nettoyage de commentaires et de conversions supplémentaires dans le code"],"de":["Refaktorisierung von von KI generiertem Code für Konsistenz","Entfernung unnötiger Schutzprüfungen und try/catch-Blöcke","Reinigung von zusätzlichen Kommentaren und Typumwandlungen im Code"],"pt":["Refatoração de código gerado por IA para consistência","Remoção de verificações defensivas e blocos try/catch desnecessários","Limpeza de comentários e conversões extras em código"],"ru":["Рефакторинг кода, сгенерированного ИИ, для согласованности","Удаление ненужных защитных проверок и блоков try/catch","Очистка лишних комментариев и приведений в коде"],"ar":["إعادة هيكلة الشفرة المولدة بواسطة الذكاء الاصطناعي من أجل الاتساق","إزالة التحقق الدفاعي والكتل try/catch غير الضرورية","تنظيف التعليقات الإضافية والتحويلات في الشفرة"]},"limitations":{"en":["Requires access to code repository","Limited to codebases with consistent style guidelines"],"zh":["需要访问代码仓库","仅限于具有一致样式指南的代码库"],"ja":["コードリポジトリへのアクセスが必要","一貫したスタイルガイドラインを持つコードベースのみに限定"],"ko":["코드 저장소에 접근할 수 있어야 함","일관된 스타일 가이드라인을 갖춘 코드베이스만 해당"],"es":["Requiere acceso al repositorio de código","Limitado a codebases con directrices de estilo coherentes"],"fr":["Nécessite un accès au référentiel de code","Limité aux codebases avec des lignes directrices de style cohérentes"],"de":["Erfordert Zugriff auf Code-Repository","Begrenzt auf Codebases mit konsistenten Stilrichtlinien"],"pt":["Requer acesso ao repositório de código","Limitado a codebases com diretrizes de estilo consistentes"],"ru":["Требует доступа к хранилищу кода","Ограничен кодовыми базами с согласованными руководствами по стилю"],"ar":["يتطلب الوصول إلى مستودع الشفرة","محدود بقواعد الشفرة التي لديها إرشادات أسلوب متسقة"]},"version":4},"contentHash":"bfdce7c7e99813d81853540f1e5fac2152928603c5f21d390b56e49034997556","qualityScore":20}');
