INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Exaphis/baby-copilot/unslop', 'unslop', 'Exaphis', 'baby-copilot', 'community', 'unslop Exaphis baby-copilot community unslop is a code completion tool that helps developers clean up AI-generated code by removing extra comments, defensive checks, and inconsistent styles. It benefits developers working with large codebases. unslop是一种代码优化工具，帮助开发者清除AI生成的冗余代码。它可以检查代码差异并删除不必要的注释、防御性检查和类型转换 unslopは、AIエージェントによって生成された冗長コードを削除するコード最適化ツールです。コードの差分を分析して、不要なコードを削除します unslop는 개발자가 AI 생성 코드의冗余 부분을 제거하는 코드 최적화 도구입니다. 코드 차이점을 분석하여 불필요한 부분을 제거하여 코드의 가독성을 향상합니다 Unslop es una herramienta de finalización de código que elimina el código innecesario introducido por la IA. Ayuda a mantener un código limpio y consistente Unslop est un outil de complétion de code qui élimine le code inutile introduit par l''IA. Il aide à maintenir un code propre et cohérent Unslop ist ein Code-Vervollständigungstool, das den nicht benötigten Code entfernt, der von der KI eingeführt wurde. Es hilft, einen sauberen und konsistenten Code beizubehalten O Unslop é uma ferramenta de conclusão de código que ajuda a remover código desnecessário e melhorar a qualidade do código Unslop - это инструмент автозавершения кода, который помогает удалять ненужный код и улучшать качество кода Unslop هو أداة استكمال الشفرة التي تساعد على إزالة الشفرة غير الضرورية وتحسين جودة الشفرة how to use unslop unslop alternative unslop setup guide what is unslop unslop vs code cleanup tools unslop install 代码优化工具 AI生成代码 代码清理 代码差异分析 代码可读性 代码优化 AI代码优化 代码分析工具 Removes extra comments inconsistent with the rest of the file Eliminates abnormal defensive checks and try/catch blocks Removes casts to any that get around type issues Deletes tests that do not test actual code Reports inconsistencies at the end of the cleanup process unslop is a teeny code completion tool that checks diffs against the main branch and removes AI-generated slop, ensuring consistent coding styles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('elmagnificogi/elmagnificogi.github.io/article-review', 'community', 'elmagnificogi', 'elmagnificogi.github.io', 'elmagnificogi/elmagnificogi.github.io', 'article-review', 0, 0, 20, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:45.615Z', '33652c68f2e04e57d21e2899b5a65b49acd846771e67d4ae6a4e33eacb7219fb', '{"id":"elmagnificogi/elmagnificogi.github.io/article-review","name":"article-review","description":{"en":"The article-review skill enables AI agents to review articles by checking for writing errors, ignoring punctuation and formatting issues, and providing a brief report of modifications. This skill benefits developers and content creators who need to review and refine articles.","zh":"文章内容审查是AIエージェント提供的文档检查和润色功能，帮助开发者提高写作质量","ja":"記事レビューは、AIエージェントが提供する文書のチェックと潤色機能で、開発者の文章の質を向上させることができます","ko":"기사 리뷰는 AI 에이전트가 제공하는 문서 체크와润色 기능으로, 개발者の 글질을 향상시킬 수 있습니다","es":"El skill de revisión de artículos utiliza instrucciones detalladas para revisar y mejorar la calidad de los textos, ignorando problemas de puntuación y mezcla de idiomas.","fr":"Le skill de révision d''articles utilise des instructions détaillées pour réviser et améliorer la qualité des textes, en ignorant les problèmes de ponctuation et de mélange de langues.","de":"Der Artikel-Überprüfungsskill verwendet detaillierte Anweisungen, um die Qualität von Texten zu überprüfen und zu verbessern, wobei Probleme mit der Zeichensetzung und der Mischung von Sprachen ignoriert werden.","pt":"O article-review é uma ferramenta de revisão de artigos que utiliza tecnologias de processamento de linguagem natural para detectar erros e sugerir melhorias","ru":"ИИ Агент article-review - это инструмент для проверки статей, который использует технологии обработки естественного языка для обнаружения ошибок и предложения улучшений","ar":"أداة المراجعة article-review هي أداة مراجعة مقالات تستخدم تقنيات معالجة اللغة الطبيعية لاكتشاف الأخطاء وتقديم مقترحات لتحسينها"},"seo":{"title":{"en":"article-review: AI-Powered Article Review Setup Guide | A...","zh":"文章内容审查Setup Guide - AIエージェント文档审查工具","ja":"記事レビューガイド - AIエージェントによる文章校正ツール","ko":"기사 리뷰 설정 가이드 - AI 에이전트 기사 작성 도구","es":"Guía de revisión de artículos con Agentes de IA","fr":"Guide de révision d''articles avec les outils d''IA","de":"Leitfaden für Artikel-Überprüfung mit KI-Agenten","pt":"Guia de Configuração do article-review: Ferramenta de Rev...","ru":"Настройка ИИ Агента article-review: Инструмент для провер...","ar":"دليل إعداد أداة المراجعة article-review: أداة مراجعة المق..."},"description":{"en":"Discover how article-review skill helps AI agents review articles efficiently. Learn how to setup and utilize this skill for optimal results.","zh":"使用AIエージェント的文章内容审查功能，自动检查和修改文档错误，提高写作质量。点击了解更多","ja":"AIエージェントの記事レビュー機能を使用して、文書のエラーを自動的にチェックして修正します。詳細はこちら","ko":"AI 에이전트의 기사 리뷰 기능을 사용하여 문서 오류를 자동으로 체크하고 수정하여 작성 품질을 향상합니다. 자세히 보기","es":"Aprende a utilizar el skill de revisión de artículos para detectar errores y mejorar la calidad de tus textos con la ayuda de Agentes de IA","fr":"Découvrez comment utiliser le skill de révision d''articles pour détecter les erreurs et améliorer la qualité de vos textes avec les outils d''IA","de":"Erfahren Sie, wie Sie den Artikel-Überprüfungsskill verwenden, um Fehler zu erkennen und die Qualität Ihrer Texte mit KI-Agenten zu verbessern","pt":"Aprenda a configurar o article-review para revisar e aperfeiçoar artigos com precisão, utilizando tecnologias de processamento de linguagem natural","ru":"Узнайте, как настроить ИИ Агент article-review для проверки и доработки статей с помощью технологий обработки естественного языка","ar":"تعرف على كيفية إعداد أداة المراجعة article-review لمراجعة وتحسين المقالات بدقة، باستخدام تقنيات معالجة اللغة الطبيعية"},"definition":{"en":"article-review is a skill that provides AI agents with detailed instructions to review articles, including checking for errors, ignoring formatting issues, and refining content.","zh":"文章内容审查是一种AIエージェント工具，用于检查和修改文档错误","ja":"記事レビューは、AIエージェントツールの一種で、文書のエラーをチェックして修正するために使用されます","ko":"기사 리뷰는 AI 에이전트 도구의 한 종류로, 문서 오류를 체크하고 수정하는 데 사용됩니다","es":"El skill de revisión de artículos es una función que utiliza Agentes de IA para revisar y mejorar la calidad de los textos","fr":"Le skill de révision d''articles est une fonction qui utilise les outils d''IA pour réviser et améliorer la qualité des textes","de":"Der Artikel-Überprüfungsskill ist eine Funktion, die KI-Agenten verwendet, um die Qualität von Texten zu überprüfen und zu verbessern","pt":"O article-review é uma ferramenta de revisão de artigos que utiliza tecnologias de processamento de linguagem natural","ru":"ИИ Агент article-review - это инструмент для проверки статей, который использует технологии обработки естественного языка","ar":"أداة المراجعة article-review هي أداة مراجعة مقالات تستخدم تقنيات معالجة اللغة الطبيعية"},"features":{"en":["Checks for writing errors in documents following the ''year-month-day-article-title'' naming convention","Ignores punctuation and mixed English and Chinese formatting issues","Provides a brief report of modifications before proceeding with further refinements","Refines article content by mimicking the writing style and tone of the original document","Executes a series of steps, including checking, reporting, and refining, to ensure thorough article review"],"zh":["自动检查文档中的文字书写错误","忽略标点符号、中英混排的问题","模仿文档中书写的风格和语气，对全文进行润色","向用户简要汇报修改点，等待确认","支持年-月-日-文章标题的文档命名规则"],"ja":["文書内の文字の書き間違いを自動的にチェック","句読点や中英混在の問題を無視","文書中の書き方のスタイルやトーンを模倣して全文を潤色","修正点をユーザーに簡潔に報告して確認を待つ","年-月-日-記事タイトルの文書命名規則をサポート"],"ko":["문서 내의文字 오류를 자동으로 체크","구분점이나 중영 混在의 문제를 무시","문서 중의 글쓰기 스타일이나 톤을 모방하여 全文을润色","수정 点을 사용자에게 간단하게 보고하여 확인을 기다림","년-월-일-기사 제목의 문서命名 규칙을 지원"],"es":["Revisión de errores de escritura","Ignorar problemas de puntuación y mezcla de idiomas","Informe de modificaciones y confirmación","Revisión y mejora de la calidad del texto","Uso de instrucciones detalladas para la revisión","Compatibilidad con formatos de archivo de texto"],"fr":["Révision des erreurs d''écriture","Ignorer les problèmes de ponctuation et de mélange de langues","Rapport de modifications et confirmation","Révision et amélioration de la qualité du texte","Utilisation d''instructions détaillées pour la révision","Compatibilité avec les formats de fichier de texte"],"de":["Überprüfung von Schreibfehlern","Ignorieren von Problemen mit der Zeichensetzung und der Mischung von Sprachen","Bericht über Änderungen und Bestätigung","Überprüfung und Verbesserung der Textqualität","Verwendung detaillierter Anweisungen für die Überprüfung","Kompatibilität mit Textdateiformaten"],"pt":["Detecção de erros de digitação","Ignorando problemas de pontuação e mistura de idiomas","Relatório de alterações e melhorias","Revisão e aperfeiçoamento de artigos","Utilização de tecnologias de processamento de linguagem natural","Compatibilidade com documentos nomeados de acordo com a regra ''ano-mês-dia-título''"],"ru":["Обнаружение ошибок набора текста","Игнорирование проблем с пунктуацией и смешением языков","Отчет о изменениях и улучшениях","Проверка и доработка статей","Использование технологий обработки естественного языка","Совместимость с документами, именованными в соответствии с правилом ''год-месяц-день-название''"],"ar":["اكتشاف الأخطاء الإملائية","تجاهل مشاكل العلامات الترقيمية واللغة المخلوطة","تقرير التعديلات والتحسينات","مراجعة وتحسين المقالات","استخدام تقنيات معالجة اللغة الطبيعية","توافق مع الوثائق المسمى وفقًا لقاعدة ''السنة-الشهر-اليوم-العنوان''"]},"keywords":{"en":["how to use article-review","what is article-review","article-review alternative","article-review setup guide","article-review install","article-review vs content review tools","AI-powered article review","article-review for AI agents","article review and refinement"],"zh":["AIエージェント","文章内容审查","文档检查","润色工具","写作质量","文字书写错误","标点符号","中英混排"],"ja":["AIエージェント","記事レビュー","文書のチェック","潤色ツール","文章の質","文字の書き間違い","句読点","中英混在"],"ko":["AI 에이전트","기사 리뷰","문서 체크","润色 도구","글질","문자 오류","구분점","중영 混在"],"es":["revisión de artículos","Agentes de IA","mejora de la calidad del texto","detección de errores","revisión de texto","herramientas de IA","revisión automática","corrección de textos"],"fr":["révision d''articles","outils d''IA","amélioration de la qualité du texte","détection d''erreurs","révision de texte","outils d''IA pour la révision","révision automatique","correction de textes"],"de":["Artikel-Überprüfung","KI-Agenten","Verbesserung der Textqualität","Fehlererkennung","Textüberprüfung","KI-Tools","automatische Überprüfung","Textkorrektur"],"pt":["revisão de artigos","ferramenta de revisão","processamento de linguagem natural","detecção de erros","revisão de textos","article-review","configuração do article-review","guia de configuração"],"ru":["проверка статей","инструмент для проверки","обработка естественного языка","обнаружение ошибок","проверка текстов","article-review","настройка ИИ Агента article-review","руководство по настройке"],"ar":["مراجعة المقالات","أداة المراجعة","معالجة اللغة الطبيعية","اكتشاف الأخطاء","مراجعة النصوص","article-review","إعداد أداة المراجعة article-review","دليل الإعداد"]}},"owner":"elmagnificogi","repo":"elmagnificogi.github.io","repoPath":"elmagnificogi/elmagnificogi.github.io","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.441Z","topics":[],"category":"community","skillMd":{"name":"article-review","description":"审查和润色博客文章内容，检查书写错误并根据既有风格进行润色。用于处理符合“年-月-日-文章标题”命名规则的文章文件。","bodyPreview":"# 文章内容审查\n\n为 Agent 提供的详细指令。\n\n## 使用时机\n\n- 在以下情况使用此技能\n- 如果文档名称符合“年-月-日-文章标题”的规则，类似：`2015-11-11-RaspberryStartup-5`\n- 如果只是要审查文章，那么只用执行指令的1、2、3步骤即可\n- 如果要审查润色文章，那么执行所有步骤\n\n## 指令\n\n- 1.帮我检查一下当前文档中是否存在文字书写错误\n- 2.忽略标点符号、中英混排的问题\n- 3.完成上述检查和修改后，先向我简要汇报修改点，等待我确认\n- 4.阅读当前文档，并模仿文档中书写的风格和语气，对全文进行润色","body":"# 文章内容审查\n\n为 Agent 提供的详细指令。\n\n## 使用时机\n\n- 在以下情况使用此技能\n- 如果文档名称符合“年-月-日-文章标题”的规则，类似：`2015-11-11-RaspberryStartup-5`\n- 如果只是要审查文章，那么只用执行指令的1、2、3步骤即可\n- 如果要审查润色文章，那么执行所有步骤\n\n## 指令\n\n- 1.帮我检查一下当前文档中是否存在文字书写错误\n- 2.忽略标点符号、中英混排的问题\n- 3.完成上述检查和修改后，先向我简要汇报修改点，等待我确认\n- 4.阅读当前文档，并模仿文档中书写的风格和语气，对全文进行润色\n"},"lastSynced":"2026-03-08T02:07:45.615Z","agentAnalysis":{"suitability":{"en":"Ideal for Natural Language Processing Agents like Claude Code and AutoGPT needing advanced text analysis and review capabilities.","zh":"适合于 Claude Code 和 AutoGPT 等自然语言处理代理，需要高级文本分析和审查功能。","ja":"Claude Code や AutoGPT などの自然言語処理エージェントに適しており、先進的なテキスト分析およびレビュー機能が必要です。","ko":"클라우드 코드 및 오토지피티 등과 같은 자연어 처리 에이전트에 적합하며, 고급 텍스트 분석 및 검토 기능이 필요합니다.","es":"Ideal para Agentes de Procesamiento de Lenguaje Natural como Claude Code y AutoGPT que necesitan capacidades de análisis y revisión de texto avanzadas.","fr":"Idéal pour les Agents de Traitement du Langage Naturel comme Claude Code et AutoGPT nécessitant des capacités d''analyse et de révision de texte avancées.","de":"Ideal für natürliche Sprachverarbeitungsagenten wie Claude Code und AutoGPT, die erweiterte Textanalyse- und Überprüfungsfunktionen benötigen.","pt":"Ideal para Agentes de Processamento de Linguagem Natural, como Claude Code e AutoGPT, que necessitam de capacidades avançadas de análise e revisão de texto.","ru":"Идеально подходит для агентов обработки естественного языка, таких как Claude Code и AutoGPT, требующих продвинутых возможностей анализа и проверки текста.","ar":"مثالي للوكلاء المعنيين بمعالجة اللغة الطبيعية مثل Claude Code و AutoGPT الذين يحتاجون إلى قدرات متقدمة لتحليل المراجعة النصية."},"recommendation":{"en":"Empowers agents to review articles by checking for writing errors, ignoring punctuation and formatting issues, and providing brief modification reports, utilizing protocols like text formatting and content analysis, and supporting file formats such as Markdown and HTML.","zh":"赋予代理审查文章的能力，通过检查写作错误、忽略标点和格式问题，并提供简短的修改报告，利用文本格式和内容分析等协议，并支持 Markdown 和 HTML 等文件格式。","ja":"エージェントが記事をレビューする機能を提供し、書き込みエラーの確認、句読点やフォーマットの問題の無視、簡単な修正レポートの提供を行い、テキスト形式やコンテンツ分析などのプロトコルを利用し、Markdown や HTML などのファイル形式をサポートします。","ko":"에이전트가 기사를 검토할 수 있는 기능을 제공하며, 작성 오류 확인, 구두점 및 서식 문제 무시 및简短한 수정 보고서 제공을 수행하며, 텍스트 형식 및 콘텐츠 분석 등의 프로토콜을 활용하며, 마크다운 및 HTML 등의 파일 형식을 지원합니다.","es":"Permite a los agentes revisar artículos comprobando errores de escritura, ignorando problemas de puntuación y formato, y proporcionando informes de modificación breves, utilizando protocolos como el formato de texto y el análisis de contenido, y admitiendo formatos de archivo como Markdown y HTML.","fr":"Permet aux agents de réviser les articles en vérifiant les erreurs d''écriture, en ignorant les problèmes de ponctuation et de mise en forme, et en fournissant des rapports de modification succincts, en utilisant des protocoles tels que la mise en forme de texte et l''analyse de contenu, et en prenant en charge des formats de fichiers tels que Markdown et HTML.","de":"Ermächtigt die Agenten, Artikel zu überprüfen, indem sie Schreibfehler überprüfen, Probleme mit der Interpunktion und dem Format ignorieren und kurze Änderungsberichte bereitstellen, indem sie Protokolle wie Textformatierung und Inhaltsanalyse verwenden und Dateiformate wie Markdown und HTML unterstützen.","pt":"Habilita os agentes a revisar artigos, verificando erros de escrita, ignorando questões de pontuação e formatação, e fornecendo relatórios de modificação breves, utilizando protocolos como formatação de texto e análise de conteúdo, e suportando formatos de arquivo como Markdown e HTML.","ru":"Наделяет агентов возможностью проверять статьи, обнаруживая ошибки написания, игнорируя проблемы пунктуации и форматирования, и предоставляя краткие отчеты о модификации, используя протоколы, такие как форматирование текста и анализ контента, и поддерживая форматы файлов, такие как Markdown и HTML.","ar":"تمكين الوكلاء من مراجعة المقالات عن طريق التحقق من أخطاء الكتابة، وتجاهل قضايا التنسيق والنقاط، وتقديم تقارير تعديل موجزة، باستخدام بروتوكولات مثل تنسيق النص وتحليل المحتوى، ودعم تنسيقات الملفات مثل Markdown و HTML."},"useCases":{"en":["Automating article proofreading and editing","Generating modification reports for content creators","Debugging writing errors in large document collections"],"zh":["自动化文章校对和编辑","为内容创作者生成修改报告","大型文档集合中的写作错误调试"],"ja":["記事の校正と編集の自動化","コンテンツクリエイター向けの修正レポートの生成","大規模なドキュメントコレクション内の書き込みエラーのデバッグ"],"ko":["기사 校对 및 편집의 자동화","콘텐츠 제작자를 위한 수정 보고서 생성","대형 문서 모음의 작성 오류 디버깅"],"es":["Automatización de la revisión y edición de artículos","Generación de informes de modificación para creadores de contenido","Depuración de errores de escritura en grandes colecciones de documentos"],"fr":["Automatisation de la révision et de l''édition d''articles","Génération de rapports de modification pour les créateurs de contenu","Débogage des erreurs d''écriture dans de grandes collections de documents"],"de":["Automatisierung der Überprüfung und Bearbeitung von Artikeln","Generierung von Änderungsberichten für Content-Ersteller","Fehlerbehebung bei Schreibfehlern in großen Dokumentensammlungen"],"pt":["Automatizar a revisão e edição de artigos","Gerar relatórios de modificação para criadores de conteúdo","Depurar erros de escrita em coleções de documentos grandes"],"ru":["Автоматизировать проверку и редактирование статей","Генерировать отчеты о модификации для создателей контента","Отладить ошибки написания в больших коллекциях документов"],"ar":["أتمتة مراجعة وتحرير المقالات","توليد تقارير تعديل لمنشئي المحتوى","تصحيح أخطاء الكتابة في مجموعات كبيرة من الوثائق"]},"limitations":{"en":["Requires text input in a specific format","Limited to reviewing articles with standard formatting"],"zh":["需要以特定格式输入文本","仅限于审查标准格式的文章"],"ja":["特定形式のテキスト入力が必要","標準形式の記事のみをレビュー可能"],"ko":["특정 형식의 텍스트 입력이 필요","표준 형식의 기사만 검토 가능"],"es":["Requiere entrada de texto en un formato específico","Limitado a la revisión de artículos con formato estándar"],"fr":["Nécessite une entrée de texte dans un format spécifique","Limité à la révision d''articles avec un format standard"],"de":["Erfordert Texteingabe in einem bestimmten Format","Begrenzt auf die Überprüfung von Artikeln mit Standardformat"],"pt":["Exige entrada de texto em um formato específico","Limitado à revisão de artigos com formatação padrão"],"ru":["Требует ввода текста в определенном формате","Ограничен проверкой статей со стандартным форматированием"],"ar":["يتطلب إدخال نص في تنسيق محدد","محدود بالمراجعة للمقالات ذات التنسيق المعياري"]},"version":4},"contentHash":"33652c68f2e04e57d21e2899b5a65b49acd846771e67d4ae6a4e33eacb7219fb","qualityScore":20}');
