INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('elmagnificogi/elmagnificogi.github.io/article-review', 'article-review', 'elmagnificogi', 'elmagnificogi.github.io', 'community', 'article-review elmagnificogi elmagnificogi.github.io community The article-review skill enables AI agents to review articles by checking for writing errors, ignoring punctuation and formatting issues, and providing a brief report of modifications. This skill benefits developers and content creators who need to review and refine articles. 文章内容审查是AIエージェント提供的文档检查和润色功能，帮助开发者提高写作质量 記事レビューは、AIエージェントが提供する文書のチェックと潤色機能で、開発者の文章の質を向上させることができます 기사 리뷰는 AI 에이전트가 제공하는 문서 체크와润色 기능으로, 개발者の 글질을 향상시킬 수 있습니다 El skill de revisión de artículos utiliza instrucciones detalladas para revisar y mejorar la calidad de los textos, ignorando problemas de puntuación y mezcla de idiomas. Le skill de révision d''articles utilise des instructions détaillées pour réviser et améliorer la qualité des textes, en ignorant les problèmes de ponctuation et de mélange de langues. Der Artikel-Überprüfungsskill verwendet detaillierte Anweisungen, um die Qualität von Texten zu überprüfen und zu verbessern, wobei Probleme mit der Zeichensetzung und der Mischung von Sprachen ignoriert werden. O article-review é uma ferramenta de revisão de artigos que utiliza tecnologias de processamento de linguagem natural para detectar erros e sugerir melhorias ИИ Агент article-review - это инструмент для проверки статей, который использует технологии обработки естественного языка для обнаружения ошибок и предложения улучшений أداة المراجعة article-review هي أداة مراجعة مقالات تستخدم تقنيات معالجة اللغة الطبيعية لاكتشاف الأخطاء وتقديم مقترحات لتحسينها how to use article-review what is article-review article-review alternative article-review setup guide article-review install article-review vs content review tools AI-powered article review article-review for AI agents article review and refinement AIエージェント 文章内容审查 文档检查 润色工具 写作质量 文字书写错误 标点符号 中英混排 Checks for writing errors in documents following the ''year-month-day-article-title'' naming convention Ignores punctuation and mixed English and Chinese formatting issues Provides a brief report of modifications before proceeding with further refinements Refines article content by mimicking the writing style and tone of the original document Executes a series of steps, including checking, reporting, and refining, to ensure thorough article review article-review is a skill that provides AI agents with detailed instructions to review articles, including checking for errors, ignoring formatting issues, and refining content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kubev2v/migration-planner-ui-app/validate', 'community', 'kubev2v', 'migration-planner-ui-app', 'kubev2v/migration-planner-ui-app', 'validate', 0, 0, 20, '2026-03-08T01:57:15.444Z', '2026-03-08T02:08:51.249Z', '949dd10c1a5ab00c1afa70a49d635035a5947fdef57d4c9cd019ca1959269c36', '{"id":"kubev2v/migration-planner-ui-app/validate","name":"validate","description":{"en":"The Validate skill automates code validation for developers, running checks like ESLint, Prettier, and TypeScript type checking. It benefits developers by ensuring code quality and security.","zh":"Validate AI Agent 提供代码检查功能，包括 ESLint、Prettier 和 TypeScript 类型检查等","ja":"Validate AIエージェントは、コード検証機能を提供します。ESLint、Prettier、TypeScript の型チェックなどが含まれます","ko":"Validate AI 에이전트는 코드 검증 기능을 제공하며 ESLint, Prettier, TypeScript 형식 검사 등이 포함됩니다","es":"La validación de código es un proceso crucial para asegurar la calidad y seguridad de tu código. Nuestra guía te muestra cómo hacerlo con herramientas como ESLint y TypeScript","fr":"La validation de code est un processus crucial pour assurer la qualité et la sécurité de votre code. Notre guide vous montre comment le faire avec des outils tels que ESLint et TypeScript","de":"Die Validierung von Code ist ein entscheidender Prozess, um die Qualität und Sicherheit Ihres Codes zu gewährleisten. Unser Leitfaden zeigt Ihnen, wie Sie dies mit Tools wie ESLint und TypeScript tun","pt":"O Validate é uma ferramenta que executa verificações de código, incluindo lint, formatação e testes unitários. Aprenda a configurá-lo para melhorar a qualidade do seu código.","ru":"Валидация - это инструмент, который выполняет проверки кода, включая lint, форматирование и юнит-тесты. Узнайте, как настроить его для улучшения качества вашего кода с помощью ИИ Агентов","ar":"Validate هو أداة تقوم بتشغيل عمليات التحقق من الكود، بما في ذلك لينت وتنسيق واختبارات الوحدات. تعرف على كيفية إعدادها لتحسين جودة كودك مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Validate: Automated Code Validation Setup Guide | AI Agen...","zh":"Validate 代码检查设定指南","ja":"Validate コード検証ベストプラクティス","ko":"Validate 코드 검증 가이드","es":"Guía de configuración de validación de código","fr":"Guide de validation de code pour les développeurs","de":"Validierung-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração do Validate: Melhores Práticas para ...","ru":"Настройка валидации: Руководство по лучшим практикам для ...","ar":"دليل إعداد Validate: أفضل الممارسات للاختبار مع أدوات الذ..."},"description":{"en":"Discover how to automate code validation with Validate. Learn how to run lint, format, type-check, security-scan, and test checks with a single command. Get ...","zh":"了解如何使用 Validate AI Agent 运行代码检查，包括 ESLint、Prettier 和 TypeScript 类型检查","ja":"Validate AIエージェントを使用してコード検証を実行する方法を学びます。ESLint、Prettier、TypeScript の型チェックなどを含みます","ko":"Validate AI 에이전트를 사용하여 코드 검증을 실행하는 방법을 알아보세요. ESLint, Prettier, TypeScript 형식 검사 등이 포함됩니다","es":"Aprende a validar tu código con herramientas como ESLint, Prettier y TypeScript. Mejora la calidad de tu código con nuestra guía","fr":"Découvrez comment valider votre code avec des outils tels que ESLint, Prettier et TypeScript. Améliorez la qualité de votre code avec notre guide","de":"Erfahren Sie, wie Sie Ihren Code mit Tools wie ESLint, Prettier und TypeScript validieren. Verbessern Sie die Qualität Ihres Codes mit unserem Leitfaden","pt":"Aprenda a configurar o Validate para melhorar a qualidade do código com ESLint, Prettier, TypeScript e testes unitários","ru":"Узнайте, как настроить валидацию для улучшения качества кода с помощью ESLint, Prettier, TypeScript и юнит-тестов с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Validate لتحسين جودة الكود باستخدام ESLint و Prettier و TypeScript واختبارات الوحدات مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Validate is a code validation tool that runs multiple checks, including linting, formatting, type checking, security scanning, and testing, to ensure code quality and security.","zh":"Validate 是一种代码检查工具，用于运行多种验证检查","ja":"Validate は、複数の検証チェックを実行するコード検証ツールです","ko":"Validate는 여러 가지 검증을 실행하는 코드 검증 도구입니다","es":"La validación de código es el proceso de verificar la calidad y seguridad de un código mediante herramientas como ESLint y TypeScript","fr":"La validation de code est le processus de vérification de la qualité et de la sécurité d''un code à l''aide d''outils tels que ESLint et TypeScript","de":"Die Validierung von Code ist der Prozess der Überprüfung der Qualität und Sicherheit eines Codes mithilfe von Tools wie ESLint und TypeScript","pt":"Validate é uma ferramenta de verificação de código que executa lint, formatação e testes unitários para garantir a qualidade do código","ru":"Валидация - это инструмент проверки кода, который выполняет lint, форматирование и юнит-тесты для обеспечения качества кода","ar":"Validate هو أداة للتحقق من الكود تقوم بتشغيل لينت وتنسيق واختبارات الوحدات لضمان جودة الكود"},"features":{"en":["Runs ESLint checks for code linting","Performs Prettier formatting checks for consistent code style","Executes TypeScript type checking for type safety","Conducts security vulnerability scans to identify potential threats","Runs unit tests using Vitest for code validation"],"zh":["运行 ESLint 检查","执行 Prettier 格式化检查","进行 TypeScript 类型检查","运行安全漏洞扫描","执行 Vitest 单元测试"],"ja":["ESLint チェックを実行","Prettier フォーマットチェックを実行","TypeScript の型チェックを実行","セキュリティ脆弱性スキャンを実行","Vitest ユニットテストを実行"],"ko":["ESLint 체크 실행","Prettier 형식화 체크 실행","TypeScript 형식 체크 실행","보안 취약점 스캔 실행","Vitest 유닛 테스트 실행"],"es":["Verificación de código con ESLint","Comprobación de formato con Prettier","Verificación de tipos con TypeScript","Análisis de seguridad con herramientas de escaneo de vulnerabilidades","Ejecución de pruebas unitarias con Vitest"],"fr":["Vérification de code avec ESLint","Vérification de format avec Prettier","Vérification de types a