INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kubev2v/migration-planner-ui-app/validate', 'validate', 'kubev2v', 'migration-planner-ui-app', 'community', 'validate kubev2v migration-planner-ui-app community The Validate skill automates code validation for developers, running checks like ESLint, Prettier, and TypeScript type checking. It benefits developers by ensuring code quality and security. Validate AI Agent 提供代码检查功能，包括 ESLint、Prettier 和 TypeScript 类型检查等 Validate AIエージェントは、コード検証機能を提供します。ESLint、Prettier、TypeScript の型チェックなどが含まれます Validate AI 에이전트는 코드 검증 기능을 제공하며 ESLint, Prettier, TypeScript 형식 검사 등이 포함됩니다 La validación de código es un proceso crucial para asegurar la calidad y seguridad de tu código. Nuestra guía te muestra cómo hacerlo con herramientas como ESLint y TypeScript La validation de code est un processus crucial pour assurer la qualité et la sécurité de votre code. Notre guide vous montre comment le faire avec des outils tels que ESLint et TypeScript Die Validierung von Code ist ein entscheidender Prozess, um die Qualität und Sicherheit Ihres Codes zu gewährleisten. Unser Leitfaden zeigt Ihnen, wie Sie dies mit Tools wie ESLint und TypeScript tun O Validate é uma ferramenta que executa verificações de código, incluindo lint, formatação e testes unitários. Aprenda a configurá-lo para melhorar a qualidade do seu código. Валидация - это инструмент, который выполняет проверки кода, включая lint, форматирование и юнит-тесты. Узнайте, как настроить его для улучшения качества вашего кода с помощью ИИ Агентов Validate هو أداة تقوم بتشغيل عمليات التحقق من الكود، بما في ذلك لينت وتنسيق واختبارات الوحدات. تعرف على كيفية إعدادها لتحسين جودة كودك مع أدوات الذكاء الاصطناعي how to use validate validate setup guide automated code validation validate vs eslint validate install what is validate validate alternative code validation best practices 代码检查 Validate AI Agent ESLint Prettier TypeScript 代码验证 安全漏洞扫描 Vitest Runs ESLint checks for code linting Performs Prettier formatting checks for consistent code style Executes TypeScript type checking for type safety Conducts security vulnerability scans to identify potential threats Runs unit tests using Vitest for code validation Validate is a code validation tool that runs multiple checks, including linting, formatting, type checking, security scanning, and testing, to ensure code quality and security.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Hunt-Gather-Create/_R1/inngest', 'community', 'Hunt-Gather-Create', '_R1', 'Hunt-Gather-Create/_R1', 'inngest', 0, 0, 20, '2026-03-08T01:57:15.453Z', '2026-03-08T02:09:03.109Z', '1676c94122b69c2ff5363c071de5675b96e3baa643c2daca8ab0bee326e80d4b', '{"id":"Hunt-Gather-Create/_R1/inngest","name":"inngest","description":{"en":"Inngest enables experts to build reliable background processing without managing infrastructure, creating durable, long-running workflows with checkpointed steps for AI pipelines and event-driven systems.","zh":"Inngest是一种构建可靠的后台处理和长期运行的工作流程的工具，支持服务器端和客户端的事件驱动系统","ja":"Inngestは、サーバーレスなワークフローを実現するためのツールで、長時間実行されるプロセスやイベント駆動システムを構築","ko":"Inngest는 안정적인 백그라운드 처리와 장기 실행 워크플로를 구축하는 데 사용되는 도구로, 서버리스 워크플로를 지원","es":"Inngest te permite crear flujos de trabajo en segundo plano confiables y escalables sin gestionar infraestructura. Crea pipelines de AI y flujos de trabajo de onboarding con pasos que sobreviven a los fallos","fr":"Inngest vous permet de créer des flux de travail en arrière-plan fiables et évolutifs sans gérer d''infrastructure. Créez des pipelines d''IA et des flux de travail d''intégration avec des étapes qui survivent aux échecs","de":"Inngest ermöglicht es Ihnen, zuverlässige und skalierbare Hintergrund-Workflows ohne Infrastrukturverwaltung zu erstellen. Erstellen Sie AI-Pipelines und Onboarding-Workflows mit Schritten, die Ausfälle überstehen","pt":"Inngest é uma ferramenta para processamento em segundo plano que permite criar fluxos de trabalho duráveis e longos sem gerenciar infraestrutura. Com Inngest, você pode criar pipelines de IA que demoram minutos, fluxos de onboarding que duram dias e sistemas de processamento de eventos que lidam ...","ru":"Inngest - это инструмент для фоновой обработки, который позволяет создавать долгосрочные и надежные рабочие процессы без управления инфраструктурой. С помощью Inngest вы можете создавать пайплайны ИИ, которые занимают минуты, потоки онбординга, которые длятся дни, и системы обработки событий, кот...","ar":"Inngest هو أداة لمعالجة الخلفية التي تمكنك من إنشاء سير عمل دائمة وطويلة الأمد دون إدارة البنية التحتية. باستخدام Inngest، يمكنك إنشاء خطوط أنابيب ذكاء اصطناعي تستغرق دقائق، ومسارات تسجيل الدخول التي تستغرق أيامًا، وأنظمة معالجة الأحداث التي تتعامل مع ملايين الأحداث."},"seo":{"title":{"en":"Inngest: Reliable Background Processing Setup Guide | AI ...","zh":"Inngest集成指南：构建可靠的后台处理","ja":"Inngestのセットアップガイド：サーバーレスなワークフローを実現","ko":"Inngest 통합 가이드: 안정적인 백그라운드 처리 구축","es":"Guía de configuración de Inngest para procesamiento en se...","fr":"Guide de mise en place d''Inngest pour le traitement en ar...","de":"Inngest-Setup-Anleitung für zuverlässiges Hintergrundvera...","pt":"Guia de Configuração Inngest para Processamento em Segund...","ru":"Настройка Inngest для Надежной Обработки в Фоновом Режиме","ar":"دليل إعداد Inngest للتعامل مع عمليات الخلفية"},"description":{"en":"Unlock durable workflows with Inngest! Learn how to build reliable background processing without managing infrastructure and discover the magic of Inngest''s ...","zh":"了解Inngest的优势，构建可靠的后台处理和长期运行的工作流程，无需管理基础设施","ja":"Inngestを活用して、サーバーレスなワークフローを実現し、長時間実行されるプロセスを構築","ko":"Inngest를 사용하여 안정적인 백그라운드 처리와 장기 실행 워크플로를 구축하는 방법을 알아보세요","es":"Aprende a integrar Inngest para crear flujos de trabajo duraderos y escalables sin gestionar infraestructura","fr":"Découvrez comment intégrer Inngest pour créer des flux de travail durables et évolutifs sans gérer d''infrastructure","de":"Erfahren Sie, wie Sie Inngest integrieren, um zuverlässige und skalierbare Workflows ohne Infrastrukturverwaltung zu erstellen","pt":"Aprenda a configurar o Inngest para criar fluxos de trabalho duráveis e longos sem gerenciar infraestrutura. Descubra como aproveitar os passos do Inngest pa...","ru":"Узнайте, как настроить Inngest для создания долгосрочных и надежных рабочих процессов без управления инфраструктурой. Откройте для себя преимущества использо...","ar":"تعلم كيفية إعداد Inngest لإنشاء سير عمل دائمة وطويلة الأمد دون إدارة البنية التحتية. اكتشف كيفية الاستفادة من خطوات Inngest لأنظمة معالجة الأحداث."},"definition":{"en":"Inngest is a serverless integration platform that allows experts to build reliable background processing without managing infrastructure, focusing on durable, long-running workflows","zh":"Inngest是一种用于构建可靠的后台处理和长期运行的工作流程的工具","ja":"Inngestとは、サーバーレスなワークフローを実現するためのツール","ko":"Inngest는 안정적인 백그라운드 처리와 장기 실행 워크플로를 구축하는 데 사용되는 도구","es":"Inngest es una herramienta de procesamiento en segundo plano que permite crear flujos de trabajo duraderos y escalables","fr":"Inngest est un outil de traitement en arrière-plan qui permet de créer des flux de travail durables et évolutifs","de":"Inngest ist ein Tool für die Hintergrundverarbeitung, mit dem zuverlässige und skalierbare Workflows erstellt werden können","pt":"Inngest é uma ferramenta de processamento em segundo plano que permite criar fluxos de trabalho duráveis e longos sem gerenciar infraestrutura.","ru":"Inngest - это инструмент для фоновой обработки, который позволяет создавать долгосрочные и надежные рабочие процессы без управления инфраструктурой.","ar":"Inngest هو أداة لمعالجة الخلفية التي تمكنك من إنشاء سير عمل دائمة وطويلة الأمد دون إدارة البنية التحتية."},"features":{"en":["Builds AI pipelines that take minutes to complete","Creates onboarding flows that span days with durable workflows","Processes millions of events with event-driven systems","Utilizes checkpointed steps to survive failures","Enables serverless background processing without infrastructure management","Supports long-running workflows with durable execution"],"zh":["支持服务器端和客户端的事件驱动系统","构建长期运行的工作流程","支持AI管道和オンボーディングフロー","每个步骤都是一个检查点，支持故障恢复"],"ja":["サーバーレスなワークフローを実現","長時間実行されるプロセスを構築","AIパイプラインとオンボーディングフローをサポート","各ステップはチェックポイントとして機能し、障害復旧をサポート"],"ko":["서버리스 워크플로를 지원","장기 실행 워크플로를 구축","AI 파이프라인과 온보딩 플로우를 지원","각 단계는 체크포인트로 작동하여 故障 복구를 지원"],"es":["Creación de flujos de trabajo en segundo plano confiables y escalables","Pasos que sobreviven a los fallos para garantizar la integridad de los datos","Integración con pipelines de AI para procesamiento avanzado","Flujos de trabajo de onboarding que abarcan varios días","Procesamiento de millones de eventos con tecnología serverless"],"fr":["Création de flux de travail en arrière-plan fiables et évolutifs","Étapes qui survivent aux échecs pour garantir l''intégrité des données","Intégration avec des pipelines d''IA pour un traitement avancé","Flux de travail d''intégration qui s''étendent sur plusieurs jours","Traitement de millions d''événements avec la technologie serverless"],"de":["Erstellung zuverlässiger und skalierbarer Hintergrund-Workflows","Schritte, die Ausfälle überstehen, um die Datenintegrität zu gewährleisten","Integration mit AI-Pipelines für erweiterte Verarbeitung","Onboarding-Workflows, die sich über mehrere Tage erstrecken","Verarbeitung von Millionen von Ereignissen mit serverloser Technologie"],"pt":["Criação de fluxos de trabalho duráveis e longos sem gerenciar infraestrutura","Suporte a pipelines de IA que demoram minutos","Suporte a fluxos de onboarding que duram dias","Suporte a sistemas de processamento de eventos que lidam com milhões de eventos","Passos do Inngest que sobrevivem a falhas","Integração com ferramentas de desenvolvimento como CLI"],"ru":["Создание долгосрочных и надежных рабочих процессов без управления инфраструктурой","Поддержка пайплайнов ИИ, которые занимают минуты","Поддержка потоков онбординга, которые длятся дни","Поддержка систем обработки событий, которые обрабатывают миллионы событий","Шаги Inngest, которые выживают после сбоев","Интеграция с инструментами разработки, такими как CLI"],"ar":["إنشاء سير عمل دائمة وطويلة الأمد دون إدارة البنية التحتية","دعم خطوط أنابيب ذكاء اصطناعي التي تستغرق دقائق","دعم مسارات تسجيل الدخول التي تستغرق أيامًا","دعم أنظمة معالجة الأحداث التي تتعامل مع ملايين الأحداث","خطوات Inngest التي تنجو من الفشل","التكامل مع أدوات التطوير مثل CLI"]},"keywords":{"en":["how to use inngest","inngest alternative","inngest setup guide","what is inngest","inngest vs serverless","inngest install","reliable background processing","durable workflows","serverless integration platform"],"zh":["Inngest","服务器端事件驱动系统","长期运行的工作流程","AI管道","オンボーディングフロー","后台处理"],"ja":["Inngest","サーバーレスなワークフロー","長時間実行されるプロセス","AIパイプライン","オンボーディングフロー","イベント駆動システム"],"ko":["Inngest","서버리스 워크플로","장기 실행 워크플로","AI 파이프라인","온보딩 플로우","백그라운드 처리"],"es":["inngest","procesamiento en segundo plano","flujos de trabajo escalables","pipelines de AI","onboarding","serverless","herramientas de desarrollo","integración de Inngest","configuración de Inngest"],"fr":["inngest","traitement en arrière-plan","flux de travail évolutifs","pipelines d''IA","intégration","serverless","outils de développement","intégration d''Inngest","configuration d''Inngest"],"de":["inngest","Hintergrundverarbeitung","skalierbare Workflows","AI-Pipelines","Onboarding","serverless","Entwicklungstools","Inngest-Integration","Inngest-Konfiguration"],"pt":["Inngest","processamento em segundo plano","fluxos de trabalho duráveis","pipelines de IA","sistemas de processamento de eventos","CLI","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Inngest","фоновая обработка","долгосрочные рабочие процессы","пайплайны ИИ","системы обработки событий","CLI","разработка программного обеспечения","инструменты разработки"],"ar":["Inngest","معالجة الخلفية","سير عمل دائمة","خطوط أنابيب ذكاء اصطناعي","أنظمة معالجة الأحداث","CLI","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Hunt-Gather-Create","repo":"_R1","repoPath":"Hunt-Gather-Create/_R1","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.453Z","topics":[],"category":"community","skillMd":{"name":"inngest","description":"Inngest expert for serverless-first background jobs, event-driven workflows, and durable execution without managing queues or workers. Use when: inngest, serverless background job, event-driven workflow, step function, durable execution.","bodyPreview":"# Inngest Integration\n\nYou are an Inngest expert who builds reliable background processing without\nmanaging infrastructure. You understand that serverless doesn''t mean you can''t\nhave durable, long-running workflows - it means you don''t manage the workers.\n\nYou''ve built AI pipelines that take minutes, onboarding flows that span days,\nand event-driven systems that process millions of events. You know that the\nmagic of Inngest is in its steps - each one a checkpoint that survives failures.\n\nYour co","body":"# Inngest Integration\n\nYou are an Inngest expert who builds reliable background processing without\nmanaging infrastructure. You understand that serverless doesn''t mean you can''t\nhave durable, long-running workflows - it means you don''t manage the workers.\n\nYou''ve built AI pipelines that take minutes, onboarding flows that span days,\nand event-driven systems that process millions of events. You know that the\nmagic of Inngest is in its steps - each one a checkpoint that survives failures.\n\nYour core philosophy:\n1. Event\n\n## Capabilities\n\n- inngest-functions\n- event-driven-workflows\n- step-functions\n- serverless-background-jobs\n- durable-sleep\n- fan-out-patterns\n- concurrency-control\n- scheduled-functions\n\n## Patterns\n\n### Basic Function Setup\n\nInngest function with typed events in Next.js\n\n### Multi-Step Workflow\n\nComplex workflow with parallel steps and error handling\n\n### Scheduled/Cron Functions\n\nFunctions that run on a schedule\n\n## Anti-Patterns\n\n### ❌ Not Using Steps\n\n### ❌ Huge Event Payloads\n\n### ❌ Ignoring Concurrency\n\n## Related Skills\n\nWorks well with: `nextjs-app-router`, `vercel-deployment`, `supabase-backend`, `email-systems`, `ai-agents-architect`, `stripe-integration`\n"},"lastSynced":"2026-03-08T02:09:03.109Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Pipeline Agents needing reliable background processing and durable workflows","zh":"非常适合需要可靠的后台处理和持久工作流的 AI Pipeline Agents","ja":"信頼性の高いバックグラウンド処理と耐久性のあるワークフローを必要とする AI パイプライン エージェントに最適","ko":"신뢰할 수 있는 백그라운드 처리와 지속적인 워크플ロー가 필요한 AI 파이프라인 에이전트에 적합","es":"Perfecto para Agentes de Canalización de IA que necesitan procesamiento de fondo confiable y flujos de trabajo duraderos","fr":"Parfait pour les Agents de Pipeline d''IA nécessitant un traitement d''arrière-plan fiable et des flux de travail durables","de":"Perfekt für AI-Pipeline-Agents, die zuverlässige Hintergrundverarbeitung und beständige Workflows benötigen","pt":"Perfeito para Agentes de Pipeline de IA que necessitam de processamento de segundo plano confiável e fluxos de trabalho duráveis","ru":"Идеально подходит для агентов AI Pipeline, которым требуются надежная фоновая обработка и прочные рабочие процессы","ar":"مثالي لعميل خط أنابيب الذكاء الاصطناعي الذي يحتاج إلى معالجة الخلفية الموثوقة والتدفقات العملية القوية"},"recommendation":{"en":"Empowers agents to create long-running workflows with checkpointed steps for AI pipelines and event-driven systems, utilizing serverless infrastructure and supporting millions of events without managing workers, while providing durable checkpoints for failure survival","zh":"赋予代理创建具有检查点步骤的长期运行工作流的能力，用于 AI 流水线和事件驱动系统，利用无服务器基础设施，并在不管理工作者的情况下支持数百万个事件，同时提供持久的检查点以实现故障生存","ja":"エージェントが、AI パイプラインとイベント駆動システムのためのチェックポイントの付いたステップを備えた長時間実行ワークフローを作成できるようにし、サーバーレス インフラストラクチャを利用し、ワーカーを管理せずに数百万のイベントをサポートし、障害耐性のあるチェックポイントを提供する","ko":"에이전트가 체크포인트가 있는 단계를 갖춘 장기 실행 워크플로를 생성할 수 있도록 하여 AI 파이프라인 및 이벤트 주도 시스템을 위한 서버리스 인프라를 활용하고 워커를 관리하지 않고 수백만개의 이벤트를 지원하며 장애 생존을 위한 지속적인 체크포인트를 제공","es":"Habilita a los agentes a crear flujos de trabajo de larga duración con pasos con puntos de control para canalizaciones de IA y sistemas orientados a eventos, utilizando infraestructura sin servidor y soportando millones de eventos sin administrar trabajadores, mientras proporciona puntos de control duraderos para la supervivencia ante errores","fr":"Permet aux agents de créer des flux de travail de longue durée avec des étapes avec des points de contrôle pour les pipelines d''IA et les systèmes orientés vers les événements, en utilisant une infrastructure sans serveur et en prenant en charge des millions d''événements sans gérer les travailleurs, tout en fournissant des points de contrôle durables pour la survie en cas d''erreur","de":"Ermächtigt Agents, lang laufende Workflows mit kontrollierten Schritten für AI-Pipelines und ereignisgesteuerte Systeme zu erstellen, die serverlose Infrastruktur nutzen und Millionen von Ereignissen unterstützen, ohne Worker verwalten zu müssen, während sie gleichzeitig beständige Prüfpunkte für das Überleben bei Fehlern bieten","pt":"Habilita os agentes a criar fluxos de trabalho de longa duração com etapas de ponto de verificação para pipelines de IA e sistemas acionados por eventos, utilizando infraestrutura sem servidor e suportando milhões de eventos sem gerenciar trabalhadores, enquanto fornece pontos de verificação duráveis para sobrevivência a falhas","ru":"Наделяет агентов возможностью создавать долгие рабочие процессы с контрольными точками для конвейеров ИИ и событийно-ориентированных систем, используя бессерверную инфраструктуру и поддерживая миллионы событий без управления работниками, а также предоставляя прочные контрольные точки для выживания при сбоях","ar":"يتمكن الوكلاء من إنشاء تدفقات عمل طويلة الأمد بخطوات محددة لنقاط التحقق لأنابيب الذكاء الاصطناعي والنظم المفعلة بالأحداث، باستخدام البنية التحتية بدون خادم ودعم ملايين الأحداث دون إدارة العمال، مع توفير نقاط تحقق قوية للبقاء على قيد الحياة في حالة الفشل"},"useCases":{"en":["Building reliable AI pipelines that process events over minutes or days","Creating event-driven systems that handle millions of events","Designing onboarding flows that span multiple days with durable checkpoints"],"zh":["构建能够处理数分钟或数天的事件的可靠 AI 流水线","创建能够处理数百万个事件的事件驱动系统","设计跨多天的入职流程，并具有持久的检查点"],"ja":["数分または数日のイベントを処理する信頼性の高い AI パイプラインを構築する","数百万のイベントを処理するイベント駆動システムを作成する","数日間のオンボーディング フローを設計し、耐久性のあるチェックポイントを実装する"],"ko":["수분 또는 수일의 이벤트를 처리하는 신뢰할 수 있는 AI 파이프라인을 구축","수백만개의 이벤트를 처리하는 이벤트 주도 시스템을 생성","数일 간의 온보딩 흐름을 설계하고 지속적인 체크포인트를 제공"],"es":["Construir canalizaciones de IA confiables que procesen eventos durante minutos o días","Crear sistemas orientados a eventos que manejen millones de eventos","Diseñar flujos de incorporación que abarquen varios días con puntos de control duraderos"],"fr":["Construire des pipelines d''IA fiables qui traitent des événements pendant des minutes ou des jours","Créer des systèmes orientés vers les événements qui gèrent des millions d''événements","Concevoir des flux d''intégration qui s''étendent sur plusieurs jours avec des points de contrôle durables"],"de":["Erstellen von zuverlässigen AI-Pipelines, die Ereignisse über Minuten oder Tage hinweg verarbeiten","Erstellen von ereignisgesteuerten Systemen, die Millionen von Ereignissen verarbeiten","Entwerfen von Onboarding-Flows, die sich über mehrere Tage erstrecken und beständige Prüfpunkte haben"],"pt":["Construir pipelines de IA confiáveis que processem eventos durante minutos ou dias","Criar sistemas acionados por eventos que lidem com milhões de eventos","Projetar fluxos de integração que abranjam vários dias com pontos de verificação duráveis"],"ru":["Построение надежных конвейеров ИИ, которые обрабатывают события в течение минут или дней","Создание событийно-ориентированных систем, которые обрабатывают миллионы событий","Разработка потоков интеграции, охватывающих несколько дней с прочными контрольными точками"],"ar":["بناء أنابيب ذكاء اصطناعي موثوقة لمعالجة الأحداث خلال دقائق أو أيام","إنشاء نظم مفعلة بالأحداث لتسريع ملايين الأحداث","تصميم تدفقات التأهيل التي تغطي أيام متعددة بنقاط تحقق قوية"]},"limitations":{"en":["Requires understanding of serverless infrastructure and event-driven systems","Infrastructure management is still necessary for worker configuration"],"zh":["需要了解无服务器基础设施和事件驱动系统","仍然需要基础设施管理来配置工作者"],"ja":["サーバーレス インフラストラクチャとイベント駆動システムの理解が必要","ワーカーの構成のためにインフラストラクチャ管理が依然として必要"],"ko":["서버리스 인프라 및 이벤트 주도 시스템에 대한 이해가 필요","워커 구성에 대한 인프라 관리가 여전히 필요"],"es":["Requiere comprensión de la infraestructura sin servidor y los sistemas orientados a eventos","La administración de infraestructura sigue siendo necesaria para la configuración de trabajadores"],"fr":["Nécessite une compréhension de l''infrastructure sans serveur et des systèmes orientés vers les événements","La gestion de l''infrastructure est toujours nécessaire pour la configuration des travailleurs"],"de":["Benötigt ein Verständnis für serverlose Infrastruktur und ereignisgesteuerte Systeme","Infrastrukturverwaltung ist immer noch erforderlich für die Worker-Konfiguration"],"pt":["Exige compreensão de infraestrutura sem servidor e sistemas acionados por eventos","A gestão de infraestrutura ainda é necessária para a configuração de trabalhadores"],"ru":["Требует понимания бессерверной инфраструктуры и событийно-ориентированных систем","Управление инфраструктурой все еще необходимо для конфигурации работников"],"ar":["يتطلب فهم البنية التحتية بدون خادم والنظم المفعلة بالأحداث","لا تزال إدارة البنية التحتية ضرورية لتهيئة العمال"]},"version":4},"contentHash":"1676c94122b69c2ff5363c071de5675b96e3baa643c2daca8ab0bee326e80d4b","qualityScore":20}');
DELETE FROM skills_fts WHERE id = 'Hunt-Gather-Create/_R1/inngest';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Hunt-Gather-Create/_R1/inngest', 'inngest', 'Hunt-Gather-Create', '_R1', 'community', 'inngest Hunt-Gather-Create _R1 community Inngest enables experts to build reliable background processing without managing infrastructure, creating durable, long-running workflows with checkpointed steps for AI pipelines and event-driven systems. Inngest是一种构建可靠的后台处理和长期运行的工作流程的工具，支持服务器端和客户端的事件驱动系统 Inngestは、サーバーレスなワークフローを実現するためのツールで、長時間実行されるプロセスやイベント駆動システムを構築 Inngest는 안정적인 백그라운드 처리와 장기 실행 워크플로를 구축하는 데 사용되는 도구로, 서버리스 워크플로를 지원 Inngest te permite crear flujos de trabajo en segundo plano confiables y escalables sin gestionar infraestructura. Crea pipelines de AI y flujos de trabajo de onboarding con pasos que sobreviven a los fallos Inngest vous permet de créer des flux de travail en arrière-plan fiables et évolutifs sans gérer d''infrastructure. Créez des pipelines d''IA et des flux de travail d''intégration avec des étapes qui survivent aux échecs Inngest ermöglicht es Ihnen, zuverlässige und skalierbare Hintergrund-Workflows ohne Infrastrukturverwaltung zu erstellen. Erstellen Sie AI-Pipelines und Onboarding-Workflows mit Schritten, die Ausfälle überstehen Inngest é uma ferramenta para processamento em segundo plano que permite criar fluxos de trabalho duráveis e longos sem gerenciar infraestrutura. Com Inngest, você pode criar pipelines de IA que demoram minutos, fluxos de onboarding que duram dias e sistemas de processamento de eventos que lidam ... Inngest - это инструмент для фоновой обработки, который позволяет создавать долгосрочные и надежные рабочие процессы без управления инфраструктурой. С помощью Inngest вы можете создавать пайплайны ИИ, которые занимают минуты, потоки онбординга, которые длятся дни, и системы обработки событий, кот... Inngest هو أداة لمعالجة الخلفية التي تمكنك من إنشاء سير عمل دائمة وطويلة الأمد دون إدارة البنية التحتية. باستخدام Inngest، يمكنك إنشاء خطوط أنابيب ذكاء اصطناعي تستغرق دقائق، ومسارات تسجيل الدخول التي تستغرق أيامًا، وأنظمة معالجة الأحداث التي تتعامل مع ملايين الأحداث. how to use inngest inngest alternative inngest setup guide what is inngest inngest vs serverless inngest install reliable background processing durable workflows serverless integration platform Inngest 服务器端事件驱动系统 长期运行的工作流程 AI管道 オンボーディングフロー 后台处理 Builds AI pipelines that take minutes to complete Creates onboarding flows that span days with durable workflows Processes millions of events with event-driven systems Utilizes checkpointed steps to survive failures Enables serverless background processing without infrastructure management Supports long-running workflows with durable execution Inngest is a serverless integration platform that allows experts to build reliable background processing without managing infrastructure, focusing on durable, long-running workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callumflack/callum-website-2025/doc-creation', 'community', 'callumflack', 'callum-website-2025', 'callumflack/callum-website-2025', 'doc-creation', 0, 0, 20, '2026-03-08T01:57:15.454Z', '2026-03-08T02:09:03.742Z', 'ae8155eb3c992d61eaeb4e946221bd2a28a0fb61430ff2d234eb9204c9785b6a', '{"id":"callumflack/callum-website-2025/doc-creation","name":"doc-creation","description":{"en":"The doc-creation skill helps developers manage documents by providing conventions for filename and placement, making it easier to organize and maintain documentation across repositories and applications.","zh":"文档创建是开发过程中的一个重要步骤，需要遵循特定的约定，包括文件命名和存放位置的规则","ja":"ドキュメント作成は開発プロセスの重要なステップであり、特定の約定に従う必要があります","ko":"문서 생성은 개발 프로세스의 중요한 단계로 특정 규칙을 따르는 것이 중요합니다","es":"La creación de documentos con herramientas de AI requiere una configuración adecuada. Aprende a hacerlo correctamente.","fr":"La création de documents avec des outils d''IA nécessite une configuration appropriée. Apprenez à le faire correctement.","de":"Die Erstellung von Dokumenten mit KI-Tools erfordert eine geeignete Konfiguration. Lernen Sie, wie Sie es richtig machen.","pt":"Crie documentação de acordo com as convenções de nomenclatura de arquivos e localização de pastas para Ferramentas de IA","ru":"Создайте документацию в соответствии с конвенциями именования файлов и размещения папок для ИИ Агентов","ar":"انشئ مستندات وفقًا لاتفاقيات تسمية الملفات وتركيب المجلدات لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"doc-creation: Document Management Setup Guide | AI Agent ...","zh":"文档创建最佳实践 - AIエージェント","ja":"ドキュメント作成ガイド - AIエージェント","ko":"문서 생성 가이드 - AI 에이전트","es":"Guía de Configuración para Creación de Documentos con Her...","fr":"Guide de Configuration pour la Création de Documents avec...","de":"Konfigurationsleitfaden für die Erstellung von Dokumenten...","pt":"Guia de Criação de Documentação: Convenções e Melhores Pr...","ru":"Настройка Создания Документов: Руководство по Конвенциям ...","ar":"دليل إنشاء المستندات: إرشادات وتقنيات لادوات الذكاء الاصط..."},"description":{"en":"Discover how to organize your documents with the doc-creation skill, learn the conventions for filename and placement, and get started with a seamless docume...","zh":"了解文档创建的技术细节，包括文件命名和存放位置的约定，使用AIエージェント实现高效的文档管理","ja":"ドキュメント作成の技術的な詳細を学び、ファイル名と配置場所の約定を使用して効率的なドキュメント管理を実現する","ko":"문서 생성의 기술적인 세부 사항을 배우고 파일 이름과 배치 위치의 규칙을 사용하여 효율적인 문서 관리를 구현합니다","es":"Aprende a configurar la creación de documentos con herramientas de AI y mejora tus flujos de trabajo con nuestras mejores prácticas","fr":"Découvrez comment configurer la création de documents avec des outils d''IA et améliorez vos flux de travail avec nos meilleures pratiques","de":"Erfahren Sie, wie Sie die Erstellung von Dokumenten mit KI-Tools konfigurieren und verbessern Sie Ihre Workflows mit unseren Best Practices","pt":"Aprenda as convenções de criação de documentação para Ferramentas de IA, incluindo nomes de arquivos e localização de pastas","ru":"Узнайте о конвенциях создания документов для ИИ Агентов, включая имена файлов и размещение папок","ar":"تعرف على اتفاقيات إنشاء المستندات لأدوات الذكاء الاصطناعي، بما في ذلك أسماء الملفات وتركيب المجلدات"},"definition":{"en":"doc-creation is a set of conventions for creating and managing documents, including filename prefixes and placement within repositories and applications","zh":"文档创建是指创建和管理文档的过程，包括文件命名、存放位置和格式的约定","ja":"ドキュメント作成とは、ファイル名、配置場所、フォーマットの約定を含むドキュメントの作成と管理のプロセス","ko":"문서 생성은 파일 이름, 배치 위치, 형식의 규칙을 포함하여 문서를 생성하고 관리하는 과정입니다","es":"La creación de documentos es el proceso de generar y organizar archivos de texto con herramientas de AI","fr":"La création de documents est le processus de génération et d''organisation de fichiers de texte avec des outils d''IA","de":"Die Erstellung von Dokumenten ist der Prozess der Generierung und Organisation von Textdateien mit KI-Tools","pt":"Criação de documentação é o processo de criar e organizar arquivos de acordo com convenções específicas para Ferramentas de IA","ru":"Создание документов - это процесс создания и организации файлов в соответствии с определенными конвенциями для ИИ Агентов","ar":"إنشاء المستندات هو عملية إنشاء وتنظيم الملفات وفقًا لاتفاقيات محددة لأدوات الذكاء الاصطناعي"},"features":{"en":["Uses YYMMDD-* prefix for filenames, such as 250115-pr-review-diff-injection.md","Supports cross-repo documentation placement in /docs at the repository root","Enables app-specific documentation placement in apps/<app>/docs","Allows package-specific documentation placement in packages/<pkg>/docs"],"zh":["使用YYMMDD-*前缀的文件命名约定","将文档存放在/docs、apps/<app>/docs或packages/<pkg>/docs目录中","支持跨存储库和工作流系统的文档管理","提供清晰的文档存放位置的指导","遵循特定的文档创建约定以提高效率"],"ja":["YYMMDD-*プレフィックスを使用したファイル名の約定","ドキュメントを/docs、apps/<app>/docs、またはpackages/<pkg>/docsディレクトリに配置","クロスリポジトリとワークフローシステムのドキュメント管理をサポート","明確なドキュメント配置場所のガイドを提供","特定のドキュメント作成約定に従って効率を向上"],"ko":["YYMMDD-* префик스를 사용한 파일 이름 규칙","문서를 /docs, apps/<app>/docs 또는 packages/<pkg>/docs 디렉토리에 배치","크로스 리포지토리와 워크플로 시스템의 문서 관리를 지원","명확한 문서 배치 위치의 가이드를 제공","특정 문서 생성 규칙을 따르도록 효율성을 향상"],"es":["Uso de prefijos de archivo `YYMMDD-*`","Colocación de documentos en `/docs` o `apps/<app>/docs`","Soporte para documentos de flujo de trabajo y sistema","Organización de documentos por paquete en `packages/<pkg>/docs`","Compatibilidad con flujos de trabajo y sistemas cruzados"],"fr":["Utilisation de préfixes de fichier `YYMMDD-*`","Placement de documents dans `/docs` ou `apps/<app>/docs`","Prise en charge de documents de flux de travail et de système","Organisation de documents par paquet dans `packages/<pkg>/docs`","Compatibilité avec les flux de travail et les systèmes croisés"],"de":["Verwendung von Dateipräfixen `YYMMDD-*`","Platzierung von Dokumenten in `/docs` oder `apps/<app>/docs`","Unterstützung für Dokumente von Workflows und Systemen","Organisation von Dokumenten pro Paket in `packages/<pkg>/docs`","Kompatibilität mit Workflows und Systemen über Kreuz"],"pt":["Uso de prefixo `YYMMDD-*` para nomes de arquivos","Localização de pastas em `/docs` para documentação de fluxo de trabalho","Uso de pastas `apps/<app>/docs` para documentação específica de aplicativos","Uso de pastas `packages/<pkg>/docs` para documentação específica de pacotes","Convenções de nomenclatura de arquivos para organização de documentação"],"ru":["Использование префикса `YYMMDD-*` для имен файлов","Размещение папок в `/docs` для документации рабочих процессов","Использование папок `apps/<app>/docs` для документации конкретных приложений","Использование папок `packages/<pkg>/docs` для документации конкретных пакетов","Конвенции именования файлов для организации документации"],"ar":["استخدام بادئة `YYMMDD-*` لأسماء الملفات","تركيب المجلدات في `/docs` للمستندات الخاصة بالتدفقات العملية","استخدام مجلدات `apps/<app>/docs` للمستندات الخاصة بالتطبيقات","استخدام مجلدات `packages/<pkg>/docs` للمستندات الخاصة بالحزم","اتفاقيات تسمية الملفات لتنظيم المستندات"]},"keywords":{"en":["doc-creation setup guide","document management conventions","how to use doc-creation","doc-creation vs other documentation tools","document organization best practices","installing doc-creation","what is doc-creation","doc-creation for AI agents","document placement strategies"],"zh":["文档创建","AIエージェント","文件命名约定","文档存放位置","跨存储库文档管理","工作流系统文档管理","文档创建最佳实践","文档管理工具","开发过程文档"],"ja":["ドキュメント作成","AIエージェント","ファイル名の約定","ドキュメント配置場所","クロスリポジトリドキュメント管理","ワークフローシステムドキュメント管理","ドキュメント作成ガイド","ドキュメント管理ツール","開発プロセスドキュメント"],"ko":["문서 생성","AI 에이전트","파일 이름 규칙","문서 배치 위치","크로스 리포지토리 문서 관리","워크플로 시스템 문서 관리","문서 생성 가이드","문서 관리 도구","개발 프로세스 문서"],"es":["creación de documentos con AI","herramientas de AI para documentos","configuración de documentos","mejores prácticas para documentos","flujo de trabajo de documentos","sistema de gestión de documentos","documento de texto","archivo de texto"],"fr":["création de documents avec IA","outils d''IA pour documents","configuration de documents","meilleures pratiques pour documents","flux de travail de documents","système de gestion de documents","document de texte","fichier de texte"],"de":["Erstellung von Dokumenten mit KI","KI-Tools für Dokumente","Konfiguration von Dokumenten","Best Practices für Dokumente","Workflow von Dokumenten","System für Dokumentenmanagement","Textdokument","Textdatei"],"pt":["criação de documentação","convenções de nomenclatura de arquivos","localização de pastas","Ferramentas de IA","documentação de fluxo de trabalho","documentação de aplicativos","documentação de pacotes","Guia de criação de documentação","Melhores práticas de documentação"],"ru":["создание документов","конвенции именования файлов","размещение папок","ИИ Агенты","документация рабочих процессов","документация приложений","документация пакетов","Руководство по созданию документов","Лучшие практики документации"],"ar":["إنشاء المستندات","اتفاقيات تسمية الملفات","تركيب المجلدات","أدوات الذكاء الاصطناعي","مستندات التدفقات العملية","مستندات التطبيقات","مستندات الحزم","دليل إنشاء المستندات","أفضل الممارسات للمستندات"]}},"owner":"callumflack","repo":"callum-website-2025","repoPath":"callumflack/callum-website-2025","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.454Z","topics":[],"category":"community","skillMd":{"name":"doc-creation","description":"","bodyPreview":"# Doc creation conventions\n\n## Filename\n\n- Use `YYMMDD-*` prefix (e.g., `250115-pr-review-diff-injection.md`).\n\n## Placement\n\n- Use `/docs` at repo root for cross-repo or workflow/system docs.\n- Use `apps/<app>/docs` for app-specific docs.\n- Use `packages/<pkg>/docs` for package-specific docs.\n- If it’s unclear, ask where it should live.","body":"# Doc creation conventions\n\n## Filename\n\n- Use `YYMMDD-*` prefix (e.g., `250115-pr-review-diff-injection.md`).\n\n## Placement\n\n- Use `/docs` at repo root for cross-repo or workflow/system docs.\n- Use `apps/<app>/docs` for app-specific docs.\n- Use `packages/<pkg>/docs` for package-specific docs.\n- If it’s unclear, ask where it should live.\n"},"lastSynced":"2026-03-08T02:09:03.742Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring standardized documentation management using Markdown files and directory structures like /docs, apps/<app>/docs, and packages/<pkg>/docs.","zh":"适用于需要使用 Markdown 文件和目录结构（如 /docs、apps/<app>/docs 和 packages/<pkg>/docs）进行标准化文档管理的 Developer Agents。","ja":"Markdown ファイルとディレクトリ構造（例：/docs、apps/<app>/docs、packages/<pkg>/docs）を使用した標準化されたドキュメント管理を必要とする Developer Agents に適しています。","ko":"Markdown 파일과 디렉토리 구조(/docs, apps/<app>/docs, packages/<pkg>/docs)를 사용하여 표준화된 문서 관리가 필요한 Developer Agents에 적합합니다.","es":"Ideal para Agentes de Desarrollador que requieren una gestión de documentación estandarizada utilizando archivos Markdown y estructuras de directorios como /docs, apps/<app>/docs y packages/<pkg>/docs.","fr":"Idéal pour les agents de développement nécessitant une gestion de documentation standardisée utilisant des fichiers Markdown et des structures de répertoires comme /docs, apps/<app>/docs et packages/<pkg>/docs.","de":"Ideal für Entwickleragenten, die eine standardisierte Dokumentenverwaltung mit Markdown-Dateien und Verzeichnisstrukturen wie /docs, apps/<app>/docs und packages/<pkg>/docs benötigen.","pt":"Ideal para Agentes de Desenvolvimento que requerem gerenciamento padronizado de documentação usando arquivos Markdown e estruturas de diretório como /docs, apps/<app>/docs e packages/<pkg>/docs.","ru":"Идеально подходит для Developer Agents, требующих стандартизированного управления документацией с использованием файлов Markdown и структур каталогов, таких как /docs, apps/<app>/docs и packages/<pkg>/docs.","ar":"مثالي لوكلاء المطورين الذين يتطلبون إدارة موحدة للوثائق باستخدام ملفات Markdown وهياكل الدلائل مثل /docs و apps/<app>/docs و packages/<pkg>/docs."},"recommendation":{"en":"Empowers agents to maintain organized repositories by enforcing filename conventions like YYMMDD-* prefix and structured placement, utilizing Markdown (.md) files for cross-repo, app-specific, and package-specific documentation, and facilitating collaboration through clear directory hierarchies.","zh":"赋予代理维护有组织的存储库的能力，通过强制执行文件名约定（如 YYMMDD-* 前缀）和结构化放置，利用 Markdown (.md) 文件进行跨存储库、应用程序特定和包特定的文档，并通过清晰的目录层次结构促进协作。","ja":"YYMMDD-* プレフィックスなどのファイナメ規約や構造化された配置を強制実施し、Markdown (.md) ファイルを使用してリポジトリ間、またはアプリケーション固有およびパッケージ固有のドキュメント化を行い、またクリアなディレクトリ階層構造を通じてコラボレーションを促進することで、エージェントが整理されたリポジトリを維持できるようにします。","ko":"파일 이름 규칙(예: YYMMDD-* 접두사) 및 구조화된 배치를 강제하고 Markdown(.md) 파일을 사용하여 리포지토리 간, 애플리케이션 특정 및 패키지 특정 문서를 작성하며, 또한 명확한 디렉토리 계층 구조를 통해 협력을促進하여 에이전트가 조직화된 리포지토리를 유지할 수 있도록 합니다.","es":"Habilita a los agentes a mantener repositorios organizados al aplicar convenciones de nombres de archivo como prefijo YYMMDD-* y colocación estructurada, utilizando archivos Markdown (.md) para documentación entre repositorios, específica de aplicaciones y específica de paquetes, y facilitando la colaboración a través de jerarquías de directorios claras.","fr":"Permet aux agents de maintenir des référentiels organisés en appliquant des conventions de noms de fichiers comme le préfixe YYMMDD-* et un placement structuré, en utilisant des fichiers Markdown (.md) pour la documentation entre référentiels, spécifique aux applications et spécifique aux packages, et en facilitant la collaboration grâce à des hiérarchies de répertoires claires.","de":"Ermächtigt Agenten, organisierte Repositorys durch die Einhaltung von Dateinamenskonventionen wie dem Präfix YYMMDD-* und strukturierter Platzierung, unter Verwendung von Markdown-Dateien (.md) für cross-repo-, app-spezifische und paket-spezifische Dokumentation, und erleichtert die Zusammenarbeit durch klare Verzeichnishierarchien.","pt":"Capacita os agentes a manter repositórios organizados, aplicando convenções de nomenclatura de arquivos como o prefixo YYMMDD-* e posicionamento estruturado, utilizando arquivos Markdown (.md) para documentação específica de repositório cruzado, aplicativo e pacote, e facilitando a colaboração por meio de hierarquias de diretório claras.","ru":"Позволяет агентам поддерживать организованные репозитории путем применения соглашений об именах файлов, таких как префикс YYMMDD-* и структурированное размещение, с использованием файлов Markdown (.md) для кросс-репозиторной, специфичной для приложения и специфичной для пакета документации, а также способствует сотрудничеству за счет четких иерархий каталогов.","ar":"يمكن الوكلاء من الحفاظ على مستودعات منظمة من خلال فرض اصطلاحات تسمية الملفات مثل بادئة YYMMDD-* والمواضع المهيكلة، واستخدام ملفات Markdown (.md) للتوثيق عبر المستودعات والمخصص للتطبيقات والحزم، وتسهيل التعاون من خلال تسلسلات هرمية واضحة للدلائل."},"useCases":{"en":["Standardizing filename formats across repositories","Automating documentation placement within /docs directories","Maintaining app-specific documentation in apps/<app>/docs"],"zh":["在存储库中标准化文件名格式","自动化文档在 /docs 目录中的放置","在 apps/<app>/docs 中维护应用程序特定的文档"],"ja":["リポジトリ全体のファイナメ形式を標準化する","/docs ディレクトリ内でのドキュメント配置の自動化","apps/<app>/docs 内でのアプリケーション固有のドキュメントの維持"],"ko":["리포지토리에서 파일 이름 형식을 표준화","/docs 디렉토리 내에서 문서 배치 자동화","apps/<app>/docs에서 애플리케이션 특정 문서 유지"],"es":["Establecer formatos de nombres de archivo estandarizados en todos los repositorios","Automatizar la colocación de documentación dentro de los directorios /docs","Mantener documentación específica de aplicaciones en apps/<app>/docs"],"fr":["Établir des formats de noms de fichiers standardisés dans tous les référentiels","Automatiser le placement de la documentation dans les répertoires /docs","Maintenir la documentation spécifique aux applications dans apps/<app>/docs"],"de":["Standardisierte Dateinamensformate in allen Repositorys festlegen","Automatisieren der Dokumentenplatzierung innerhalb der /docs-Verzeichnisse","Aufrechterhalten von app-spezifischer Dokumentation in apps/<app>/docs"],"pt":["Padronização de formatos de nome de arquivo em repositórios","Automatização do posicionamento da documentação dentro de diretórios /docs","Manutenção de documentação específica do aplicativo em apps/<app>/docs"],"ru":["Стандартизация форматов имен файлов в репозиториях","Автоматизация размещения документации в каталогах /docs","Ведение документации, специфичной для приложения, в apps/<app>/docs"],"ar":["توحيد تنسيقات أسماء الملفات عبر المستودعات","أتمتة وضع التوثيق داخل دلائل /docs","الحفاظ على التوثيق المخصص للتطبيقات في apps/<app>/docs"]},"limitations":{"en":["Requires adherence to specified filename and directory conventions","Limited to Markdown file format","Dependent on clear repository structure"],"zh":["需要遵守指定的文件名和目录约定","仅限 Markdown 文件格式","依赖于清晰的存储库结构"],"ja":["指定されたファイナメおよびディレクトリ規約への従業が必要","Markdown ファイル形式のみに限定される","クリアなリポジトリ構造に依存する"],"ko":["지정된 파일 이름 및 디렉토리 규칙을遵守해야 함","Markdown 파일 형식만限","명확한 리포지토리 구조에 의존"],"es":["Requiere la adhesión a las convenciones de nombres de archivo y directorios especificadas","Limitado al formato de archivo Markdown","Dependiente de una estructura de repositorio clara"],"fr":["Nécessite l''adhésion aux conventions de noms de fichiers et de répertoires spécifiées","Limité au format de fichier Markdown","Dépendant d''une structure de référentiel claire"],"de":["Erfordert die Einhaltung der spezifizierten Datei- und Verzeichnis-Konventionen","Begrenzt auf das Markdown-Dateiformat","Abhängig von einer klaren Repository-Struktur"],"pt":["Requer adesão às convenções especificadas de nome de arquivo e diretório","Limitado ao formato de arquivo Markdown","Dependente de uma estrutura clara de repositório"],"ru":["Требует соблюдения указанных соглашений об именах файлов и каталогов","Ограничено форматом файла Markdown","Зависит от четкой структуры репозитория"],"ar":["يتطلب الالتزام باتفاقيات تسمية الملفات والدلائل المحددة","مقتصر على تنسيق ملف Markdown","يعتمد على هيكل واضح للمستودع"]},"version":4},"contentHash":"ae8155eb3c992d61eaeb4e946221bd2a28a0fb61430ff2d234eb9204c9785b6a","qualityScore":20}');
