INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('callumflack/callum-website-2025/doc-creation', 'doc-creation', 'callumflack', 'callum-website-2025', 'community', 'doc-creation callumflack callum-website-2025 community The doc-creation skill helps developers manage documents by providing conventions for filename and placement, making it easier to organize and maintain documentation across repositories and applications. 文档创建是开发过程中的一个重要步骤，需要遵循特定的约定，包括文件命名和存放位置的规则 ドキュメント作成は開発プロセスの重要なステップであり、特定の約定に従う必要があります 문서 생성은 개발 프로세스의 중요한 단계로 특정 규칙을 따르는 것이 중요합니다 La creación de documentos con herramientas de AI requiere una configuración adecuada. Aprende a hacerlo correctamente. La création de documents avec des outils d''IA nécessite une configuration appropriée. Apprenez à le faire correctement. Die Erstellung von Dokumenten mit KI-Tools erfordert eine geeignete Konfiguration. Lernen Sie, wie Sie es richtig machen. Crie documentação de acordo com as convenções de nomenclatura de arquivos e localização de pastas para Ferramentas de IA Создайте документацию в соответствии с конвенциями именования файлов и размещения папок для ИИ Агентов انشئ مستندات وفقًا لاتفاقيات تسمية الملفات وتركيب المجلدات لأدوات الذكاء الاصطناعي doc-creation setup guide document management conventions how to use doc-creation doc-creation vs other documentation tools document organization best practices installing doc-creation what is doc-creation doc-creation for AI agents document placement strategies 文档创建 AIエージェント 文件命名约定 文档存放位置 跨存储库文档管理 工作流系统文档管理 文档创建最佳实践 文档管理工具 开发过程文档 Uses YYMMDD-* prefix for filenames, such as 250115-pr-review-diff-injection.md Supports cross-repo documentation placement in /docs at the repository root Enables app-specific documentation placement in apps/<app>/docs Allows package-specific documentation placement in packages/<pkg>/docs doc-creation is a set of conventions for creating and managing documents, including filename prefixes and placement within repositories and applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('abpaul/codex-compound-engineering/cloud-transfer', 'community', 'abpaul', 'codex-compound-engineering', 'abpaul/codex-compound-engineering', 'cloud-transfer', 0, 0, 20, '2026-03-08T01:57:15.456Z', '2026-03-08T02:09:06.541Z', '38f165903ddbbd223b8cb3f9ea4562b673c8354f281ac380b24909a636ddce85', '{"id":"abpaul/codex-compound-engineering/cloud-transfer","name":"cloud-transfer","description":{"en":"The cloud-transfer skill enables deterministic file transfer and sync tasks for developers, ensuring reproducibility and verification. It supports explicit source and destination paths, approved credential sources, and retention expectations.","zh":"Cloud Transfer是一种用于可靠文件传输和同步的技能，确保数据的完整性和可验证性。它支持explicit source path、destination path和sync mode","ja":"Cloud Transferは、ファイル転送と同期のためのスキルで、データの完全性と検証可能性を保証します。明示的なソースパス、宛先パス、同期モードをサポート","ko":"클라우드 전송은 파일 전송과 동기화를 위한 기술로 데이터의 무결성과 검증 가능성을 보장합니다. 명시적인 소스 경로, 대상 경로 및 동기화 모드를 지원","es":"Cloud-transfer es una habilidad para tareas de transferencia de archivos deterministas con rclone. Valida la configuración y verifica la integridad de la transferencia.","fr":"Cloud-transfer est une compétence pour les tâches de transfert de fichiers déterministes avec rclone. Elle valide la configuration et vérifie l''intégrité du transfert.","de":"Cloud-transfer ist ein Skill für deterministische Dateitransfertasks mit rclone. Er validiert die Konfiguration und überprüft die Integrität des Transfers.","pt":"O Cloud Transfer é uma habilidade para tarefas de transferência de arquivos determinísticas, com foco em reproducibilidade e verificação","ru":"Cloud Transfer - это навык для детерминированной передачи файлов, обеспечивающий воспроизводимость и проверку","ar":"Cloud Transfer هو مهارة لنقل الملفات القابل للتشغيل مرة أخرى مع التركيز على التحقق والتحقق من الصحة"},"seo":{"title":{"en":"cloud-transfer: Deterministic File Transfer Setup Guide |...","zh":"云传输设置指南 - 使用Cloud Transfer进行可靠的文件同步","ja":"Cloud Transferのベストプラクティス - 決定的ファイル転送のためのガイド","ko":"클라우드 전송 설정 가이드 - Cloud Transfer를 사용한 파일 동기화","es":"Guía de configuración de cloud-transfer para transferenci...","fr":"Configurer cloud-transfer pour des tâches de transfert de...","de":"Cloud-Transfer-Setup-Leitfaden für deterministische Datei...","pt":"Guia de Configuração do Cloud Transfer para Tarefas de Tr...","ru":"Настройка ИИ Агентов для Cloud Transfer: Руководство по п...","ar":"دليل إعداد Cloud Transfer للعمليات المحوسبة لنقل الملفات"},"description":{"en":"Discover how to set up cloud-transfer for reliable file sync tasks. Learn about prerequisites, workflow, and retention expectations to ensure reproducibility...","zh":"了解Cloud Transfer的工作原理，并学习如何使用它进行可靠的文件同步和传输。查看我们的设置指南和最佳实践","ja":"Cloud Transferのしくみを学び、ファイル転送のためのベストプラクティスを確認する。設定ガイドとチュートリアルを参照","ko":"클라우드 전송의 작동 원리를 알아보고 파일 동기화와 전송을 위한 설정 가이드와 모범 사례를 확인하세요","es":"Aprende a configurar cloud-transfer para tareas de transferencia de archivos reproducibles y verificables con rclone y credenciales seguras","fr":"Découvrez comment configurer cloud-transfer pour des tâches de transfert de fichiers réutilisables et vérifiables avec rclone et des informations d''identific...","de":"Erfahren Sie, wie Sie cloud-transfer für wiederverwendbare und überprüfbare Dateitransfertasks mit rclone und sicheren Anmeldeinformationen konfigurieren","pt":"Aprenda a configurar o Cloud Transfer para tarefas de transferência de arquivos determinísticas com reproducibilidade e verificação","ru":"Узнайте, как настроить ИИ Агенты для Cloud Transfer, чтобы обеспечить надежную передачу файлов с проверкой целостности","ar":"اكتشف كيفية إعداد Cloud Transfer للعمليات المحوسبة لنقل الملفات ب_salama و_tafdil"},"definition":{"en":"cloud-transfer is a Rails-first Codex skill for deterministic file transfer and sync tasks, inspired by Every''s compound engineering, ensuring reproducibility and verification.","zh":"Cloud Transfer是一种AIエージェント技能，用于进行可靠的文件传输和同步","ja":"Cloud Transferは、AIエージェントのスキルで、ファイル転送と同期のためのもの","ko":"클라우드 전송은 AI 에이전트 기술로 파일 전송과 동기화를 위한 것입니다","es":"Cloud-transfer es una herramienta de transferencia de archivos que utiliza rclone para tareas de transferencia deterministas y verificables","fr":"Cloud-transfer est un outil de transfert de fichiers qui utilise rclone pour des tâches de transfert déterministes et vérifiables","de":"Cloud-transfer ist ein Dateitransfer-Tool, das rclone für deterministische und überprüfbare Dateitransfertasks verwendet","pt":"O que é Cloud Transfer? É uma habilidade de transferência de arquivos que garante a reproducibilidade e verificação","ru":"Что такое Cloud Transfer? Это навык передачи файлов, обеспечивающий воспроизводимость и проверку","ar":"ما هو Cloud Transfer؟ إنه مهارة لنقل الملفات التي تضمن إعادة التشغيل والتحقق"},"features":{"en":["Validates rclone config and destination for secure file transfer","Supports explicit source and destination paths for customizable sync tasks","Runs upload/sync with explicit source/target for reliable file transfer","Verifies transfer integrity and resulting URLs/paths for data consistency","Produces a concise transfer manifest for easy tracking and monitoring"],"zh":["支持explicit source path和destination path","提供sync mode（copy和sync）","验证传输完整性和生成的URL/路径","支持approved credential source","提供Retention/overwrite expectations"],"ja":["明示的なソースパスと宛先パスのサポート","同期モード（コピーと同期）の提供","転送の完全性と生成されたURL/パスの検証","承認された資格情報ソースのサポート","Retention/overwrite expectationsの提供"],"ko":["명시적인 소스 경로와 대상 경로 지원","동기화 모드（복사와 동기화）제공","전송 무결성과 생성된 URL/경로 검증","승인된 자격 증명 소스 지원","보존/오버라이트 기대값 제공"],"es":["Validación de configuración de rclone","Transferencia de archivos con modo de sincronización explícito","Verificación de la integridad de la transferencia","Uso de credenciales seguras y aprobadas","Generación de un manifiesto de transferencia conciso"],"fr":["Validation de la configuration de rclone","Transfert de fichiers avec mode de synchronisation explicite","Vérification de l''intégrité du transfert","Utilisation d''informations d''identification sécurisées et approuvées","Génération d''un manifeste de transfert concis"],"de":["Validierung der rclone-Konfiguration","Dateitransfer mit explizitem Synchronisationsmodus","Überprüfung der Integrität des Transfers","Verwendung sicherer und genehmigter Anmeldeinformationen","Erstellung eines knappen Transfer-Manifests"],"pt":["Validação de configuração do rclone","Transferência de arquivos com modo de sincronização explícito","Verificação de integridade de transferência","Geração de um manifesto de transferência conciso","Suporte a credenciais aprovadas","Retenção e sobreposição de arquivos"],"ru":["Валидация конфигурации rclone","Передача файлов с явным режимом синхронизации","Проверка целостности передачи","Генерация краткого манифеста передачи","Поддержка утвержденных учетных данных","Хранение и перезапись файлов"],"ar":["التحقق من صحة تكوين rclone","نقل الملفات مع وضع مزامنة صريح","التحقق من صحة نقل","إنتاج مаниفست نقل موجز","دعم بيانات اعتماد معتمدة","الاحتفاظ بمسار الملفات وكتابة فوقها"]},"keywords":{"en":["how to use cloud-transfer","cloud-transfer setup guide","cloud-transfer alternative","cloud-transfer vs rclone","deterministic file transfer","file sync tasks","reproducibility in file transfer","verification in cloud storage","cloud-transfer install"],"zh":["Cloud Transfer","文件传输","文件同步","AIエージェント","可靠文件传输","文件完整性","explicit source path","destination path","sync mode"],"ja":["Cloud Transfer","ファイル転送","ファイル同期","AIエージェント","ファイル転送のためのスキル","ファイルの完全性","明示的なソースパス","宛先パス","同期モード"],"ko":["클라우드 전송","파일 전송","파일 동기화","AI 에이전트","안전한 파일 전송","파일 무결성","명시적인 소스 경로","대상 경로","동기화 모드"],"es":["cloud-transfer","transferencia de archivos determinista","rclone","credenciales seguras","verificación de integridad","manifiesto de transferencia","herramientas de AI para desarrolladores","Herramientas de transferencia de archivos en la nube"],"fr":["cloud-transfer","transfert de fichiers déterministe","rclone","informations d''identification sécurisées","vérification d''intégrité","manifeste de transfert","outils d''IA pour les développeurs","Outils de transfert de fichiers dans le cloud"],"de":["cloud-transfer","deterministischer Dateitransfer","rclone","sichere Anmeldeinformationen","Integritätsüberprüfung","Transfer-Manifest","KI-Tools für Entwickler","Cloud-Dateitransfer-Tools"],"pt":["Cloud Transfer","transferência de arquivos","reproducibilidade","verificação","rclone","sincronização de arquivos","segurança de dados","gerenciamento de arquivos"],"ru":["Cloud Transfer","передача файлов","воспроизводимость","проверка","rclone","синхронизация файлов","безопасность данных","управление файлами"],"ar":["Cloud Transfer","نقل الملفات","إعادة التشغيل","التحقق","rclone","مزامنة الملفات","أمان البيانات","إدارة الملفات"]}},"owner":"abpaul","repo":"codex-compound-engineering","repoPath":"abpaul/codex-compound-engineering","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.456Z","topics":[],"category":"community","skillMd":{"name":"cloud-transfer","description":"Upload and sync files to cloud providers using reproducible rclone-based workflows.","bodyPreview":"# Cloud Transfer\n\nUse this skill for deterministic file transfer/sync tasks where reproducibility and verification matter.\n\n## Prerequisites\n\n- explicit source path, destination path, and sync mode (`copy` vs `sync`)\n- approved credential source (never commit secrets)\n- retention/overwrite expectations\n\n## Workflow\n\n1. Validate rclone config and destination.\n2. Run upload/sync with explicit source/target.\n3. Verify transfer integrity and resulting URLs/paths.\n4. Produce a concise transfer manife","body":"# Cloud Transfer\n\nUse this skill for deterministic file transfer/sync tasks where reproducibility and verification matter.\n\n## Prerequisites\n\n- explicit source path, destination path, and sync mode (`copy` vs `sync`)\n- approved credential source (never commit secrets)\n- retention/overwrite expectations\n\n## Workflow\n\n1. Validate rclone config and destination.\n2. Run upload/sync with explicit source/target.\n3. Verify transfer integrity and resulting URLs/paths.\n4. Produce a concise transfer manifest (what moved, where, and checksum/size summary).\n\n## Rails Touchpoints\n\nWhen transfer scope includes Rails artifacts:\n\n- treat `storage/` and user-uploaded blobs as sensitive data\n- preserve environment boundaries (do not mix staging/prod datasets)\n- include migration/backfill artifact references when transfer supports release rollout\n\n## Context Discipline\n\n- Load provider docs only for the active target backend; do not preload every provider reference.\n"},"lastSynced":"2026-03-08T02:09:06.541Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps and Data Engineering Agents requiring deterministic cloud storage operations with full audit trails.","zh":"适用于需要确定性云存储操作和完整审计跟踪的DevOps和数据工程代理。","ja":"決定性クラウドストレージ操作と完全な監査トレイルが必要なDevOpsとデータエンジニアリングエージェントに適しています。","ko":"결정적 클라우드 스토리지 연산과 완전한 감사 추적이 필요한 DevOps 및 데이터 엔지니어링 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps y Data Engineering que requieren operaciones de almacenamiento en la nube deterministas con registros de auditoría completos.","fr":"Idéal pour les agents DevOps et Data Engineering nécessitant des opérations de stockage cloud déterministes avec des traces d''audit complètes.","de":"Ideal für DevOps- und Data-Engineering-Agenten, die deterministische Cloud-Speicheroperationen mit vollständigen Audit-Trail benötigen.","pt":"Ideal para agentes de DevOps e Data Engineering que exigem operações de armazenamento em nuvem determinísticas com rastros de auditoria completos.","ru":"Идеально подходит для агентов DevOps и Data Engineering, требующих детерминированных операций облачного хранилища с полными аудиторскими журналами.","ar":"مثالي لعمليات وكيل DevOps و Data Engineering التي تتطلب عمليات تخزين سحابي محددة مع سجلات تدقيق كاملة."},"recommendation":{"en":"Enables deterministic file transfer and synchronization with explicit source/destination paths and rclone configuration validation. Provides transfer integrity verification and produces concise transfer manifests for complete reproducibility.","zh":"启用确定性文件传输和同步，具有显式源/目标路径和rclone配置验证。提供传输完整性验证，并为完整再现性生成简洁的传输清单。","ja":"明示的なソース/宛先パスとrclone構成の検証を備えた決定的なファイル転送と同期を可能にします。転送の完全性の検証を提供し、完全な再現性のために簡潔な転送マニフェストを生成します。","ko":"명시적 소스/대상 경로 및 rclone 구성 검증을 갖춘 결정적 파일 전송 및 동기화를 가능하게 합니다. 전송 완전성 검증을 제공하며, 완전한 재현성을 위해 간결한 전송 매니페스트를 생성합니다.","es":"Habilita la transferencia y sincronización de archivos deterministas con rutas de origen/destino explícitas y validación de configuración de rclone. Proporciona verificación de integridad de transferencia y produce manifiestos de transferencia concisos para una reproducibilidad completa.","fr":"Permet le transfert et la synchronisation de fichiers déterministes avec des chemins source/destination explicites et une validation de configuration de rclone. Fournit une vérification de l''intégrité du transfert et produit des manifestes de transfert concis pour une reproductibilité complète.","de":"Ermöglicht deterministische Dateiübertragung und -synchronisation mit expliziten Quell-/Zielpfaden und rclone-Konfigurationsvalidierung. Bietet Übertragungsintegritätsprüfung und erzeugt präzise Übertragungsmanifeste für eine vollständige Reproduzierbarkeit.","pt":"Permite transferência de arquivos determinística e sincronização com caminhos de origem/destino explícitos e validação de configuração do rclone. Fornece verificação de integridade de transferência e produz manifestos de transferência concisos para reprodutibilidade completa.","ru":"Позволяет выполнять детерминированную передачу файлов и синхронизацию с явными исходными/целевыми путями и проверкой конфигурации rclone. Обеспечивает проверку целостности передачи и генерирует краткие манифесты передачи для полной воспроизводимости.","ar":"يسمح بنقل الملفات القاطع وتزامن المسارات المحددة明確 مع مسارات مصدر / وجهة صريحة وتحقق من صحة تكوين rclone. يوفر التحقق من صحة النقل لإنتاج manifests النقل الموجزة للتناسخ الكامل."},"useCases":{"en":["Automating production data pipeline deployments","Synchronizing build artifacts between cloud environments","Verifying large-scale data migration integrity","Generating audit trails for compliance requirements"],"zh":["自动化生产数据管道部署","在云环境之间同步构建工件","验证大规模数据迁移完整性","为合规性要求生成审计跟踪"],"ja":["生产データパイプラインのデプロイの自動化","クラウド環境間のビルドアーティファクトの同期","大規模データ移行の完全性の検証","コンプライアンス要件のための監査トレイルの生成"],"ko":["생산 데이터 파이프라인 배포 자동화","클라우드 환경 간의 빌드 아티팩트 동기화","대규모 데이터 마이그레이션完整性 검증","준수 요구 사항을 위한 감사 추적 생성"],"es":["Automatización de despliegues de pipelines de datos de producción","Sincronización de artefactos de compilación entre entornos de nube","Verificación de la integridad de la migración de datos a gran escala","Generación de registros de auditoría para requisitos de cumplimiento"],"fr":["Automatisation des déploiements de pipelines de données de production","Synchronisation des artefacts de build entre les environnements cloud","Vérification de l''intégrité de la migration de données à grande échelle","Génération de traces d''audit pour les exigences de conformité"],"de":["Automatisierung von Produktionsdaten-Pipeline-Bereitstellungen","Synchronisierung von Build-Artefakten zwischen Cloud-Umgebungen","Überprüfung der Integrität von groß angelegten Datenmigrationen","Erzeugung von Audit-Trail für Compliance-Anforderungen"],"pt":["Automatizar implantações de pipelines de dados de produção","Sincronizar artefatos de compilação entre ambientes de nuvem","Verificar a integridade da migração de dados em grande escala","Gerar rastros de auditoria para requisitos de conformidade"],"ru":["Автоматизировать развертывания производственных конвейеров данных","Синхронизировать артефакты сборки между облачными средами","Проверять целостность крупномасштабной миграции данных","Генерировать аудиторские журналы для требований соответствия"],"ar":["توفير تلقائي لعمليات خط أنابيب البيانات الإنتاجية","مزامنة مكونات البناء بين بيئات السحابية","التحقق من سلامة هجرة البيانات على نطاق واسع","توليد سجلات تدقيق لتلبية متطلبات التوافق"]},"limitations":{"en":["Requires pre-configured rclone credentials","Needs explicit source/destination path definitions","Depends on approved credential sources only"],"zh":["需要预配置的rclone凭证","需要显式源/目标路径定义","仅依赖于批准的凭证来源"],"ja":["事前に構成されたrcloneクレデンシャルが必要","明示的なソース/宛先パスの定義が必要","承認されたクレデンシャルソースのみに依存"],"ko":["사전에 구성된 rclone 자격 증명이 필요","명시적 소스/대상 경로 정의가 필요","승인된 자격 증명 소스만에 의존"],"es":["Requiere credenciales de rclone preconfiguradas","Necesita definiciones de ruta de origen/destino explícitas","Depende solo de fuentes de credenciales aprobadas"],"fr":["Nécessite des informations d''identification de rclone préconfigurées","Nécessite des définitions de chemin source/destination explicites","Dépend uniquement de sources de crédits approuvées"],"de":["Benötigt vorkonfigurierte rclone-Anmeldeinformationen","Benötigt explizite Quell-/Zielpfad-Definitionen","Hängt nur von genehmigten Zertifikatsquellen ab"],"pt":["Exige credenciais pré-configuradas do rclone","Necessita definições de caminho de origem/destino explícitas","Depende apenas de fontes de credenciais aprovadas"],"ru":["Требует предварительно настроенных учетных данных rclone","Требует явных определений исходного/целевого пути","Зависит только от утвержденных источников учетных данных"],"ar":["يتطلب أوراق اعتماد مسبقة التهيئة من rclone","يحتاج إلى تعريفات مسار مصدر / وجهة صريحة","يعتمد فقط على مصادر اعتماد معتمدة"]},"version":4},"contentHash":"38f165903ddbbd223b8cb3f9ea4562b673c8354f281ac380b24909a636ddce85","qualityScore":20}');
