INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('abpaul/codex-compound-engineering/cloud-transfer', 'cloud-transfer', 'abpaul', 'codex-compound-engineering', 'community', 'cloud-transfer abpaul codex-compound-engineering community The cloud-transfer skill enables deterministic file transfer and sync tasks for developers, ensuring reproducibility and verification. It supports explicit source and destination paths, approved credential sources, and retention expectations. Cloud Transfer是一种用于可靠文件传输和同步的技能，确保数据的完整性和可验证性。它支持explicit source path、destination path和sync mode Cloud Transferは、ファイル転送と同期のためのスキルで、データの完全性と検証可能性を保証します。明示的なソースパス、宛先パス、同期モードをサポート 클라우드 전송은 파일 전송과 동기화를 위한 기술로 데이터의 무결성과 검증 가능성을 보장합니다. 명시적인 소스 경로, 대상 경로 및 동기화 모드를 지원 Cloud-transfer es una habilidad para tareas de transferencia de archivos deterministas con rclone. Valida la configuración y verifica la integridad de la transferencia. Cloud-transfer est une compétence pour les tâches de transfert de fichiers déterministes avec rclone. Elle valide la configuration et vérifie l''intégrité du transfert. Cloud-transfer ist ein Skill für deterministische Dateitransfertasks mit rclone. Er validiert die Konfiguration und überprüft die Integrität des Transfers. O Cloud Transfer é uma habilidade para tarefas de transferência de arquivos determinísticas, com foco em reproducibilidade e verificação Cloud Transfer - это навык для детерминированной передачи файлов, обеспечивающий воспроизводимость и проверку Cloud Transfer هو مهارة لنقل الملفات القابل للتشغيل مرة أخرى مع التركيز على التحقق والتحقق من الصحة how to use cloud-transfer cloud-transfer setup guide cloud-transfer alternative cloud-transfer vs rclone deterministic file transfer file sync tasks reproducibility in file transfer verification in cloud storage cloud-transfer install Cloud Transfer 文件传输 文件同步 AIエージェント 可靠文件传输 文件完整性 explicit source path destination path sync mode Validates rclone config and destination for secure file transfer Supports explicit source and destination paths for customizable sync tasks Runs upload/sync with explicit source/target for reliable file transfer Verifies transfer integrity and resulting URLs/paths for data consistency Produces a concise transfer manifest for easy tracking and monitoring cloud-transfer is a Rails-first Codex skill for deterministic file transfer and sync tasks, inspired by Every''s compound engineering, ensuring reproducibility and verification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mweinbach/SwiftGMessages/asc-build-lifecycle', 'community', 'mweinbach', 'SwiftGMessages', 'mweinbach/SwiftGMessages', 'asc-build-lifecycle', 0, 0, 20, '2026-03-08T01:57:15.457Z', '2026-03-08T02:09:08.283Z', 'e4b39daf094abc444a00395884130495dcaf0db1c2324835cd7b34ce255a0473', '{"id":"mweinbach/SwiftGMessages/asc-build-lifecycle","name":"asc-build-lifecycle","description":{"en":"The asc-build-lifecycle skill helps developers manage build state, processing, and retention for their applications. It provides features to find the latest build, inspect processing state, and distribute builds via TestFlight.","zh":"asc-build-lifecycle技能用于管理构建状态、处理和保留。支持查找最新构建、检查处理状态和分发流程","ja":"asc-build-lifecycleスキルは、ビルド状態、処理、保留を管理するために使用されます。最新のビルドの検索、処理状態の確認、配布フローの実行をサポートします","ko":"asc-build-lifecycle 스킬은 빌드 상태, 처리, 보존을 관리하기 위해 사용됩니다. 최신 빌드 검색, 처리 상태 확인, 배포 흐름 실행을 지원합니다","es":"La habilidad asc-build-lifecycle permite a los desarrolladores gestionar el estado de compilación y procesamiento de sus aplicaciones. Pueden encontrar la compilación más reciente y realizar flujos de distribución","fr":"La compétence asc-build-lifecycle permet aux développeurs de gérer l''état de construction et de traitement de leurs applications. Ils peuvent trouver la construction la plus récente et effectuer des flux de distribution","de":"Die Fähigkeit asc-build-lifecycle ermöglicht es Entwicklern, den Build-Zustand und die Verarbeitung ihrer Anwendungen zu verwalten. Sie können den neuesten Build finden und Verteilungsflüsse durchführen","pt":"O ASC Build Lifecycle é uma ferramenta para gerenciar o estado de build, processamento e retenção. Ele oferece comandos para encontrar builds, inspecionar o estado de processamento e distribuir fluxos de trabalho.","ru":"ИИ Агент ASC Build Lifecycle - это инструмент для управления состоянием сборки, обработкой и хранением. Он предлагает команды для поиска сборок, осмотра состояния обработки и распространения рабочих потоков.","ar":"دورة حياة البناء ASC هي أداة لإدارة حالة البناء والمعالجة والاحتفاظ بها. وهي توفر أوامر للعثور على عمليات البناء والتحقق من حالة المعالجة وتوزيع تدفقات العمل."},"seo":{"title":{"en":"asc-build-lifecycle: Manage Build State for AI Agents | A...","zh":"asc-build-lifecycle Setup Guide - AIエージェント构建生命周期管理","ja":"asc-build-lifecycle Setup Guide - AIエージェントビルドライフサイクル管理","ko":"asc-build-lifecycle Setup Guide - AI 에이전트 빌드 라이프사이클 관리","es":"Guía de configuración de asc-build-lifecycle para desarro...","fr":"Guide de mise en place d''asc-build-lifecycle pour les dév...","de":"Einrichtungsleitfaden für asc-build-lifecycle-Entwickler","pt":"Guia de Configuração do Ciclo de Vida de Build ASC","ru":"Настройка ИИ Агента ASC Build Lifecycle","ar":"دليل إعداد دورة حياة بناء ASC"},"description":{"en":"Discover how to streamline your build lifecycle with asc-build-lifecycle. Learn to manage build state, processing, and retention with ease. Get started now!","zh":"了解asc-build-lifecycle技能，管理构建状态、处理和保留。查找最新构建、检查处理状态和分发流程","ja":"asc-build-lifecycleスキルを使用して、ビルド状態、処理、保留を管理します。最新のビルドを検索し、処理状態を確認し、配布フローを実行します","ko":"asc-build-lifecycle 스킬을 사용하여 빌드 상태, 처리, 보존을 관리합니다. 최신 빌드를 찾고, 처리 상태를 확인하고, 배포 흐름을 실행합니다","es":"Aprende a gestionar el estado de compilación, procesamiento y retención con la habilidad asc-build-lifecycle. Descubre cómo encontrar la compilación correcta...","fr":"Découvrez comment gérer l''état de construction, le traitement et la rétention avec la compétence asc-build-lifecycle. Apprenez à trouver la construction corr...","de":"Erfahren Sie, wie Sie den Build-Zustand, die Verarbeitung und die Aufbewahrung mit der Fähigkeit asc-build-lifecycle verwalten. Entdecken Sie, wie Sie den ri...","pt":"Aprenda a gerenciar o estado de build, processamento e retenção com o ASC Build Lifecycle. Descubra como encontrar builds, inspecionar o estado de processame...","ru":"Узнайте, как управлять состоянием сборки, обработкой и хранением с помощью ИИ Агента ASC Build Lifecycle. Откройте для себя, как найти сборки, осмотреть сост...","ar":"تعلم كيفية إدارة حالة البناء والمعالجة والاحتفاظ بها مع دورة حياة البناء ASC. اكتشف كيفية العثور على عمليات البناء والتحقق من حالة المعالجة وتوزيع تدفقات العمل."},"definition":{"en":"asc-build-lifecycle is a skill that enables developers to manage build state, processing, and retention using commands like asc builds latest and asc builds info.","zh":"asc-build-lifecycle是AIエージェント的一种技能，用于管理构建状态、处理和保留","ja":"asc-build-lifecycleは、ビルド状態、処理、保留を管理するためのAIエージェントのスキルです","ko":"asc-build-lifecycle은 빌드 상태, 처리, 보존을 관리하기 위한 AI 에이전트의 스킬입니다","es":"Asc-build-lifecycle es una habilidad que permite a los desarrolladores gestionar el estado de compilación y procesamiento de sus aplicaciones","fr":"Asc-build-lifecycle est une compétence qui permet aux développeurs de gérer l''état de construction et de traitement de leurs applications","de":"Asc-build-lifecycle ist eine Fähigkeit, die es Entwicklern ermöglicht, den Build-Zustand und die Verarbeitung ihrer Anwendungen zu verwalten","pt":"O ASC Build Lifecycle é uma ferramenta de gerenciamento de ciclo de vida de build que ajuda a gerenciar o estado de build, processamento e retenção.","ru":"ИИ Агент ASC Build Lifecycle - это инструмент управления циклом жизни сборки, который помогает управлять состоянием сборки, обработкой и хранением.","ar":"دورة حياة البناء ASC هي أداة لإدارة دورة حياة البناء التي تساعد في إدارة حالة البناء والمعالجة والاحتفاظ بها."},"features":{"en":["Find the latest build using the asc builds latest command","Inspect processing state with the asc builds info command","Distribute builds via TestFlight using the asc publish testflight command","List recent builds with the asc builds list command","Sort builds by uploaded date using the --sort -uploadedDate flag","Limit build results using the --limit flag"],"zh":["查找最新构建：`asc builds latest --app \"APP_ID\" --version \"1.2.3\" --platform IOS`","检查处理状态：`asc builds info --build \"BUILD_ID\"`","分发流程：`asc publish testflight --app \"APP_ID\" --ipa \"./app.ipa\" --group \"GROUP_ID\" --wait`","支持最近构建列表：`asc builds list --app \"APP_ID\" --sort -uploadedDate --limit 10`"],"ja":["最新のビルドの検索：`asc builds latest --app \"APP_ID\" --version \"1.2.3\" --platform IOS`","処理状態の確認：`asc builds info --build \"BUILD_ID\"`","配布フロー：`asc publish testflight --app \"APP_ID\" --ipa \"./app.ipa\" --group \"GROUP_ID\" --wait`","最近のビルド一覧のサポート：`asc builds list --app \"APP_ID\" --sort -uploadedDate --limit 10`"],"ko":["최신 빌드 검색：`asc builds latest --app \"APP_ID\" --version \"1.2.3\" --platform IOS`","처리 상태 확인：`asc builds info --build \"BUILD_ID\"`","배포 흐름：`asc publish testflight --app \"APP_ID\" --ipa \"./app.ipa\" --group \"GROUP_ID\" --wait`","최근 빌드 목록 지원：`asc builds list --app \"APP_ID\" --sort -uploadedDate --limit 10`"],"es":["Gestión del estado de compilación","Procesamiento de compilaciones","Retención de compilaciones","Búsqueda de la compilación más reciente","Flujos de distribución con TestFlight","Uso de la CLI para gestionar compilaciones"],"fr":["Gestion de l''état de construction","Traitement des constructions","Rétention des constructions","Recherche de la construction la plus récente","Flux de distribution avec TestFlight","Utilisation de la CLI pour gérer les constructions"],"de":["Verwaltung des Build-Zustands","Verarbeitung von Builds","Aufbewahrung von Builds","Suche nach dem neuesten Build","Verteilungsflüsse mit TestFlight","Verwendung der CLI zur Build-Verwaltung"],"pt":["Encontrar builds mais recentes com `asc builds latest`","Inspecionar o estado de processamento com `asc builds info`","Distribuir fluxos de trabalho com `asc publish testflight`","Gerenciar o estado de build com `asc builds list`","Filtrar builds por plataforma com `--platform IOS`","Ordenar builds por data de upload com `--sort -uploadedDate`"],"ru":["Поиск последних сборок с помощью `asc builds latest`","Осмотр состояния обработки с помощью `asc builds info`","Распространение рабочих потоков с помощью `asc publish testflight`","Управление состоянием сборки с помощью `asc builds list`","Фильтрация сборок по платформе с помощью `--platform IOS`","Сортировка сборок по дате загрузки с помощью `--sort -uploadedDate`"],"ar":["العثور على عمليات البناء الأخيرة مع `asc builds latest`","التحقق من حالة المعالجة مع `asc builds info`","توزيع تدفقات العمل مع `asc publish testflight`","إدارة حالة البناء مع `asc builds list`","تصفية عمليات البناء حسب المنصة مع `--platform IOS`","ترتيب عمليات البناء حسب تاريخ الرفع مع `--sort -uploadedDate`"]},"keywords":{"en":["how to use asc-build-lifecycle","what is asc-build-lifecycle","asc-build-lifecycle alternative","asc-build-lifecycle vs fastlane","asc-build-lifecycle install","asc-build-lifecycle setup guide","manage build state with asc-build-lifecycle","asc-build-lifecycle for iOS development","asc-build-lifecycle for AI agents"],"zh":["asc-build-lifecycle","AIエージェント","构建生命周期管理","查找最新构建","检查处理状态","分发流程","最近构建列表"],"ja":["asc-build-lifecycle","AIエージェント","ビルドライフサイクル管理","最新のビルドの検索","処理状態の確認","配布フロー","最近のビルド一覧"],"ko":["asc-build-lifecycle","AI 에이전트","빌드 라이프사이클 관리","최신 빌드 검색","처리 상태 확인","배포 흐름","최근 빌드 목록"],"es":["asc-build-lifecycle","gestión de compilaciones","estado de compilación","procesamiento de compilaciones","retención de compilaciones","TestFlight","CLI","desarrollo de aplicaciones","herramientas de desarrollo"],"fr":["asc-build-lifecycle","gestion de constructions","état de construction","traitement de constructions","rétention de constructions","TestFlight","CLI","développement d''applications","outils de développement"],"de":["asc-build-lifecycle","Build-Verwaltung","Build-Zustand","Verarbeitung von Builds","Aufbewahrung von Builds","TestFlight","CLI","Anwendungsentwicklung","Entwicklungstools"],"pt":["ASC Build Lifecycle","gerenciamento de ciclo de vida de build","ferramenta de gerenciamento de build","encontrar builds","inspecionar estado de processamento","distribuir fluxos de trabalho","CLI","React","Python"],"ru":["ИИ Агент ASC Build Lifecycle","управление циклом жизни сборки","инструмент управления сборкой","поиск сборок","осмотр состояния обработки","распространение рабочих потоков","CLI","React","Python"],"ar":["دورة حياة البناء ASC","إدارة دورة حياة البناء","أداة لإدارة البناء","العثور على عمليات البناء","التحقق من حالة المعالجة","توزيع تدفقات العمل","CLI","React","Python"]}},"owner":"mweinbach","repo":"SwiftGMessages","repoPath":"mweinbach/SwiftGMessages","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.457Z","topics":[],"category":"community","skillMd":{"name":"asc-build-lifecycle","description":"Track build processing, find latest builds, and clean up old builds with asc. Use when managing build retention or waiting on processing.","bodyPreview":"# ASC Build Lifecycle\n\nUse this skill to manage build state, processing, and retention.\n\n## Find the right build\n- Latest build:\n  - `asc builds latest --app \"APP_ID\" --version \"1.2.3\" --platform IOS`\n- Recent builds:\n  - `asc builds list --app \"APP_ID\" --sort -uploadedDate --limit 10`\n\n## Inspect processing state\n- `asc builds info --build \"BUILD_ID\"`\n\n## Distribution flows\n- Prefer end-to-end:\n  - `asc publish testflight --app \"APP_ID\" --ipa \"./app.ipa\" --group \"GROUP_ID\" --wait`\n  - `asc publ","body":"# ASC Build Lifecycle\n\nUse this skill to manage build state, processing, and retention.\n\n## Find the right build\n- Latest build:\n  - `asc builds latest --app \"APP_ID\" --version \"1.2.3\" --platform IOS`\n- Recent builds:\n  - `asc builds list --app \"APP_ID\" --sort -uploadedDate --limit 10`\n\n## Inspect processing state\n- `asc builds info --build \"BUILD_ID\"`\n\n## Distribution flows\n- Prefer end-to-end:\n  - `asc publish testflight --app \"APP_ID\" --ipa \"./app.ipa\" --group \"GROUP_ID\" --wait`\n  - `asc publish appstore --app \"APP_ID\" --ipa \"./app.ipa\" --version \"1.2.3\" --wait --submit --confirm`\n\n## Cleanup\n- Preview expiration:\n  - `asc builds expire-all --app \"APP_ID\" --older-than 90d --dry-run`\n- Apply expiration:\n  - `asc builds expire-all --app \"APP_ID\" --older-than 90d --confirm`\n- Single build:\n  - `asc builds expire --build \"BUILD_ID\"`\n\n## Notes\n- `asc builds upload` prepares upload operations only; use `asc publish` for end-to-end flows.\n- For long processing times, use `--wait`, `--poll-interval`, and `--timeout` where supported.\n"},"lastSynced":"2026-03-08T02:09:08.283Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing automated build lifecycle management for iOS applications","zh":"非常适合需要自动化iOS应用程序构建生命周期管理的DevOps代理","ja":"iOSアプリケーションの自動化されたビルドライフサイクル管理を必要とするDevOpsエージェントに最適","ko":"iOS 애플리케이션에 대한 자동화된 빌드 라이프사이클 관리가 필요한 DevOps 에이전트에 완벽함","es":"Perfecto para agentes de DevOps que necesitan una gestión automática del ciclo de vida de compilación para aplicaciones de iOS","fr":"Parfait pour les agents DevOps ayant besoin d''une gestion automatisée du cycle de vie de construction pour les applications iOS","de":"Perfekt für DevOps-Agents, die eine automatisierte Build-Lebenszyklusverwaltung für iOS-Anwendungen benötigen","pt":"Perfeito para Agentes DevOps que necessitam de gerenciamento automatizado do ciclo de vida de build para aplicativos iOS","ru":"Идеально для агентов DevOps, которым требуется автоматизированное управление жизненным циклом сборки для приложений iOS","ar":"مثالي لعميل DevOps الذين يحتاجون إلى إدارة دورة حياة البناء الآلي لتطبيقات iOS"},"recommendation":{"en":"Empowers agents to manage build state, processing, and retention via the App Store Connect API, utilizing features like finding the latest build, inspecting processing state, and distributing builds via TestFlight, all while leveraging command-line tools like `asc builds` and `asc publish`","zh":"使代理能够通过App Store Connect API管理构建状态、处理和保留，利用诸如查找最新构建、检查处理状态以及通过TestFlight分发构建等功能，同时利用`asc builds`和`asc publish`等命令行工具","ja":"App Store Connect APIを介してビルド状態、処理、および保持を管理するエージェントを強化し、最新のビルドの検索、処理状態の検査、TestFlightを介したビルドの配布などの機能を活用し、`asc builds`や`asc publish`などのコマンドラインツールを活用します","ko":"에이전트가 App Store Connect API를 통해 빌드 상태, 처리 및 보존을 관리할 수 있도록 하며, 최신 빌드 찾기, 처리 상태 점검 및 TestFlight를 통한 빌드 배포와 같은 기능을 활용하고, `asc builds` 및 `asc publish`와 같은 명령줄 도구를 활용합니다","es":"Habilita a los agentes a gestionar el estado de compilación, el procesamiento y la retención a través de la API de App Store Connect, utilizando características como encontrar la última compilación, inspeccionar el estado de procesamiento y distribuir compilaciones a través de TestFlight, todo mientras aprovecha herramientas de línea de comandos como `asc builds` y `asc publish`","fr":"Permet aux agents de gérer l''état de construction, le traitement et la rétention via l''API App Store Connect, en utilisant des fonctionnalités comme la recherche de la dernière construction, l''inspection de l''état de traitement et la distribution de constructions via TestFlight, le tout en exploitant des outils de ligne de commande comme `asc builds` et `asc publish`","de":"Ermöglicht es Agenten, den Build-Zustand, die Verarbeitung und die Aufbewahrung über die App Store Connect API zu verwalten, indem Funktionen wie das Finden des letzten Builds, die Inspektion des Verarbeitungszustands und die Verteilung von Builds über TestFlight verwendet werden, alles unter Nutzung von Befehlszeilenwerkzeugen wie `asc builds` und `asc publish`","pt":"Habilita os agentes a gerenciar o estado de build, processamento e retenção por meio da API do App Store Connect, utilizando recursos como encontrar a última build, inspecionar o estado de processamento e distribuir builds por meio do TestFlight, tudo isso aproveitando ferramentas de linha de comando como `asc builds` e `asc publish`","ru":"Позволяет агентам управлять состоянием сборки, обработкой и хранением через API App Store Connect, используя функции, такие как поиск последней сборки, осмотр состояния обработки и распространение сборок через TestFlight, все это при помощи командных инструментов, таких как `asc builds` и `asc publish`","ar":"يمكن للعميل إدارة حالة البناء والمعالجة والاحتفاظ من خلال واجهة برمجة تطبيقات App Store Connect، باستخدام ميزات مثل العثور على آخر بناء، وفحص حالة المعالجة، وتوزيع البناء عبر TestFlight، كل ذلك بالاستفادة من أدوات سطر الأوامر مثل `asc builds` و `asc publish`"},"useCases":{"en":["Automating build distribution to TestFlight","Inspecting build processing state for debugging purposes","Retrieving the latest build for application testing"],"zh":["自动化构建分发到TestFlight","检查构建处理状态以进行调试","检索最新构建以进行应用程序测试"],"ja":["TestFlightへのビルド配信の自動化","デバッグ目的でのビルド処理状態の検査","アプリケーションテスト用の最新ビルドの取得"],"ko":["TestFlight로의 빌드 배포 자동화","디버깅 목적으로 빌드 처리 상태 검사","애플리케이션 테스트를 위한 최신 빌드 검색"],"es":["Automatización de la distribución de compilaciones a TestFlight","Inspección del estado de procesamiento de compilación para fines de depuración","Recuperación de la última compilación para pruebas de aplicaciones"],"fr":["Automatisation de la distribution de constructions vers TestFlight","Inspection de l''état de traitement de construction pour des fins de débogage","Récupération de la dernière construction pour des tests d''applications"],"de":["Automatisierung der Build-Verteilung an TestFlight","Inspektion des Build-Verarbeitungszustands zu Debugging-Zwecken","Abruf des letzten Builds für Anwendungstests"],"pt":["Automatizar a distribuição de build para TestFlight","Inspecionar o estado de processamento de build para fins de depuração","Recuperar a última build para testes de aplicativos"],"ru":["Автоматизировать распространение сборок на TestFlight","Осмотреть состояние обработки сборки для целей отладки","Получить последнюю сборку для тестирования приложений"],"ar":["تأتمتية توزيع البناء إلى TestFlight","فحص حالة معالجة البناء لأغراض تصحيح الأخطاء","استرجاع آخر بناء لاختبار التطبيقات"]},"limitations":{"en":["Requires App Store Connect API access","Limited to iOS application builds","Dependent on command-line tool `asc`"],"zh":["需要App Store Connect API访问权限","仅限于iOS应用程序构建","依赖于命令行工具`asc`"],"ja":["App Store Connect APIへのアクセスが必要","iOSアプリケーションビルドに限定","コマンドラインツール`asc`に依存"],"ko":["App Store Connect API 액세스 필요","iOS 애플리케이션 빌드로 제한됨","명령줄 도구 `asc`에 의존"],"es":["Requiere acceso a la API de App Store Connect","Limitado a compilaciones de aplicaciones de iOS","Dependiente de la herramienta de línea de comandos `asc`"],"fr":["Nécessite un accès à l''API App Store Connect","Limité aux constructions d''applications iOS","Dépendant de l''outil de ligne de commande `asc`"],"de":["Benötigt Zugriff auf die App Store Connect API","Begrenzt auf iOS-Anwendungsbuilds","Abhängig von der Befehlszeilenwerkzeug `asc`"],"pt":["Requer acesso à API do App Store Connect","Limitado a builds de aplicativos iOS","Dependente da ferramenta de linha de comando `asc`"],"ru":["Требует доступа к API App Store Connect","Ограничен сборками приложений iOS","Зависит от командного инструмента `asc`"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات App Store Connect","محدود لبناء تطبيقات iOS","يعتمد على أداة سطر الأوامر `asc`"]},"version":4},"contentHash":"e4b39daf094abc444a00395884130495dcaf0db1c2324835cd7b34ce255a0473","qualityScore":20}');
