INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mweinbach/SwiftGMessages/asc-build-lifecycle', 'asc-build-lifecycle', 'mweinbach', 'SwiftGMessages', 'community', 'asc-build-lifecycle mweinbach SwiftGMessages community The asc-build-lifecycle skill helps developers manage build state, processing, and retention for their applications. It provides features to find the latest build, inspect processing state, and distribute builds via TestFlight. asc-build-lifecycle技能用于管理构建状态、处理和保留。支持查找最新构建、检查处理状态和分发流程 asc-build-lifecycleスキルは、ビルド状態、処理、保留を管理するために使用されます。最新のビルドの検索、処理状態の確認、配布フローの実行をサポートします asc-build-lifecycle 스킬은 빌드 상태, 처리, 보존을 관리하기 위해 사용됩니다. 최신 빌드 검색, 처리 상태 확인, 배포 흐름 실행을 지원합니다 La habilidad asc-build-lifecycle permite a los desarrolladores gestionar el estado de compilación y procesamiento de sus aplicaciones. Pueden encontrar la compilación más reciente y realizar flujos de distribución La compétence asc-build-lifecycle permet aux développeurs de gérer l''état de construction et de traitement de leurs applications. Ils peuvent trouver la construction la plus récente et effectuer des flux de distribution Die Fähigkeit asc-build-lifecycle ermöglicht es Entwicklern, den Build-Zustand und die Verarbeitung ihrer Anwendungen zu verwalten. Sie können den neuesten Build finden und Verteilungsflüsse durchführen O ASC Build Lifecycle é uma ferramenta para gerenciar o estado de build, processamento e retenção. Ele oferece comandos para encontrar builds, inspecionar o estado de processamento e distribuir fluxos de trabalho. ИИ Агент ASC Build Lifecycle - это инструмент для управления состоянием сборки, обработкой и хранением. Он предлагает команды для поиска сборок, осмотра состояния обработки и распространения рабочих потоков. دورة حياة البناء ASC هي أداة لإدارة حالة البناء والمعالجة والاحتفاظ بها. وهي توفر أوامر للعثور على عمليات البناء والتحقق من حالة المعالجة وتوزيع تدفقات العمل. how to use asc-build-lifecycle what is asc-build-lifecycle asc-build-lifecycle alternative asc-build-lifecycle vs fastlane asc-build-lifecycle install asc-build-lifecycle setup guide manage build state with asc-build-lifecycle asc-build-lifecycle for iOS development asc-build-lifecycle for AI agents asc-build-lifecycle AIエージェント 构建生命周期管理 查找最新构建 检查处理状态 分发流程 最近构建列表 Find the latest build using the asc builds latest command Inspect processing state with the asc builds info command Distribute builds via TestFlight using the asc publish testflight command List recent builds with the asc builds list command Sort builds by uploaded date using the --sort -uploadedDate flag Limit build results using the --limit flag asc-build-lifecycle is a skill that enables developers to manage build state, processing, and retention using commands like asc builds latest and asc builds info.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xrm07/codex-spp/spp-stats', 'community', 'xrm07', 'codex-spp', 'xrm07/codex-spp', 'spp-stats', 0, 0, 20, '2026-03-08T01:57:15.463Z', '2026-03-08T02:09:17.838Z', '0638a1c1cc965dbcb8235733204d3fd1eb5b964068fb667a74950285678c2cfe', '{"id":"xrm07/codex-spp/spp-stats","name":"spp-stats","description":{"en":"spp-stats is a skill that evaluates weekly gate metrics using consistent definitions, benefiting AI agent developers. It provides metrics such as human_lines_added and ai_lines_added.","zh":"spp-stats AIエージェント提供一貫性的指标定义，评估週次ゲート指標，包括human_lines_added、ai_lines_added等","ja":"spp-stats AIエージェントは、一貫した定義で週次ゲート指標を評価します。メトリックにはhuman_lines_added、ai_lines_addedなどが含まれます","ko":"spp-stats AI 에이전트는 일관된 정의로 주간 게이트 지표를 평가하며, human_lines_added, ai_lines_added 등이 포함됩니다","es":"spp-stats es una herramienta CLI que evalúa métricas semanales de commits de IA y humanos. Calcula ratios de contribución, aplica reglas de atribución priorizadas y proporciona orientación para mejorar la productividad del desarrollador.","fr":"spp-stats est un outil CLI qui évalue les métriques hebdomadaires des commits IA et humains. Il calcule les ratios de contribution, applique des règles d''attribution prioritaires et fournit des conseils pour la productivité développeur.","de":"spp-stats ist ein CLI-Tool zur Auswertung wöchentlicher KI- und Human-Commit-Metriken. Es berechnet Beitragsverhältnisse, wendet priorisierte Zuschreibungsregeln an und bietet Leitlinien für die Entwicklerproduktivität.","pt":"O spp-stats é uma habilidade que avalia o desempenho de agentes de IA com métricas como human_lines_added e ai_lines_added. Saiba como configurá-lo.","ru":"Spp-stats - это навык, который оценивает производительность ИИ агентов с метриками, такими как human_lines_added и ai_lines_added. Узнайте, как его настроить.","ar":"spp-stats هو مهارة تقييم أداء وكلاء الذكاء الاصطناعي باستخدام معايير مثل human_lines_added و ai_lines_added. تعرف على كيفية إعداده."},"seo":{"title":{"en":"spp-stats: Metric Analysis for AI Agents | AI Agent Skill","zh":"AIエージェントspp-stats指标设置指南","ja":"spp-stats AIエージェントの評価メトリック設定方法","ko":"AI 에이전트 spp-stats 메트릭 설정 가이드","es":"spp-stats: Guía de configuración para métricas de commits...","fr":"spp-stats: Guide de configuration pour les métriques de c...","de":"spp-stats: Einrichtungsanleitung für KI-Commit-Metriken","pt":"Guia de Configuração do spp-stats: Métricas de Desempenho...","ru":"Настройка spp-stats: Метрики Производительности ИИ Агентов","ar":"دليل إعداد spp-stats: معايير أداء وكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock data-driven insights with spp-stats. Discover how to evaluate weekly gate metrics and improve your AI agent''s performance. Get started now!","zh":"了解spp-stats AIエージェント的指标定义和评估方法，优化你的AI开发流程","ja":"spp-stats AIエージェントのメトリック定義と評価方法をマスターし、AI開発プロセスを最適化する","ko":"spp-stats AI 에이전트의 메트릭 정의와 평가 방법을 알아보고 AI 개발 프로세스를 최적화하세요","es":"Analiza commits de IA y humanos con spp-stats. Calcula ratio de contribución, prioriza atribución (fix manual, trailers, git notes) y genera informes para me...","fr":"Analysez les commits IA et humains avec spp-stats. Calculez le ratio de contribution, priorisez l''attribution (correctif manuel, trailers, notes git) et géné...","de":"Analysieren Sie KI- und Human-Commits mit spp-stats. Berechnen Sie Beitragsverhältnisse, priorisieren Sie die Zuschreibung (manueller Fix, Trailer, Git-Notes...","pt":"Aprenda a configurar o spp-stats para avaliar o desempenho de agentes de IA com métricas precisas como human_lines_added e ai_lines_added","ru":"Узнайте, как настроить spp-stats для оценки производительности ИИ агентов с точными метриками, такими как human_lines_added и ai_lines_added","ar":"تعرف على كيفية إعداد spp-stats لتقييم أداء وكلاء الذكاء الاصطناعي باستخدام معايير دقيقة مثل human_lines_added و ai_lines_added"},"definition":{"en":"spp-stats is a technical skill that assesses weekly gate metrics, including human and AI contributions, to provide actionable insights for AI agent optimization.","zh":"spp-stats是用于评估AIエージェント週次ゲート指標的一种技能","ja":"spp-statsは、AIエージェントの週次ゲート指標を評価するスキルです","ko":"spp-stats는 AI 에이전트의 주간 게이트 지표를 평가하는 스킬입니다","es":"spp-stats es un agente de IA que analiza métricas de commits de desarrollo usando definiciones consistentes. Evalúa líneas agregadas y recuentos de commits humanos/IA, calcula ratios y aplica un sistema de atribución de cuatro niveles para la medición de productividad.","fr":"spp-stats est un agent IA qui analyse les métriques de commits de développement avec des définitions cohérentes. Il évalue les lignes ajoutées et les comptes de commits humains/IA, calcule les ratios et applique un système d''attribution à quatre niveaux pour mesurer la productivité.","de":"spp-stats ist ein KI-Agent zur Analyse von Entwicklungs-Commit-Metriken mit konsistenten Definitionen. Er bewertet hinzugefügte Zeilen und Commit-Zählungen für Mensch/KI, berechnet Verhältnisse und wendet ein vierstufiges Zuschreibungssystem für die Produktivitätsmessung an.","pt":"O spp-stats é uma habilidade de avaliação de desempenho de agentes de IA que utiliza métricas como human_lines_added e ai_lines_added","ru":"Spp-stats - это навык оценки производительности ИИ агентов, который использует метрики, такие как human_lines_added и ai_lines_added","ar":"spp-stats هو مهارة تقييم أداء وكلاء الذكاء الاصطناعي التي تستخدم معايير مثل human_lines_added و ai_lines_added"},"features":{"en":["Evaluates weekly gate metrics using consistent definitions","Provides metrics such as human_lines_added and ai_lines_added","Supports attribution priority via manual fix, commit trailer, and git notes","Offers guidance on improving the human/AI ratio","Includes specific strategies for improving the ratio in subsequent weeks"],"zh":["提供human_lines_added、ai_lines_added等指标定义","支持manual fix、commit trailer、codex bot author/email match等归属优先级","计算ratio = human / (human + ai)以评估週次ゲート指標"," Drive Modeへの遷移理由を説明","提供次週ratio改善的具体策"],"ja":["human_lines_added、ai_lines_addedなどのメトリック定義を提供","manual fix、commit trailer、codex bot author/email matchなどの帰属優先順位をサポート","ratio = human / (human + ai)を計算して週次ゲート指標を評価","Drive Modeへの遷移理由を説明","次週のratio改善のための具体的な戦略を提供"],"ko":["human_lines_added, ai_lines_added 등 메트릭 정의 제공","manual fix, commit trailer, codex bot author/email match 등 귀속 우선 순위를 지원","ratio = human / (human + ai) 계산으로 주간 게이트 지표 평가","Drive Mode로의 전환 이유 설명","다음 주 ratio 개선 위한 구체적인 전략 제공"],"es":["Cálculo de ratio humano/(humano+IA) para métricas de contribución","Sistema de atribución de 4 niveles: fix manual, commit trailers, coincidencia de autor, git notes","Soporte para trailers de commit ''Co-Authored-By: Codex''","Detección automática basada en autor/email de Codex bot","Integración con git notes mediante etiquetas spp:ai y spp:human","Generación de orientación específica para mejorar ratios semanales"],"fr":["Calcul du ratio humain/(humain+IA) pour les métriques de contribution","Système d''attribution à 4 niveaux: correctif manuel, trailers de commit, correspondance auteur, notes git","Prise en charge des trailers de commit ''Co-Authored-By: Codex''","Détection automatique basée sur l''auteur/email du bot Codex","Intégration avec les notes git via les tags spp:ai et spp:human","Génération de conseils spécifiques pour améliorer les ratios hebdomadaires"],"de":["Berechnung des Human/(Human+KI)-Verhältnisses für Beitragsmetriken","4-Stufen-Zuschreibungssystem: manueller Fix, Commit-Trailer, Autor-Matching, Git-Notes","Unterstützung für ''Co-Authored-By: Codex'' Commit-Trailer","Automatische Erkennung basierend auf Codex-Bot-Autor/Email","Integration mit Git-Notes über spp:ai und spp:human Tags","Generierung spezifischer Leitlinien zur wöchentlichen Verbesserung von Verhältnissen"],"pt":["Avaliação de desempenho de agentes de IA com métricas precisas","Cálculo de human_lines_added e ai_lines_added","Definição de prioridade de atribuição para commits","Suporte a várias estratégias de atribuição, incluindo manual fix e commit trailer","Análise de ratio de human para ai","Recomendações para melhorar o desempenho"],"ru":["Оценка производительности ИИ агентов с точными метриками","Расчет human_lines_added и ai_lines_added","Определение приоритета атрибуции для коммитов","Поддержка нескольких стратегий атрибуции, включая ручной фикс и трейлер коммита","Анализ соотношения human к ai","Рекомендации для улучшения производительности"],"ar":["تقييم أداء وكلاء الذكاء الاصطناعي بمعايير دقيقة","حساب human_lines_added و ai_lines_added","تحديد أولوية الإسناد للملتزمات","دعم استراتيجيات إسناد متعددة، بما في ذلك الإصلاح اليدوي وتريلر الملتزم","تحليل نسبة الإنسان إلى الذكاء الاصطناعي","توصيات لتحسين الأداء"]},"keywords":{"en":["how to use spp-stats","spp-stats setup guide","what is spp-stats","spp-stats alternative","spp-stats vs other AI metrics tools","spp-stats install","spp-stats metric analysis","improving human/AI ratio with spp-stats","spp-stats for AI agent development"],"zh":["AIエージェント","spp-stats","週次ゲート指標","human_lines_added","ai_lines_added","ratio计算","Drive Mode","AI开发流程优化"],"ja":["AIエージェント","spp-stats","週次ゲート指標","human_lines_added","ai_lines_added","ratio計算","Drive Mode","AI開発プロセス最適化"],"ko":["AI 에이전트","spp-stats","주간 게이트 지표","human_lines_added","ai_lines_added","ratio 계산","Drive Mode","AI 개발 프로세스 최적화"],"es":["spp-stats configuración","métricas commits IA","ratio contribución desarrollador","atribución commits Codex","git notes spp:ai","herramientas productividad desarrollador","CLI métricas programación","agentes IA desarrollo software"],"fr":["configuration spp-stats","métriques commits IA","ratio contribution développeur","attribution commits Codex","notes git spp:ai","outils productivité développeur","CLI métriques programmation","agents IA développement logiciel"],"de":["spp-stats Einrichtung","KI-Commit-Metriken","Entwickler-Beitragsverhältnis","Codex-Commit-Zuschreibung","Git-Notes spp:ai","Entwicklerproduktivitätstools","CLI Metriken Programmierung","KI-Agenten Softwareentwicklung"],"pt":["spp-stats","agentes de IA","métricas de desempenho","human_lines_added","ai_lines_added","prioridade de atribuição","commits","desempenho de agentes de IA","otimização de desempenho"],"ru":["spp-stats","ИИ агенты","метрики производительности","human_lines_added","ai_lines_added","приоритет атрибуции","коммиты","производительность ИИ агентов","оптимизация производительности"],"ar":["spp-stats","وكلاء الذكاء الاصطناعي","معايير أداء","human_lines_added","ai_lines_added","أولوية الإسناد","الملتزمات","أداء وكلاء الذكاء الاصطناعي","تحسين الأداء"]}},"owner":"xrm07","repo":"codex-spp","repoPath":"xrm07/codex-spp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.463Z","topics":[],"category":"community","skillMd":{"name":"spp-stats","description":"Compute and explain codex-spp weekly gate metrics. Use when evaluating human:ai ratio, attribution outcomes, and corrective actions.","bodyPreview":"# spp-stats\n\n週次ゲート指標を一貫した定義で評価するスキル。\n\n## Metric Definitions\n\n- `human_lines_added`\n- `ai_lines_added`\n- `human_commit_count`\n- `ai_commit_count`\n- `ratio = human / (human + ai)`\n\n## Attribution Priority\n\n1. manual fix (`spp attrib fix`)\n2. commit trailer (`Co-Authored-By: Codex`)\n3. codex bot author/email match\n4. git notes (`spp:ai`, `spp:human`)\n\n## Guidance\n\n- ratio 未達なら Drive Mode への遷移理由を説明する。\n- 次週に ratio を改善する具体策を 2〜3 個提示する。","body":"# spp-stats\n\n週次ゲート指標を一貫した定義で評価するスキル。\n\n## Metric Definitions\n\n- `human_lines_added`\n- `ai_lines_added`\n- `human_commit_count`\n- `ai_commit_count`\n- `ratio = human / (human + ai)`\n\n## Attribution Priority\n\n1. manual fix (`spp attrib fix`)\n2. commit trailer (`Co-Authored-By: Codex`)\n3. codex bot author/email match\n4. git notes (`spp:ai`, `spp:human`)\n\n## Guidance\n\n- ratio 未達なら Drive Mode への遷移理由を説明する。\n- 次週に ratio を改善する具体策を 2〜3 個提示する。\n"},"lastSynced":"2026-03-08T02:09:17.838Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing weekly gate metrics evaluation and consistent definition-based assessments.","zh":"非常适合需要每周门禁指标评估和基于一致定义评估的代码分析智能体。","ja":"週次のゲートメトリクス評価と一貫した定義ベースの評価を必要とするコード分析エージェントに最適です。","ko":"주간 게이트 메트릭 평가와 일관된 정의 기반 평가가 필요한 코드 분석 에이전트에 완벽합니다.","es":"Ideal para agentes de análisis de código que necesitan evaluación semanal de métricas de gate y evaluaciones consistentes basadas en definiciones.","fr":"Idéal pour les agents d''analyse de code nécessitant une évaluation hebdomadaire des métriques de gate et des évaluations cohérentes basées sur des définitions.","de":"Perfekt für Code Analysis Agents, die wöchentliche Gate-Metrikenbewertung und konsistente, definitionsbasierte Bewertungen benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de avaliação semanal de métricas de gate e avaliações consistentes baseadas em definições.","ru":"Идеально подходит для Агентов Анализа Кода, которым требуется еженедельная оценка метрик gate и последовательная оценка на основе определений.","ar":"مثالي لوكلاء تحليل التعليمات البرمجية التي تحتاج إلى تقييم مقاييس البوابة الأسبوعية وتقييمات قائمة على التعريفات بشكل متسق."},"recommendation":{"en":"Empowers agents to track human and AI contributions through metrics like human_lines_added and ai_lines_added, utilizing attribution priority rules and git notes for accurate assessments.","zh":"使智能体能够通过 human_lines_added 和 ai_lines_added 等指标跟踪人类和AI的贡献，利用归因优先级规则和 git notes 进行准确评估。","ja":"帰属優先順位ルールと git notes を活用して正確な評価を行い、human_lines_added や ai_lines_added などのメトリクスを通じて人間とAIの貢献を追跡するエージェントを強化します。","ko":"human_lines_added 및 ai_lines_added와 같은 메트릭을 통해 인간과 AI의 기여도를 추적하고, 정확한 평가를 위해 귀속 우선순위 규칙과 git notes를 활용하여 에이전트를 강화합니다.","es":"Permite a los agentes rastrear las contribuciones humanas y de IA mediante métricas como human_lines_added y ai_lines_added, utilizando reglas de prioridad de atribución y git notes para evaluaciones precisas.","fr":"Permet aux agents de suivre les contributions humaines et IA grâce à des métriques comme human_lines_added et ai_lines_added, en utilisant des règles de priorité d''attribution et des git notes pour des évaluations précises.","de":"Ermöglicht Agents das Verfolgen menschlicher und KI-Beiträge durch Metriken wie human_lines_added und ai_lines_added, unter Verwendung von Attributionsprioritätsregeln und git notes für genaue Bewertungen.","pt":"Capacita os agentes a rastrear contribuições humanas e de IA por meio de métricas como human_lines_added e ai_lines_added, utilizando regras de prioridade de atribuição e git notes para avaliações precisas.","ru":"Позволяет агентам отслеживать вклад человека и ИИ с помощью таких метрик, как human_lines_added и ai_lines_added, используя правила приоритета атрибуции и git notes для точной оценки.","ar":"يمكن الوكلاء من تتبع مساهمات البشر والذكاء الاصطناعي من خلال مقاييس مثل human_lines_added و ai_lines_added، مستخدمين قواعد أولوية الإسناد وملاحظات git لإجراء تقييمات دقيقة."},"useCases":{"en":["Evaluating weekly gate metrics for AI agent development","Tracking human and AI contributions to codebases","Analyzing ratio of human to AI contributions for Drive Mode transition insights"],"zh":["评估AI智能体开发的每周门禁指标","跟踪人类和AI对代码库的贡献","分析人类与AI贡献比率以获取驱动模式转换洞察"],"ja":["AIエージェント開発のための週次のゲートメトリクス評価","コードベースへの人間とAIの貢献の追跡","ドライブモード移行の洞察のための人間とAIの貢献比率の分析"],"ko":["AI 에이전트 개발을 위한 주간 게이트 메트릭 평가","코드베이스에 대한 인간과 AI의 기여 추적","드라이브 모드 전환 통찰력을 위한 인간 대 AI 기여 비율 분석"],"es":["Evaluación de métricas de gate semanales para el desarrollo de agentes de IA","Seguimiento de contribuciones humanas y de IA en bases de código","Análisis de la proporción de contribuciones humanas frente a las de IA para obtener información sobre la transición al Drive Mode"],"fr":["Évaluation des métriques de gate hebdomadaires pour le développement d''agents IA","Suivi des contributions humaines et IA aux bases de code","Analyse du ratio des contributions humaines par rapport à l''IA pour des insights sur la transition en mode Drive"],"de":["Bewertung wöchentlicher Gate-Metriken für die Entwicklung von KI-Agents","Verfolgung menschlicher und KI-Beiträge zu Codebasen","Analyse des Verhältnisses von menschlichen zu KI-Beiträgen für Einblicke in den Drive Mode-Übergang"],"pt":["Avaliação de métricas de gate semanais para desenvolvimento de agente de IA","Rastreamento de contribuições humanas e de IA para bases de código","Análise da proporção de contribuições humanas para IA para insights de transição do Modo de Condução"],"ru":["Оценка еженедельных метрик gate для разработки агентов ИИ","Отслеживание вклада человека и ИИ в кодовые базы","Анализ соотношения вклада человека и ИИ для получения сведений о переходе в Режим Привода (Drive Mode)"],"ar":["تقييم مقاييس البوابة الأسبوعية لتطوير وكيل الذكاء الاصطناعي","تتبع مساهمات البشر والذكاء الاصطناعي في قواعد التعليمات البرمجية","تحليل نسبة مساهمات البشر إلى الذكاء الاصطناعي للحصول على رؤى حول الانتقال إلى وضع القيادة (Drive Mode)"]},"limitations":{"en":["Requires consistent definition-based assessments","Limited to weekly gate metrics evaluation","Dependent on accurate attribution priority and git notes"],"zh":["需要基于一致定义的评估","仅限于每周门禁指标评估","依赖于准确的归因优先级和git notes"],"ja":["一貫した定義ベースの評価が必要","週次のゲートメトリクス評価に限定される","正確な帰属優先順位とgit notesに依存"],"ko":["일관된 정의 기반 평가 필요","주간 게이트 메트릭 평가로 제한됨","정확한 귀속 우선순위 및 git notes에 의존"],"es":["Requiere evaluaciones consistentes basadas en definiciones","Limitado a la evaluación semanal de métricas de gate","Depende de una atribución de prioridad precisa y de git notes"],"fr":["Nécessite des évaluations cohérentes basées sur des définitions","Limité à l''évaluation hebdomadaire des métriques de gate","Dépend de règles de priorité d''attribution précises et des git notes"],"de":["Erfordert konsistente, definitionsbasierte Bewertungen","Beschränkt auf die wöchentliche Bewertung von Gate-Metriken","Abhängig von genauen Attributionsprioritätsregeln und git notes"],"pt":["Requer avaliações consistentes baseadas em definições","Limitado à avaliação de métricas de gate semanais","Dependente de prioridade de atribuição precisa e git notes"],"ru":["Требует последовательной оценки на основе определений","Ограничено оценкой еженедельных метрик gate","Зависит от точного приоритета атрибуции и git notes"],"ar":["يتطلب تقييمات قائمة على التعريفات بشكل متسق","يقتصر على تقييم مقاييس البوابة الأسبوعية","يعتمد على أولوية إسناد دقيقة وملاحظات git"]},"version":4},"contentHash":"0638a1c1cc965dbcb8235733204d3fd1eb5b964068fb667a74950285678c2cfe","qualityScore":20}');
